CREATE OR REPLACE FUNCTION public._crs_match_open_followup(p_client uuid, p_call_time timestamp with time zone, p_rep uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  -- p_rep is accepted for signature stability but intentionally UNUSED: the
  -- caller cannot be resolved to a CRM user (see the migration header). Adding
  -- a rep filter here silently reduces matches to zero.
  SELECT f.id
  FROM public.records f
  WHERE f.model_id = public._sales_followups_model_id()
    AND public._followup_client_id_of(f.data) = p_client::text
    AND COALESCE(f.data->>'followup_status', 'open') IN ('open', 'in_progress')
    AND COALESCE(f.data->'followup_type'->>0, f.data->>'followup_type')
        IS DISTINCT FROM 'whatsapp_follow_up'
  ORDER BY abs(extract(epoch FROM (
             COALESCE(public.try_timestamptz(f.data->>'scheduled_datetime'), p_call_time) - p_call_time
           ))) ASC,
           f.created_at ASC
  LIMIT 1;
$function$;
CREATE OR REPLACE FUNCTION public._followup_client_id_of(d jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE
    WHEN d IS NULL THEN NULL
    WHEN jsonb_typeof(d->'client_id') = 'array' THEN nullif(d->'client_id'->>0, '')
    ELSE nullif(d->>'client_id', '')
  END;
$function$;
CREATE OR REPLACE FUNCTION public._followup_next_action_type(d jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE COALESCE(d->'followup_type'->>0, d->>'followup_type')
    WHEN 'whatsapp_follow_up'             THEN 'whatsapp'
    WHEN 'offer_follow_up'                THEN 'offer'
    WHEN 'financing_follow_up'            THEN 'financing'
    WHEN 'reservation_payment_follow_up'  THEN 'financing'
    WHEN 'ownership_transfer_follow_up'   THEN 'ownership'
    ELSE 'call'
  END;
$function$;
CREATE OR REPLACE FUNCTION public._geo_clean_dissolve(g geometry, eps double precision, min_part_area double precision, min_hole_area double precision)
 RETURNS geometry
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE v_closed geometry; v_out geometry;
BEGIN
  IF g IS NULL OR ST_IsEmpty(g) THEN RETURN NULL; END IF;
  v_closed := ST_MakeValid(ST_Buffer(ST_Buffer(ST_MakeValid(g), eps), -eps));
  v_closed := ST_Multi(ST_CollectionExtract(v_closed, 3));
  WITH parts AS (SELECT (ST_Dump(v_closed)).geom AS p),
       big AS (SELECT p FROM parts WHERE ST_Area(p) >= min_part_area),
       rebuilt AS (
         SELECT ST_MakePolygon(ST_ExteriorRing(p),
                  coalesce((SELECT array_agg(r) FROM (
                    SELECT ST_InteriorRingN(p, i) AS r
                    FROM generate_series(1, ST_NumInteriorRings(p)) i
                    WHERE ST_Area(ST_MakePolygon(ST_InteriorRingN(p, i))) >= min_hole_area
                  ) keep_holes), ARRAY[]::geometry[])) AS p
         FROM big)
  SELECT ST_Multi(ST_CollectionExtract(ST_MakeValid(ST_Collect(p)), 3)) INTO v_out FROM rebuilt;
  IF v_out IS NULL OR ST_IsEmpty(v_out) THEN v_out := v_closed; END IF;
  IF v_out IS NULL OR ST_IsEmpty(v_out) THEN
    v_out := ST_Multi(ST_CollectionExtract(ST_MakeValid(g), 3));
  END IF;
  RETURN v_out;
END;
$function$;
