CREATE OR REPLACE FUNCTION public.aqar_extractions_upsert(p_rows jsonb, p_job_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_count integer;
BEGIN
  IF jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'aqar_extractions_upsert: p_rows must be a JSON array, got %', jsonb_typeof(p_rows);
  END IF;
  INSERT INTO public.aqar_listing_extractions AS t (listing_id, data, job_id, extracted_at)
  SELECT r->>'listing_id', r->'data', p_job_id, now()
  FROM jsonb_array_elements(p_rows) r
  WHERE r->>'listing_id' IS NOT NULL
  ON CONFLICT (listing_id) DO UPDATE
    SET data = EXCLUDED.data, job_id = EXCLUDED.job_id, extracted_at = now();
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END $function$;
CREATE OR REPLACE FUNCTION public.bind_my_auth_uid()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  caller_uid uuid := auth.uid();
  caller_email text := lower(coalesce((auth.jwt() ->> 'email'), ''));
  bound_user_id uuid;
BEGIN
  IF caller_uid IS NULL THEN
    RAISE EXCEPTION 'no_session' USING ERRCODE = '28000';
  END IF;

  IF caller_email = '' THEN
    RAISE EXCEPTION 'no_email_claim' USING ERRCODE = '28000';
  END IF;

  SELECT id INTO bound_user_id
    FROM public.users
   WHERE auth_uid = caller_uid AND is_active = true
   LIMIT 1;
  IF bound_user_id IS NOT NULL THEN
    RETURN bound_user_id;
  END IF;

  UPDATE public.users
     SET auth_uid    = caller_uid,
         updated_at  = now()
   WHERE auth_uid IS NULL
     AND lower(email) = caller_email
     AND is_active = true
   RETURNING id INTO bound_user_id;

  RETURN bound_user_id;
END
$function$;
