CREATE OR REPLACE FUNCTION public.call_result_suggestion_confirm(p_id uuid, p_outcome text, p_fields jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_me uuid := public.wassell_app_user_id(auth.uid());
BEGIN
  IF v_me IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
  UPDATE public.call_result_suggestions
     SET status = 'confirmed', confirmed_outcome = p_outcome,
         confirmed_fields = COALESCE(p_fields, '{}'::jsonb),
         confirmed_by = v_me, confirmed_at = now()
   WHERE id = p_id AND rep_user_id = v_me AND status = 'ready';
  RETURN FOUND;
END;
$function$;
CREATE OR REPLACE FUNCTION public.call_result_suggestion_enqueue(p_call_record_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_calls   uuid := public._sales_phone_calls_model_id();
  v_rec     public.records%ROWTYPE;
  v_client  uuid;
  v_rep     uuid;
  v_when    timestamptz;
  v_match   uuid;
  v_ftype   text;
  v_id      uuid;
BEGIN
  SELECT * INTO v_rec FROM public.records WHERE id = p_call_record_id;
  IF NOT FOUND OR v_rec.model_id IS DISTINCT FROM v_calls THEN RETURN NULL; END IF;
  IF v_rec.data->>'direction' IS DISTINCT FROM 'outbound' THEN RETURN NULL; END IF;

  v_client := NULLIF(v_rec.data->>'client_link', '')::uuid;
  IF v_client IS NULL THEN RETURN NULL; END IF;

  v_when  := COALESCE(public.try_timestamptz(v_rec.data->>'call_time'), v_rec.created_at, now());
  v_match := public._crs_match_open_followup(v_client, v_when, NULL);

  IF v_match IS NOT NULL THEN
    SELECT COALESCE(f.data->'followup_type'->>0, f.data->>'followup_type'),
           NULLIF(COALESCE(f.data->'sales_rep'->>0, f.data->>'sales_rep'), '')::uuid
      INTO v_ftype, v_rep
      FROM public.records f WHERE f.id = v_match;
  END IF;

  IF v_rep IS NULL THEN
    SELECT NULLIF(COALESCE(c.data->'client_owner'->>0, c.data->>'client_owner'), '')::uuid
      INTO v_rep
      FROM public.records c WHERE c.id = v_client;
  END IF;

  IF v_rep IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.users WHERE id = v_rep AND is_active
  ) THEN
    v_rep := NULL;
  END IF;

  IF v_rep IS NULL THEN RETURN NULL; END IF;

  INSERT INTO public.call_result_suggestions
    (call_record_id, call_log_id, client_id, rep_user_id, followup_id, followup_type, kind)
  VALUES
    (p_call_record_id, p_call_record_id, v_client, v_rep, v_match, v_ftype,
     CASE WHEN v_match IS NULL THEN 'log_interaction' ELSE 'confirm_followup' END)
  ON CONFLICT (call_record_id) WHERE status IN ('queued','running','ready') DO NOTHING
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.call_result_suggestion_fail(p_id uuid, p_error text)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH updated AS (
    UPDATE public.call_result_suggestions
       SET status = 'failed', finished_at = now(), error = p_error
     WHERE id = p_id AND status = 'running'
    RETURNING 1)
  SELECT EXISTS (SELECT 1 FROM updated);
$function$;
CREATE OR REPLACE FUNCTION public.call_result_suggestion_ready(p_id uuid, p_outcome text, p_confidence integer, p_reasoning text, p_summary text, p_fields jsonb, p_quoted text, p_model text, p_source text)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH updated AS (
    UPDATE public.call_result_suggestions
       SET status = 'ready', finished_at = now(), error = NULL,
           suggested_outcome = p_outcome, confidence = p_confidence,
           reasoning = p_reasoning, summary = p_summary,
           suggested_fields = COALESCE(p_fields, '{}'::jsonb),
           quoted_phrase = p_quoted, model = p_model, source = p_source
     WHERE id = p_id AND status = 'running'
    RETURNING 1)
  SELECT EXISTS (SELECT 1 FROM updated);
$function$;
CREATE OR REPLACE FUNCTION public.call_result_suggestions_watchdog()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_n int;
BEGIN
  UPDATE public.call_result_suggestions
     SET status = 'failed', finished_at = now(),
         error = 'analysis worker did not finish within 10 minutes'
   WHERE status = 'running' AND started_at < now() - interval '10 minutes';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$function$;
CREATE OR REPLACE FUNCTION public.claude_job_block(p_job_id uuid, p_error text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.claude_jobs SET status='blocked_subscription_limit', error=p_error, finished_at=NULL WHERE id=p_job_id;
END $function$;
CREATE OR REPLACE FUNCTION public.claude_job_claim_next(p_worker text)
 RETURNS SETOF claude_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_interactive_kinds constant text[] := ARRAY['ping','client_study'];
  v_batch_kinds       constant text[] := ARRAY['mkt_content_enrichment','mkt_campaign_summary'];
  v_ocr_kinds         constant text[] := ARRAY['mkt_visual_ocr'];
  v_aqar_kinds        constant text[] := ARRAY['aqar_listing_extract'];
  v_lease_kinds       constant text[] := ARRAY['ping','client_study','mkt_content_enrichment',
                                               'mkt_campaign_summary','mkt_visual_ocr',
                                               'aqar_listing_extract'];
  v_holds_interactive boolean; v_holds_marketing boolean; v_holds_ocr boolean; v_holds_aqar boolean;
  v_interactive_orphan boolean; v_marketing_orphan boolean; v_ocr_orphan boolean; v_aqar_orphan boolean;
  v_holds_any boolean; v_no_leases boolean;
  v_may_interactive boolean; v_may_batch boolean; v_may_ocr boolean; v_may_aqar boolean;
BEGIN
  SELECT NOT EXISTS (SELECT 1 FROM public.claude_runner_lease) INTO v_no_leases;

  SELECT EXISTS (SELECT 1 FROM public.claude_runner_lease l WHERE l.lease_name='interactive'
      AND l.released_at IS NULL AND l.expires_at > now() AND l.owner_id = p_worker) INTO v_holds_interactive;
  SELECT EXISTS (SELECT 1 FROM public.claude_runner_lease l
      WHERE (l.lease_name = 'marketing_intelligence' OR starts_with(l.lease_name, 'marketing_intelligence#'))
      AND l.released_at IS NULL AND l.expires_at > now() AND l.owner_id = p_worker) INTO v_holds_marketing;
  SELECT EXISTS (SELECT 1 FROM public.claude_runner_lease l WHERE l.lease_name='ocr'
      AND l.released_at IS NULL AND l.expires_at > now() AND l.owner_id = p_worker) INTO v_holds_ocr;
  SELECT EXISTS (SELECT 1 FROM public.claude_runner_lease l
      WHERE (l.lease_name = 'aqar' OR starts_with(l.lease_name, 'aqar#'))
      AND l.released_at IS NULL AND l.expires_at > now() AND l.owner_id = p_worker) INTO v_holds_aqar;

  SELECT NOT EXISTS (SELECT 1 FROM public.claude_runner_lease l WHERE l.lease_name='interactive'
      AND l.released_at IS NULL AND l.expires_at > now()) INTO v_interactive_orphan;
  SELECT NOT EXISTS (SELECT 1 FROM public.claude_runner_lease l
      WHERE (l.lease_name = 'marketing_intelligence' OR starts_with(l.lease_name, 'marketing_intelligence#'))
      AND l.released_at IS NULL AND l.expires_at > now()) INTO v_marketing_orphan;
  SELECT NOT EXISTS (SELECT 1 FROM public.claude_runner_lease l WHERE l.lease_name='ocr'
      AND l.released_at IS NULL AND l.expires_at > now()) INTO v_ocr_orphan;
  SELECT NOT EXISTS (SELECT 1 FROM public.claude_runner_lease l
      WHERE (l.lease_name = 'aqar' OR starts_with(l.lease_name, 'aqar#'))
      AND l.released_at IS NULL AND l.expires_at > now()) INTO v_aqar_orphan;

  v_holds_any := v_holds_interactive OR v_holds_marketing OR v_holds_ocr OR v_holds_aqar;

  v_may_interactive := v_no_leases OR v_holds_interactive OR (v_interactive_orphan AND v_holds_any);
  v_may_batch       := v_no_leases OR v_holds_marketing   OR (v_marketing_orphan   AND v_holds_any);
  v_may_ocr         := v_no_leases OR v_holds_ocr         OR (v_ocr_orphan         AND v_holds_any);
  v_may_aqar        := v_no_leases OR v_holds_aqar        OR (v_aqar_orphan        AND v_holds_any);

  SELECT id INTO v_id FROM public.claude_jobs
  WHERE status = 'pending'
    AND (
      kind <> ALL (v_lease_kinds)
      OR (kind = ANY (v_interactive_kinds) AND v_may_interactive)
      OR (kind = ANY (v_batch_kinds)       AND v_may_batch)
      OR (kind = ANY (v_ocr_kinds)         AND v_may_ocr)
      OR (kind = ANY (v_aqar_kinds)        AND v_may_aqar)
    )
  ORDER BY
    CASE
      WHEN kind = ANY (v_interactive_kinds) AND v_may_interactive THEN 0
      WHEN kind <> ALL (v_lease_kinds) THEN 1
      ELSE 2
    END,
    created_at
  FOR UPDATE SKIP LOCKED
  LIMIT 1;
  IF v_id IS NULL THEN RETURN; END IF;

  RETURN QUERY
  UPDATE public.claude_jobs
  SET status='running', claimed_by=p_worker, started_at=now(), attempts=attempts+1
  WHERE id = v_id
  RETURNING *;
END;
$function$;
CREATE OR REPLACE FUNCTION public.claude_job_complete(p_job_id uuid, p_result jsonb)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  UPDATE public.claude_jobs
  SET status = 'ready', result = p_result, finished_at = now(), error = NULL
  WHERE id = p_job_id AND status = 'running'
  RETURNING true;
$function$;
CREATE OR REPLACE FUNCTION public.claude_job_fail(p_job_id uuid, p_error text)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  UPDATE public.claude_jobs
  SET status = 'failed', error = left(coalesce(p_error, 'unknown'), 4000), finished_at = now()
  WHERE id = p_job_id AND status = 'running'
  RETURNING true;
$function$;
CREATE OR REPLACE FUNCTION public.claude_job_interrupt(p_job_id uuid, p_owner text, p_reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n int;
BEGIN
  UPDATE public.claude_jobs
     SET status='pending', claimed_by=NULL, started_at=NULL,
         error = coalesce(p_reason,'interrupted by runner shutdown')
   WHERE id = p_job_id AND status='running' AND claimed_by = p_owner;
  GET DIAGNOSTICS n = ROW_COUNT; RETURN n > 0;
END $function$;
CREATE OR REPLACE FUNCTION public.claude_jobs_recover_orphaned(p_owner text, p_min_age_seconds integer DEFAULT 180, p_max_attempts integer DEFAULT 3)
 RETURNS TABLE(job_id uuid, kind text, prior_owner text, action text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  WITH orphaned AS (
    SELECT j.id, j.kind AS j_kind, j.claimed_by, j.attempts
    FROM public.claude_jobs j
    WHERE j.status = 'running'
      AND j.claimed_by IS DISTINCT FROM p_owner
      AND j.started_at < now() - make_interval(secs => p_min_age_seconds)
      -- NEW: never touch a job whose claimer still holds a live lease. Another
      -- lane running its own work is not an orphan.
      AND NOT EXISTS (
        SELECT 1 FROM public.claude_runner_lease l
        WHERE l.owner_id = j.claimed_by
          AND l.released_at IS NULL
          AND l.expires_at > now()
      )
    FOR UPDATE
  ),
  requeued AS (
    UPDATE public.claude_jobs j
    SET status = 'pending', claimed_by = NULL, started_at = NULL,
        error = format('recovered: runner %s died mid-job (attempt %s)', o.claimed_by, o.attempts)
    FROM orphaned o
    WHERE j.id = o.id AND o.attempts < p_max_attempts
    RETURNING j.id, o.j_kind, o.claimed_by, 'requeued'::text AS act
  ),
  failed AS (
    UPDATE public.claude_jobs j
    SET status = 'failed', finished_at = now(),
        error = format('recovered: runner %s died mid-job %s times — not retried', o.claimed_by, o.attempts)
    FROM orphaned o
    WHERE j.id = o.id AND o.attempts >= p_max_attempts
    RETURNING j.id, o.j_kind, o.claimed_by, 'failed'::text AS act
  )
  SELECT r.id, r.j_kind, r.claimed_by, r.act FROM requeued r
  UNION ALL
  SELECT f.id, f.j_kind, f.claimed_by, f.act FROM failed f;
END;
$function$;
CREATE OR REPLACE FUNCTION public.claude_jobs_unblock()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n int;
BEGIN
  UPDATE public.claude_jobs SET status='pending', error=NULL WHERE status='blocked_subscription_limit';
  GET DIAGNOSTICS n = ROW_COUNT; RETURN n;
END $function$;
CREATE OR REPLACE FUNCTION public.claude_jobs_watchdog()
 RETURNS integer
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH swept AS (
    UPDATE public.claude_jobs
    SET status = 'failed', error = 'watchdog: runner did not finish within 45 minutes',
        finished_at = now()
    WHERE status = 'running' AND started_at < now() - interval '45 minutes'
    RETURNING 1
  )
  SELECT count(*)::int FROM swept;
$function$;
CREATE OR REPLACE FUNCTION public.claude_runner_health(p_lease text DEFAULT 'marketing_intelligence'::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'checked_at', now(),
    'lease', (
      SELECT jsonb_build_object(
        'name', l.lease_name, 'owner_id', l.owner_id, 'host', l.host, 'pid', l.pid,
        'acquired_at', l.acquired_at, 'heartbeat_at', l.heartbeat_at,
        'expires_at', l.expires_at, 'released_at', l.released_at,
        'is_live', (l.released_at IS NULL AND l.expires_at > now()),
        'heartbeat_age_seconds', EXTRACT(EPOCH FROM (now() - l.heartbeat_at))::int
      )
      FROM public.claude_runner_lease l WHERE l.lease_name = p_lease
    ),
    'leases', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'name', l.lease_name, 'owner_id', l.owner_id, 'host', l.host, 'pid', l.pid,
        'acquired_at', l.acquired_at, 'heartbeat_at', l.heartbeat_at,
        'expires_at', l.expires_at, 'released_at', l.released_at,
        'is_live', (l.released_at IS NULL AND l.expires_at > now()),
        'heartbeat_age_seconds', EXTRACT(EPOCH FROM (now() - l.heartbeat_at))::int
      ) ORDER BY l.lease_name), '[]'::jsonb)
      FROM public.claude_runner_lease l
    ),
    'queue', (
      SELECT coalesce(jsonb_object_agg(s.status, s.n), '{}'::jsonb)
      FROM (SELECT status, count(*)::int AS n FROM public.claude_jobs GROUP BY status) s
    ),
    'oldest_pending_age_seconds', (
      SELECT EXTRACT(EPOCH FROM (now() - min(created_at)))::int
      FROM public.claude_jobs WHERE status = 'pending'
    ),
    'current_job', (
      SELECT jsonb_build_object(
        'id', j.id, 'kind', j.kind, 'started_at', j.started_at,
        'claimed_by', j.claimed_by, 'attempts', j.attempts,
        'running_seconds', EXTRACT(EPOCH FROM (now() - j.started_at))::int
      )
      FROM public.claude_jobs j WHERE j.status = 'running'
      ORDER BY j.started_at LIMIT 1
    ),
    'running_jobs', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id', j.id, 'kind', j.kind, 'started_at', j.started_at,
        'claimed_by', j.claimed_by,
        'running_seconds', EXTRACT(EPOCH FROM (now() - j.started_at))::int
      ) ORDER BY j.started_at), '[]'::jsonb)
      FROM public.claude_jobs j WHERE j.status = 'running'
    ),
    'failures_24h', (
      SELECT coalesce(jsonb_agg(f), '[]'::jsonb) FROM (
        SELECT kind, count(*)::int AS n,
               left(coalesce((array_agg(error ORDER BY finished_at DESC))[1], ''), 200) AS last_error
        FROM public.claude_jobs
        WHERE status = 'failed' AND finished_at > now() - interval '24 hours'
        GROUP BY kind
      ) f
    ),
    'blocked_count', (
      SELECT count(*)::int FROM public.claude_jobs
      WHERE status = 'failed' AND error ILIKE '%limit%' AND finished_at > now() - interval '24 hours'
    ),
    'last_completed_at', (
      SELECT max(finished_at) FROM public.claude_jobs WHERE status = 'ready'
    ),
    'awaiting_intelligence_posts', (
      SELECT count(*)::int FROM public.mkt_content_posts
      WHERE processing_status = 'awaiting_intelligence'
    )
  );
$function$;
CREATE OR REPLACE FUNCTION public.claude_runner_lease_acquire(p_lease text, p_owner text, p_host text, p_pid integer, p_ttl_seconds integer DEFAULT 120)
 RETURNS TABLE(acquired boolean, current_owner text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.claude_runner_lease;
BEGIN
  INSERT INTO public.claude_runner_lease AS l (lease_name, owner_id, host, pid, acquired_at, heartbeat_at, expires_at, released_at)
  VALUES (p_lease, p_owner, p_host, p_pid, now(), now(), now() + make_interval(secs => p_ttl_seconds), NULL)
  ON CONFLICT (lease_name) DO UPDATE
    SET owner_id = p_owner, host = p_host, pid = p_pid,
        acquired_at = CASE WHEN l.owner_id = p_owner THEN l.acquired_at ELSE now() END,
        heartbeat_at = now(),
        expires_at = now() + make_interval(secs => p_ttl_seconds),
        released_at = NULL
    -- only the CURRENT owner may renew; anyone else may take over only after expiry
    -- (or after an explicit release).
    WHERE l.owner_id = p_owner OR l.expires_at < now() OR l.released_at IS NOT NULL
  RETURNING * INTO v_row;

  IF v_row.lease_name IS NOT NULL THEN
    RETURN QUERY SELECT true, v_row.owner_id, v_row.expires_at; RETURN;
  END IF;
  -- conflict target matched but the WHERE blocked the update → someone else owns it
  SELECT * INTO v_row FROM public.claude_runner_lease WHERE lease_name = p_lease;
  RETURN QUERY SELECT false, v_row.owner_id, v_row.expires_at;
END $function$;
CREATE OR REPLACE FUNCTION public.claude_runner_lease_release(p_lease text, p_owner text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n int;
BEGIN
  UPDATE public.claude_runner_lease
     SET released_at = now(), expires_at = now()
   WHERE lease_name = p_lease AND owner_id = p_owner;
  GET DIAGNOSTICS n = ROW_COUNT; RETURN n > 0;
END $function$;
CREATE OR REPLACE FUNCTION public.claude_runner_lease_status(p_lease text DEFAULT 'marketing_intelligence'::text)
 RETURNS TABLE(lease_name text, owner_id text, host text, pid integer, acquired_at timestamp with time zone, heartbeat_at timestamp with time zone, expires_at timestamp with time zone, is_live boolean, heartbeat_age_seconds integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT l.lease_name, l.owner_id, l.host, l.pid, l.acquired_at, l.heartbeat_at, l.expires_at,
         (l.released_at IS NULL AND l.expires_at > now()) AS is_live,
         EXTRACT(EPOCH FROM (now() - l.heartbeat_at))::int AS heartbeat_age_seconds
  FROM public.claude_runner_lease l WHERE l.lease_name = p_lease;
$function$;
CREATE OR REPLACE FUNCTION public.claude_runner_sql(p_sql text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb;
BEGIN
  PERFORM set_config('transaction_read_only', 'on', true);
  PERFORM set_config('statement_timeout', '30000', true);
  EXECUTE format('SELECT COALESCE(jsonb_agg(t), ''[]''::jsonb) FROM (%s) t', p_sql) INTO v;
  RETURN v;
END;
$function$;
CREATE OR REPLACE FUNCTION public.clean_text_entry_patch(p_record_id uuid, p_entry_id text, p_patch jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_rows int;
BEGIN
  IF p_patch IS NULL OR jsonb_typeof(p_patch) <> 'object' THEN
    RAISE EXCEPTION 'clean_text_entry_patch: p_patch must be a jsonb object';
  END IF;

  UPDATE public.records r
  SET data = (
        SELECT jsonb_set(r.data, ARRAY['cleaning', (t.idx - 1)::text], t.elem || p_patch)
        FROM jsonb_array_elements(r.data->'cleaning') WITH ORDINALITY AS t(elem, idx)
        WHERE t.elem->>'id' = p_entry_id
        LIMIT 1
      ),
      updated_at = now()
  WHERE r.id = p_record_id
    AND jsonb_typeof(r.data->'cleaning') = 'array'
    AND EXISTS (
      SELECT 1 FROM jsonb_array_elements(r.data->'cleaning') AS e(elem)
      WHERE e.elem->>'id' = p_entry_id
    );

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN
    RAISE EXCEPTION 'clean_text_entry_patch: cleaning entry % not present on record % - draft deleted or entry removed',
      p_entry_id, p_record_id;
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.conflict_storm_candidates(p_version integer)
 RETURNS TABLE(record_id uuid, model_id uuid, model_name text, version integer, updated_at timestamp with time zone, stale interval)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
  SELECT r.id, r.model_id, m.name, r.version, r.updated_at, now() - r.updated_at
  FROM public.records r
  LEFT JOIN public.models m ON m.id = r.model_id
  WHERE r.version = p_version
  ORDER BY r.updated_at ASC;
$function$;
CREATE OR REPLACE FUNCTION public.conflict_storm_sweep()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_rollbacks      bigint;
  v_prev_rollbacks bigint;
  v_prev_at        timestamptz;
  v_secs           numeric;
  v_rate           numeric := 0;
  v_aborted        int;
  v_active         int;
  v_recent         timestamptz;
  v_alert          bigint;
  v_storm          boolean := false;
  v_offenders      jsonb;
  v_storm_minutes  numeric;
  c_threshold      numeric := 75;
BEGIN
  SELECT sum(xact_rollback) INTO v_rollbacks
  FROM pg_stat_database WHERE datname = current_database();

  SELECT last_rollbacks, last_at INTO v_prev_rollbacks, v_prev_at
  FROM public.conflict_sweep_state WHERE id;

  IF v_prev_rollbacks IS NOT NULL THEN
    v_secs := greatest(extract(epoch FROM (now() - v_prev_at)), 1);
    v_rate := greatest(v_rollbacks - v_prev_rollbacks, 0) / v_secs;
  END IF;

  INSERT INTO public.conflict_sweep_state (id, last_rollbacks, last_at)
  VALUES (true, v_rollbacks, now())
  ON CONFLICT (id) DO UPDATE
    SET last_rollbacks = EXCLUDED.last_rollbacks, last_at = EXCLUDED.last_at;

  SELECT
    count(*) FILTER (WHERE state = 'idle in transaction (aborted)'),
    count(*) FILTER (WHERE state = 'active')
  INTO v_aborted, v_active
  FROM pg_stat_activity
  WHERE backend_type = 'client backend'
    AND query ILIKE '%p_expected_version%';

  v_storm := v_prev_rollbacks IS NOT NULL AND v_rate >= c_threshold;

  BEGIN
    INSERT INTO public.conflict_rate_samples (sampled_at, rollback_rate, aborted, active, storm)
    VALUES (now(), round(v_rate, 1), v_aborted, v_active, v_storm);
    DELETE FROM public.conflict_rate_samples       WHERE sampled_at   < now() - interval '30 days';
    DELETE FROM public.conflict_telemetry_buckets  WHERE bucket_start < now() - interval '14 days';
  EXCEPTION WHEN others THEN
    RAISE WARNING 'conflict_storm_sweep telemetry persist/prune failed (non-fatal): % %', SQLSTATE, SQLERRM;
  END;

  IF NOT v_storm THEN
    RETURN jsonb_build_object('storm', false, 'rollback_rate', round(v_rate, 1),
                              'aborted', coalesce(v_aborted, 0), 'active', coalesce(v_active, 0));
  END IF;

  SELECT coalesce(jsonb_agg(o), '[]'::jsonb) INTO v_offenders
  FROM (
    SELECT service, session_id, tab_id, build_id, record_id, model_id, reject_reason,
           sum(count) AS conflicts
    FROM public.conflict_telemetry_buckets
    WHERE bucket_start >= now() - interval '60 seconds'
    GROUP BY 1,2,3,4,5,6,7
    ORDER BY conflicts DESC LIMIT 5
  ) o;

  SELECT round(extract(epoch FROM (now() - max(sampled_at))) / 60, 1) INTO v_storm_minutes
  FROM public.conflict_rate_samples WHERE NOT storm;

  SELECT max(created_at) INTO v_recent
  FROM public.system_alerts
  WHERE kind = 'conflict_storm'
    AND created_at > now() - CASE WHEN coalesce(v_storm_minutes, 0) > 60
                                  THEN interval '60 minutes'
                                  ELSE interval '10 minutes' END;

  IF v_recent IS NULL THEN
    INSERT INTO public.system_alerts (kind, severity, detail)
    VALUES ('conflict_storm', 'critical', jsonb_build_object(
      'rollback_rate_per_sec', round(v_rate, 1),
      'storm_run_minutes', v_storm_minutes,
      'aborted_record_save_backends', v_aborted,
      'active_record_save_backends', v_active,
      'top_offenders', v_offenders,
      'runbook',
        'record_save version-conflict storm. top_offenders (above) names cooperating clients; if EMPTY the ' ||
        'offender is a non-reporting client (old bundle / server loop) — the Postgres logs may lag HOURS under ' ||
        'flood, so identify the hot record live instead: sample pg_locks (locktype=''tuple'', relation=records) ' ||
        'and map page/tuple via ctid, or check pg_stat_statements deltas. Then: ' ||
        'SELECT public.block_conflict_storm_record(''<record-id>'', 15); (terminal reject) — or for a DEAD record ' ||
        'INSERT a record_save_blocks row with mode=''noop'' (instant success breaks any retry loop; NEVER noop a ' ||
        'record still receiving legitimate edits). If one tab is the source, also revoke that user''s auth session.'
    ))
    RETURNING id INTO v_alert;
  END IF;

  RETURN jsonb_build_object('storm', true, 'rollback_rate', round(v_rate, 1),
                            'storm_run_minutes', v_storm_minutes,
                            'aborted', coalesce(v_aborted, 0), 'active', coalesce(v_active, 0),
                            'top_offenders', v_offenders,
                            'alert_id', v_alert);
END;
$function$;
CREATE OR REPLACE FUNCTION public.data_migration_job_cancel(p_record_id uuid)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  WITH updated AS (
    UPDATE public.data_migration_jobs
       SET status      = 'cancelled',
           finished_at = now()
     WHERE migration_record_id = p_record_id
       AND status IN ('queued','running')
    RETURNING 1
  )
  SELECT EXISTS (SELECT 1 FROM updated);
$function$;
CREATE OR REPLACE FUNCTION public.data_migration_job_claim_next(p_worker_id text)
 RETURNS TABLE(job_id uuid, migration_record_id uuid, user_id uuid, kind text, payload jsonb, attempts integer)
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  UPDATE public.data_migration_jobs
     SET status     = 'running',
         worker_id  = p_worker_id,
         started_at = now(),
         attempts   = data_migration_jobs.attempts + 1
   WHERE id = (
     SELECT id
       FROM public.data_migration_jobs
      WHERE status = 'queued'
      ORDER BY created_at
      FOR UPDATE SKIP LOCKED
      LIMIT 1
   )
   RETURNING id, migration_record_id, user_id, kind, payload, attempts;
$function$;
CREATE OR REPLACE FUNCTION public.data_migration_job_complete(p_job_id uuid, p_result jsonb DEFAULT NULL::jsonb)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  WITH updated AS (
    UPDATE public.data_migration_jobs
       SET status        = 'done',
           finished_at   = now(),
           result        = p_result,
           error_message = NULL
     WHERE id = p_job_id
       AND status = 'running'
    RETURNING 1
  )
  SELECT EXISTS (SELECT 1 FROM updated);
$function$;
CREATE OR REPLACE FUNCTION public.data_migration_job_enqueue(p_record_id uuid, p_user_id uuid, p_kind text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  INSERT INTO public.data_migration_jobs (migration_record_id, user_id, kind, payload)
  VALUES (p_record_id, p_user_id, p_kind, COALESCE(p_payload, '{}'::jsonb))
  ON CONFLICT (migration_record_id) WHERE status IN ('queued','running') DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    SELECT id INTO v_id
      FROM public.data_migration_jobs
     WHERE migration_record_id = p_record_id
       AND status IN ('queued','running')
     ORDER BY created_at DESC
     LIMIT 1;
  END IF;

  RETURN v_id;
END $function$;
CREATE OR REPLACE FUNCTION public.data_migration_job_fail(p_job_id uuid, p_error text)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  WITH updated AS (
    UPDATE public.data_migration_jobs
       SET status        = 'failed',
           finished_at   = now(),
           error_message = p_error
     WHERE id = p_job_id
       AND status = 'running'
    RETURNING 1
  )
  SELECT EXISTS (SELECT 1 FROM updated);
$function$;
CREATE OR REPLACE FUNCTION public.data_migration_jobs_watchdog()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_count   int := 0;
  v_tmp     int := 0;
  v_orphans int := 0;
  v_dm_model uuid;
  c_orphan_grace interval := interval '30 minutes';
  v_msg   text := 'The migration worker did not finish within 45 minutes — it likely crashed mid-run. Press Retry to try again.';
  v_orphan_msg text := 'No active migration job was found while this record was still busy — the worker crashed or a tab closed mid-run. Cleaned up by the watchdog; press Retry to run again.';
BEGIN
  -- Phase 1 (UNCHANGED): jobs stuck 'running' > 45 min
  CREATE TEMP TABLE _stale_dmj ON COMMIT DROP AS
    SELECT id, migration_record_id, kind
      FROM public.data_migration_jobs
     WHERE status = 'running'
       AND started_at < now() - interval '45 minutes';

  UPDATE public.data_migration_jobs j
     SET status = 'failed', finished_at = now(), error_message = v_msg
    FROM _stale_dmj s
   WHERE j.id = s.id;

  UPDATE public.records r
     SET data = r.data || jsonb_build_object('status','failed','error_message',v_msg,'phase',NULL),
         updated_at = now()
    FROM _stale_dmj s
   WHERE r.id = s.migration_record_id
     AND s.kind = 'extract'
     AND COALESCE(r.data->>'status','') = 'extracting';

  UPDATE public.records r
     SET data = r.data || jsonb_build_object('prep_busy',false,'error_message',v_msg),
         updated_at = now()
    FROM _stale_dmj s
   WHERE r.id = s.migration_record_id
     AND s.kind = 'plan'
     AND COALESCE((r.data->>'prep_busy')::boolean, false) = true;

  UPDATE public.records r
     SET data = r.data || jsonb_build_object('discuss_busy',false,'error_message',v_msg),
         updated_at = now()
    FROM _stale_dmj s
   WHERE r.id = s.migration_record_id
     AND s.kind = 'discuss'
     AND COALESCE((r.data->>'discuss_busy')::boolean, false) = true;

  SELECT COUNT(*) INTO v_count FROM _stale_dmj;

  -- Phase 2 (T7): records stuck BUSY with NO active job
  SELECT id INTO v_dm_model FROM public.models WHERE name = 'data_migration' LIMIT 1;

  UPDATE public.records r
     SET data = r.data || jsonb_build_object(
                  'status','failed', 'error_message',v_orphan_msg, 'phase',NULL,
                  'prep_busy',false, 'discuss_busy',false),
         updated_at = now()
   WHERE r.model_id = v_dm_model
     AND COALESCE(r.data->>'status','') IN ('extracting','migrating')
     AND r.updated_at < now() - c_orphan_grace
     AND NOT EXISTS (SELECT 1 FROM public.data_migration_jobs j
                      WHERE j.migration_record_id = r.id AND j.status IN ('queued','running'));
  GET DIAGNOSTICS v_tmp = ROW_COUNT;  v_orphans := v_orphans + v_tmp;

  UPDATE public.records r
     SET data = r.data || jsonb_build_object('prep_busy',false,'error_message',v_orphan_msg),
         updated_at = now()
   WHERE r.model_id = v_dm_model
     AND COALESCE((r.data->>'prep_busy')::boolean, false) = true
     AND COALESCE(r.data->>'status','') NOT IN ('extracting','migrating')
     AND r.updated_at < now() - c_orphan_grace
     AND NOT EXISTS (SELECT 1 FROM public.data_migration_jobs j
                      WHERE j.migration_record_id = r.id AND j.status IN ('queued','running'));
  GET DIAGNOSTICS v_tmp = ROW_COUNT;  v_orphans := v_orphans + v_tmp;

  UPDATE public.records r
     SET data = r.data || jsonb_build_object('discuss_busy',false,'error_message',v_orphan_msg),
         updated_at = now()
   WHERE r.model_id = v_dm_model
     AND COALESCE((r.data->>'discuss_busy')::boolean, false) = true
     AND COALESCE(r.data->>'status','') NOT IN ('extracting','migrating')
     AND r.updated_at < now() - c_orphan_grace
     AND NOT EXISTS (SELECT 1 FROM public.data_migration_jobs j
                      WHERE j.migration_record_id = r.id AND j.status IN ('queued','running'));
  GET DIAGNOSTICS v_tmp = ROW_COUNT;  v_orphans := v_orphans + v_tmp;

  RETURN v_count + v_orphans;
END $function$;
CREATE OR REPLACE FUNCTION public.deck_job_claim_next(p_worker_id text)
 RETURNS TABLE(job_id uuid, deck_record_id uuid, user_id uuid, payload jsonb, attempts integer)
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  UPDATE public.deck_jobs
     SET status     = 'running',
         worker_id  = p_worker_id,
         started_at = now(),
         attempts   = deck_jobs.attempts + 1
   WHERE id = (
     SELECT id
       FROM public.deck_jobs
      WHERE status = 'pending'
      ORDER BY created_at
      FOR UPDATE SKIP LOCKED
      LIMIT 1
   )
   RETURNING id, deck_record_id, user_id, payload, attempts;
$function$;
CREATE OR REPLACE FUNCTION public.deck_job_complete(p_job_id uuid)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  WITH updated AS (
    UPDATE public.deck_jobs
       SET status       = 'done',
           completed_at = now(),
           error        = NULL
     WHERE id = p_job_id
       AND status = 'running'
    RETURNING 1
  )
  SELECT EXISTS (SELECT 1 FROM updated);
$function$;
CREATE OR REPLACE FUNCTION public.deck_job_fail(p_job_id uuid, p_error text)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  WITH updated AS (
    UPDATE public.deck_jobs
       SET status       = 'failed',
           completed_at = now(),
           error        = p_error
     WHERE id = p_job_id
       AND status = 'running'
    RETURNING 1
  )
  SELECT EXISTS (SELECT 1 FROM updated);
$function$;
CREATE OR REPLACE FUNCTION public.deck_jobs_notify_new()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  PERFORM pg_notify('deck_jobs_new', NEW.id::text);
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.deck_jobs_watchdog()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_count int := 0;
  v_msg   text := 'watchdog: worker did not finish within 20 minutes — likely crashed mid-run. Press Try again to retry.';
BEGIN
  WITH stale AS (
    UPDATE public.deck_jobs
       SET status       = 'failed',
           completed_at = now(),
           error        = v_msg
     WHERE status = 'running'
       AND started_at < now() - interval '20 minutes'
     RETURNING id, deck_record_id
  ),
  recs AS (
    UPDATE public.records r
       SET data = r.data || jsonb_build_object(
             'status', 'failed',
             'error_message', v_msg
           ),
           updated_at = now()
      FROM stale s
     WHERE r.id = s.deck_record_id
       AND COALESCE(r.data->>'status','') = 'generating'
  )
  SELECT COUNT(*) INTO v_count FROM stale;

  RETURN v_count;
END;
$function$;
CREATE OR REPLACE FUNCTION public.district_boundaries_for_city(p_city_id text)
 RETURNS TABLE(spl_district_id text, district_record_id uuid, geojson jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT b.spl_district_id, b.district_record_id, ST_AsGeoJSON(b.geom)::jsonb
  FROM public.district_boundaries b
  WHERE b.city_id = p_city_id AND b.is_active;
$function$;
CREATE OR REPLACE FUNCTION public.district_boundaries_in_bbox(p_min_lng double precision, p_min_lat double precision, p_max_lng double precision, p_max_lat double precision)
 RETURNS TABLE(spl_district_id text, district_record_id uuid, geojson jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT b.spl_district_id, b.district_record_id, ST_AsGeoJSON(b.geom)::jsonb
  FROM public.district_boundaries b
  WHERE b.is_active
    AND b.geom && ST_MakeEnvelope(p_min_lng, p_min_lat, p_max_lng, p_max_lat, 4326);
$function$;
CREATE OR REPLACE FUNCTION public.district_for_point(p_lat double precision, p_lng double precision)
 RETURNS TABLE(district_record_id uuid, spl_district_id text, city_id text, region_id text)
 LANGUAGE sql
 STABLE PARALLEL SAFE
AS $function$
  select b.district_record_id, b.spl_district_id, b.city_id, b.region_id
  from public.district_boundaries b
  where b.is_active
    and p_lat is not null
    and p_lng is not null
    and ST_Contains(b.geom, ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326))
  order by ST_Area(b.geom) asc
  limit 1
$function$;
CREATE OR REPLACE FUNCTION public.district_outline(p_district_id uuid, p_max_points integer DEFAULT 60)
 RETURNS TABLE(district_id uuid, name_ar text, points jsonb, center_lat double precision, center_lng double precision)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_geom geometry;
  v_tol  double precision := 0.0005;
  v_pts  jsonb;
  v_n    int;
BEGIN
  SELECT b.geom INTO v_geom
    FROM public.district_boundaries b
   WHERE b.district_record_id = p_district_id AND COALESCE(b.is_active, true)
   LIMIT 1;
  IF v_geom IS NULL THEN RETURN; END IF;

  FOR i IN 1..6 LOOP
    SELECT jsonb_agg(jsonb_build_array(
             round(ST_Y(d.geom)::numeric, 5), round(ST_X(d.geom)::numeric, 5)))
      INTO v_pts
      FROM ST_DumpPoints(ST_ExteriorRing(ST_ConvexHull(ST_SimplifyPreserveTopology(v_geom, v_tol)))) d;
    v_n := COALESCE(jsonb_array_length(v_pts), 0);
    EXIT WHEN v_n > 0 AND v_n <= p_max_points;
    v_tol := v_tol * 2;
  END LOOP;

  RETURN QUERY
  SELECT p_district_id,
         (SELECT COALESCE(r.data->>'display_name', r.data->>'name_ar')
            FROM public.unified_records r WHERE r.id = p_district_id),
         v_pts,
         ST_Y(ST_Centroid(v_geom))::double precision,
         ST_X(ST_Centroid(v_geom))::double precision;
END $function$;
CREATE OR REPLACE FUNCTION public.districts_for_points(p_points jsonb)
 RETURNS TABLE(id text, district_record_id uuid, spl_district_id text, city_id text, region_id text)
 LANGUAGE sql
 STABLE PARALLEL SAFE
AS $function$
  select
    pt.id,
    d.district_record_id,
    d.spl_district_id,
    d.city_id,
    d.region_id
  from jsonb_to_recordset(coalesce(p_points, '[]'::jsonb))
       as pt(id text, lat double precision, lng double precision)
  left join lateral (
    select b.district_record_id, b.spl_district_id, b.city_id, b.region_id
    from public.district_boundaries b
    where b.is_active
      and pt.lat is not null
      and pt.lng is not null
      and ST_Contains(b.geom, ST_SetSRID(ST_MakePoint(pt.lng, pt.lat), 4326))
    limit 1
  ) d on true
$function$;
CREATE OR REPLACE FUNCTION public.document_comments_guard_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.file_id <> OLD.file_id
     OR NEW.parent_id IS DISTINCT FROM OLD.parent_id
     OR NEW.author_id <> OLD.author_id
     OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'document_comments: file_id/parent_id/author_id/created_at are immutable';
  END IF;
  IF NEW.body <> OLD.body
     AND public.wassell_app_user_id((SELECT auth.uid())) IS DISTINCT FROM OLD.author_id THEN
    RAISE EXCEPTION 'document_comments: only the author may edit a comment body';
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.document_comments_validate_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  parent_file uuid;
  parent_parent uuid;
BEGIN
  IF NEW.parent_id IS NOT NULL THEN
    SELECT file_id, parent_id INTO parent_file, parent_parent
      FROM public.document_comments WHERE id = NEW.parent_id;
    IF parent_file IS NULL THEN
      RAISE EXCEPTION 'document_comments: parent % not found', NEW.parent_id;
    END IF;
    IF parent_file <> NEW.file_id THEN
      RAISE EXCEPTION 'document_comments: reply file_id must match parent';
    END IF;
    IF parent_parent IS NOT NULL THEN
      RAISE EXCEPTION 'document_comments: replies cannot nest (parent is itself a reply)';
    END IF;
    NEW.anchor_text := NULL;
    NEW.resolved := false;
    NEW.resolved_by_user_id := NULL;
    NEW.resolved_at := NULL;
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.document_job_claim_next(p_worker_id text)
 RETURNS TABLE(job_id uuid, source_record_id uuid, source_model_id uuid, template_id uuid, template_file_id uuid, target_folder_id uuid, owner_user_id uuid, owner_auth_uid uuid, client_record_id uuid, unit_record_id uuid, project_record_id uuid, attempts integer, template_label_ar text, template_label_en text, content_json jsonb, settings jsonb)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH claimed AS (
    UPDATE public.document_jobs j
       SET status     = 'running',
           worker_id  = p_worker_id,
           started_at = now(),
           attempts   = j.attempts + 1
     WHERE j.id = (
       SELECT id FROM public.document_jobs
        WHERE status = 'queued'
        ORDER BY created_at
        FOR UPDATE SKIP LOCKED
        LIMIT 1
     )
     RETURNING j.id, j.source_record_id, j.source_model_id, j.template_id,
               j.template_file_id, j.target_folder_id, j.owner_user_id,
               j.owner_auth_uid, j.client_record_id, j.unit_record_id,
               j.project_record_id, j.attempts
  )
  SELECT c.id, c.source_record_id, c.source_model_id, c.template_id,
         c.template_file_id, c.target_folder_id, c.owner_user_id,
         c.owner_auth_uid, c.client_record_id, c.unit_record_id,
         c.project_record_id, c.attempts,
         dt.label_ar, dt.label_en,
         wd.content_json, wd.settings
    FROM claimed c
    JOIN public.document_templates dt ON dt.id = c.template_id
    JOIN public.wassel_documents   wd ON wd.file_id = dt.file_id;
$function$;
CREATE OR REPLACE FUNCTION public.document_job_complete(p_job_id uuid, p_result_file_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  UPDATE public.document_jobs
     SET status = 'completed', finished_at = now(), error = NULL, result_file_id = p_result_file_id
   WHERE id = p_job_id AND status = 'running'
  RETURNING id INTO v_id;
  RETURN v_id IS NOT NULL;
END $function$;
CREATE OR REPLACE FUNCTION public.document_job_enqueue(p_source_record_id uuid, p_source_model_id uuid, p_template_id uuid, p_template_file_id uuid, p_target_folder_id uuid, p_owner_user_id uuid, p_owner_auth_uid uuid, p_client_record_id uuid, p_unit_record_id uuid, p_project_record_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  INSERT INTO public.document_jobs (
    source_record_id, source_model_id, template_id, template_file_id,
    target_folder_id, owner_user_id, owner_auth_uid,
    client_record_id, unit_record_id, project_record_id
  )
  VALUES (
    p_source_record_id, p_source_model_id, p_template_id, p_template_file_id,
    p_target_folder_id, p_owner_user_id, p_owner_auth_uid,
    p_client_record_id, p_unit_record_id, p_project_record_id
  )
  ON CONFLICT (source_record_id, template_id) WHERE status IN ('queued','running') DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    SELECT id INTO v_id
      FROM public.document_jobs
     WHERE source_record_id = p_source_record_id
       AND template_id = p_template_id
       AND status IN ('queued','running')
     ORDER BY created_at DESC
     LIMIT 1;
  END IF;

  RETURN v_id;
END $function$;
CREATE OR REPLACE FUNCTION public.document_job_fail(p_job_id uuid, p_error text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  UPDATE public.document_jobs
     SET status = 'failed', finished_at = now(), error = p_error
   WHERE id = p_job_id AND status = 'running'
  RETURNING id INTO v_id;
  RETURN v_id IS NOT NULL;
END $function$;
CREATE OR REPLACE FUNCTION public.document_jobs_watchdog()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_count int := 0;
BEGIN
  WITH stale AS (
    UPDATE public.document_jobs
       SET status = 'failed', finished_at = now(),
           error = 'watchdog: generation did not finish within 10 minutes — likely crashed mid-run.'
     WHERE status = 'running' AND started_at < now() - interval '10 minutes'
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_count FROM stale;
  RETURN v_count;
END $function$;
CREATE OR REPLACE FUNCTION public.drop_model_view(p_model_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_view_name text;
BEGIN
  IF p_model_name IS NULL OR p_model_name = '' THEN RETURN; END IF;
  v_view_name := 'v_' || p_model_name;
  EXECUTE format('DROP VIEW IF EXISTS public.%I', v_view_name);
END;
$function$;
CREATE OR REPLACE FUNCTION public.file_preview_claim_next(p_worker_id text)
 RETURNS TABLE(job_id uuid, file_id uuid, attempts integer, storage_bucket text, storage_path text, mime_type text, size_bytes bigint, original_name text)
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  WITH claimed AS (
    UPDATE public.file_preview_jobs j
       SET status     = 'running',
           worker_id  = p_worker_id,
           started_at = now(),
           attempts   = j.attempts + 1
     WHERE j.id = (
       SELECT id FROM public.file_preview_jobs
        WHERE status = 'queued'
        ORDER BY created_at
        FOR UPDATE SKIP LOCKED
        LIMIT 1
     )
     RETURNING j.id, j.file_id, j.attempts
  )
  SELECT c.id, c.file_id, c.attempts,
         f.storage_bucket, f.storage_path, f.mime_type, f.size_bytes, f.original_name
    FROM claimed c
    JOIN public.files f ON f.id = c.file_id;
$function$;
CREATE OR REPLACE FUNCTION public.file_preview_complete(p_job_id uuid, p_preview_path text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_file uuid;
BEGIN
  UPDATE public.file_preview_jobs
     SET status = 'completed', finished_at = now(), error = NULL
   WHERE id = p_job_id AND status = 'running'
  RETURNING file_id INTO v_file;
  IF v_file IS NULL THEN RETURN false; END IF;

  UPDATE public.files
     SET preview_status = 'ready',
         preview_storage_path = p_preview_path,
         preview_generated_at = now(),
         preview_error = NULL
   WHERE id = v_file;
  RETURN true;
END $function$;
CREATE OR REPLACE FUNCTION public.file_preview_enqueue(p_file_id uuid, p_force boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  f public.files%ROWTYPE;
BEGIN
  SELECT * INTO f FROM public.files WHERE id = p_file_id FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;

  IF f.preview_status = 'ready' AND f.preview_storage_path IS NOT NULL THEN
    RETURN 'ready';
  END IF;
  IF f.preview_status = 'failed' AND NOT p_force THEN
    RETURN 'failed';
  END IF;

  INSERT INTO public.file_preview_jobs (file_id)
  VALUES (p_file_id)
  ON CONFLICT (file_id) WHERE status IN ('queued','running') DO NOTHING;

  UPDATE public.files
     SET preview_status = 'pending', preview_error = NULL
   WHERE id = p_file_id;

  RETURN 'pending';
END $function$;
CREATE OR REPLACE FUNCTION public.file_preview_fail(p_job_id uuid, p_error text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_file uuid;
BEGIN
  UPDATE public.file_preview_jobs
     SET status = 'failed', finished_at = now(), error = p_error
   WHERE id = p_job_id AND status = 'running'
  RETURNING file_id INTO v_file;
  IF v_file IS NULL THEN RETURN false; END IF;

  UPDATE public.files
     SET preview_status = 'failed', preview_error = p_error
   WHERE id = v_file
     AND preview_status IS DISTINCT FROM 'ready';
  RETURN true;
END $function$;
CREATE OR REPLACE FUNCTION public.file_preview_watchdog()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_count int := 0;
  v_msg   text := 'watchdog: preview conversion did not finish within 10 minutes — likely crashed mid-run.';
BEGIN
  WITH stale AS (
    UPDATE public.file_preview_jobs
       SET status = 'failed', finished_at = now(), error = v_msg
     WHERE status = 'running'
       AND started_at < now() - interval '10 minutes'
    RETURNING file_id
  ),
  flipped AS (
    UPDATE public.files f
       SET preview_status = 'failed', preview_error = v_msg
      FROM stale s
     WHERE f.id = s.file_id
       AND f.preview_status IS DISTINCT FROM 'ready'
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_count FROM stale;
  RETURN v_count;
END $function$;
CREATE OR REPLACE FUNCTION public.fill_market_listing_extras_signals()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  patch jsonb;
BEGIN
  IF jsonb_typeof(NEW.data->'scraped_extras') = 'array' THEN
    SELECT jsonb_strip_nulls(jsonb_build_object(
      'views_count',  max(CASE WHEN e->>'raw_label' = 'المشاهدات'
                                AND e->>'details' ~ '^[0-9]+$'
                               THEN (e->>'details')::numeric END),
      'deed_number',  max(CASE WHEN e->>'raw_label' = 'رقم الصك'
                                AND coalesce(e->>'details', '') <> ''
                               THEN e->>'details' END),
      'street_width', max(CASE WHEN e->>'raw_label' = 'عرض الشارع'
                                AND e->>'details' ~ '^[0-9]+(\.[0-9]+)?$'
                               THEN (e->>'details')::numeric END)
    ))
    INTO patch
    FROM jsonb_array_elements(NEW.data->'scraped_extras') e;

    NEW.data := NEW.data || coalesce(patch, '{}'::jsonb);
  END IF;

  NEW.data := NEW.data || public.market_listing_quality(NEW.data);
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.fill_market_listing_property_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
  NEW.data := NEW.data || public.market_listing_property_identity(NEW.data);
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.fin_can_access_scenario(p_scenario_id uuid, p_auth_uid uuid DEFAULT auth.uid())
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.fin_scenarios s
    WHERE s.id = p_scenario_id
      AND s.deleted_at IS NULL
      AND (
        public.wassell_is_admin(p_auth_uid)
        OR s.owner_user_id = public.wassell_app_user_id(p_auth_uid)
        OR s.assigned_specialist_user_id = public.wassell_app_user_id(p_auth_uid)
        OR s.created_by_user_id = public.wassell_app_user_id(p_auth_uid)
      )
  );
$function$;
CREATE OR REPLACE FUNCTION public.fin_product_version_at(p_product_id uuid, p_as_of date DEFAULT CURRENT_DATE)
 RETURNS fin_product_versions
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT v.* FROM public.fin_product_versions v
  WHERE v.product_id = p_product_id AND v.is_active
    AND v.effective_from <= p_as_of
    AND (v.effective_to IS NULL OR v.effective_to > p_as_of)
  ORDER BY v.effective_from DESC, v.version_number DESC
  LIMIT 1;
$function$;
CREATE OR REPLACE FUNCTION public.fin_rate_version_at(p_product_id uuid, p_as_of date DEFAULT CURRENT_DATE)
 RETURNS fin_product_rate_versions
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT v.* FROM public.fin_product_rate_versions v
  WHERE v.product_id = p_product_id AND v.is_active
    AND v.effective_from <= p_as_of
    AND (v.effective_to IS NULL OR v.effective_to > p_as_of)
    AND (v.campaign_end_date IS NULL OR v.campaign_end_date >= p_as_of)
  ORDER BY v.effective_from DESC, v.version_number DESC
  LIMIT 1;
$function$;
CREATE OR REPLACE FUNCTION public.fin_rule_version_at(p_rule_key text, p_as_of date DEFAULT CURRENT_DATE)
 RETURNS fin_regulatory_rule_versions
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT v.*
  FROM public.fin_regulatory_rule_versions v
  JOIN public.fin_regulatory_rules r ON r.id = v.rule_id
  WHERE r.rule_key = p_rule_key
    AND r.is_active
    AND v.is_active
    AND v.effective_from <= p_as_of
    AND (v.effective_to IS NULL OR v.effective_to > p_as_of)
  ORDER BY v.effective_from DESC, v.version_number DESC
  LIMIT 1;
$function$;
CREATE OR REPLACE FUNCTION public.fin_tg_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_scenario_id uuid;
  v_parent_exists boolean;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION '% is append-only (attempted UPDATE) — create a new row instead of rewriting history', TG_TABLE_NAME
      USING ERRCODE = 'check_violation';
  END IF;

  -- DELETE path. fin_cash_flows reaches its scenario through the run.
  IF TG_TABLE_NAME = 'fin_cash_flows' THEN
    SELECT r.scenario_id INTO v_scenario_id
    FROM public.fin_calculation_runs r WHERE r.id = OLD.run_id;
    -- The run is already gone => the cascade is underway.
    IF v_scenario_id IS NULL THEN RETURN OLD; END IF;
  ELSE
    v_scenario_id := OLD.scenario_id;
  END IF;

  IF v_scenario_id IS NULL THEN RETURN OLD; END IF;

  SELECT EXISTS (SELECT 1 FROM public.fin_scenarios s WHERE s.id = v_scenario_id)
    INTO v_parent_exists;

  IF v_parent_exists THEN
    RAISE EXCEPTION '% is append-only — a single row cannot be deleted from a live scenario''s history (delete the whole scenario instead)', TG_TABLE_NAME
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN OLD;
END $function$;
CREATE OR REPLACE FUNCTION public.fin_tg_observation_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  RAISE EXCEPTION 'benchmark observations are immutable (attempted % on %)', TG_OP, OLD.id
    USING ERRCODE = 'check_violation';
END $function$;
CREATE OR REPLACE FUNCTION public.fin_tg_run_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.run_number IS NULL OR NEW.run_number = 0 THEN
    SELECT COALESCE(MAX(run_number), 0) + 1 INTO NEW.run_number
    FROM public.fin_calculation_runs WHERE scenario_id = NEW.scenario_id;
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.fin_tg_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN NEW.updated_at := now(); RETURN NEW; END $function$;
CREATE OR REPLACE FUNCTION public.fin_tg_version_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'financing version rows are append-only - retire the version (effective_to / is_active) instead of deleting %', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.effective_from IS DISTINCT FROM OLD.effective_from THEN
    RAISE EXCEPTION 'effective_from is immutable on financing version % - create a new version', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.source_id IS DISTINCT FROM OLD.source_id THEN
    RAISE EXCEPTION 'source_id is immutable on financing version % - create a new version', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.financing_freeze_completed_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.completed_at IS NOT NULL
     AND NEW.result_snapshot IS DISTINCT FROM OLD.result_snapshot THEN
    RAISE EXCEPTION 'financing_scenarios: result_snapshot is frozen once completed (scenario %) - duplicate the scenario instead of rewriting its result', OLD.scenario_number
      USING ERRCODE = 'check_violation';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.financing_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN NEW.updated_at := now(); RETURN NEW; END $function$;
CREATE OR REPLACE FUNCTION public.find_client_id_by_phone(p_phone text)
 RETURNS uuid
 LANGUAGE sql
 STABLE
AS $function$
  SELECT cl.id
  FROM public.unified_records cl
  WHERE cl.model_id = (SELECT id FROM public.models WHERE name = 'clients')
    AND public.ksa_phone_canon(p_phone) IS NOT NULL
    AND public.ksa_phone_canon(cl.data->>'phone_number') = public.ksa_phone_canon(p_phone)
  ORDER BY cl.created_at
  LIMIT 1
$function$;
CREATE OR REPLACE FUNCTION public.freeze_apply_row(p_model_id uuid, p_id uuid, p_data jsonb, p_created_by uuid DEFAULT NULL::uuid, p_expected_version integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_model       record;
  v_table       text;
  v_field       jsonb;
  v_fname       text;
  v_ftype       text;
  v_is_multi    boolean;
  v_assignments text := '';
  v_arr         jsonb;
  v_row         jsonb;
  v_row_index   int;
  v_existing    int;
  v_overflow    text[] := ARRAY[]::text[];
BEGIN
  SELECT * INTO v_model FROM models WHERE id = p_model_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'model % not found in freeze_apply_row', p_model_id; END IF;
  v_table := public.freeze_safe_ident(v_model.name);

  IF p_expected_version IS NOT NULL THEN
    EXECUTE format('SELECT version FROM public.%I WHERE id = $1', v_table) USING p_id INTO v_existing;
    IF v_existing IS NOT NULL AND v_existing <> p_expected_version THEN
      RAISE EXCEPTION 'version_mismatch: record was edited by another user (loaded v%, current v%)',
        p_expected_version, v_existing
      USING ERRCODE = 'serialization_failure', HINT = 'reload the record to see latest changes';
    END IF;
  END IF;

  IF p_created_by IS NOT NULL THEN
    EXECUTE format('UPDATE public.%I SET created_by_user_id = COALESCE(created_by_user_id, $1) WHERE id = $2', v_table)
      USING p_created_by, p_id;
  END IF;

  FOR v_field IN
    SELECT field FROM jsonb_array_elements(v_model.schema->'sections') AS sec(value),
         LATERAL jsonb_array_elements(sec.value->'fields') AS field
  LOOP
    v_fname := v_field->>'name'; v_ftype := v_field->>'type';
    v_is_multi := COALESCE((v_field->>'is_multi')::boolean, false);
    IF v_fname IS NULL OR v_fname = '' THEN CONTINUE; END IF;
    IF public.freeze_is_virtual(v_ftype) THEN CONTINUE; END IF;
    IF COALESCE(v_field->>'storage','column') = 'overflow' THEN
      v_overflow := array_append(v_overflow, v_fname); CONTINUE;
    END IF;
    IF public.freeze_is_multi_value(v_ftype, v_is_multi) THEN CONTINUE; END IF;
    IF v_assignments <> '' THEN v_assignments := v_assignments || ', '; END IF;

    IF v_ftype = 'range' THEN
      v_assignments := v_assignments || format('%I = public.try_numeric(($1->%L)->>''min''), %I = public.try_numeric(($1->%L)->>''max'')',
        v_fname || '_min', v_fname, v_fname || '_max', v_fname);
    ELSIF v_ftype IN ('number', 'currency', 'formula') THEN
      v_assignments := v_assignments || format('%I = public.try_numeric($1->>%L)', v_fname, v_fname);
    ELSIF v_ftype IN ('date', 'datetime') THEN
      v_assignments := v_assignments || format('%I = public.try_timestamptz($1->>%L)', v_fname, v_fname);
    ELSIF v_ftype = 'checkbox' THEN
      v_assignments := v_assignments || format('%I = public.try_boolean($1->>%L)', v_fname, v_fname);
    ELSIF v_ftype IN ('notes', 'section_mirror', 'section_selector', 'assignee') THEN
      v_assignments := v_assignments || format('%I = $1->%L', v_fname, v_fname);
    ELSE
      v_assignments := v_assignments || format('%I = $1->>%L', v_fname, v_fname);
    END IF;
  END LOOP;

  IF v_assignments <> '' THEN
    EXECUTE format('UPDATE public.%I SET %s, updated_at = now() WHERE id = $2', v_table, v_assignments)
      USING p_data, p_id;
  END IF;

  IF array_length(v_overflow, 1) IS NOT NULL THEN
    EXECUTE format('UPDATE public.%I SET custom_data = COALESCE((SELECT jsonb_object_agg(k, $1->k) FROM unnest($2::text[]) AS k WHERE $1 ? k), ''{}''::jsonb), updated_at = now() WHERE id = $3', v_table)
      USING p_data, v_overflow, p_id;
  END IF;

  FOR v_field IN
    SELECT field FROM jsonb_array_elements(v_model.schema->'sections') AS sec(value),
         LATERAL jsonb_array_elements(sec.value->'fields') AS field
  LOOP
    v_fname := v_field->>'name'; v_ftype := v_field->>'type';
    v_is_multi := COALESCE((v_field->>'is_multi')::boolean, false);
    IF v_fname IS NULL OR v_fname = '' THEN CONTINUE; END IF;
    IF COALESCE(v_field->>'storage','column') = 'overflow' THEN CONTINUE; END IF;
    IF NOT public.freeze_is_multi_value(v_ftype, v_is_multi) THEN CONTINUE; END IF;
    EXECUTE format('DELETE FROM public.%I WHERE record_id = $1', v_table || '__' || v_fname) USING p_id;

    v_arr := p_data->v_fname;
    IF v_arr IS NULL OR jsonb_typeof(v_arr) <> 'array' THEN CONTINUE; END IF;

    IF v_ftype = 'multiselect' THEN
      EXECUTE format('INSERT INTO public.%I (record_id, value) SELECT $1, value::text FROM jsonb_array_elements_text($2)',
        v_table || '__' || v_fname) USING p_id, v_arr;
    ELSIF v_ftype = 'lookup' THEN
      EXECUTE format('INSERT INTO public.%I (record_id, target_record_id) SELECT $1, value::uuid FROM jsonb_array_elements_text($2) WHERE value <> ''''',
        v_table || '__' || v_fname) USING p_id, v_arr;
    ELSIF v_ftype = 'table' THEN
      v_row_index := 0;
      FOR v_row IN SELECT * FROM jsonb_array_elements(v_arr) LOOP
        EXECUTE format('INSERT INTO public.%I (record_id, row_index, %s) VALUES ($1, $2, %s)',
          v_table || '__' || v_fname,
          public.freeze_table_columns_dml(v_field->'table_columns', false),
          public.freeze_table_columns_dml(v_field->'table_columns', true)
        ) USING p_id, v_row_index, v_row;
        v_row_index := v_row_index + 1;
      END LOOP;
    END IF;
  END LOOP;
END;
$function$;
CREATE OR REPLACE FUNCTION public.freeze_build_table_subtable_columns(p_columns jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_col  jsonb;
  v_name text;
  v_type text;
  v_out  text := '';
BEGIN
  IF p_columns IS NULL OR jsonb_typeof(p_columns) <> 'array' THEN
    RETURN 'placeholder_unused boolean';
  END IF;
  FOR v_col IN SELECT * FROM jsonb_array_elements(p_columns) LOOP
    v_name := v_col->>'name';
    v_type := v_col->>'type';
    IF v_name IS NULL OR v_name = '' THEN CONTINUE; END IF;
    PERFORM public.freeze_safe_ident(v_name);
    IF v_out <> '' THEN v_out := v_out || ', '; END IF;
    IF v_type IN ('number', 'currency', 'formula') THEN
      v_out := v_out || format('%I numeric', v_name);
    ELSIF v_type = 'date' THEN
      v_out := v_out || format('%I timestamptz', v_name);
    ELSE
      v_out := v_out || format('%I text', v_name);
    END IF;
  END LOOP;
  IF v_out = '' THEN v_out := 'placeholder_unused boolean'; END IF;
  RETURN v_out;
END;
$function$;
CREATE OR REPLACE FUNCTION public.freeze_check_coercion(p_model_id uuid)
 RETURNS TABLE(record_id uuid, field_name text, field_type text, raw_value text, reason text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_field jsonb;
  v_fname text;
  v_ftype text;
  v_schema jsonb;
BEGIN
  SELECT schema INTO v_schema FROM models WHERE id = p_model_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'model % not found', p_model_id;
  END IF;

  FOR v_field IN
    SELECT field
    FROM jsonb_array_elements(v_schema->'sections') AS sec(value),
         LATERAL jsonb_array_elements(sec.value->'fields') AS field
  LOOP
    v_fname := v_field->>'name';
    v_ftype := v_field->>'type';
    IF v_fname IS NULL OR v_fname = '' THEN CONTINUE; END IF;

    -- numeric types
    IF v_ftype IN ('number', 'currency', 'formula') THEN
      RETURN QUERY
        SELECT r.id, v_fname, v_ftype, r.data->>v_fname,
               'cannot coerce to numeric'::text
        FROM records r
        WHERE r.model_id = p_model_id
          AND r.data ? v_fname
          AND r.data->>v_fname IS NOT NULL
          AND r.data->>v_fname <> ''
          AND public.try_numeric(r.data->>v_fname) IS NULL;

    -- timestamptz
    ELSIF v_ftype IN ('date', 'datetime') THEN
      RETURN QUERY
        SELECT r.id, v_fname, v_ftype, r.data->>v_fname,
               'cannot coerce to timestamptz'::text
        FROM records r
        WHERE r.model_id = p_model_id
          AND r.data ? v_fname
          AND r.data->>v_fname IS NOT NULL
          AND r.data->>v_fname <> ''
          AND public.try_timestamptz(r.data->>v_fname) IS NULL;

    -- boolean
    ELSIF v_ftype = 'checkbox' THEN
      RETURN QUERY
        SELECT r.id, v_fname, v_ftype, r.data->>v_fname,
               'cannot coerce to boolean'::text
        FROM records r
        WHERE r.model_id = p_model_id
          AND r.data ? v_fname
          AND r.data->>v_fname IS NOT NULL
          AND r.data->>v_fname <> ''
          AND public.try_boolean(r.data->>v_fname) IS NULL;

    -- range — both halves
    ELSIF v_ftype = 'range' THEN
      RETURN QUERY
        SELECT r.id, v_fname || '.min', v_ftype, r.data->v_fname->>'min',
               'cannot coerce range min to numeric'::text
        FROM records r
        WHERE r.model_id = p_model_id
          AND r.data ? v_fname
          AND r.data->v_fname->>'min' IS NOT NULL
          AND r.data->v_fname->>'min' <> ''
          AND public.try_numeric(r.data->v_fname->>'min') IS NULL;
      RETURN QUERY
        SELECT r.id, v_fname || '.max', v_ftype, r.data->v_fname->>'max',
               'cannot coerce range max to numeric'::text
        FROM records r
        WHERE r.model_id = p_model_id
          AND r.data ? v_fname
          AND r.data->v_fname->>'max' IS NOT NULL
          AND r.data->v_fname->>'max' <> ''
          AND public.try_numeric(r.data->v_fname->>'max') IS NULL;

    -- multiselect must be a JSON array (or scalar/null which we tolerate)
    ELSIF v_ftype = 'multiselect' THEN
      RETURN QUERY
        SELECT r.id, v_fname, v_ftype, r.data->>v_fname,
               'multiselect value must be a JSON array'::text
        FROM records r
        WHERE r.model_id = p_model_id
          AND r.data ? v_fname
          AND r.data->v_fname IS NOT NULL
          AND jsonb_typeof(r.data->v_fname) NOT IN ('array', 'null');

    -- multi-lookup must be array; single lookup must be scalar
    ELSIF v_ftype = 'lookup' THEN
      IF COALESCE((v_field->>'is_multi')::boolean, false) THEN
        RETURN QUERY
          SELECT r.id, v_fname, v_ftype, r.data->>v_fname,
                 'multi-lookup value must be a JSON array'::text
          FROM records r
          WHERE r.model_id = p_model_id
            AND r.data ? v_fname
            AND r.data->v_fname IS NOT NULL
            AND jsonb_typeof(r.data->v_fname) NOT IN ('array', 'null');
      END IF;

    -- table fields must be array of row objects
    ELSIF v_ftype = 'table' THEN
      RETURN QUERY
        SELECT r.id, v_fname, v_ftype, r.data->>v_fname,
               'table value must be a JSON array of rows'::text
        FROM records r
        WHERE r.model_id = p_model_id
          AND r.data ? v_fname
          AND r.data->v_fname IS NOT NULL
          AND jsonb_typeof(r.data->v_fname) NOT IN ('array', 'null');
    END IF;
  END LOOP;
END;
$function$;
CREATE OR REPLACE FUNCTION public.freeze_copy_records(p_model_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_model record;
  v_table text;
  v_rec   record;
BEGIN
  SELECT * INTO v_model FROM models WHERE id = p_model_id;
  IF NOT FOUND OR NOT v_model.is_hardcoded THEN RETURN; END IF;
  v_table := public.freeze_safe_ident(v_model.name);

  FOR v_rec IN
    SELECT id, data, created_by_user_id, created_at, updated_at
      FROM records WHERE model_id = p_model_id
  LOOP
    -- Insert the parent row with timestamps + creator stamp preserved.
    EXECUTE format(
      'INSERT INTO public.%I (id, created_by_user_id, created_at, updated_at) VALUES ($1, $2, $3, $4)',
      v_table
    ) USING v_rec.id, v_rec.created_by_user_id, v_rec.created_at, v_rec.updated_at;

    -- Apply the JSONB payload (scalar columns + junctions + subtables).
    -- We pass NULL for p_created_by because the parent INSERT above
    -- already set the column; freeze_apply_row's COALESCE keeps it.
    PERFORM public.freeze_apply_row(p_model_id, v_rec.id, v_rec.data, NULL);
  END LOOP;
END;
$function$;
CREATE OR REPLACE FUNCTION public.freeze_is_multi_value(p_ftype text, p_is_multi boolean)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT p_ftype = 'multiselect'
      OR p_ftype = 'table'
      OR (p_ftype = 'lookup' AND COALESCE(p_is_multi, false));
$function$;
CREATE OR REPLACE FUNCTION public.freeze_is_virtual(p_ftype text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT p_ftype = 'mirror';
$function$;
CREATE OR REPLACE FUNCTION public.freeze_model(p_model_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_model       record;
  v_table       text;
  v_columns     text := '';
  v_field       jsonb;
  v_fname       text;
  v_ftype       text;
  v_is_multi    boolean;
  v_failures    int;
  v_record_count int;
  v_seq_name    text;
  v_max_num     bigint;
BEGIN
  SELECT * INTO v_model FROM models WHERE id = p_model_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'model % not found', p_model_id; END IF;
  IF v_model.is_hardcoded THEN RAISE EXCEPTION 'model "%" is already frozen', v_model.name; END IF;
  IF NOT public.is_freezable_model(v_model.name) THEN
    RAISE EXCEPTION 'model "%" is not freezable (custom-UI model)', v_model.name;
  END IF;

  v_table := public.freeze_safe_ident(v_model.name);

  IF EXISTS (SELECT 1 FROM information_schema.tables
             WHERE table_schema = 'public' AND table_name = v_table) THEN
    RAISE EXCEPTION 'table public.% already exists — drop it before re-freezing', v_table;
  END IF;

  SELECT count(*) INTO v_failures FROM public.freeze_check_coercion(p_model_id);
  IF v_failures > 0 THEN
    RAISE EXCEPTION 'freeze aborted: % records have coercion failures (call freeze_check_coercion to see them)', v_failures;
  END IF;

  FOR v_field IN
    SELECT field FROM jsonb_array_elements(v_model.schema->'sections') AS sec(value),
                      LATERAL jsonb_array_elements(sec.value->'fields') AS field
  LOOP
    v_fname := v_field->>'name';
    v_ftype := v_field->>'type';
    v_is_multi := COALESCE((v_field->>'is_multi')::boolean, false);
    IF v_fname IS NULL OR v_fname = '' THEN CONTINUE; END IF;
    IF public.freeze_is_virtual(v_ftype) THEN CONTINUE; END IF;
    IF public.freeze_is_multi_value(v_ftype, v_is_multi) THEN CONTINUE; END IF;
    IF COALESCE(v_field->>'storage','column') = 'overflow' THEN CONTINUE; END IF;
    PERFORM public.freeze_safe_ident(v_fname);
    IF v_columns <> '' THEN v_columns := v_columns || ', '; END IF;
    IF v_ftype = 'range' THEN
      v_columns := v_columns || format('%I numeric, %I numeric', v_fname || '_min', v_fname || '_max');
    ELSIF v_ftype IN ('number', 'currency', 'formula') THEN
      v_columns := v_columns || format('%I numeric', v_fname);
    ELSIF v_ftype IN ('date', 'datetime') THEN
      v_columns := v_columns || format('%I timestamptz', v_fname);
    ELSIF v_ftype = 'checkbox' THEN
      v_columns := v_columns || format('%I boolean', v_fname);
    ELSIF v_ftype IN ('notes', 'section_mirror', 'section_selector', 'assignee') THEN
      v_columns := v_columns || format('%I jsonb', v_fname);
    ELSE
      v_columns := v_columns || format('%I text', v_fname);
    END IF;
  END LOOP;

  EXECUTE format(
    'CREATE TABLE public.%I (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), %s, custom_data jsonb NOT NULL DEFAULT ''{}''::jsonb, created_by_user_id uuid REFERENCES public.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now())',
    v_table,
    CASE WHEN v_columns = '' THEN 'placeholder_unused boolean' ELSE v_columns END
  );

  EXECUTE format(
    'CREATE TRIGGER set_updated_at_%I BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION update_updated_at_column()',
    v_table, v_table
  );

  EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', v_table);
  EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', v_table);

  FOR v_field IN
    SELECT field FROM jsonb_array_elements(v_model.schema->'sections') AS sec(value),
                      LATERAL jsonb_array_elements(sec.value->'fields') AS field
  LOOP
    v_fname := v_field->>'name';
    v_ftype := v_field->>'type';
    v_is_multi := COALESCE((v_field->>'is_multi')::boolean, false);
    IF v_fname IS NULL OR v_fname = '' THEN CONTINUE; END IF;
    IF NOT public.freeze_is_multi_value(v_ftype, v_is_multi) THEN CONTINUE; END IF;
    IF COALESCE(v_field->>'storage','column') = 'overflow' THEN CONTINUE; END IF;
    PERFORM public.freeze_safe_ident(v_fname);

    IF v_ftype = 'multiselect' THEN
      EXECUTE format('CREATE TABLE public.%I (record_id uuid NOT NULL REFERENCES public.%I(id) ON DELETE CASCADE, value text NOT NULL, PRIMARY KEY (record_id, value))',
        v_table || '__' || v_fname, v_table);
    ELSIF v_ftype = 'lookup' THEN
      EXECUTE format('CREATE TABLE public.%I (record_id uuid NOT NULL REFERENCES public.%I(id) ON DELETE CASCADE, target_record_id uuid NOT NULL, PRIMARY KEY (record_id, target_record_id))',
        v_table || '__' || v_fname, v_table);
    ELSIF v_ftype = 'table' THEN
      EXECUTE format('CREATE TABLE public.%I (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid NOT NULL REFERENCES public.%I(id) ON DELETE CASCADE, row_index int NOT NULL, %s, created_at timestamptz NOT NULL DEFAULT now())',
        v_table || '__' || v_fname, v_table,
        public.freeze_build_table_subtable_columns(v_field->'table_columns'));
      EXECUTE format('CREATE INDEX %I ON public.%I (record_id, row_index)',
        'idx_' || v_table || '__' || v_fname || '_record', v_table || '__' || v_fname);
    END IF;

    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', v_table || '__' || v_fname);
    EXECUTE format('CREATE POLICY "frozen_junction_view" ON public.%I FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.%I p WHERE p.id = record_id))',
      v_table || '__' || v_fname, v_table);
    EXECUTE format('CREATE POLICY "frozen_junction_write" ON public.%I FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.%I p WHERE p.id = record_id)) WITH CHECK (EXISTS (SELECT 1 FROM public.%I p WHERE p.id = record_id))',
      v_table || '__' || v_fname, v_table, v_table);
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', v_table || '__' || v_fname);
  END LOOP;

  FOR v_field IN
    SELECT field FROM jsonb_array_elements(v_model.schema->'sections') AS sec(value),
                      LATERAL jsonb_array_elements(sec.value->'fields') AS field
    WHERE field->>'type' = 'auto_id'
  LOOP
    v_fname    := v_field->>'name';
    v_seq_name := v_table || '__' || v_fname || '_seq';
    EXECUTE format(
      $q$SELECT COALESCE(max((regexp_replace(data->>%L, '^.*?(\d+)$', '\1'))::bigint), 0)
         FROM records WHERE model_id = $1 AND data->>%L ~ '\d+'$q$,
      v_fname, v_fname
    ) USING p_model_id INTO v_max_num;
    EXECUTE format('CREATE SEQUENCE public.%I START WITH %s', v_seq_name, GREATEST(v_max_num + 1, 1));
    EXECUTE format('GRANT USAGE ON SEQUENCE public.%I TO authenticated', v_seq_name);
  END LOOP;

  UPDATE models SET is_hardcoded = true, table_name = v_table WHERE id = p_model_id;
  PERFORM public.freeze_copy_records(p_model_id);
  EXECUTE format('DROP VIEW IF EXISTS public.%I', 'v_' || v_table);
  PERFORM public.regenerate_frozen_model_artifacts(p_model_id);
  SELECT count(*) INTO v_record_count FROM records WHERE model_id = p_model_id;
  DELETE FROM records WHERE model_id = p_model_id;
  PERFORM public.rebuild_unified_records();

  RETURN jsonb_build_object('model_id', p_model_id, 'model_name', v_model.name,
    'table_name', v_table, 'rows_copied', v_record_count, 'frozen_at', now());
END;
$function$;
CREATE OR REPLACE FUNCTION public.freeze_model_safe(p_model_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_model record;
  v_locked boolean;
  v_result jsonb;
BEGIN
  v_locked := pg_try_advisory_xact_lock(hashtext('freeze_model:' || p_model_id::text));
  IF NOT v_locked THEN
    RAISE EXCEPTION 'freeze_model_safe: another freeze is already in progress for model %', p_model_id
      USING ERRCODE = 'lock_not_available';
  END IF;

  SELECT id, name, is_hardcoded INTO v_model FROM public.models WHERE id = p_model_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'freeze_model_safe: model % not found', p_model_id;
  END IF;
  IF v_model.is_hardcoded THEN
    RETURN jsonb_build_object(
      'ok', true,
      'already_frozen', true,
      'model_id', v_model.id,
      'model_name', v_model.name
    );
  END IF;

  v_result := public.freeze_model(p_model_id);

  BEGIN
    INSERT INTO public.activity_log (
      category, event_type, actor_user_id, actor_email,
      target_model_id, target_label, summary_ar, summary_en, status, details
    )
    VALUES (
      'system',
      'model_freeze',
      (SELECT auth.uid()),
      NULL,
      p_model_id,
      v_model.name,
      'تم تجميد النموذج "' || v_model.name || '"',
      'Froze model "' || v_model.name || '"',
      'success',
      v_result
    );
  EXCEPTION WHEN others THEN
    RAISE NOTICE '[freeze_model_safe] activity_log insert failed: %', SQLERRM;
  END;

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.freeze_safe_ident(p text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF p IS NULL OR p = '' THEN
    RAISE EXCEPTION 'identifier may not be empty';
  END IF;
  IF p !~ '^[a-z_][a-z0-9_]*$' THEN
    RAISE EXCEPTION 'invalid identifier: %', p;
  END IF;
  IF length(p) > 50 THEN
    RAISE EXCEPTION 'identifier too long (>50 chars): %', p;
  END IF;
  RETURN p;
END;
$function$;
CREATE OR REPLACE FUNCTION public.freeze_table_columns_dml(p_columns jsonb, p_values boolean)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_col   jsonb;
  v_name  text;
  v_type  text;
  v_out   text := '';
BEGIN
  IF p_columns IS NULL OR jsonb_typeof(p_columns) <> 'array' THEN
    RETURN '';
  END IF;
  FOR v_col IN SELECT * FROM jsonb_array_elements(p_columns) LOOP
    v_name := v_col->>'name';
    v_type := v_col->>'type';
    IF v_name IS NULL OR v_name = '' THEN CONTINUE; END IF;
    IF v_out <> '' THEN v_out := v_out || ', '; END IF;
    IF p_values THEN
      IF v_type IN ('number', 'currency', 'formula') THEN
        v_out := v_out || format('public.try_numeric($3->>%L)', v_name);
      ELSIF v_type = 'date' THEN
        v_out := v_out || format('public.try_timestamptz($3->>%L)', v_name);
      ELSE
        v_out := v_out || format('$3->>%L', v_name);
      END IF;
    ELSE
      v_out := v_out || format('%I', v_name);
    END IF;
  END LOOP;
  RETURN v_out;
END;
$function$;
CREATE OR REPLACE FUNCTION public.frozen_bump_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF OLD.version = NEW.version THEN
    NEW.version := OLD.version + 1;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.generation_job_cancel(p_job_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_status  text;
  v_record  uuid;
  v_message text;
BEGIN
  SELECT status, record_id, message_id
    INTO v_status, v_record, v_message
    FROM public.generation_jobs
   WHERE id = p_job_id AND user_id = auth.uid()
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  IF v_status NOT IN ('queued','running') THEN
    RETURN v_status;
  END IF;
  UPDATE public.generation_jobs
     SET status = 'cancelled', finished_at = now()
   WHERE id = p_job_id;
  UPDATE public.records r
     SET data = jsonb_set(r.data, '{messages}', (
           SELECT jsonb_agg(
             CASE WHEN msg->>'id' = v_message
                  THEN msg || jsonb_build_object('status','cancelled')
                  ELSE msg END)
           FROM jsonb_array_elements(r.data->'messages') AS msg
         ), true),
         updated_at = now()
   WHERE r.id = v_record AND r.data ? 'messages';
  RETURN v_status;
END;
$function$;
CREATE OR REPLACE FUNCTION public.generation_job_claim_next(p_worker_id text, p_kind text DEFAULT 'image'::text)
 RETURNS TABLE(job_id uuid, record_id uuid, message_id text, generation_id text, user_id uuid, kind text, prompt text, params jsonb, attempts integer)
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  UPDATE public.generation_jobs
     SET status     = 'running',
         worker_id  = p_worker_id,
         started_at = now(),
         attempts   = generation_jobs.attempts + 1
   WHERE id = (
     SELECT id FROM public.generation_jobs
      WHERE status = 'queued' AND kind = p_kind
      ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 1
   )
   RETURNING id, record_id, message_id, generation_id, user_id, kind, prompt, params, attempts;
$function$;
CREATE OR REPLACE FUNCTION public.generation_job_complete(p_job_id uuid, p_result jsonb)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  WITH updated AS (
    UPDATE public.generation_jobs
       SET status = 'completed', finished_at = now(), result = p_result, error = NULL
     WHERE id = p_job_id AND status = 'running'
    RETURNING 1
  )
  SELECT EXISTS (SELECT 1 FROM updated);
$function$;
CREATE OR REPLACE FUNCTION public.generation_job_fail(p_job_id uuid, p_error text)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  WITH updated AS (
    UPDATE public.generation_jobs
       SET status = 'failed', finished_at = now(), error = p_error
     WHERE id = p_job_id AND status = 'running'
    RETURNING 1
  )
  SELECT EXISTS (SELECT 1 FROM updated);
$function$;
CREATE OR REPLACE FUNCTION public.generation_jobs_watchdog()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_count int  := 0;
  v_msg   text := 'watchdog: generation did not finish within 15 minutes — likely crashed mid-run. Press Retry to try again.';
BEGIN
  WITH stale AS (
    UPDATE public.generation_jobs
       SET status      = 'failed',
           finished_at = now(),
           error       = v_msg
     WHERE status = 'running'
       AND started_at < now() - interval '15 minutes'
    RETURNING id, record_id, message_id
  ),
  by_record AS (
    SELECT record_id, array_agg(message_id) AS msg_ids
      FROM stale
     GROUP BY record_id
  ),
  recs AS (
    UPDATE public.records r
       SET data = jsonb_set(r.data, '{messages}', (
             SELECT jsonb_agg(
               CASE WHEN msg->>'id' = ANY(b.msg_ids)
                    THEN msg || jsonb_build_object('status','failed','error',v_msg)
                    ELSE msg END)
             FROM jsonb_array_elements(r.data->'messages') AS msg
           ), true),
           updated_at = now()
      FROM by_record b
     WHERE r.id = b.record_id
       AND r.data ? 'messages'
    RETURNING 1
  ),
  recs_cleaning AS (
    UPDATE public.records r
       SET data = jsonb_set(r.data, '{cleaning}', (
             SELECT jsonb_agg(
               CASE WHEN c->>'id' = ANY(b.msg_ids)
                    THEN c || jsonb_build_object('status','failed','error',v_msg)
                    ELSE c END)
             FROM jsonb_array_elements(r.data->'cleaning') AS c
           ), true),
           updated_at = now()
      FROM by_record b
     WHERE r.id = b.record_id
       AND r.data ? 'cleaning'
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_count FROM stale;

  RETURN v_count;
END;
$function$;
CREATE OR REPLACE FUNCTION public.geo_apply_review_decisions()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE n integer;
BEGIN
  WITH upd AS (
    UPDATE public.records p
    SET data = p.data || jsonb_build_object(
        'district_lookup', q.chosen_district_id::text,
        'district_name',  d.data->>'display_name',
        'city_lookup',    d.data->>'city_lookup',
        'region_lookup',  d.data->>'region_lookup',
        'district_match_status', 'manual_selected',
        'location_verified_at', '2026-06-25',
        'district_migration_notes', 'manual review'||coalesce(' — '||q.reviewer_note,''))
    FROM public._geo_review_queue q
    JOIN public.records d ON d.id = q.chosen_district_id
    WHERE p.id = q.project_id AND q.chosen_district_id IS NOT NULL
      AND p.model_id = '220c49b9-de57-492d-9eca-c0d9f54fd40f'
    RETURNING 1)
  SELECT count(*) INTO n FROM upd;
  RETURN n;
END $function$;
CREATE OR REPLACE FUNCTION public.geo_boundaries_resync_names()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE d int; c int; r int;
BEGIN
  UPDATE public.geo_boundaries gb
  SET name_ar = x.name_ar, name_en = x.name_en, record_id = x.id, updated_at = now()
  FROM public.districts x
  WHERE gb.tier = 'district' AND gb.external_id = x.spl_district_id
    AND (gb.name_ar IS DISTINCT FROM x.name_ar OR gb.name_en IS DISTINCT FROM x.name_en);
  GET DIAGNOSTICS d = ROW_COUNT;

  UPDATE public.geo_boundaries gb
  SET name_ar = x.name_ar, name_en = x.name_en, record_id = x.id, updated_at = now()
  FROM public.cities x
  WHERE gb.tier = 'city' AND gb.external_id = x.spl_city_id
    AND (gb.name_ar IS DISTINCT FROM x.name_ar OR gb.name_en IS DISTINCT FROM x.name_en);
  GET DIAGNOSTICS c = ROW_COUNT;

  UPDATE public.geo_boundaries gb
  SET name_ar = x.name_ar, name_en = x.name_en, record_id = x.id, updated_at = now()
  FROM public.regions x
  WHERE gb.tier = 'region' AND gb.external_id = x.id::text
    AND (gb.name_ar IS DISTINCT FROM x.name_ar OR gb.name_en IS DISTINCT FROM x.name_en);
  GET DIAGNOSTICS r = ROW_COUNT;

  -- Rows whose source record no longer exists: a district deleted after the backfill
  -- would otherwise keep drawing on the map forever.
  DELETE FROM public.geo_boundaries gb
  WHERE gb.tier = 'district'
    AND NOT EXISTS (SELECT 1 FROM public.districts x WHERE x.spl_district_id = gb.external_id);

  RETURN jsonb_build_object('districts', d, 'cities', c, 'regions', r);
END; $function$;
CREATE OR REPLACE FUNCTION public.geo_boundary_import_admin(p_row jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tier text := p_row->>'level';
  v_cc   text := p_row->>'country_code';
  v_ext  text := p_row->>'ref_id';
  v_rec  uuid;
  v_parent text;
  v_geom geometry;
BEGIN
  v_geom := ST_Multi(ST_CollectionExtract(
              ST_MakeValid(ST_SetSRID(ST_GeomFromGeoJSON(p_row->>'geometry_geojson'), 4326)), 3));
  IF v_geom IS NULL OR ST_IsEmpty(v_geom) THEN
    RAISE EXCEPTION 'empty geometry for % % %', v_tier, v_cc, v_ext;
  END IF;

  IF v_tier = 'region' THEN
    SELECT r.id INTO v_rec
    FROM public.unified_records r
    JOIN public.models m ON m.id = r.model_id AND m.name = 'regions'
    WHERE coalesce(r.data->>'country_code','') = v_cc
      AND public._geo_norm_admin_name(r.data->>'name_ar')
        = public._geo_norm_admin_name(p_row->>'name_ar')
    LIMIT 1;
    IF v_rec IS NULL THEN
      RAISE WARNING 'geo_boundary_import_admin: region %/% matched no regions record; keying by ISO %',
        v_cc, p_row->>'name_ar', v_ext;
    ELSE
      v_ext := v_rec::text;
    END IF;
    v_parent := v_cc;
  ELSIF v_tier = 'country' THEN
    SELECT r.id INTO v_rec
    FROM public.unified_records r
    JOIN public.models m ON m.id = r.model_id AND m.name = 'countries'
    WHERE r.data->>'iso_code' = v_cc LIMIT 1;
    v_ext := v_cc;
    v_parent := NULL;
  ELSE
    RAISE EXCEPTION 'geo_boundary_import_admin only handles country/region, got %', v_tier;
  END IF;

  INSERT INTO public.geo_boundaries
    (tier, external_id, record_id, parent_external_id, country_code, name_ar, name_en, geom, source, updated_at)
  VALUES (v_tier, v_ext, v_rec, v_parent, v_cc,
          p_row->>'name_ar', p_row->>'name_en', v_geom,
          'osm: boundary=administrative relation ' || coalesce(p_row->>'osm_id','?'), now())
  ON CONFLICT (tier, external_id) DO UPDATE
    SET record_id = coalesce(excluded.record_id, geo_boundaries.record_id),
        parent_external_id = excluded.parent_external_id,
        country_code = excluded.country_code,
        name_ar = coalesce(excluded.name_ar, geo_boundaries.name_ar),
        name_en = coalesce(excluded.name_en, geo_boundaries.name_en),
        geom = excluded.geom, source = excluded.source, updated_at = now();

  RETURN jsonb_build_object('tier', v_tier, 'external_id', v_ext,
                            'joined', v_rec IS NOT NULL, 'points', ST_NPoints(v_geom));
END;
$function$;
CREATE OR REPLACE FUNCTION public.geo_boundary_stage_apply()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_applied int; v_invalid int;
BEGIN
  INSERT INTO public.geo_boundaries
    (tier, external_id, parent_external_id, country_code, name_ar, name_en, geom, source, updated_at)
  SELECT s.tier, s.external_id, s.parent_external_id, s.country_code, s.name_ar, s.name_en,
         ST_MakeValid(ST_SetSRID(ST_GeomFromGeoJSON(s.geojson::text), 4326)),
         s.source, now()
  FROM public._geo_boundary_stage s
  ON CONFLICT (tier, external_id) DO UPDATE SET
    parent_external_id = EXCLUDED.parent_external_id,
    country_code = EXCLUDED.country_code,
    name_ar = EXCLUDED.name_ar, name_en = EXCLUDED.name_en,
    geom = EXCLUDED.geom, source = EXCLUDED.source, updated_at = now();
  GET DIAGNOSTICS v_applied = ROW_COUNT;
  SELECT count(*) INTO v_invalid FROM public.geo_boundaries WHERE NOT ST_IsValid(geom);
  RETURN jsonb_build_object('applied', v_applied, 'invalid_geometry', v_invalid);
END; $function$;
CREATE OR REPLACE FUNCTION public.geo_boundary_stage_reset()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v int;
BEGIN
  DELETE FROM public._geo_boundary_stage WHERE external_id IS NOT NULL;
  GET DIAGNOSTICS v = ROW_COUNT;
  RETURN jsonb_build_object('cleared', v);
END; $function$;
CREATE OR REPLACE FUNCTION public.geo_map_layers(p_min_lng double precision, p_min_lat double precision, p_max_lng double precision, p_max_lat double precision, p_zoom integer, p_max_features integer DEFAULT 400)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_env      geometry;
  v_tier     text;
  v_tol      double precision;
  v_minspan  double precision;
  v_cap      int := greatest(1, least(coalesce(p_max_features, 400), 2000));
  v_bounds   jsonb;
  v_roads    jsonb;
  v_marks    jsonb;
  v_total    int;
  v_shown    int;
BEGIN
  v_env  := ST_MakeEnvelope(p_min_lng, p_min_lat, p_max_lng, p_max_lat, 4326);
  v_tier := public.geo_map_tier_for_zoom(p_zoom);
  v_tol := 360.0 / (256.0 * power(2, greatest(p_zoom, 1))) * 2.0;
  v_minspan := v_tol * 2.0;

  -- DISTINCT ON the entity, not the row. `record_id` is the same for two rows
  -- describing one region under different key conventions; falling back to
  -- external_id keeps rows that legitimately have no record (countries).
  -- Newest wins, then the richer geometry, so the tie-break is deterministic.
  WITH deduped AS (
    SELECT DISTINCT ON (b.tier, coalesce(b.record_id::text, b.external_id))
           b.external_id, b.record_id, b.parent_external_id, b.tier,
           b.name_ar, b.name_en, b.country_code, b.geom
    FROM public.geo_boundaries b
    WHERE b.tier = v_tier
      AND b.geom && v_env
      AND greatest(ST_XMax(b.geom) - ST_XMin(b.geom), ST_YMax(b.geom) - ST_YMin(b.geom)) >= v_minspan
    ORDER BY b.tier, coalesce(b.record_id::text, b.external_id), b.updated_at DESC, ST_NPoints(b.geom) DESC
  ),
  picked AS (
    SELECT * FROM deduped ORDER BY ST_Area(geom) DESC LIMIT v_cap
  )
  SELECT jsonb_build_object('type', 'FeatureCollection',
           'features', coalesce(jsonb_agg(jsonb_build_object(
             'type', 'Feature',
             'id', p.tier || ':' || p.external_id,
             'properties', jsonb_build_object(
               'tier', p.tier, 'external_id', p.external_id, 'record_id', p.record_id,
               'parent_external_id', p.parent_external_id, 'country_code', p.country_code,
               'name_ar', p.name_ar, 'name_en', p.name_en),
             'geometry', ST_AsGeoJSON(ST_SimplifyPreserveTopology(p.geom, v_tol), 5)::jsonb)), '[]'::jsonb)),
         count(*)
    INTO v_bounds, v_shown
  FROM picked p;

  -- Total counts DEDUPED entities too, else `truncated` would lie whenever a second
  -- convention doubled the raw row count.
  SELECT count(*) INTO v_total FROM (
    SELECT DISTINCT coalesce(b.record_id::text, b.external_id)
    FROM public.geo_boundaries b
    WHERE b.tier = v_tier AND b.geom && v_env) t;

  IF p_zoom >= 9 THEN
    SELECT jsonb_build_object('type', 'FeatureCollection',
             'features', coalesce(jsonb_agg(jsonb_build_object(
               'type', 'Feature', 'id', e.external_id,
               'properties', jsonb_build_object('external_id', e.external_id, 'category', e.category,
                 'type', e.type, 'name_ar', e.name_ar, 'name_en', e.name_en, 'geom_kind', e.geom_kind),
               'geometry', ST_AsGeoJSON(ST_SimplifyPreserveTopology(e.geom, v_tol), 5)::jsonb)), '[]'::jsonb))
      INTO v_roads
    FROM (SELECT * FROM public.geo_elements
           WHERE category IN ('roads_major', 'ring_roads', 'metro_lines')
             AND is_active AND geom && v_env
           ORDER BY ST_Length(geom) DESC LIMIT least(v_cap, 150)) e;
  ELSE
    v_roads := jsonb_build_object('type', 'FeatureCollection', 'features', '[]'::jsonb);
  END IF;

  IF p_zoom >= 11 THEN
    SELECT jsonb_build_object('type', 'FeatureCollection',
             'features', coalesce(jsonb_agg(jsonb_build_object(
               'type', 'Feature', 'id', e.external_id,
               'properties', jsonb_build_object('external_id', e.external_id, 'category', e.category,
                 'type', e.type, 'name_ar', e.name_ar, 'name_en', e.name_en, 'geom_kind', e.geom_kind),
               'geometry', ST_AsGeoJSON(ST_PointOnSurface(e.geom), 5)::jsonb)), '[]'::jsonb))
      INTO v_marks
    FROM (SELECT * FROM public.geo_elements
           WHERE category IN ('landmarks', 'malls', 'universities', 'airports_transport', 'islands')
             AND is_active AND is_searchable AND review_status = 'approved'
             AND geom && v_env
           ORDER BY confidence_score DESC NULLS LAST LIMIT least(v_cap, 200)) e;
  ELSE
    v_marks := jsonb_build_object('type', 'FeatureCollection', 'features', '[]'::jsonb);
  END IF;

  RETURN jsonb_build_object(
    'tier', v_tier, 'zoom', p_zoom, 'simplify_tolerance', v_tol,
    'boundaries', v_bounds, 'roads', v_roads, 'landmarks', v_marks,
    'boundaries_total', v_total, 'boundaries_shown', coalesce(v_shown, 0),
    'truncated', v_total > coalesce(v_shown, 0));
END; $function$;
CREATE OR REPLACE FUNCTION public.geo_map_tier_for_zoom(p_zoom integer)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Bands chosen so the outline on screen is always the one you could meaningfully
  -- click: whole-Gulf view → countries, national view → regions, metro view → the city
  -- extent, street view → districts.
  SELECT CASE
    WHEN p_zoom <= 5 THEN 'country'
    WHEN p_zoom <= 7 THEN 'region'
    WHEN p_zoom <= 9 THEN 'city'
    ELSE 'district'
  END;
$function$;
CREATE OR REPLACE FUNCTION public.geo_uae_apply_boundaries()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_staged     int;
  v_applied    int;
  v_unlinked   int;
  v_invalid    int;
  v_recentred  int;
  v_outside    int;
BEGIN
  SELECT count(*) INTO v_staged FROM public._geo_uae_stage_boundaries;

  DELETE FROM public.district_boundaries
  WHERE spl_district_id LIKE 'AE-%'
    AND spl_district_id NOT IN (SELECT spl_district_id FROM public._geo_uae_stage_boundaries);

  INSERT INTO public.district_boundaries
    (district_record_id, spl_district_id, city_id, region_id, geom, geometry_type,
     boundary_source, boundary_updated_at, is_active)
  SELECT
    d.id, s.spl_district_id, s.city_id, s.region_id,
    ST_MakeValid(ST_SetSRID(ST_GeomFromGeoJSON(s.geojson::text), 4326)),
    s.geometry_type,
    'OpenStreetMap via Overpass API (ODbL)',
    now(), true
  FROM public._geo_uae_stage_boundaries s
  LEFT JOIN public.districts d ON d.spl_district_id = s.spl_district_id
  ON CONFLICT (spl_district_id) DO UPDATE SET
    district_record_id  = EXCLUDED.district_record_id,
    city_id             = EXCLUDED.city_id,
    region_id           = EXCLUDED.region_id,
    geom                = EXCLUDED.geom,
    geometry_type       = EXCLUDED.geometry_type,
    boundary_source     = EXCLUDED.boundary_source,
    boundary_updated_at = now(),
    is_active           = true;

  -- Re-centre every UAE district that has a boundary onto a point guaranteed to be
  -- inside it. Only writes when the value actually moves, so re-running is a no-op.
  WITH fixed AS (
    SELECT d.id,
           ST_Y(ST_PointOnSurface(b.geom))::numeric AS lat,
           ST_X(ST_PointOnSurface(b.geom))::numeric AS lng
    FROM public.districts d
    JOIN public.district_boundaries b ON b.district_record_id = d.id
    WHERE d.country_code = 'AE'
  )
  UPDATE public.districts d
  SET centroid_lat = round(f.lat, 7), centroid_lng = round(f.lng, 7),
      center_lat   = round(f.lat, 7), center_lng   = round(f.lng, 7)
  FROM fixed f
  WHERE d.id = f.id
    AND (d.centroid_lat IS DISTINCT FROM round(f.lat, 7)
      OR d.centroid_lng IS DISTINCT FROM round(f.lng, 7));
  GET DIAGNOSTICS v_recentred = ROW_COUNT;

  SELECT count(*) INTO v_applied FROM public.district_boundaries WHERE spl_district_id LIKE 'AE-%';
  SELECT count(*) INTO v_unlinked FROM public.district_boundaries
   WHERE spl_district_id LIKE 'AE-%' AND district_record_id IS NULL;
  SELECT count(*) INTO v_invalid FROM public.district_boundaries
   WHERE spl_district_id LIKE 'AE-%' AND NOT ST_IsValid(geom);
  -- Must be 0 after the re-centre. Reported rather than assumed.
  SELECT count(*) INTO v_outside
    FROM public.districts d JOIN public.district_boundaries b ON b.district_record_id = d.id
   WHERE d.country_code = 'AE' AND d.centroid_lat IS NOT NULL
     AND NOT ST_Contains(b.geom, ST_SetSRID(ST_MakePoint(d.centroid_lng::float8, d.centroid_lat::float8), 4326));

  RETURN jsonb_build_object(
    'staged', v_staged, 'applied', v_applied,
    'unlinked_to_district', v_unlinked, 'invalid_geometry', v_invalid,
    'recentred_on_surface', v_recentred, 'centroid_outside_own_polygon', v_outside);
END; $function$;
CREATE OR REPLACE FUNCTION public.geo_uae_stage_reset()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_deleted int;
BEGIN
  DELETE FROM public._geo_uae_stage_boundaries WHERE spl_district_id IS NOT NULL;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN jsonb_build_object('cleared', v_deleted);
END; $function$;
CREATE OR REPLACE FUNCTION public.get_public_dashboard(p_token text)
 RETURNS dashboards
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_limit       int := 60;
  v_window      timestamptz := date_trunc('minute', now());
  v_count       int;
  v_dashboard   dashboards;
BEGIN
  IF p_token IS NULL OR length(p_token) < 8 THEN
    RAISE EXCEPTION 'invalid token' USING ERRCODE = 'invalid_parameter_value';
  END IF;

  INSERT INTO public.public_dashboard_rate_limit (token, window_start, hit_count)
  VALUES (p_token, v_window, 1)
  ON CONFLICT (token, window_start)
  DO UPDATE SET hit_count = public_dashboard_rate_limit.hit_count + 1
  RETURNING hit_count INTO v_count;

  IF v_count > v_limit THEN
    RAISE EXCEPTION 'rate limit exceeded for public dashboard token (% per minute)', v_limit
      USING ERRCODE = 'too_many_connections';
  END IF;

  IF (v_count % 50) = 0 THEN
    DELETE FROM public.public_dashboard_rate_limit
     WHERE window_start < now() - INTERVAL '1 hour';
  END IF;

  SELECT * INTO v_dashboard FROM dashboards
   WHERE public_token = p_token AND is_public = true
   LIMIT 1;
  RETURN v_dashboard;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_shared_file(p_token text, p_password text DEFAULT NULL::text)
 RETURNS TABLE(file_id uuid, original_name text, mime_type text, size_bytes bigint, kind text, allow_download boolean, requires_password boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  link public.shared_links%ROWTYPE;
  f public.files%ROWTYPE;
BEGIN
  SELECT * INTO link FROM public.shared_links WHERE token = p_token AND is_active = true LIMIT 1;
  IF NOT FOUND THEN RETURN; END IF;
  IF link.expires_at IS NOT NULL AND link.expires_at < now() THEN RETURN; END IF;
  IF link.password_hash IS NOT NULL THEN
    IF p_password IS NULL OR crypt(p_password, link.password_hash) <> link.password_hash THEN
      RETURN QUERY SELECT
        NULL::uuid, NULL::text, NULL::text, NULL::bigint, NULL::text,
        link.allow_download, true;
      RETURN;
    END IF;
  END IF;
  SELECT * INTO f FROM public.files WHERE id = link.file_id LIMIT 1;
  IF NOT FOUND THEN RETURN; END IF;
  RETURN QUERY SELECT
    f.id, f.original_name, f.mime_type, f.size_bytes, f.kind,
    link.allow_download, false;
END $function$;
CREATE OR REPLACE FUNCTION public.get_visit_for_rating(p_token text)
 RETURNS TABLE(project_name text, visit_date text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    (SELECT p.data->>'project_name' FROM public.records p
      WHERE p.id = COALESCE(NULLIF(v.data->'project_id'->>0,''), NULLIF(v.data->>'project_id',''))::uuid
      LIMIT 1) AS project_name,
    v.data->>'scheduled_datetime' AS visit_date
  FROM public.records v
  JOIN public.models m ON m.id = v.model_id AND m.name = 'visits'
  WHERE NULLIF(v.data->>'rating_token','') = p_token
  LIMIT 1;
$function$;
CREATE OR REPLACE FUNCTION public.increment_push_failure(p_id uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  UPDATE push_subscriptions
     SET failure_count = failure_count + 1
   WHERE id = p_id;
$function$;
CREATE OR REPLACE FUNCTION public.is_freezable_model(p_model_name text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT p_model_name IS NOT NULL
     AND p_model_name NOT IN ('chats', 'ai_chats');
$function$;
CREATE OR REPLACE FUNCTION public.kill_conflict_storm_record(p_id uuid, p_reason text DEFAULT 'conflict storm mitigation'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE v_model uuid;
BEGIN
  SELECT model_id INTO v_model FROM public.records WHERE id = p_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('killed', false, 'reason', 'record not found in records table (frozen model or bad id?)');
  END IF;
  CREATE TABLE IF NOT EXISTS public._backup_conflict_storm_kills (
    backed_up_at timestamptz NOT NULL DEFAULT now(), reason text, LIKE public.records
  );
  INSERT INTO public._backup_conflict_storm_kills
    SELECT now(), p_reason, r.* FROM public.records r WHERE r.id = p_id;
  DELETE FROM public.records WHERE id = p_id;
  INSERT INTO public.system_alerts (kind, severity, detail)
  VALUES ('conflict_storm_killed', 'info', jsonb_build_object('record_id', p_id, 'model_id', v_model, 'reason', p_reason));
  RETURN jsonb_build_object('killed', true, 'record_id', p_id, 'model_id', v_model);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ksa_phone_canon(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE
           WHEN d = ''        THEN NULL
           WHEN d ~ '^966'    THEN d
           WHEN d ~ '^0'      THEN '966' || substring(d from 2)
           WHEN length(d) = 9 THEN '966' || d
           ELSE d
         END
  FROM (
    SELECT CASE WHEN d0 ~ '^00' THEN substring(d0 from 3) ELSE d0 END AS d
    FROM (SELECT regexp_replace(coalesce(p, ''), '\D', '', 'g') AS d0) z
  ) y
$function$;
CREATE OR REPLACE FUNCTION public.listing_mirror_backlog(p_limit integer DEFAULT 500, p_active_only boolean DEFAULT true)
 RETURNS TABLE(listing_id uuid, external_id text, missing integer, total integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT r.id,
         r.data->>'external_id',
         (SELECT count(*)::int
            FROM jsonb_array_elements_text(r.data->'image_urls') AS u(url)
           WHERE u.url ~ '^https?://'
             AND COALESCE(r.data->'image_mirror_map','{}'::jsonb) -> u.url IS NULL),
         jsonb_array_length(r.data->'image_urls')
  FROM public.records r
  WHERE r.model_id = public._listing_mirror_model_id()
    AND jsonb_typeof(r.data->'image_urls') = 'array'
    AND jsonb_array_length(r.data->'image_urls') > 0
    AND (NOT p_active_only OR COALESCE((r.data->>'is_active')::boolean, true))
    AND EXISTS (
      SELECT 1 FROM jsonb_array_elements_text(r.data->'image_urls') AS u(url)
      WHERE u.url ~ '^https?://'
        AND COALESCE(r.data->'image_mirror_map','{}'::jsonb) -> u.url IS NULL
    )
  ORDER BY r.created_at DESC
  LIMIT p_limit;
$function$;
CREATE OR REPLACE FUNCTION public.listing_mirror_enqueue(p_listing_id uuid, p_reason text DEFAULT 'manual'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_job_id  uuid;
  v_data    jsonb;
  v_missing int;
  v_depth   int;
  v_cap     int;
BEGIN
  SELECT r.data INTO v_data
  FROM public.records r
  WHERE r.id = p_listing_id AND r.model_id = public._listing_mirror_model_id();
  IF v_data IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT count(*) INTO v_missing
  FROM jsonb_array_elements_text(
         CASE WHEN jsonb_typeof(v_data->'image_urls') = 'array'
              THEN v_data->'image_urls' ELSE '[]'::jsonb END) AS u(url)
  WHERE u.url ~ '^https?://'
    AND COALESCE(v_data->'image_mirror_map', '{}'::jsonb) -> u.url IS NULL;

  IF v_missing = 0 THEN
    RETURN NULL;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.generation_jobs
    WHERE record_id = p_listing_id
      AND kind = 'listing-mirror'
      AND status IN ('queued','running')
  ) THEN
    RETURN NULL;
  END IF;

  SELECT s.max_queue_depth INTO v_cap FROM public.listing_mirror_settings s WHERE s.id;
  IF COALESCE(v_cap, 0) > 0 THEN
    SELECT count(*) INTO v_depth
    FROM public.generation_jobs
    WHERE kind = 'listing-mirror' AND status = 'queued';
    IF v_depth >= v_cap THEN
      RETURN NULL;
    END IF;
  END IF;

  v_job_id := gen_random_uuid();
  INSERT INTO public.generation_jobs (id, record_id, message_id, user_id, kind, status, prompt, params)
  VALUES (
    v_job_id, p_listing_id, NULL, NULL, 'listing-mirror', 'queued', NULL,
    jsonb_build_object('listing_id', p_listing_id, 'reason', p_reason, 'missing_at_enqueue', v_missing)
  );
  RETURN v_job_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.listing_mirror_map_patch(p_listing_id uuid, p_patch jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_rows int;
BEGIN
  IF p_patch IS NULL OR jsonb_typeof(p_patch) <> 'object' THEN
    RAISE EXCEPTION 'listing_mirror_map_patch: p_patch must be a jsonb object';
  END IF;

  UPDATE public.records r
  SET data = jsonb_set(
        r.data,
        '{image_mirror_map}',
        COALESCE(r.data->'image_mirror_map', '{}'::jsonb) || p_patch
      ),
      updated_at = now()
  WHERE r.id = p_listing_id;

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN
    RAISE EXCEPTION 'listing_mirror_map_patch: listing % not found', p_listing_id;
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.listing_mirror_stats(p_active_only boolean DEFAULT true)
 RETURNS TABLE(listings_total integer, listings_pending integer, photos_total integer, photos_mirrored integer, photos_pending integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '120s'
AS $function$
  WITH per_listing AS (
    SELECT r.id,
           count(*) FILTER (WHERE u.url ~ '^https?://')::int AS total,
           count(*) FILTER (
             WHERE u.url ~ '^https?://'
               AND COALESCE(r.data->'image_mirror_map','{}'::jsonb) -> u.url IS NULL
           )::int AS missing
    FROM public.records r
    CROSS JOIN LATERAL jsonb_array_elements_text(r.data->'image_urls') AS u(url)
    WHERE r.model_id = public._listing_mirror_model_id()
      AND jsonb_typeof(r.data->'image_urls') = 'array'
      AND (NOT p_active_only OR COALESCE((r.data->>'is_active')::boolean, true))
    GROUP BY r.id
  )
  SELECT count(*)::int,
         count(*) FILTER (WHERE missing > 0)::int,
         COALESCE(sum(total), 0)::int,
         COALESCE(sum(total - missing), 0)::int,
         COALESCE(sum(missing), 0)::int
  FROM per_listing;
$function$;
CREATE OR REPLACE FUNCTION public.mark_whatsapp_replied(p_client_id uuid, p_message_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_model_id uuid;
  v_msg_at   timestamptz := COALESCE(p_message_at, now());
  v_count    integer;
BEGIN
  IF p_client_id IS NULL THEN
    RETURN 0;
  END IF;

  SELECT id INTO v_model_id FROM public.models WHERE name = 'followups' LIMIT 1;
  IF v_model_id IS NULL THEN
    RETURN 0;
  END IF;

  -- 1. True reply to a check-in → mark 'replied' (v2 semantics, unchanged):
  --    the task must be WAITING and the message must postdate the send.
  UPDATE public.records r
  SET data = jsonb_set(r.data, '{whatsapp_state}', '"replied"'::jsonb, true)
  WHERE r.model_id = v_model_id
    AND COALESCE(NULLIF(r.data->>'followup_status', ''), 'open') IN ('open', 'in_progress')
    AND jsonb_typeof(r.data->'followup_type') = 'array'
    AND r.data->'followup_type' ? 'whatsapp_follow_up'
    AND r.data->>'client_id' = p_client_id::text
    AND r.data->>'whatsapp_state' = 'message_sent_waiting_response'
    AND v_msg_at >= COALESCE(public.try_timestamptz(r.data->>'sent_at'), '-infinity'::timestamptz);

  GET DIAGNOSTICS v_count = ROW_COUNT;

  -- 2. Early message on a FRESH task (no check-in sent yet) → NOT a reply;
  --    stamp client_messaged_at so the queue surfaces the task now while the
  --    rep keeps the full choice screen. Only advances (never rewinds), so
  --    webhook retries / re-deliveries of older messages are no-ops.
  UPDATE public.records r
  SET data = jsonb_set(r.data, '{client_messaged_at}', to_jsonb(v_msg_at), true)
  WHERE r.model_id = v_model_id
    AND COALESCE(NULLIF(r.data->>'followup_status', ''), 'open') IN ('open', 'in_progress')
    AND jsonb_typeof(r.data->'followup_type') = 'array'
    AND r.data->'followup_type' ? 'whatsapp_follow_up'
    AND r.data->>'client_id' = p_client_id::text
    AND COALESCE(r.data->>'whatsapp_state', '') = ''
    AND COALESCE(public.try_timestamptz(r.data->>'client_messaged_at'), '-infinity'::timestamptz) < v_msg_at;

  RETURN v_count;
END;
$function$;
CREATE OR REPLACE FUNCTION public.market_listing_bridge_property_keys()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_model uuid := '8f06bc39-4bee-42e9-9fab-77023fb89ede';
  v_n integer;
BEGIN
  WITH anchor AS (
    SELECT DISTINCT ON (data->>'ad_license_number')
           data->>'ad_license_number' AS lic, data->>'property_key' AS key
    FROM public.records
    WHERE model_id = v_model
      AND COALESCE(data->>'ad_license_number','') <> ''
      AND (data->>'property_tier')::int = 2
    ORDER BY data->>'ad_license_number', id
  )
  UPDATE public.records r
     SET data = r.data || jsonb_build_object('property_key', a.key, 'property_tier', 1)
    FROM anchor a
   WHERE r.model_id = v_model
     AND r.data->>'ad_license_number' = a.lic
     AND COALESCE((r.data->>'property_tier')::int, 9) <> 2
     AND r.data->>'property_key' IS DISTINCT FROM a.key;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $function$;
CREATE OR REPLACE FUNCTION public.market_listing_merge(p_id uuid, p_patch jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_patch jsonb;
  k text;
BEGIN
  -- A null in an incoming patch means "no value extracted this run", NOT "clear
  -- the stored value". Stripping nulls is what lets the DAILY push (pushToCrm)
  -- come through this RPC instead of PATCHing the whole `data` object: a full
  -- replace was erasing deed_number / ad_license_number / scraped_extras on
  -- every touched row (measured 2026-07-29: of 3,350 rows updated on 07-26,
  -- exactly 1 still had a deed), which is also what erases property_split and
  -- the REGA worker's advertiser_phone / rega_lookup_* set.
  v_patch := jsonb_strip_nulls(p_patch);
  -- ...except where an explicit null IS the new value: a listing that came back
  -- from 'sold' to 'active' must lose its sold_at.
  FOREACH k IN ARRAY ARRAY['sold_at'] LOOP
    IF p_patch ? k THEN v_patch := v_patch || jsonb_build_object(k, p_patch -> k); END IF;
  END LOOP;

  UPDATE public.records
     SET data = data || v_patch,
         updated_at = now()
   WHERE id = p_id
     AND model_id = '8f06bc39-4bee-42e9-9fab-77023fb89ede';
END $function$;
CREATE OR REPLACE FUNCTION public.market_listing_property_identity(d jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
  WITH v AS (
    SELECT
      NULLIF(btrim(COALESCE(d->>'deed_number', '')), '') AS deed,
      public.try_numeric(regexp_replace(COALESCE(d->>'area', ''), '[^0-9.]', '', 'g')) AS area,
      public.try_numeric(d->>'latitude')  AS lat,
      public.try_numeric(d->>'longitude') AS lng
  )
  SELECT CASE
    WHEN v.deed IS NOT NULL AND v.area > 0 AND v.lat IS NOT NULL AND v.lng IS NOT NULL THEN
      jsonb_build_object('property_key',
        'D:' || v.deed || ':' || floor(v.area)::text || ':' || round(v.lat,4)::text || ':' || round(v.lng,4)::text,
        'property_tier', 2)
    WHEN v.lat IS NOT NULL AND v.lng IS NOT NULL AND v.area > 0 THEN
      jsonb_build_object('property_key',
        'G:' || round(v.lat,4)::text || ':' || round(v.lng,4)::text || ':' || floor(v.area)::text,
        'property_tier', 3)
    ELSE jsonb_build_object('property_key', NULL, 'property_tier', NULL)
  END
  FROM v;
$function$;
CREATE OR REPLACE FUNCTION public.market_listing_quality(d jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  cls text;
  is_building boolean;
  core_filled int; core_expected int;
  sec_filled int; sec_expected int;
  img_full numeric; desc_full numeric; feat_full numeric;
  rating numeric; src_ts timestamptz; days numeric;
  completeness numeric; media numeric; description numeric;
  trust numeric; freshness numeric;
  score int; grade text;
BEGIN
  cls := CASE WHEN d->>'category' = 'أراضي-للبيع' THEN 'land'
              WHEN d->>'category' IN ('عمائر-للبيع','استراحة-للبيع') THEN 'mid'
              ELSE 'housing' END;
  is_building := d->>'category' = 'عمائر-للبيع';

  core_filled :=
      (CASE WHEN coalesce(public.try_numeric(d->>'price'), 0) > 0 THEN 1 ELSE 0 END)
    + (CASE WHEN coalesce(public.try_numeric(d->>'area'), 0) > 0 THEN 1 ELSE 0 END)
    + (CASE WHEN coalesce(d->>'property_type','') <> '' THEN 1 ELSE 0 END)
    + (CASE WHEN coalesce(d->'location'->>'district','') <> '' THEN 1 ELSE 0 END)
    + (CASE WHEN coalesce(d->>'title','') <> '' THEN 1 ELSE 0 END)
    + (CASE WHEN cls = 'land'
            THEN (CASE WHEN coalesce(public.try_numeric(d->>'street_width'), 0) > 0 THEN 1 ELSE 0 END)
               + (CASE WHEN coalesce(d->>'frontage','') <> '' THEN 1 ELSE 0 END)
            WHEN is_building THEN 0
            ELSE (CASE WHEN coalesce(d->>'bedrooms','') <> '' THEN 1 ELSE 0 END)
               + (CASE WHEN coalesce(d->>'bathrooms','') <> '' THEN 1 ELSE 0 END)
       END);
  core_expected := CASE WHEN is_building THEN 5 ELSE 7 END;

  IF cls = 'land' THEN
    sec_filled :=
        (CASE WHEN coalesce(d->>'street_name','') <> '' THEN 1 ELSE 0 END)
      + (CASE WHEN d->>'latitude' IS NOT NULL THEN 1 ELSE 0 END);
    sec_expected := 2;
  ELSIF is_building THEN
    sec_filled :=
        (CASE WHEN coalesce(d->>'age','') <> '' THEN 1 ELSE 0 END)
      + (CASE WHEN coalesce(d->>'street_name','') <> '' THEN 1 ELSE 0 END)
      + (CASE WHEN coalesce(d->>'frontage','') <> '' THEN 1 ELSE 0 END)
      + (CASE WHEN coalesce(d->>'floors_count','') <> '' THEN 1 ELSE 0 END)
      + (CASE WHEN d->>'latitude' IS NOT NULL THEN 1 ELSE 0 END);
    sec_expected := 5;
  ELSE
    sec_filled :=
        (CASE WHEN coalesce(d->>'age','') <> '' THEN 1 ELSE 0 END)
      + (CASE WHEN coalesce(d->>'street_name','') <> '' THEN 1 ELSE 0 END)
      + (CASE WHEN coalesce(d->>'frontage','') <> '' THEN 1 ELSE 0 END)
      + (CASE WHEN coalesce(d->>'living_rooms','') <> '' THEN 1 ELSE 0 END)
      + (CASE WHEN coalesce(d->>'floors_count','') <> '' THEN 1 ELSE 0 END)
      + (CASE WHEN d->>'latitude' IS NOT NULL THEN 1 ELSE 0 END);
    sec_expected := 6;
  END IF;

  completeness := 21.0 * core_filled / core_expected
                +  9.0 * sec_filled / sec_expected;

  img_full := CASE cls WHEN 'land' THEN 3 WHEN 'mid' THEN 5 ELSE 10 END;
  media := 20.0 * least(1.0, sqrt(coalesce(public.try_numeric(d->>'image_count'), 0) / img_full))
         + (CASE WHEN coalesce(public.try_numeric(d->>'video_count'), 0) > 0 THEN 5.0 ELSE 0 END);

  desc_full := CASE cls WHEN 'land' THEN 250 WHEN 'mid' THEN 300 ELSE 400 END;
  feat_full := CASE cls WHEN 'housing' THEN 5 ELSE 3 END;
  description := 14.0 * least(1.0, coalesce(public.try_numeric(d->>'description_char_count'), 0) / desc_full)
               +  6.0 * least(1.0, coalesce(public.try_numeric(d->>'feature_count'), 0) / feat_full);

  rating := public.try_numeric(d->>'advertiser_rating');
  trust := (CASE WHEN coalesce(d->>'ad_license_number','') <> '' THEN 7.5 ELSE 0 END)
         + (CASE WHEN coalesce(d->>'deed_number','') <> '' THEN 4.5 ELSE 0 END)
         + 3.0 * (CASE WHEN rating IS NULL OR rating = 4 THEN 0.5
                       ELSE greatest(0.0, least(1.0, (rating - 3) / 2)) END);

  src_ts := public.try_timestamptz(d->>'source_last_updated_at');
  IF src_ts IS NULL THEN
    freshness := 5.0;
  ELSE
    days := extract(epoch FROM now() - src_ts) / 86400.0;
    freshness := 10.0 * (CASE WHEN days <= 7 THEN 1.0
                              WHEN days >= 90 THEN 0.0
                              ELSE 1.0 - (days - 7) / 83.0 END);
  END IF;

  score := round(completeness + media + description + trust + freshness)::int;
  score := greatest(0, least(100, score));
  grade := CASE WHEN score >= 92 THEN 'A'
                WHEN score >= 83 THEN 'B'
                WHEN score >= 70 THEN 'C'
                ELSE 'D' END;

  RETURN jsonb_build_object(
    'quality_score', score,
    'quality_grade', grade,
    'quality_breakdown', jsonb_build_array(
      jsonb_build_object('البند', 'اكتمال البيانات', 'النقاط', round(completeness, 1), 'من', 30),
      jsonb_build_object('البند', 'الوسائط (صور وفيديو)', 'النقاط', round(media, 1), 'من', 25),
      jsonb_build_object('البند', 'الوصف والمميزات', 'النقاط', round(description, 1), 'من', 20),
      jsonb_build_object('البند', 'الموثوقية والترخيص', 'النقاط', round(trust, 1), 'من', 15),
      jsonb_build_object('البند', 'حداثة الإعلان', 'النقاط', round(freshness, 1), 'من', 10)));
END $function$;
CREATE OR REPLACE FUNCTION public.market_listing_set_split(p_ids uuid[], p_split boolean)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE v_n integer;
BEGIN
  UPDATE public.records
     SET data = CASE WHEN p_split THEN data || jsonb_build_object('property_split', true)
                     ELSE data - 'property_split' END
   WHERE model_id = '8f06bc39-4bee-42e9-9fab-77023fb89ede'
     AND id = ANY (p_ids)
     AND COALESCE((data->>'property_split')::boolean, false) IS DISTINCT FROM p_split;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_activity_trend(p_bucket text DEFAULT 'month'::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_org uuid DEFAULT NULL::uuid, p_project uuid DEFAULT NULL::uuid)
 RETURNS TABLE(bucket_start date, posts bigint, ads bigint, platforms bigint, organizations bigint, engagement bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH posts AS (
    SELECT date_trunc(coalesce(p_bucket,'month'), cp.published_at)::date AS b,
           cp.id, cp.platform, cp.organization_id,
           coalesce((cp.engagement->>'likes')::bigint,0)
         + coalesce((cp.engagement->>'comments')::bigint,0)
         + coalesce((cp.engagement->>'shares')::bigint,0)
         + coalesce((cp.engagement->>'views')::bigint,0) AS eng
    FROM mkt_content_posts cp
    WHERE cp.published_at IS NOT NULL
      AND (p_from IS NULL OR cp.published_at >= p_from)
      AND (p_to   IS NULL OR cp.published_at <  (p_to + 1))
      AND (p_org  IS NULL OR cp.organization_id = p_org)
      AND (p_project IS NULL OR EXISTS (
            SELECT 1 FROM mkt_content_attributions a
            WHERE a.content_post_id = cp.id AND a.project_id = p_project
              AND a.review_status IN ('auto_accepted','confirmed')))
  ),
  ads AS (
    SELECT date_trunc(coalesce(p_bucket,'month'),
                      coalesce(pa.platform_started_at, pa.first_seen_at))::date AS b,
           pa.id
    FROM mkt_paid_ads pa
    WHERE coalesce(pa.platform_started_at, pa.first_seen_at) IS NOT NULL
      AND (p_from IS NULL OR coalesce(pa.platform_started_at, pa.first_seen_at) >= p_from)
      AND (p_to   IS NULL OR coalesce(pa.platform_started_at, pa.first_seen_at) < (p_to + 1))
      AND (p_org  IS NULL OR pa.organization_id = p_org)
      AND p_project IS NULL   -- ads carry no project attribution yet
  ),
  buckets AS (SELECT b FROM posts UNION SELECT b FROM ads)
  SELECT k.b AS bucket_start,
         coalesce((SELECT count(DISTINCT p.id) FROM posts p WHERE p.b = k.b), 0),
         coalesce((SELECT count(DISTINCT a.id) FROM ads   a WHERE a.b = k.b), 0),
         coalesce((SELECT count(DISTINCT p.platform) FROM posts p WHERE p.b = k.b), 0),
         coalesce((SELECT count(DISTINCT p.organization_id) FROM posts p WHERE p.b = k.b), 0),
         coalesce((SELECT sum(p.eng) FROM posts p WHERE p.b = k.b), 0)
  FROM buckets k ORDER BY 1;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_ad_attribution_upsert(p_paid_ad_id uuid, p_project_id uuid, p_method text, p_confidence numeric, p_evidence jsonb DEFAULT '{}'::jsonb, p_auto_accept boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.mkt_ad_attributions (paid_ad_id, project_id, attribution_method, confidence, evidence, review_status)
  VALUES (p_paid_ad_id, p_project_id, p_method, p_confidence, COALESCE(p_evidence,'{}'::jsonb),
          CASE WHEN p_auto_accept THEN 'auto_accepted' ELSE 'candidate' END)
  ON CONFLICT (paid_ad_id, project_id) DO UPDATE SET
    confidence = GREATEST(mkt_ad_attributions.confidence, EXCLUDED.confidence),
    evidence = EXCLUDED.evidence,
    -- never downgrade a human-confirmed/rejected decision
    review_status = CASE WHEN mkt_ad_attributions.review_status IN ('confirmed','rejected')
                         THEN mkt_ad_attributions.review_status ELSE EXCLUDED.review_status END;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_ad_mark_removed(p_organization_id uuid, p_platform text, p_seen_ids text[], p_run_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; n int := 0;
BEGIN
  FOR r IN SELECT id, external_ad_id FROM public.mkt_paid_ads
            WHERE organization_id = p_organization_id AND platform = p_platform
              AND is_active = true AND NOT (external_ad_id = ANY(COALESCE(p_seen_ids,'{}')))
  LOOP
    UPDATE public.mkt_paid_ads SET is_active=false, platform_ended_at=now(), updated_at=now() WHERE id = r.id;
    INSERT INTO public.mkt_ad_history(paid_ad_id, change_type, old_value, run_id)
      VALUES (r.id, 'removed', to_jsonb(r.external_ad_id), p_run_id);
    n := n + 1;
  END LOOP;
  RETURN n;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_alert_emit(p_kind text, p_dedup_key text, p_title text, p_severity text DEFAULT 'warning'::text, p_subject_type text DEFAULT NULL::text, p_subject_id text DEFAULT NULL::text, p_body text DEFAULT NULL::text, p_evidence jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  INSERT INTO public.mkt_ops_alerts (kind, dedup_key, title, severity, subject_type, subject_id, body, evidence)
  VALUES (p_kind, p_dedup_key, p_title, p_severity, p_subject_type, p_subject_id, p_body, COALESCE(p_evidence,'{}'::jsonb))
  ON CONFLICT (dedup_key) DO UPDATE SET
    last_seen_at = now(),
    occurrences  = mkt_ops_alerts.occurrences + 1,
    title        = EXCLUDED.title,
    severity     = EXCLUDED.severity,
    body         = EXCLUDED.body,
    evidence     = EXCLUDED.evidence,
    status       = CASE WHEN mkt_ops_alerts.status = 'resolved' THEN 'open' ELSE mkt_ops_alerts.status END,
    resolved_at  = CASE WHEN mkt_ops_alerts.status = 'resolved' THEN NULL ELSE mkt_ops_alerts.resolved_at END
  RETURNING id INTO v_id;
  RETURN v_id;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_alert_emit(p_kind text, p_severity text, p_title_ar text, p_title_en text, p_target_type text, p_target_id uuid, p_evidence jsonb, p_dedup_key text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.mkt_mgmt_alerts
    (kind, severity, title_ar, title_en, target_type, target_id, evidence, dedup_key)
  VALUES (p_kind, p_severity, p_title_ar, p_title_en, p_target_type, p_target_id,
          COALESCE(p_evidence, '{}'::jsonb), p_dedup_key)
  ON CONFLICT (dedup_key) DO NOTHING;
  RETURN CASE WHEN FOUND THEN 1 ELSE 0 END;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_alert_resolve(p_kind text, p_subject_id text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  UPDATE public.mkt_ops_alerts SET status='resolved', resolved_at=now()
  WHERE kind=p_kind AND coalesce(subject_id,'')=coalesce(p_subject_id,'') AND status<>'resolved';
$function$;
CREATE OR REPLACE FUNCTION public.mkt_alert_set_status(p_id uuid, p_status text, p_user uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  UPDATE public.mkt_ops_alerts SET
    status = p_status,
    acknowledged_by = CASE WHEN p_status='acknowledged' THEN p_user ELSE acknowledged_by END,
    acknowledged_at = CASE WHEN p_status='acknowledged' THEN now() ELSE acknowledged_at END,
    resolved_at     = CASE WHEN p_status='resolved' THEN now() ELSE resolved_at END
  WHERE id = p_id;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_approved_artifact(p_deliverable_id uuid, p_type text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT id FROM public.mkt_content_versions
   WHERE deliverable_id = p_deliverable_id AND version_type = p_type
     AND approval_state = 'approved'
   ORDER BY version_number DESC LIMIT 1;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_asset_enqueue_processing(p_asset_ids uuid[] DEFAULT NULL::uuid[], p_limit integer DEFAULT 50)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_n int := 0; r record;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.wassell_mkt_can('write_content') THEN
    RAISE EXCEPTION 'your marketing role does not permit asset processing'
      USING ERRCODE='insufficient_privilege';
  END IF;

  FOR r IN
    SELECT a.id
    FROM public.mkt_raw_assets a
    WHERE a.archived_at IS NULL
      AND a.file_id IS NOT NULL
      AND (p_asset_ids IS NULL OR a.id = ANY(p_asset_ids))
      AND (p_asset_ids IS NOT NULL OR a.processing_status = 'not_attempted')
      -- never double-queue: an asset already pending/running is skipped even
      -- when explicitly named, so a double-click cannot spend twice
      AND NOT EXISTS (
        SELECT 1 FROM public.mkt_collection_jobs j
        WHERE j.kind = 'asset_process'
          AND j.status IN ('queued','running')
          AND (j.params ->> 'asset_id') = a.id::text)
    LIMIT greatest(1, least(coalesce(p_limit,50), 500))
  LOOP
    PERFORM public.mkt_job_enqueue('asset_process','internal',NULL,
      jsonb_build_object('asset_id', r.id::text), 45, NULL, NULL);
    UPDATE public.mkt_raw_assets SET processing_status='pending' WHERE id=r.id;
    v_n := v_n + 1;
  END LOOP;
  RETURN v_n;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_asset_processing_complete(p_asset_id uuid, p_status text, p_ocr_text text DEFAULT NULL::text, p_transcript text DEFAULT NULL::text, p_ai_description text DEFAULT NULL::text, p_tags text[] DEFAULT NULL::text[], p_error text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_status NOT IN ('completed','degraded','failed','unsupported') THEN
    RAISE EXCEPTION 'invalid processing status: %', p_status USING ERRCODE='check_violation';
  END IF;
  UPDATE public.mkt_raw_assets SET
    -- COALESCE, not overwrite: a degraded run that only got OCR must not wipe a
    -- transcript an earlier run produced.
    ocr_text         = COALESCE(NULLIF(p_ocr_text,''),        ocr_text),
    transcript       = COALESCE(NULLIF(p_transcript,''),      transcript),
    ai_description   = COALESCE(NULLIF(p_ai_description,''),  ai_description),
    tags             = CASE WHEN p_tags IS NULL OR array_length(p_tags,1) IS NULL
                            THEN tags ELSE p_tags END,
    processing_status = p_status,
    processing_error  = p_error,
    updated_at        = now()
  WHERE id = p_asset_id;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_attribution_upsert(p_content_post_id uuid, p_project_id uuid, p_method text, p_confidence numeric, p_evidence jsonb DEFAULT '{}'::jsonb, p_matched_aliases text[] DEFAULT '{}'::text[], p_auto_accept boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_status text;
BEGIN
  SELECT id, review_status INTO v_id, v_status FROM public.mkt_content_attributions
   WHERE content_post_id = p_content_post_id AND project_id = p_project_id;
  IF v_id IS NULL THEN
    INSERT INTO public.mkt_content_attributions
      (content_post_id, project_id, attribution_method, confidence, evidence, matched_aliases, review_status)
    VALUES (p_content_post_id, p_project_id, p_method, p_confidence, COALESCE(p_evidence,'{}'::jsonb),
            COALESCE(p_matched_aliases,'{}'),
            CASE WHEN p_auto_accept THEN 'auto_accepted' ELSE 'candidate' END)
    RETURNING id INTO v_id;
  ELSIF v_status IN ('confirmed','rejected') THEN
    NULL;
  ELSE
    UPDATE public.mkt_content_attributions SET
      attribution_method = CASE WHEN p_confidence >= confidence THEN p_method ELSE attribution_method END,
      confidence         = GREATEST(confidence, p_confidence),
      evidence           = COALESCE(p_evidence, evidence),
      matched_aliases    = CASE WHEN array_length(p_matched_aliases,1) IS NULL THEN matched_aliases ELSE p_matched_aliases END,
      review_status      = CASE WHEN p_auto_accept AND review_status='candidate' THEN 'auto_accepted' ELSE review_status END,
      updated_at         = now()
    WHERE id = v_id;
  END IF;
  RETURN v_id;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_campaign_activation_blockers(p_campaign_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c record; missing text[];
BEGIN
  SELECT * INTO c FROM public.mkt_internal_campaigns WHERE id = p_campaign_id;
  IF c IS NULL THEN RETURN ARRAY['not_found']; END IF;
  missing := public.mkt_campaign_missing_requirements(p_campaign_id);
  IF c.campaign_class = 'paid' AND NOT EXISTS (
       SELECT 1 FROM public.mkt_platform_campaigns WHERE campaign_id = p_campaign_id) THEN
    missing := array_append(missing, 'platform_campaign');
  END IF;
  RETURN missing;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_campaign_classify(p_campaign_id uuid, p_class text, p_plan_id uuid DEFAULT NULL::uuid, p_goal_id uuid DEFAULT NULL::uuid, p_initiative_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c record; v_before text;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.wassell_mkt_can('write_campaign') THEN
    RAISE EXCEPTION 'MKT:not_permitted' USING ERRCODE = '42501';
  END IF;
  IF p_class IS NULL OR p_class NOT IN ('organic', 'paid') THEN
    RAISE EXCEPTION 'MKT:campaign_class_required' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO c FROM public.mkt_internal_campaigns WHERE id = p_campaign_id;
  IF c IS NULL THEN RAISE EXCEPTION 'MKT:not_found' USING ERRCODE = 'no_data_found'; END IF;
  v_before := c.campaign_class;

  UPDATE public.mkt_internal_campaigns SET
    campaign_class  = p_class,
    channel_mix     = CASE WHEN channel_mix = 'both' THEN channel_mix ELSE p_class END,
    plan_id         = COALESCE(p_plan_id, plan_id),
    primary_goal_id = COALESCE(p_goal_id, primary_goal_id),
    initiative_id   = COALESCE(p_initiative_id, initiative_id)
  WHERE id = p_campaign_id;

  SELECT * INTO c FROM public.mkt_internal_campaigns WHERE id = p_campaign_id;
  RETURN jsonb_build_object(
    'campaign_id', p_campaign_id,
    'class_before', v_before,
    'class_after', c.campaign_class,
    'needs_classification', c.needs_classification,
    'missing', to_jsonb(public.mkt_campaign_missing_requirements(p_campaign_id))
  );
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_campaign_content_counts(p_campaign_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH produced AS (
    SELECT id FROM public.mkt_content_items
     WHERE origin_campaign_id = p_campaign_id AND archived_at IS NULL),
  reused AS (
    SELECT DISTINCT u.content_item_id AS id
      FROM public.mkt_content_usage u
      JOIN public.mkt_content_items ci ON ci.id = u.content_item_id AND ci.archived_at IS NULL
     WHERE u.campaign_id = p_campaign_id
       AND u.content_item_id NOT IN (SELECT id FROM produced)),
  legacy AS (
    SELECT id FROM public.mkt_content_items
     WHERE campaign_id = p_campaign_id AND archived_at IS NULL
       AND (origin_campaign_id IS NULL OR origin_campaign_id <> p_campaign_id)
       AND id NOT IN (SELECT id FROM reused)),
  paid_creative AS (
    SELECT DISTINCT a.content_item_id AS id
      FROM public.mkt_ads a
      JOIN public.mkt_ad_groups g ON g.id = a.ad_group_id
      JOIN public.mkt_platform_campaigns pc ON pc.id = g.platform_campaign_id
     WHERE pc.campaign_id = p_campaign_id AND a.content_item_id IS NOT NULL),
  uniq AS (
    SELECT id FROM produced UNION SELECT id FROM reused
    UNION SELECT id FROM legacy UNION SELECT id FROM paid_creative)
  SELECT jsonb_build_object(
    'produced_content_count',  (SELECT count(*) FROM produced),
    'reused_content_count',    (SELECT count(*) FROM reused),
    'legacy_content_count',    (SELECT count(*) FROM legacy),
    'paid_creative_count',     (SELECT count(*) FROM paid_creative),
    'unique_content_count',    (SELECT count(*) FROM uniq),
    'approved_content_count',  (SELECT count(*) FROM public.mkt_content_items
                                 WHERE id IN (SELECT id FROM uniq)
                                   AND status IN ('approved','ready_to_publish','scheduled','published')),
    'published_content_count', (SELECT count(*) FROM public.mkt_content_items
                                 WHERE id IN (SELECT id FROM uniq) AND status = 'published'));
$function$;
CREATE OR REPLACE FUNCTION public.mkt_campaign_event_emit(p_campaign uuid, p_kind text, p_dedup text, p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  INSERT INTO public.mkt_campaign_events(campaign_id,kind,dedup_key,payload)
  VALUES (p_campaign,p_kind,p_dedup,COALESCE(p_payload,'{}'::jsonb))
  ON CONFLICT (dedup_key) DO NOTHING RETURNING id INTO v_id;
  RETURN v_id;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_campaign_evidence(p_campaign_ids uuid[])
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(jsonb_agg(ev ORDER BY ev->>'campaign_id'), '[]'::jsonb) FROM (
    SELECT jsonb_build_object(
      'campaign_id',   c.id,
      'label',         coalesce(c.manual_label, c.label),
      'organization',  (SELECT coalesce(o.name_en, o.name_ar) FROM mkt_organizations o WHERE o.id = c.organization_id),
      'objective',     c.objective,
      'platforms',     to_jsonb(c.platforms),
      'is_active',     c.is_active,
      'first_seen_at', c.first_seen_at,
      'last_seen_at',  c.last_seen_at,
      'member_count',  c.member_count,
      'organic_count', c.organic_count,
      'paid_count',    c.paid_count,
      'reused_creatives', c.reused_creatives,
      'offers',        to_jsonb(c.offers),
      'payment_plans', to_jsonb(c.payment_plans),
      'ctas',          to_jsonb(c.ctas),
      'key_message',   c.key_message,
      'project', (
        SELECT jsonb_build_object('project_id', c.project_id, 'name', r.data->>'project_name')
        FROM unified_records r WHERE r.id = c.project_id
      ),
      'members', coalesce(m.members, '[]'::jsonb),
      'members_included', coalesce(m.n, 0),
      'members_omitted',  greatest(0, c.member_count - coalesce(m.n, 0)),
      'sibling_campaigns', coalesce(sib.rows, '[]'::jsonb),
      'siblings_omitted', greatest(0, coalesce(sib.total, 0) - coalesce(sib.n, 0))
    ) AS ev
    FROM mkt_campaigns c
    LEFT JOIN LATERAL (
      SELECT jsonb_agg(mm) AS members, count(*) AS n
      FROM (
        SELECT jsonb_build_object(
          'member_type', cm.member_type,
          'post_id',     cm.content_post_id,
          'ad_id',       cm.paid_ad_id,
          'platform',    coalesce(cp.platform, 'meta'),
          'post_type',   cp.post_type,
          'published_at', coalesce(cp.published_at, pa.first_seen_at),
          'url',         coalesce(cp.post_url, pa.landing_url),
          'caption',     left(coalesce(cp.caption, pa.headline, ''), 1200),
          'caption_full_length', length(coalesce(cp.caption, pa.headline, '')),
          'transcript',  left(coalesce((SELECT string_agg(nullif(t.text,''), ' ')
                                        FROM mkt_transcripts t
                                        WHERE t.content_post_id = cp.id AND t.status='done'), ''), 2500),
          'ocr_text',    left(coalesce((SELECT string_agg(nullif(v.text,''), ' | ')
                                        FROM mkt_visual_text v
                                        WHERE v.content_post_id = cp.id), ''), 1500),
          'engagement',  cp.engagement,
          'enrichment',  (SELECT jsonb_build_object('content_type', e.result->>'content_type',
                                                    'offer', e.result->>'offer',
                                                    'price', e.result->>'price',
                                                    'district', e.result->>'district',
                                                    'campaign_message', e.result->>'campaign_message')
                          FROM mkt_content_enrichment e WHERE e.content_post_id = cp.id)
        ) AS mm
        FROM mkt_campaign_members cm
        LEFT JOIN mkt_content_posts cp ON cp.id = cm.content_post_id
        LEFT JOIN mkt_paid_ads      pa ON pa.id = cm.paid_ad_id
        WHERE cm.campaign_id = c.id
        ORDER BY coalesce(cp.published_at, pa.first_seen_at) DESC NULLS LAST
        LIMIT 40
      ) z
    ) m ON true
    LEFT JOIN LATERAL (
      SELECT jsonb_agg(ss) AS rows, count(*) AS n,
             (SELECT count(*) FROM mkt_campaigns s2
               WHERE s2.organization_id = c.organization_id AND s2.id <> c.id) AS total
      FROM (
        SELECT jsonb_build_object(
                 'campaign_id', s.id, 'label', coalesce(s.manual_label, s.label),
                 'objective', s.objective, 'platforms', to_jsonb(s.platforms),
                 'member_count', s.member_count, 'is_active', s.is_active,
                 'key_message', s.key_message) AS ss
        FROM mkt_campaigns s
        WHERE s.organization_id = c.organization_id AND s.id <> c.id
        ORDER BY s.last_seen_at DESC NULLS LAST
        LIMIT 10
      ) y
    ) sib ON true
    WHERE c.id = ANY(p_campaign_ids)
  ) s;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_campaign_member_upsert(p_campaign uuid, p_member_type text, p_content_post uuid, p_paid_ad uuid, p_signals jsonb)
 RETURNS TABLE(id uuid, was_inserted boolean, moved boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_existing record; v_id uuid; v_ins boolean := false; v_moved boolean := false;
BEGIN
  SELECT * INTO v_existing FROM public.mkt_campaign_members
   WHERE (p_content_post IS NOT NULL AND content_post_id = p_content_post)
      OR (p_paid_ad IS NOT NULL AND paid_ad_id = p_paid_ad)
   LIMIT 1;
  IF v_existing.id IS NOT NULL THEN
    IF v_existing.status IN ('confirmed','rejected','moved') THEN
      RETURN QUERY SELECT v_existing.id, false, false; RETURN;
    END IF;
    IF v_existing.campaign_id <> p_campaign THEN v_moved := true; END IF;
    UPDATE public.mkt_campaign_members SET campaign_id=p_campaign, signals=COALESCE(p_signals,'{}'::jsonb)
     WHERE mkt_campaign_members.id=v_existing.id RETURNING mkt_campaign_members.id INTO v_id;
    RETURN QUERY SELECT v_id, false, v_moved; RETURN;
  END IF;
  INSERT INTO public.mkt_campaign_members(campaign_id,member_type,content_post_id,paid_ad_id,signals,status)
  VALUES (p_campaign,p_member_type,p_content_post,p_paid_ad,COALESCE(p_signals,'{}'::jsonb),'auto')
  RETURNING mkt_campaign_members.id INTO v_id; v_ins := true;
  RETURN QUERY SELECT v_id, v_ins, false;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_campaign_merge(p_src uuid, p_dst uuid, p_actor uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE mkt_campaign_members SET campaign_id=p_dst, status=CASE WHEN status='auto' THEN 'moved' ELSE status END WHERE campaign_id=p_src;
  INSERT INTO mkt_campaign_corrections(action,campaign_id,to_campaign_id,actor_user_id) VALUES ('merge',p_src,p_dst,p_actor);
  DELETE FROM mkt_campaigns WHERE id=p_src;
  PERFORM mkt_campaign_refresh_rollups(p_dst);
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_campaign_missing_requirements(p_campaign_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c record; missing text[] := '{}';
BEGIN
  SELECT * INTO c FROM public.mkt_internal_campaigns WHERE id = p_campaign_id;
  IF c IS NULL THEN RETURN ARRAY['not_found']; END IF;
  IF c.campaign_class IS NULL       THEN missing := array_append(missing, 'campaign_class'); END IF;
  IF c.plan_id IS NULL              THEN missing := array_append(missing, 'plan'); END IF;
  IF c.primary_goal_id IS NULL      THEN missing := array_append(missing, 'primary_goal'); END IF;
  IF c.owner_user_id IS NULL        THEN missing := array_append(missing, 'owner'); END IF;
  IF c.start_date IS NULL           THEN missing := array_append(missing, 'start_date'); END IF;
  IF c.end_date IS NULL             THEN missing := array_append(missing, 'end_date'); END IF;
  IF c.objective IS NULL OR btrim(c.objective) = ''
                                    THEN missing := array_append(missing, 'objective'); END IF;
  IF COALESCE(CASE WHEN jsonb_typeof(c.deliverables) = 'array'
                   THEN jsonb_array_length(c.deliverables) END, 0) = 0
                                    THEN missing := array_append(missing, 'deliverables'); END IF;
  RETURN missing;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_campaign_move_member(p_member uuid, p_to_campaign uuid, p_actor uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_from uuid;
BEGIN
  SELECT campaign_id INTO v_from FROM mkt_campaign_members WHERE id=p_member;
  UPDATE mkt_campaign_members SET campaign_id=p_to_campaign, status='moved' WHERE id=p_member;
  INSERT INTO mkt_campaign_corrections(action,campaign_id,to_campaign_id,member_id,actor_user_id) VALUES ('move',v_from,p_to_campaign,p_member,p_actor);
  PERFORM mkt_campaign_refresh_rollups(v_from); PERFORM mkt_campaign_refresh_rollups(p_to_campaign);
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_campaign_next_statuses(p_campaign_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c record; s text; res jsonb := '[]'::jsonb; blockers text[];
BEGIN
  SELECT * INTO c FROM public.mkt_internal_campaigns WHERE id = p_campaign_id;
  IF c IS NULL THEN RETURN res; END IF;
  blockers := public.mkt_campaign_activation_blockers(p_campaign_id);
  FOREACH s IN ARRAY ARRAY['draft','planned','active','paused','completed','cancelled','archived'] LOOP
    CONTINUE WHEN s = c.status;
    CONTINUE WHEN NOT public.mkt_campaign_status_allowed(c.status, s);
    res := res || jsonb_build_object(
      'status', s,
      'allowed', CASE WHEN s IN ('planned','active') THEN array_length(blockers,1) IS NULL ELSE true END,
      'blockers', CASE WHEN s IN ('planned','active')
                       THEN to_jsonb(COALESCE(blockers, ARRAY[]::text[])) ELSE '[]'::jsonb END);
  END LOOP;
  RETURN res;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_campaign_progress(p_campaign_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c record; counts jsonb; req int; done int; tgt numeric; act numeric;
        deliv jsonb; pub jsonb; outcome jsonb;
BEGIN
  SELECT * INTO c FROM public.mkt_internal_campaigns WHERE id = p_campaign_id;
  IF c IS NULL THEN RETURN NULL; END IF;
  counts := public.mkt_campaign_content_counts(p_campaign_id);

  SELECT COALESCE(sum(COALESCE((d->>'required')::int, 0)), 0),
         COALESCE(sum(COALESCE((d->>'completed')::int, 0)), 0)
    INTO req, done
    FROM jsonb_array_elements(CASE WHEN jsonb_typeof(c.deliverables) = 'array'
                                   THEN c.deliverables ELSE '[]'::jsonb END) d;
  deliv := CASE WHEN COALESCE(req, 0) = 0
                THEN jsonb_build_object('state', 'no_target')
                ELSE jsonb_build_object('state', 'measured', 'done', done, 'total', req) END;

  pub := CASE WHEN (counts->>'approved_content_count')::int = 0
              THEN jsonb_build_object('state', 'no_target')
              ELSE jsonb_build_object('state', 'measured',
                     'done',  (counts->>'published_content_count')::int,
                     'total', (counts->>'approved_content_count')::int) END;

  tgt := c.target_leads;
  act := NULLIF(c.actual_results->>'leads', '')::numeric;
  outcome := CASE
    WHEN tgt IS NULL THEN jsonb_build_object('state', 'no_target')
    WHEN act IS NULL THEN jsonb_build_object('state', 'awaiting_data', 'total', tgt)
    ELSE jsonb_build_object('state', 'measured', 'done', act, 'total', tgt) END;

  RETURN jsonb_build_object(
    'deliverables', deliv, 'publication', pub, 'outcome', outcome,
    'metric', 'leads', 'counts', counts);
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_campaign_refresh(p_campaign uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_total int; v_active int; v_was_active boolean;
BEGIN
  SELECT count(*), count(*) FILTER (WHERE is_active) INTO v_total, v_active FROM public.mkt_paid_ads WHERE campaign_id=p_campaign;
  SELECT is_active INTO v_was_active FROM public.mkt_ad_campaigns WHERE id=p_campaign;
  UPDATE public.mkt_ad_campaigns SET ad_count=v_total, active_ad_count=v_active,
    is_active=(v_active>0), ended_at=CASE WHEN v_active=0 AND ended_at IS NULL THEN now() ELSE ended_at END,
    updated_at=now() WHERE id=p_campaign;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_campaign_refresh_rollups(p_campaign uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.mkt_campaigns c SET
    member_count = (SELECT count(*) FROM mkt_campaign_members m WHERE m.campaign_id=c.id AND m.status<>'rejected'),
    organic_count = (SELECT count(*) FROM mkt_campaign_members m WHERE m.campaign_id=c.id AND m.member_type='content' AND m.status<>'rejected'),
    paid_count = (SELECT count(*) FROM mkt_campaign_members m WHERE m.campaign_id=c.id AND m.member_type='ad' AND m.status<>'rejected'),
    updated_at = now()
  WHERE c.id=p_campaign;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_campaign_rename(p_campaign uuid, p_label text, p_actor uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE mkt_campaigns SET manual_label=p_label, label=COALESCE(p_label,label), updated_at=now() WHERE id=p_campaign;
  INSERT INTO mkt_campaign_corrections(action,campaign_id,detail,actor_user_id) VALUES ('rename',p_campaign,jsonb_build_object('label',p_label),p_actor);
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_campaign_set_member_status(p_member uuid, p_status text, p_actor uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_c uuid;
BEGIN
  UPDATE mkt_campaign_members SET status=p_status WHERE id=p_member RETURNING campaign_id INTO v_c;
  INSERT INTO mkt_campaign_corrections(action,campaign_id,member_id,detail,actor_user_id) VALUES (p_status,v_c,p_member,jsonb_build_object('status',p_status),p_actor);
  PERFORM mkt_campaign_refresh_rollups(v_c);
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_campaign_status_allowed(p_from text, p_to text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE
    WHEN p_from IS NULL       THEN p_to = 'draft'
    WHEN p_from = p_to        THEN true
    WHEN p_from = 'draft'     THEN p_to IN ('planned', 'cancelled')
    WHEN p_from = 'planned'   THEN p_to IN ('active', 'draft', 'cancelled')
    WHEN p_from = 'active'    THEN p_to IN ('paused', 'completed', 'cancelled')
    WHEN p_from = 'paused'    THEN p_to IN ('active', 'completed', 'cancelled')
    WHEN p_from = 'completed' THEN p_to = 'archived'
    WHEN p_from = 'cancelled' THEN p_to = 'archived'
    WHEN p_from = 'archived'  THEN false
    ELSE false
  END;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_campaign_summary_upsert(p_campaign uuid, p_org uuid, p_model text, p_skill_version text, p_result jsonb, p_evidence_refs jsonb, p_confidence numeric, p_cost numeric, p_status text, p_failure text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_members int; v_last timestamptz;
BEGIN
  SELECT member_count, last_seen_at INTO v_members, v_last
  FROM public.mkt_campaigns WHERE id = p_campaign;

  INSERT INTO public.mkt_campaign_summaries(
    campaign_id, organization_id, model, skill_version, result, evidence_refs,
    confidence, cost_usd, status, failure_reason,
    member_count_at_summary, last_seen_at_at_summary)
  VALUES (p_campaign, p_org, p_model, p_skill_version,
          COALESCE(p_result,'{}'::jsonb), COALESCE(p_evidence_refs,'[]'::jsonb),
          COALESCE(p_confidence,0), COALESCE(p_cost,0), COALESCE(p_status,'done'), p_failure,
          COALESCE(v_members,0), v_last)
  ON CONFLICT (campaign_id) DO UPDATE SET
    organization_id = EXCLUDED.organization_id, model = EXCLUDED.model,
    skill_version = EXCLUDED.skill_version, result = EXCLUDED.result,
    evidence_refs = EXCLUDED.evidence_refs, confidence = EXCLUDED.confidence,
    cost_usd = EXCLUDED.cost_usd, status = EXCLUDED.status,
    failure_reason = EXCLUDED.failure_reason,
    member_count_at_summary = EXCLUDED.member_count_at_summary,
    last_seen_at_at_summary = EXCLUDED.last_seen_at_at_summary,
    updated_at = now()
  RETURNING id INTO v_id;
  RETURN v_id;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_campaign_upsert(p_signature text, p_organization_id uuid, p_advertiser_name text, p_landing_page_id uuid DEFAULT NULL::uuid, p_cta text DEFAULT NULL::text, p_headline text DEFAULT NULL::text, p_run_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, was_inserted boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_new boolean := false;
BEGIN
  SELECT c.id INTO v_id FROM public.mkt_ad_campaigns c WHERE c.platform='meta' AND c.signature=p_signature;
  IF v_id IS NULL THEN
    INSERT INTO public.mkt_ad_campaigns (platform, signature, organization_id, advertiser_name, landing_page_id, primary_cta, primary_headline)
    VALUES ('meta', p_signature, p_organization_id, p_advertiser_name, p_landing_page_id, p_cta, p_headline)
    RETURNING mkt_ad_campaigns.id INTO v_id;
    v_new := true;
  ELSE
    UPDATE public.mkt_ad_campaigns c SET last_seen_at=now(), updated_at=now(),
      advertiser_name=COALESCE(c.advertiser_name, p_advertiser_name),
      primary_cta=COALESCE(c.primary_cta, p_cta),
      primary_headline=COALESCE(c.primary_headline, p_headline),
      landing_page_id=COALESCE(c.landing_page_id, p_landing_page_id)
    WHERE c.id=v_id;
  END IF;
  RETURN QUERY SELECT v_id, v_new;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_campaign_upsert(p_signature text, p_org uuid, p_project uuid, p_label text, p_objective text, p_platforms text[], p_first timestamp with time zone, p_last timestamp with time zone, p_active boolean, p_offers text[], p_payment_plans text[], p_ctas text[], p_key_message text, p_reused integer, p_confidence numeric, p_evidence jsonb, p_version text)
 RETURNS TABLE(id uuid, was_inserted boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_ins boolean := false;
BEGIN
  INSERT INTO public.mkt_campaigns(signature,organization_id,project_id,label,objective,platforms,first_seen_at,last_seen_at,is_active,offers,payment_plans,ctas,key_message,reused_creatives,confidence,evidence,grouping_version)
  VALUES (p_signature,p_org,p_project,p_label,p_objective,COALESCE(p_platforms,'{}'),p_first,p_last,COALESCE(p_active,true),COALESCE(p_offers,'{}'),COALESCE(p_payment_plans,'{}'),COALESCE(p_ctas,'{}'),p_key_message,COALESCE(p_reused,0),COALESCE(p_confidence,0),COALESCE(p_evidence,'{}'::jsonb),COALESCE(p_version,'cg-v1'))
  ON CONFLICT (signature) DO UPDATE SET
    project_id=COALESCE(EXCLUDED.project_id, mkt_campaigns.project_id),
    label=COALESCE(mkt_campaigns.manual_label, EXCLUDED.label),
    objective=EXCLUDED.objective, platforms=EXCLUDED.platforms,
    first_seen_at=LEAST(mkt_campaigns.first_seen_at, EXCLUDED.first_seen_at),
    last_seen_at=GREATEST(mkt_campaigns.last_seen_at, EXCLUDED.last_seen_at),
    is_active=EXCLUDED.is_active, offers=EXCLUDED.offers, payment_plans=EXCLUDED.payment_plans,
    ctas=EXCLUDED.ctas, key_message=EXCLUDED.key_message, reused_creatives=EXCLUDED.reused_creatives,
    confidence=EXCLUDED.confidence, evidence=EXCLUDED.evidence, updated_at=now()
  RETURNING mkt_campaigns.id, (xmax = 0) INTO v_id, v_ins;
  RETURN QUERY SELECT v_id, v_ins;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_capacity_status(p_channel_plan_id uuid, p_week_start date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  ch record;
  v_prog int; v_camp int; v_reactive int; v_available int;
  v_requests jsonb;
BEGIN
  SELECT * INTO ch FROM public.mkt_channel_plans WHERE id = p_channel_plan_id;
  IF ch IS NULL THEN RETURN NULL; END IF;

  SELECT COALESCE(sum(slots_requested), 0) INTO v_prog
    FROM public.mkt_capacity_allocations
    WHERE channel_plan_id = p_channel_plan_id AND week_start = p_week_start
      AND allocation_kind = 'program_reservation';

  SELECT COALESCE(sum(slots_requested), 0) INTO v_camp
    FROM public.mkt_capacity_allocations
    WHERE channel_plan_id = p_channel_plan_id AND week_start = p_week_start
      AND allocation_kind = 'campaign_allocation';

  SELECT COALESCE(sum(slots_requested), ch.reactive_reserve) INTO v_reactive
    FROM public.mkt_capacity_allocations
    WHERE channel_plan_id = p_channel_plan_id AND week_start = p_week_start
      AND allocation_kind = 'reactive_reserve';

  v_available := CASE WHEN ch.max_per_week IS NULL THEN NULL
                      ELSE ch.max_per_week - v_prog - COALESCE(v_reactive, 0) END;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'allocation_id', a.id,
           'campaign_id',   a.campaign_id,
           'code',          c.code,
           'name_ar',       c.name_ar,
           'requested',     a.slots_requested,
           'granted',       a.slots_granted
         ) ORDER BY a.slots_requested DESC), '[]'::jsonb)
    INTO v_requests
    FROM public.mkt_capacity_allocations a
    JOIN public.mkt_internal_campaigns c ON c.id = a.campaign_id
   WHERE a.channel_plan_id = p_channel_plan_id AND a.week_start = p_week_start
     AND a.allocation_kind = 'campaign_allocation';

  RETURN jsonb_build_object(
    'channel_plan_id',  p_channel_plan_id,
    'platform',         ch.platform,
    'account_handle',   ch.account_handle,
    'week_start',       p_week_start,
    'capacity_configured', ch.max_per_week IS NOT NULL,
    'week_capacity',    ch.max_per_week,
    'program_reserved', v_prog,
    'reactive_reserved', COALESCE(v_reactive, 0),
    'campaign_available', v_available,
    'campaign_requested', v_camp,
    'over_allocated_by', CASE WHEN v_available IS NULL THEN NULL
                              WHEN v_camp > v_available THEN v_camp - v_available
                              ELSE 0 END,
    'is_over_allocated', CASE WHEN v_available IS NULL THEN NULL
                              ELSE v_camp > v_available END,
    'campaign_requests', v_requests
  );
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_check_processing_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_window    numeric := mkt_setting_num('ops_processing_window_hours', 24);
  v_min_n     numeric := mkt_setting_num('ops_processing_min_sample', 10);
  v_deg_ratio numeric := mkt_setting_num('ops_processing_degraded_ratio', 0.5);
  v_fail_n    numeric := mkt_setting_num('ops_processing_failure_alert', 3);
  v_since     timestamptz;
  v_total int; v_failed int; v_degraded int; v_infra int;
  v_ratio numeric;
BEGIN
  v_since := now() - (v_window * interval '1 hour');

  SELECT
    count(*) FILTER (WHERE status IN ('succeeded','failed')),
    count(*) FILTER (WHERE status = 'failed'),
    count(*) FILTER (WHERE status = 'succeeded'
                       AND (result->>'degraded' = 'true'
                            OR jsonb_array_length(COALESCE(result->'errors','[]'::jsonb)) > 0)),
    count(*) FILTER (WHERE COALESCE(error_message,'') ILIKE '%vision(infrastructure)%'
                        OR COALESCE(result::text,'') ILIKE '%vision(infrastructure)%')
  INTO v_total, v_failed, v_degraded, v_infra
  FROM public.mkt_collection_jobs
  WHERE kind = 'content_process' AND finished_at >= v_since;

  v_ratio := CASE WHEN v_total > 0 THEN round(v_degraded::numeric / v_total, 3) ELSE 0 END;

  IF v_infra > 0 THEN
    PERFORM mkt_alert_emit(
      'processing_infrastructure', 'processing_infrastructure',
      'تعطّل في معالجة المحتوى — سبب خارجي', 'critical', 'system', 'content_process',
      v_infra || ' مهمة تعذّر فيها استخراج النص من الصور (رصيد/مصادقة/حد استخدام)',
      jsonb_build_object('window_hours', v_window, 'affected_jobs', v_infra,
                         'hint', 'check Anthropic credit balance and API key'));
  ELSE
    PERFORM mkt_alert_resolve('processing_infrastructure', 'content_process');
  END IF;

  IF v_failed >= v_fail_n THEN
    PERFORM mkt_alert_emit(
      'processing_failures', 'processing_failures',
      'إخفاق في معالجة المحتوى', 'critical', 'system', 'content_process',
      v_failed || ' من ' || v_total || ' مهمة أخفقت',
      jsonb_build_object('window_hours', v_window, 'failed', v_failed, 'total', v_total,
                         'threshold', v_fail_n));
  ELSE
    PERFORM mkt_alert_resolve('processing_failures', 'content_process');
  END IF;

  IF v_total >= v_min_n AND v_ratio >= v_deg_ratio THEN
    PERFORM mkt_alert_emit(
      'processing_degraded', 'processing_degraded',
      'معالجة المحتوى ناقصة', 'warning', 'system', 'content_process',
      round(v_ratio * 100) || '% من المهام اكتملت بشكل جزئي',
      jsonb_build_object('window_hours', v_window, 'degraded', v_degraded,
                         'total', v_total, 'ratio', v_ratio, 'threshold', v_deg_ratio));
  ELSE
    PERFORM mkt_alert_resolve('processing_degraded', 'content_process');
  END IF;

  RETURN jsonb_build_object('window_hours', v_window, 'total', v_total, 'failed', v_failed,
                            'degraded', v_degraded, 'degraded_ratio', v_ratio,
                            'infrastructure', v_infra);
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_compute_share_of_voice(p_from date, p_to date, p_scope_type text DEFAULT 'market'::text, p_scope_key text DEFAULT ''::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_rows integer;
BEGIN
  WITH posts AS (
    SELECT cp.organization_id, cp.id,
           coalesce((cp.engagement->>'likes')::bigint,0)
         + coalesce((cp.engagement->>'comments')::bigint,0)
         + coalesce((cp.engagement->>'shares')::bigint,0)
         + coalesce((cp.engagement->>'views')::bigint,0) AS eng
    FROM mkt_content_posts cp
    WHERE cp.published_at >= p_from AND cp.published_at < (p_to + 1)
      AND cp.organization_id IS NOT NULL
      AND (p_scope_type = 'market' OR EXISTS (
            SELECT 1 FROM mkt_observed_facts f
            WHERE f.content_post_id = cp.id
              AND f.fact_type = CASE p_scope_type WHEN 'district' THEN 'district' ELSE 'city' END
              AND f.normalized_key = mkt_fact_norm_key(
                    CASE p_scope_type WHEN 'district' THEN 'district' ELSE 'city' END, p_scope_key)))
  ),
  ads AS (
    SELECT pa.organization_id, pa.id FROM mkt_paid_ads pa
    WHERE coalesce(pa.platform_started_at, pa.first_seen_at) >= p_from
      AND coalesce(pa.platform_started_at, pa.first_seen_at) < (p_to + 1)
      AND pa.organization_id IS NOT NULL
      AND p_scope_type = 'market'
  ),
  agg AS (
    SELECT o.id AS organization_id,
           coalesce(pc.c, 0) AS post_count,
           coalesce(ac.c, 0) AS ad_count,
           coalesce(pc.e, 0) AS engagement_total
    FROM mkt_organizations o
    LEFT JOIN (SELECT organization_id, count(*) c, sum(eng) e FROM posts GROUP BY 1) pc
           ON pc.organization_id = o.id
    LEFT JOIN (SELECT organization_id, count(*) c FROM ads GROUP BY 1) ac
           ON ac.organization_id = o.id
    WHERE coalesce(pc.c,0) + coalesce(ac.c,0) > 0
  ),
  tot AS (SELECT sum(post_count + ad_count)::numeric AS total_n FROM agg)
  INSERT INTO mkt_share_of_voice
    (period_start, period_end, scope_type, scope_key, organization_id,
     post_count, ad_count, engagement_total, share_pct, computed_at)
  SELECT p_from, p_to, p_scope_type, coalesce(p_scope_key,''), organization_id,
         post_count, ad_count, engagement_total,
         round(100 * (post_count + ad_count) / nullif((SELECT total_n FROM tot),0), 2),
         now()
  FROM agg
  ON CONFLICT (period_start, period_end, scope_type, scope_key, organization_id)
  DO UPDATE SET post_count=EXCLUDED.post_count, ad_count=EXCLUDED.ad_count,
                engagement_total=EXCLUDED.engagement_total,
                share_pct=EXCLUDED.share_pct, computed_at=now();
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_content_bulk_assign(p_ids uuid[], p_owner_user_id uuid, p_also_deliverables boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_items int; v_dels int := 0;
BEGIN
  IF p_ids IS NULL OR array_length(p_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'no content items given' USING ERRCODE='no_data_found';
  END IF;

  UPDATE public.mkt_content_items
     SET owner_user_id = p_owner_user_id, updated_at = now()
   WHERE id = ANY(p_ids);
  GET DIAGNOSTICS v_items = ROW_COUNT;

  IF p_also_deliverables THEN
    UPDATE public.mkt_content_deliverables
       SET owner_user_id = p_owner_user_id, updated_at = now()
     WHERE content_item_id = ANY(p_ids) AND archived_at IS NULL;
    GET DIAGNOSTICS v_dels = ROW_COUNT;
  END IF;

  RETURN jsonb_build_object(
    'requested', array_length(p_ids, 1),
    'items_updated', v_items,
    'deliverables_updated', v_dels,
    'refused', array_length(p_ids, 1) - v_items);
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_content_duplicate(p_source_id uuid, p_title text DEFAULT NULL::text, p_reuse_kind text DEFAULT 'refresh'::text, p_copy_artifacts boolean DEFAULT false, p_actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  src record; v_new uuid; d record; v_del uuid; v_tasks int := 0; n int;
  v_dels int := 0; v_arts int := 0; a record;
BEGIN
  SELECT * INTO src FROM public.mkt_content_items WHERE id = p_source_id;
  IF src IS NULL THEN
    RAISE EXCEPTION 'content item not found' USING ERRCODE='no_data_found';
  END IF;

  INSERT INTO public.mkt_content_items (
    title, content_type, status, priority, purpose, project_id, campaign_id,
    owner_user_id, language, target_audience, content_pillar,
    hook, main_idea, cta, reference_links, production_notes,
    organic_or_paid, funnel_stage, content_angle, offer_message, cta_destination,
    plan_id, primary_goal_id, primary_pillar_id, strategic_purpose,
    origin_kind, origin_program_id, origin_campaign_id,
    strategy_version_id, scope_kind, scope_note,
    audience_insight, core_promise, evidence, desired_action,
    mandatory_info, prohibited_claims, always_on_reason,
    parent_content_item_id, reuse_kind,
    created_by_user_id
  ) VALUES (
    COALESCE(NULLIF(btrim(p_title), ''), src.title || ' — نسخة'),
    src.content_type, 'idea', src.priority, src.purpose, src.project_id, src.campaign_id,
    src.owner_user_id, src.language, src.target_audience, src.content_pillar,
    src.hook, src.main_idea, src.cta, src.reference_links, src.production_notes,
    src.organic_or_paid, src.funnel_stage, src.content_angle, src.offer_message, src.cta_destination,
    src.plan_id, src.primary_goal_id, src.primary_pillar_id, src.strategic_purpose,
    src.origin_kind, src.origin_program_id, src.origin_campaign_id,
    src.strategy_version_id, src.scope_kind, src.scope_note,
    src.audience_insight, src.core_promise, src.evidence, src.desired_action,
    src.mandatory_info, src.prohibited_claims, src.always_on_reason,
    p_source_id, COALESCE(p_reuse_kind, 'refresh'),
    p_actor
  ) RETURNING id INTO v_new;

  FOR d IN SELECT * FROM public.mkt_content_deliverables
            WHERE content_item_id = p_source_id AND archived_at IS NULL
            ORDER BY deliverable_number
  LOOP
    INSERT INTO public.mkt_content_deliverables (
      content_item_id, label, platform, social_account_id, distribution, format,
      language, aspect_ratio, target_seconds, owner_user_id,
      primary_kpi, kpi_unit, kpi_target, workflow_template_key,
      cta_destination, destination_url, notes,
      needs_classification, created_by_user_id
    ) VALUES (
      v_new, d.label, d.platform, d.social_account_id, d.distribution, d.format,
      d.language, d.aspect_ratio, d.target_seconds, d.owner_user_id,
      d.primary_kpi, d.kpi_unit, d.kpi_target, d.workflow_template_key,
      d.cta_destination, d.destination_url, d.notes,
      (d.platform IS NULL), p_actor
    ) RETURNING id INTO v_del;
    v_dels := v_dels + 1;

    BEGIN
      v_tasks := v_tasks + public.mkt_generate_deliverable_tasks(v_del, false);
    EXCEPTION WHEN no_data_found THEN
      RAISE NOTICE 'deliverable % (%): no workflow template, no tasks generated', v_del, d.format;
    END;

    IF p_copy_artifacts THEN
      FOR a IN
        SELECT * FROM public.mkt_content_versions
         WHERE deliverable_id = d.id AND approval_state = 'approved'
           AND payload ? 'text' AND btrim(COALESCE(payload->>'text','')) <> ''
      LOOP
        INSERT INTO public.mkt_content_versions (
          content_item_id, deliverable_id, version_type, payload,
          change_summary, owner_user_id, parent_version_id, approval_state, created_by_user_id
        ) VALUES (
          v_new, v_del, a.version_type, a.payload,
          format('copied from %s v%s', src.content_number, a.version_number),
          p_actor, a.id, 'draft', p_actor
        );
        v_arts := v_arts + 1;
      END LOOP;
    END IF;
  END LOOP;

  INSERT INTO public.mkt_content_roles (content_item_id, user_id, role_key, is_reviewer,
                                        is_final_approver, note, created_by_user_id)
  SELECT v_new, r.user_id, r.role_key, r.is_reviewer, r.is_final_approver, r.note, p_actor
    FROM public.mkt_content_roles r
   WHERE r.content_item_id = p_source_id AND r.deliverable_id IS NULL
  ON CONFLICT DO NOTHING;

  INSERT INTO public.mkt_asset_links (asset_id, target_type, target_id, role, note, created_by_user_id)
  SELECT l.asset_id, 'content_item', v_new, l.role,
         format('linked from %s', src.content_number), p_actor
    FROM public.mkt_asset_links l
   WHERE l.target_type = 'content_item' AND l.target_id = p_source_id
     AND l.role IS DISTINCT FROM 'final'
  ON CONFLICT (asset_id, target_type, target_id) DO NOTHING;
  GET DIAGNOSTICS n = ROW_COUNT;

  RETURN jsonb_build_object(
    'id', v_new,
    'content_number', (SELECT content_number FROM public.mkt_content_items WHERE id = v_new),
    'source_id', p_source_id,
    'source_number', src.content_number,
    'deliverables', v_dels,
    'tasks', v_tasks,
    'artifacts_copied', v_arts,
    'assets_linked', n);
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_content_media_upsert(p_post uuid, p_carousel_index integer, p_kind text, p_original_url text, p_bucket text, p_path text, p_url text, p_mime text, p_bytes bigint, p_width integer, p_height integer, p_duration_ms integer, p_checksum text, p_phash text, p_status text, p_failure text)
 RETURNS TABLE(id uuid, was_inserted boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_ins boolean := false;
BEGIN
  INSERT INTO public.mkt_content_media(content_post_id,carousel_index,media_kind,original_url,stored_bucket,stored_path,stored_url,mime_type,bytes,width,height,duration_ms,checksum_sha256,phash,download_status,failure_reason,last_verified_at)
  VALUES (p_post,COALESCE(p_carousel_index,0),p_kind,p_original_url,p_bucket,p_path,p_url,p_mime,p_bytes,p_width,p_height,p_duration_ms,p_checksum,p_phash,COALESCE(p_status,'pending'),p_failure, CASE WHEN p_status='stored' THEN now() END)
  ON CONFLICT (content_post_id,carousel_index,media_kind) DO UPDATE SET
    original_url=COALESCE(EXCLUDED.original_url, mkt_content_media.original_url),
    stored_bucket=COALESCE(EXCLUDED.stored_bucket, mkt_content_media.stored_bucket),
    stored_path=COALESCE(EXCLUDED.stored_path, mkt_content_media.stored_path),
    stored_url=COALESCE(EXCLUDED.stored_url, mkt_content_media.stored_url),
    mime_type=COALESCE(EXCLUDED.mime_type, mkt_content_media.mime_type),
    bytes=COALESCE(EXCLUDED.bytes, mkt_content_media.bytes),
    width=COALESCE(EXCLUDED.width, mkt_content_media.width),
    height=COALESCE(EXCLUDED.height, mkt_content_media.height),
    duration_ms=COALESCE(EXCLUDED.duration_ms, mkt_content_media.duration_ms),
    checksum_sha256=COALESCE(EXCLUDED.checksum_sha256, mkt_content_media.checksum_sha256),
    phash=COALESCE(EXCLUDED.phash, mkt_content_media.phash),
    download_status=EXCLUDED.download_status,
    failure_reason=EXCLUDED.failure_reason,
    last_verified_at=CASE WHEN EXCLUDED.download_status='stored' THEN now() ELSE mkt_content_media.last_verified_at END,
    updated_at=now()
  RETURNING mkt_content_media.id, (xmax = 0) INTO v_id, v_ins;
  RETURN QUERY SELECT v_id, v_ins;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_content_missing_context(p_content_item_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c record; missing text[] := ARRAY[]::text[];
BEGIN
  SELECT * INTO c FROM public.mkt_content_items WHERE id = p_content_item_id;
  IF c IS NULL THEN RETURN ARRAY['content item not found']; END IF;

  IF c.strategic_purpose IS NULL OR btrim(c.strategic_purpose) = '' THEN
    missing := array_append(missing, 'strategic_purpose'); END IF;
  IF c.plan_id IS NULL           THEN missing := array_append(missing, 'plan'); END IF;
  IF c.primary_goal_id IS NULL   THEN missing := array_append(missing, 'primary_goal'); END IF;
  IF c.origin_kind IS NULL       THEN missing := array_append(missing, 'origin'); END IF;
  IF c.primary_pillar_id IS NULL THEN missing := array_append(missing, 'primary_pillar'); END IF;
  IF c.target_audience IS NULL OR btrim(c.target_audience) = '' THEN
    missing := array_append(missing, 'audience'); END IF;
  IF c.cta_destination IS NULL AND (c.cta IS NULL OR btrim(c.cta) = '') THEN
    missing := array_append(missing, 'intended_result_or_cta'); END IF;

  RETURN missing;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_content_missing_requirements(p_item_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c record; missing text[] := ARRAY[]::text[]; v_sv_status text;
BEGIN
  SELECT * INTO c FROM public.mkt_content_items WHERE id = p_item_id;
  IF c IS NULL THEN RETURN ARRAY['not_found']; END IF;

  IF c.scope_kind IS NULL                                THEN missing := array_append(missing,'scope'); END IF;
  IF c.owner_user_id IS NULL                             THEN missing := array_append(missing,'owner'); END IF;

  IF c.strategy_version_id IS NULL THEN
    missing := array_append(missing,'strategy_version');
  ELSE
    SELECT status INTO v_sv_status FROM public.mkt_strategy_versions WHERE id = c.strategy_version_id;
    IF v_sv_status NOT IN ('approved','superseded') THEN
      missing := array_append(missing,'approved_strategy_version');
    END IF;
  END IF;
  IF c.plan_id IS NULL                                   THEN missing := array_append(missing,'plan'); END IF;

  IF c.primary_goal_id IS NULL
     AND (c.always_on_reason IS NULL OR btrim(c.always_on_reason) = '') THEN
    missing := array_append(missing,'goal_or_always_on_reason');
  END IF;

  IF c.target_audience IS NULL OR btrim(c.target_audience) = ''
                                                         THEN missing := array_append(missing,'audience'); END IF;
  IF COALESCE(NULLIF(btrim(c.core_promise),''), NULLIF(btrim(c.main_idea),'')) IS NULL
                                                         THEN missing := array_append(missing,'message'); END IF;
  IF COALESCE(NULLIF(btrim(c.desired_action),''), NULLIF(btrim(c.cta),'')) IS NULL
                                                         THEN missing := array_append(missing,'desired_action'); END IF;

  IF NOT EXISTS (SELECT 1 FROM public.mkt_content_deliverables
                  WHERE content_item_id = p_item_id AND archived_at IS NULL) THEN
    missing := array_append(missing,'at_least_one_deliverable');
  END IF;

  RETURN missing;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_content_next_statuses(p_from text)
 RETURNS text[]
 LANGUAGE sql
 STABLE
AS $function$
  SELECT COALESCE(array_agg(s ORDER BY ord), ARRAY[]::text[])
  FROM unnest(ARRAY[
    'idea','brief','writing','awaiting_script_approval','approved_for_production',
    'raw_assets_required','recording','designing','editing','internal_review',
    'revision_requested','awaiting_final_approval','approved','ready_to_publish',
    'scheduled','published','cancelled','archived'
  ]) WITH ORDINALITY AS t(s, ord)
  WHERE s <> p_from
    AND public.mkt_content_status_allowed(p_from, s);
$function$;
CREATE OR REPLACE FUNCTION public.mkt_content_org_attribute(p_post uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid;
BEGIN
  SELECT organization_id INTO v_org FROM public.mkt_content_posts WHERE id = p_post;
  IF v_org IS NULL THEN RETURN; END IF;
  PERFORM public.mkt_attribution_upsert(
            p_post, l.project_id,
            CASE WHEN l.relationship_type = 'developer' THEN 'developer_account' ELSE 'marketer_assignment' END,
            0.40,
            jsonb_build_object('source','org_level','relationship', l.relationship_type),
            '{}'::text[], false)
  FROM public.mkt_project_organizations l
  WHERE l.organization_id = v_org
    AND l.relationship_type IN ('developer','authorized_marketer')
    AND l.project_id IN (
      SELECT (data->>'project')::uuid FROM public.unified_records
      WHERE model_id='6609286a-f95a-45db-94e6-48cfa915ccbd' AND data->>'project' ~ '^[0-9a-fA-F-]{36}$'
    );
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_content_org_attribute_trg()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.mkt_content_org_attribute(NEW.id);
  RETURN NULL;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_content_post_upsert(p_platform text, p_external_id text, p_provider text, p_social_account_id uuid DEFAULT NULL::uuid, p_organization_id uuid DEFAULT NULL::uuid, p_post_url text DEFAULT NULL::text, p_canonical_url text DEFAULT NULL::text, p_post_type text DEFAULT NULL::text, p_caption text DEFAULT NULL::text, p_lang text DEFAULT NULL::text, p_published_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_media_refs jsonb DEFAULT '[]'::jsonb, p_thumbnail_ref text DEFAULT NULL::text, p_duration_ms integer DEFAULT NULL::integer, p_hashtags text[] DEFAULT '{}'::text[], p_mentions text[] DEFAULT '{}'::text[], p_engagement jsonb DEFAULT '{}'::jsonb, p_content_hash text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, was_inserted boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_existing uuid;
BEGIN
  SELECT cp.id INTO v_existing FROM public.mkt_content_posts cp
   WHERE cp.platform = p_platform AND cp.external_id = p_external_id;

  IF v_existing IS NULL THEN
    INSERT INTO public.mkt_content_posts (
      platform, external_id, social_account_id, organization_id, post_url, canonical_url,
      post_type, caption, lang, published_at, media_refs, thumbnail_ref, duration_ms,
      hashtags, mentions, engagement, content_hash, providers, first_provider,
      first_seen_at, last_seen_at)
    VALUES (
      p_platform, p_external_id, p_social_account_id, p_organization_id, p_post_url, p_canonical_url,
      p_post_type, p_caption, p_lang, p_published_at, COALESCE(p_media_refs,'[]'::jsonb), p_thumbnail_ref,
      p_duration_ms, COALESCE(p_hashtags,'{}'), COALESCE(p_mentions,'{}'),
      COALESCE(p_engagement,'{}'::jsonb), p_content_hash, ARRAY[p_provider], p_provider,
      now(), now())
    RETURNING mkt_content_posts.id INTO v_id;
    RETURN QUERY SELECT v_id, true;
  ELSE
    UPDATE public.mkt_content_posts cp SET
      providers        = (SELECT array_agg(DISTINCT x) FROM unnest(cp.providers || ARRAY[p_provider]) x),
      social_account_id = COALESCE(p_social_account_id, cp.social_account_id),
      organization_id   = COALESCE(p_organization_id, cp.organization_id),
      post_url          = COALESCE(p_post_url, cp.post_url),
      canonical_url     = COALESCE(p_canonical_url, cp.canonical_url),
      post_type         = COALESCE(p_post_type, cp.post_type),
      caption           = COALESCE(p_caption, cp.caption),
      published_at      = COALESCE(p_published_at, cp.published_at),
      media_refs        = CASE WHEN p_media_refs IS NULL OR p_media_refs='[]'::jsonb THEN cp.media_refs ELSE p_media_refs END,
      thumbnail_ref     = COALESCE(p_thumbnail_ref, cp.thumbnail_ref),
      duration_ms       = COALESCE(p_duration_ms, cp.duration_ms),
      hashtags          = CASE WHEN array_length(p_hashtags,1) IS NULL THEN cp.hashtags ELSE p_hashtags END,
      mentions          = CASE WHEN array_length(p_mentions,1) IS NULL THEN cp.mentions ELSE p_mentions END,
      engagement        = CASE WHEN p_engagement IS NULL OR p_engagement='{}'::jsonb THEN cp.engagement ELSE p_engagement END,
      content_hash      = COALESCE(p_content_hash, cp.content_hash),
      last_seen_at      = now()
    WHERE cp.id = v_existing;
    RETURN QUERY SELECT v_existing, false;
  END IF;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_content_rollup(p_content_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pubs int; v_published int; v_measured int;
  v_views numeric; v_eng numeric; v_clicks numeric;
  v_direct int; v_influenced int; v_unknown int; v_revenue numeric;
BEGIN
  SELECT count(*), count(*) FILTER (WHERE status = 'published')
    INTO v_pubs, v_published
    FROM public.mkt_publications WHERE content_item_id = p_content_item_id;

  WITH latest AS (
    SELECT DISTINCT ON (s.publication_id) s.*
      FROM public.mkt_performance_snapshots s
      JOIN public.mkt_publications p ON p.id = s.publication_id
     WHERE p.content_item_id = p_content_item_id
       AND s.collection_status IN ('collected','partial')
     ORDER BY s.publication_id, s.captured_at DESC
  )
  SELECT count(*),
         sum(COALESCE((metrics->>'views')::numeric, (metrics->>'impressions')::numeric)),
         sum(COALESCE((metrics->>'likes')::numeric,0) + COALESCE((metrics->>'comments')::numeric,0)
           + COALESCE((metrics->>'shares')::numeric,0) + COALESCE((metrics->>'saves')::numeric,0)),
         sum((metrics->>'link_clicks')::numeric)
    INTO v_measured, v_views, v_eng, v_clicks
    FROM latest;

  SELECT count(DISTINCT client_id) FILTER (WHERE touch_type = 'last'
             OR attribution_type IN ('platform_lead_form','manual_confirmed')),
         count(DISTINCT client_id) FILTER (WHERE touch_type IN ('first','multi')
             AND NOT (attribution_type IN ('platform_lead_form','manual_confirmed'))),
         count(DISTINCT client_id) FILTER (WHERE touch_type = 'unknown'
             AND attribution_type NOT IN ('platform_lead_form','manual_confirmed')),
         sum(revenue)
    INTO v_direct, v_influenced, v_unknown, v_revenue
    FROM public.mkt_lead_attributions
   WHERE content_item_id = p_content_item_id;

  RETURN jsonb_build_object(
    'content_item_id',  p_content_item_id,
    'publications',     v_pubs,
    'published',        v_published,
    'coverage',         jsonb_build_object('measured', COALESCE(v_measured,0), 'total', v_pubs),
    'is_measurable',    COALESCE(v_measured,0) > 0,
    'views',            v_views,
    'engagement',       v_eng,
    'link_clicks',      v_clicks,
    'leads_direct',     COALESCE(v_direct,0),
    'leads_influenced', COALESCE(v_influenced,0),
    'leads_unknown',    COALESCE(v_unknown,0),
    'revenue',          v_revenue
  );
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_content_save_view(p_name text, p_filters jsonb, p_view_mode text DEFAULT 'pipeline'::text, p_is_shared boolean DEFAULT false, p_is_default boolean DEFAULT false)
 RETURNS mkt_content_saved_views
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE me uuid; out_row public.mkt_content_saved_views;
BEGIN
  me := public.wassell_app_user_id(auth.uid());
  IF me IS NULL THEN
    RAISE EXCEPTION 'no signed-in user' USING ERRCODE='insufficient_privilege';
  END IF;
  IF p_name IS NULL OR btrim(p_name) = '' THEN
    RAISE EXCEPTION 'a saved view needs a name' USING ERRCODE='invalid_parameter_value';
  END IF;

  INSERT INTO public.mkt_content_saved_views
    (name, owner_user_id, filters, view_mode, is_shared, is_default)
  VALUES
    (btrim(p_name), me, COALESCE(p_filters, '{}'::jsonb),
     COALESCE(p_view_mode, 'pipeline'), COALESCE(p_is_shared, false),
     COALESCE(p_is_default, false))
  ON CONFLICT (owner_user_id, lower(btrim(name))) DO UPDATE
    SET filters    = EXCLUDED.filters,
        view_mode  = EXCLUDED.view_mode,
        is_shared  = EXCLUDED.is_shared,
        is_default = EXCLUDED.is_default,
        updated_at = now()
  RETURNING * INTO out_row;

  RETURN out_row;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_content_set_status(p_post uuid, p_status text, p_media_count integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.mkt_content_posts
     SET processing_status=p_status,
         media_count=COALESCE(p_media_count, media_count),
         processed_at=CASE WHEN p_status IN ('processed','partial','failed') THEN now() ELSE processed_at END,
         updated_at=now()
   WHERE id=p_post;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_content_state(p_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  c record; missing text[]; v_next jsonb; v_blockers jsonb; v_del int; v_done int; v_total int;
  v_waiting int;
BEGIN
  SELECT * INTO c FROM public.mkt_content_items WHERE id = p_item_id;
  IF c IS NULL THEN RETURN NULL; END IF;

  missing := public.mkt_content_missing_requirements(p_item_id);

  SELECT count(*) INTO v_del FROM public.mkt_content_deliverables
   WHERE content_item_id = p_item_id AND archived_at IS NULL;

  SELECT count(*) FILTER (WHERE status IN ('completed','skipped')), count(*)
    INTO v_done, v_total
    FROM public.mkt_content_tasks
   WHERE content_item_id = p_item_id AND status <> 'cancelled';

  SELECT to_jsonb(t) INTO v_next FROM (
    SELECT tk.id, tk.title, tk.task_type, tk.deliverable_id, tk.assigned_user_id, tk.due_date
      FROM public.mkt_content_tasks tk
     WHERE tk.content_item_id = p_item_id
       AND tk.status IN ('not_started','in_progress','changes_requested')
     ORDER BY tk.sort_order, tk.created_at LIMIT 1) t;

  -- Reported separately as a count, so "9 steps queued behind it" is still
  -- visible without pretending each is its own problem.
  SELECT count(*) INTO v_waiting
    FROM public.mkt_content_tasks t
    JOIN public.mkt_content_tasks p ON p.id = t.depends_on_task_id
   WHERE t.content_item_id = p_item_id AND t.status = 'blocked'
     AND p.status NOT IN ('completed','skipped');

  SELECT coalesce(jsonb_agg(b), '[]'::jsonb) INTO v_blockers FROM (
    SELECT jsonb_build_object('kind','task_blocked','id', t.id,'label', t.title,
                              'reason', t.blocked_reason) AS b
      FROM public.mkt_content_tasks t
      LEFT JOIN public.mkt_content_tasks p ON p.id = t.depends_on_task_id
     WHERE t.content_item_id = p_item_id AND t.status = 'blocked'
       AND (t.depends_on_task_id IS NULL OR p.status IN ('completed','skipped'))
    UNION ALL
    SELECT jsonb_build_object('kind','stale_artifact','id',v.id,
                              'label', v.version_type, 'reason', v.stale_reason)
      FROM public.mkt_content_versions v
     WHERE v.content_item_id = p_item_id AND v.is_stale AND v.approval_state = 'approved'
  ) x;

  RETURN jsonb_build_object(
    'status', c.status,
    'missing', to_jsonb(missing),
    'is_activatable', array_length(missing,1) IS NULL,
    'deliverables', v_del,
    'tasks_done', v_done, 'tasks_total', v_total,
    'waiting_on_predecessor', v_waiting,
    'progress_pct', CASE WHEN v_total = 0 THEN NULL
                         ELSE round((v_done::numeric / v_total) * 100) END,
    'next_action', v_next,
    'blockers', v_blockers,
    'is_overdue', c.due_date IS NOT NULL AND c.due_date < current_date
                  AND c.status NOT IN ('published','cancelled','archived'));
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_content_status_allowed(p_from text, p_to text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT p_from = p_to OR p_to IN ('cancelled','archived') OR
    (p_from, p_to) IN (
      ('idea','brief'),
      ('brief','writing'),('brief','idea'),
      ('writing','awaiting_script_approval'),('writing','brief'),
      ('awaiting_script_approval','approved_for_production'),
      ('awaiting_script_approval','revision_requested'),('awaiting_script_approval','writing'),
      ('approved_for_production','raw_assets_required'),('approved_for_production','recording'),
      ('approved_for_production','designing'),('approved_for_production','editing'),
      ('raw_assets_required','recording'),('raw_assets_required','designing'),('raw_assets_required','editing'),
      ('recording','editing'),('recording','internal_review'),
      ('designing','internal_review'),
      ('editing','internal_review'),
      ('internal_review','revision_requested'),('internal_review','awaiting_final_approval'),
      ('revision_requested','writing'),('revision_requested','recording'),
      ('revision_requested','designing'),('revision_requested','editing'),('revision_requested','internal_review'),
      ('awaiting_final_approval','approved'),('awaiting_final_approval','revision_requested'),
      ('approved','ready_to_publish'),('approved','revision_requested'),
      ('ready_to_publish','scheduled'),('ready_to_publish','published'),('ready_to_publish','approved'),
      ('scheduled','published'),('scheduled','ready_to_publish'),
      ('cancelled','idea')
    );
$function$;
CREATE OR REPLACE FUNCTION public.mkt_cost_summary()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH runs AS (
    SELECT r.*, (r.provider_cost->>'usage_total_usd')::numeric AS usd, (r.provider_cost->>'dataset_items')::numeric AS items,
           j.kind AS kind, a.organization_id AS org_id
    FROM mkt_ingestion_runs r
    LEFT JOIN mkt_collection_jobs j ON j.ingestion_run_id = r.id
    LEFT JOIN mkt_social_accounts a ON a.id = r.source_account_id
  )
  SELECT jsonb_build_object(
    'today_usd',   (SELECT COALESCE(sum(usd),0) FROM runs WHERE started_at >= date_trunc('day', now())),
    'month_usd',   (SELECT COALESCE(sum(usd),0) FROM runs WHERE started_at >= date_trunc('month', now())),
    'total_usd',   (SELECT COALESCE(sum(usd),0) FROM runs),
    'runs_month',  (SELECT count(*) FROM runs WHERE started_at >= date_trunc('month', now()) AND status<>'running'),
    'items_month', (SELECT COALESCE(sum(items),0) FROM runs WHERE started_at >= date_trunc('month', now())),
    'avg_per_run', (SELECT CASE WHEN count(*) FILTER (WHERE status<>'running')>0 THEN round(sum(usd)/count(*) FILTER (WHERE status<>'running'),4) ELSE 0 END FROM runs WHERE started_at >= date_trunc('month', now())),
    'avg_per_item',(SELECT CASE WHEN COALESCE(sum(items),0)>0 THEN round(sum(usd)/sum(items),4) ELSE 0 END FROM runs WHERE started_at >= date_trunc('month', now())),
    'by_provider', (SELECT COALESCE(jsonb_object_agg(provider, o), '{}'::jsonb) FROM (SELECT provider, jsonb_build_object('usd', round(COALESCE(sum(usd),0),4), 'runs', count(*) FILTER (WHERE status<>'running'), 'items', COALESCE(sum(items),0)) o FROM runs WHERE started_at >= date_trunc('month', now()) GROUP BY provider) p),
    'by_kind',     (SELECT COALESCE(jsonb_object_agg(COALESCE(kind,'other'), o), '{}'::jsonb) FROM (SELECT kind, jsonb_build_object('usd', round(COALESCE(sum(usd),0),4), 'runs', count(*)) o FROM runs WHERE started_at >= date_trunc('month', now()) AND status<>'running' GROUP BY kind) k),
    'by_org',      (SELECT COALESCE(jsonb_agg(o), '[]'::jsonb) FROM (SELECT jsonb_build_object('organization_id', org_id, 'name', (SELECT COALESCE(name_ar,name_en) FROM mkt_organizations WHERE id=org_id), 'usd', round(COALESCE(sum(usd),0),4), 'runs', count(*)) o FROM runs WHERE started_at >= date_trunc('month', now()) AND org_id IS NOT NULL GROUP BY org_id ORDER BY sum(usd) DESC NULLS LAST) og),
    'spike', (SELECT CASE WHEN today > mkt_setting_num('ops_cost_spike_floor_usd',1.0) AND avg7 > 0 AND today > avg7 * mkt_setting_num('ops_cost_spike_factor',3.0)
                     THEN jsonb_build_object('is_spike', true, 'today_usd', round(today,4), 'avg7_usd', round(avg7,4))
                     ELSE jsonb_build_object('is_spike', false, 'today_usd', round(today,4), 'avg7_usd', round(avg7,4)) END
              FROM (SELECT (SELECT COALESCE(sum(usd),0) FROM runs WHERE started_at >= date_trunc('day', now())) AS today,
                           (SELECT COALESCE(avg(dc),0) FROM (SELECT date_trunc('day', started_at) dd, sum(usd) dc FROM runs WHERE started_at >= now()-interval '8 days' AND started_at < date_trunc('day', now()) GROUP BY 1) z) AS avg7) q)
  );
$function$;
CREATE OR REPLACE FUNCTION public.mkt_deliverable_attainment(p_deliverable_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE d record; v_actual numeric; v_at date;
BEGIN
  SELECT * INTO d FROM public.mkt_content_deliverables WHERE id = p_deliverable_id;
  IF d IS NULL THEN RETURN NULL; END IF;

  SELECT kpi_actual, measured_at INTO v_actual, v_at
    FROM public.mkt_content_results
   WHERE deliverable_id = p_deliverable_id AND kpi_actual IS NOT NULL
   ORDER BY measured_at DESC NULLS LAST, created_at DESC LIMIT 1;

  RETURN jsonb_build_object(
    'kpi', d.primary_kpi, 'unit', d.kpi_unit,
    'target', d.kpi_target, 'actual', v_actual, 'measured_at', v_at,
    'is_measured', v_actual IS NOT NULL,
    'attainment_pct', CASE
      WHEN v_actual IS NULL OR d.kpi_target IS NULL OR d.kpi_target = 0 THEN NULL
      ELSE round((v_actual / d.kpi_target) * 100, 1) END);
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_deliverable_bulk_schedule(p_ids uuid[], p_start_at timestamp with time zone, p_interval_mins integer DEFAULT 1440)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  d record; i int := 0; v_set int := 0; v_ready int := 0;
  v_blocked jsonb := '[]'::jsonb; v_when timestamptz; v_blk text[];
BEGIN
  IF p_ids IS NULL OR array_length(p_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'no deliverables given' USING ERRCODE='no_data_found';
  END IF;
  IF p_start_at IS NULL THEN
    RAISE EXCEPTION 'a start time is required' USING ERRCODE='invalid_parameter_value';
  END IF;

  FOR d IN
    SELECT dv.id, dv.content_item_id, dv.deliverable_number, dv.platform,
           c.content_number, c.title
      FROM public.mkt_content_deliverables dv
      JOIN public.mkt_content_items c ON c.id = dv.content_item_id
     WHERE dv.id = ANY(p_ids) AND dv.archived_at IS NULL
     ORDER BY c.content_number, dv.deliverable_number
  LOOP
    v_when := p_start_at + (i * COALESCE(p_interval_mins, 1440) || ' minutes')::interval;

    UPDATE public.mkt_content_deliverables
       SET planned_publish_at = v_when, updated_at = now()
     WHERE id = d.id;
    IF FOUND THEN v_set := v_set + 1; END IF;

    v_blk := public.mkt_deliverable_schedule_blockers(d.id);
    IF array_length(v_blk, 1) IS NULL THEN
      v_ready := v_ready + 1;
    ELSE
      v_blocked := v_blocked || jsonb_build_object(
        'deliverable_id', d.id,
        'label', d.content_number || ' / D' || d.deliverable_number,
        'blockers', to_jsonb(v_blk));
    END IF;
    i := i + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'requested', array_length(p_ids, 1),
    'scheduled', v_set,
    'ready_to_publish', v_ready,
    'still_blocked', v_blocked,
    'refused', array_length(p_ids, 1) - v_set);
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_deliverable_planned_seconds(p_deliverable_id uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT sum(planned_seconds)::integer FROM public.mkt_video_scenes
   WHERE deliverable_id = p_deliverable_id AND planned_seconds IS NOT NULL;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_deliverable_schedule_blockers(p_deliverable_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE d record; missing text[] := ARRAY[]::text[]; s record;
BEGIN
  SELECT * INTO d FROM public.mkt_content_deliverables WHERE id = p_deliverable_id;
  IF d IS NULL THEN RETURN ARRAY['not_found']; END IF;

  IF d.platform IS NULL            THEN missing := array_append(missing,'platform'); END IF;
  IF d.social_account_id IS NULL   THEN missing := array_append(missing,'platform_account'); END IF;
  IF d.planned_publish_at IS NULL  THEN missing := array_append(missing,'publish_time'); END IF;

  FOR s IN
    SELECT ws.artifact_type FROM public.mkt_workflow_steps ws
     WHERE ws.template_key = COALESCE(d.workflow_template_key,
             (SELECT key FROM public.mkt_workflow_templates WHERE format = d.format AND is_active LIMIT 1))
       AND ws.gates_publish AND ws.artifact_type IS NOT NULL
  LOOP
    IF public.mkt_approved_artifact(p_deliverable_id, s.artifact_type) IS NULL THEN
      missing := array_append(missing, 'approved_' || s.artifact_type);
    END IF;
  END LOOP;

  IF d.distribution IN ('paid','both')
     AND NOT EXISTS (SELECT 1 FROM public.mkt_publications
                      WHERE deliverable_id = p_deliverable_id AND ad_id IS NOT NULL) THEN
    missing := array_append(missing,'paid_ad_link');
  END IF;

  RETURN missing;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_diagnostic_set(p_check text, p_status text, p_detail text DEFAULT NULL::text, p_latency_ms integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  INSERT INTO public.mkt_diagnostics (check_name, status, detail, latency_ms, checked_at)
  VALUES (p_check, p_status, p_detail, p_latency_ms, now())
  ON CONFLICT (check_name) DO UPDATE SET status=EXCLUDED.status, detail=EXCLUDED.detail, latency_ms=EXCLUDED.latency_ms, checked_at=now();
$function$;
CREATE OR REPLACE FUNCTION public.mkt_discovery_evidence_add(p_run uuid, p_org uuid, p_source text, p_kind text, p_platform text, p_handle text, p_url text, p_title text, p_snippet text, p_extracted jsonb DEFAULT '{}'::jsonb, p_screenshot text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  INSERT INTO public.mkt_discovery_evidence (run_id, organization_id, source, kind, platform, handle, url, title, snippet, extracted, screenshot_ref)
  VALUES (p_run, p_org, p_source, p_kind, p_platform, p_handle, p_url, p_title, p_snippet, COALESCE(p_extracted,'{}'::jsonb), p_screenshot)
  RETURNING id;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_discovery_query_log(p_run uuid, p_org uuid, p_source text, p_query text, p_results integer)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  INSERT INTO public.mkt_discovery_queries (run_id, organization_id, source, query, result_count)
  VALUES (p_run, p_org, p_source, p_query, COALESCE(p_results,0));
$function$;
CREATE OR REPLACE FUNCTION public.mkt_discovery_run_finish(p_run uuid, p_status text, p_sources text[], p_queries integer, p_evidence integer, p_candidates integer, p_confirmed integer, p_cost numeric, p_summary jsonb DEFAULT '{}'::jsonb, p_error text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  UPDATE public.mkt_discovery_runs SET
    status=p_status, sources_used=COALESCE(p_sources,'{}'), queries_count=p_queries, evidence_count=p_evidence,
    candidates_count=p_candidates, confirmed_count=p_confirmed, cost_usd=p_cost,
    summary=COALESCE(p_summary,'{}'::jsonb), error=p_error, finished_at=now()
  WHERE id=p_run;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_discovery_run_start(p_org uuid, p_trigger text DEFAULT 'manual'::text)
 RETURNS uuid
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  INSERT INTO public.mkt_discovery_runs (organization_id, trigger) VALUES (p_org, p_trigger) RETURNING id;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_emit_facts_enrichment(p_enr_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n integer := 0; m integer := 0;
BEGIN
  DELETE FROM mkt_observed_facts WHERE source_type='enrichment' AND source_id=p_enr_id;

  WITH scalars AS (
    SELECT e.id AS enr_id, e.content_post_id, e.organization_id, e.primary_project_id,
           cp.published_at, k AS json_key, e.result->>k AS value_text
    FROM mkt_content_enrichment e
    JOIN mkt_content_posts cp ON cp.id = e.content_post_id
    CROSS JOIN LATERAL (VALUES ('offer'),('price'),('payment_plan'),('financing'),
                               ('district'),('location'),('campaign_message'),
                               ('content_type'),('objective'),('language'),('audience')) v(k)
    WHERE e.id = p_enr_id AND jsonb_typeof(e.result->k)='string'
      AND length(trim(e.result->>k)) > 0
  ),
  routed AS (
    SELECT s.*,
           CASE WHEN s.json_key = 'offer' AND NOT mkt_is_commercial_offer(s.value_text)
                THEN 'selling_point' ELSE s.json_key END AS fact_type
    FROM scalars s
  ),
  ded AS (
    SELECT DISTINCT ON (fact_type, mkt_fact_norm_key(fact_type, value_text)) *
    FROM routed ORDER BY fact_type, mkt_fact_norm_key(fact_type, value_text), value_text
  ),
  ins AS (
    INSERT INTO mkt_observed_facts
      (fact_type, value_text, value_num, value_unit, normalized_key, organization_id,
       project_id, content_post_id, source_type, source_id, extractor,
       extractor_version, confidence, observed_at)
    SELECT fact_type, left(value_text, 2000),
           CASE WHEN fact_type='price' THEN mkt_fact_num(value_text) END,
           CASE WHEN fact_type='price' AND mkt_fact_num(value_text) IS NOT NULL THEN 'SAR' END,
           mkt_fact_norm_key(fact_type, value_text),
           organization_id, primary_project_id, content_post_id,
           'enrichment', enr_id, 'skill', 'live-v2', 0.8, published_at
    FROM ded
    ON CONFLICT (source_type, source_id, fact_type, normalized_key, extractor) DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO n FROM ins;

  WITH arrays AS (
    SELECT e.id AS enr_id, e.content_post_id, e.organization_id, e.primary_project_id,
           cp.published_at,
           CASE v.k WHEN 'unit_types' THEN 'unit_type' WHEN 'amenities' THEN 'amenity'
                    WHEN 'selling_points' THEN 'selling_point' WHEN 'ctas' THEN 'cta' END AS fact_type,
           trim(elem) AS value_text
    FROM mkt_content_enrichment e
    JOIN mkt_content_posts cp ON cp.id = e.content_post_id
    CROSS JOIN LATERAL (VALUES ('unit_types'),('amenities'),('selling_points'),('ctas')) v(k)
    CROSS JOIN LATERAL jsonb_array_elements_text(
          CASE WHEN jsonb_typeof(e.result->v.k)='array' THEN e.result->v.k ELSE '[]'::jsonb END) elem
    WHERE e.id = p_enr_id AND length(trim(elem)) > 0
  ),
  ded2 AS (
    SELECT DISTINCT ON (fact_type, mkt_fact_norm_key(fact_type, value_text)) *
    FROM arrays ORDER BY fact_type, mkt_fact_norm_key(fact_type, value_text), value_text
  ),
  ins2 AS (
    INSERT INTO mkt_observed_facts
      (fact_type, value_text, normalized_key, organization_id, project_id,
       content_post_id, source_type, source_id, extractor, extractor_version,
       confidence, observed_at)
    SELECT fact_type, left(value_text, 2000), mkt_fact_norm_key(fact_type, value_text),
           organization_id, primary_project_id, content_post_id,
           'enrichment', enr_id, 'skill', 'live-v2', 0.8, published_at
    FROM ded2 WHERE fact_type IS NOT NULL
    ON CONFLICT (source_type, source_id, fact_type, normalized_key, extractor) DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO m FROM ins2;

  RETURN n + m;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_emit_facts_paid_ad(p_ad_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n integer := 0;
BEGIN
  DELETE FROM mkt_observed_facts WHERE source_type='paid_ad' AND source_id=p_ad_id;

  WITH claims AS (
    SELECT a.id, a.organization_id, coalesce(a.platform_started_at, a.first_seen_at) AS observed_at,
           t.fact_type, t.value_text
    FROM mkt_paid_ads a
    CROSS JOIN LATERAL (VALUES
      ('cta',              a.cta),
      ('url',              a.landing_url),
      ('campaign_message', a.headline)
    ) t(fact_type, value_text)
    WHERE a.id = p_ad_id AND t.value_text IS NOT NULL AND length(trim(t.value_text)) > 0
  ),
  ded AS (
    SELECT DISTINCT ON (fact_type, mkt_fact_norm_key(fact_type, value_text)) *
    FROM claims ORDER BY fact_type, mkt_fact_norm_key(fact_type, value_text), value_text
  ),
  ins AS (
    INSERT INTO mkt_observed_facts
      (fact_type, value_text, normalized_key, organization_id, paid_ad_id,
       source_type, source_id, extractor, extractor_version, confidence, observed_at)
    SELECT fact_type, left(trim(value_text), 2000), mkt_fact_norm_key(fact_type, value_text),
           organization_id, id, 'paid_ad', id, 'deterministic', 'live-v1', 0.9, observed_at
    FROM ded
    ON CONFLICT (source_type, source_id, fact_type, normalized_key, extractor) DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO n FROM ins;
  RETURN n;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_emit_facts_visual_text(p_vt_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n integer := 0;
BEGIN
  DELETE FROM mkt_observed_facts WHERE source_type='visual_text' AND source_id=p_vt_id;

  WITH src AS (
    SELECT v.id AS vt_id, v.content_post_id, cp.organization_id, cp.published_at,
           k.key AS json_key, elem AS raw_value
    FROM mkt_visual_text v
    JOIN mkt_content_posts cp ON cp.id = v.content_post_id
    CROSS JOIN LATERAL jsonb_each(v.structured) k(key, val)
    CROSS JOIN LATERAL jsonb_array_elements_text(
          CASE WHEN jsonb_typeof(k.val)='array' THEN k.val ELSE '[]'::jsonb END) elem
    WHERE v.id = p_vt_id AND v.structured IS NOT NULL
      AND k.key IN ('prices','offers','payment_plans','unit_types','districts',
                    'locations','phones','urls','ctas','dates','project_names',
                    'developer_names','amenities','selling_points')
      AND length(trim(elem)) > 0
  ),
  mapped AS (
    SELECT vt_id, content_post_id, organization_id, published_at,
           CASE json_key
             WHEN 'prices' THEN 'price'
             -- ROUTING: a non-commercial "offer" is a selling point, not an
             -- offer. Fixes historical rows on re-emit and guards against model
             -- drift going forward.
             WHEN 'offers' THEN CASE WHEN mkt_is_commercial_offer(raw_value)
                                     THEN 'offer' ELSE 'selling_point' END
             WHEN 'payment_plans'  THEN 'payment_plan'
             WHEN 'unit_types'     THEN 'unit_type'
             WHEN 'districts'      THEN 'district'
             WHEN 'locations'      THEN 'location'
             WHEN 'phones'         THEN 'phone'
             WHEN 'urls'           THEN 'url'
             WHEN 'ctas'           THEN 'cta'
             WHEN 'dates'          THEN 'delivery_date'
             WHEN 'project_names'  THEN 'project_name'
             WHEN 'developer_names' THEN 'developer_name'
             WHEN 'amenities'      THEN 'amenity'
             WHEN 'selling_points' THEN 'selling_point'
           END AS fact_type,
           trim(raw_value) AS value_text
    FROM src
  ),
  deduped AS (
    SELECT DISTINCT ON (fact_type, mkt_fact_norm_key(fact_type, value_text))
           vt_id, content_post_id, organization_id, published_at, fact_type, value_text
    FROM mapped WHERE fact_type IS NOT NULL
    ORDER BY fact_type, mkt_fact_norm_key(fact_type, value_text), value_text
  ),
  ins AS (
    INSERT INTO mkt_observed_facts
      (fact_type, value_text, value_num, value_unit, normalized_key, organization_id,
       content_post_id, source_type, source_id, extractor, extractor_version,
       confidence, observed_at)
    SELECT fact_type, left(value_text, 2000),
           CASE WHEN fact_type='price' THEN mkt_fact_num(value_text) END,
           CASE WHEN fact_type='price' AND mkt_fact_num(value_text) IS NOT NULL THEN 'SAR' END,
           mkt_fact_norm_key(fact_type, value_text),
           organization_id, content_post_id, 'visual_text', vt_id, 'ocr', 'live-v2',
           0.7, published_at
    FROM deduped
    ON CONFLICT (source_type, source_id, fact_type, normalized_key, extractor) DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO n FROM ins;
  RETURN n;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_enqueue_campaign_summaries(p_org uuid, p_batch integer DEFAULT 4, p_max_jobs integer DEFAULT 10, p_min_members integer DEFAULT 1, p_force boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_jobs int := 0; v_ids uuid[];
BEGIN
  LOOP
    EXIT WHEN v_jobs >= p_max_jobs;
    SELECT array_agg(id) INTO v_ids FROM (
      SELECT c.id FROM mkt_campaigns c
      LEFT JOIN mkt_campaign_summaries su ON su.campaign_id = c.id
      WHERE c.organization_id = p_org
        AND c.member_count >= p_min_members
        AND (
          p_force
          OR su.id IS NULL
          OR su.status = 'failed'
          OR su.member_count_at_summary IS DISTINCT FROM c.member_count
          OR su.last_seen_at_at_summary IS DISTINCT FROM c.last_seen_at
        )
        AND NOT EXISTS (
          SELECT 1 FROM claude_jobs j
          WHERE j.kind = 'mkt_campaign_summary' AND j.status IN ('pending','running')
            AND j.payload->'campaign_ids' @> to_jsonb(c.id::text)
        )
      ORDER BY c.last_seen_at DESC NULLS LAST
      LIMIT GREATEST(1, p_batch)
    ) z;
    EXIT WHEN v_ids IS NULL OR array_length(v_ids,1) IS NULL;
    INSERT INTO claude_jobs(kind, payload, status)
    VALUES ('mkt_campaign_summary',
            jsonb_build_object('organization_id', p_org, 'campaign_ids', to_jsonb(v_ids)),
            'pending');
    v_jobs := v_jobs + 1;
  END LOOP;
  RETURN v_jobs;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_enqueue_content_processing(p_org uuid, p_limit integer DEFAULT 100, p_force boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_count int := 0; r record;
BEGIN
  FOR r IN
    SELECT cp.id FROM public.mkt_content_posts cp
    WHERE cp.organization_id = p_org
      AND (p_force OR cp.processing_status IN ('collected','failed','partial'))
      AND cp.availability = 'available'
    ORDER BY cp.published_at DESC NULLS LAST
    LIMIT GREATEST(0, p_limit)
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM public.mkt_collection_jobs j
      WHERE j.kind='content_process' AND j.status IN ('queued','running')
        AND (j.params->>'content_post_id')::uuid = r.id
    ) THEN
      PERFORM public.mkt_job_enqueue('content_process','internal',NULL,
        jsonb_build_object('content_post_id', r.id, 'organization_id', p_org), 45, NULL, NULL);
      v_count := v_count + 1;
    END IF;
  END LOOP;
  RETURN v_count;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_enqueue_due_accounts()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; n int := 0; v_cap int; v_paused boolean;
BEGIN
  SELECT (value)::boolean INTO v_paused FROM public.mkt_settings WHERE key='collection_paused';
  IF COALESCE(v_paused, true) THEN RETURN 0; END IF;
  SELECT COALESCE((value)::int, 10) INTO v_cap FROM public.mkt_settings WHERE key='max_accounts_per_batch';
  FOR r IN
    SELECT a.id, a.provider, a.last_incremental_at, a.last_metrics_at, a.cadence
      FROM public.mkt_social_accounts a
      JOIN public.mkt_providers pr ON pr.provider_key = a.provider AND pr.is_enabled
     WHERE a.collection_enabled AND a.is_active AND a.provider IS NOT NULL
     ORDER BY a.last_incremental_at NULLS FIRST LIMIT v_cap
  LOOP
    IF r.last_incremental_at IS NULL OR r.last_incremental_at < now() - interval '20 hours' THEN
      PERFORM public.mkt_job_enqueue('incremental', r.provider, r.id, '{"reason":"scheduled"}'::jsonb, 100); n := n + 1;
    END IF;
    IF r.last_metrics_at IS NULL OR r.last_metrics_at < now() - interval '20 hours' THEN
      PERFORM public.mkt_job_enqueue('post_metrics', r.provider, r.id, '{"reason":"scheduled"}'::jsonb, 120); n := n + 1;
    END IF;
  END LOOP;
  RETURN n;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_enqueue_intelligence(p_org uuid, p_batch integer DEFAULT 15, p_max_jobs integer DEFAULT 20)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_jobs int := 0; v_ids uuid[];
BEGIN
  LOOP
    EXIT WHEN v_jobs >= p_max_jobs;
    SELECT array_agg(id) INTO v_ids FROM (
      SELECT cp.id FROM mkt_content_posts cp
      WHERE cp.organization_id = p_org AND cp.processing_status = 'awaiting_intelligence'
        AND NOT EXISTS (
          SELECT 1 FROM claude_jobs j WHERE j.kind='mkt_content_enrichment' AND j.status IN ('pending','running')
            AND j.payload->'post_ids' @> to_jsonb(cp.id::text)
        )
      ORDER BY cp.published_at DESC NULLS LAST
      LIMIT GREATEST(1, p_batch)
    ) z;
    EXIT WHEN v_ids IS NULL OR array_length(v_ids,1) IS NULL;
    INSERT INTO claude_jobs(kind, payload, status)
    VALUES ('mkt_content_enrichment', jsonb_build_object('organization_id', p_org, 'post_ids', to_jsonb(v_ids)), 'pending');
    v_jobs := v_jobs + 1;
  END LOOP;
  RETURN v_jobs;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_enrichment_upsert(p_post uuid, p_model text, p_rule_version text, p_org uuid, p_developer uuid, p_marketer uuid, p_primary_project uuid, p_candidates jsonb, p_result jsonb, p_cost numeric, p_status text, p_failure text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  INSERT INTO public.mkt_content_enrichment(content_post_id,model,rule_version,organization_id,developer_id,marketer_id,primary_project_id,candidate_projects,result,cost_usd,status,failure_reason)
  VALUES (p_post,p_model,p_rule_version,p_org,p_developer,p_marketer,p_primary_project,COALESCE(p_candidates,'[]'::jsonb),COALESCE(p_result,'{}'::jsonb),COALESCE(p_cost,0),COALESCE(p_status,'done'),p_failure)
  ON CONFLICT (content_post_id) DO UPDATE SET
    model=EXCLUDED.model, rule_version=EXCLUDED.rule_version, organization_id=EXCLUDED.organization_id,
    developer_id=EXCLUDED.developer_id, marketer_id=EXCLUDED.marketer_id, primary_project_id=EXCLUDED.primary_project_id,
    candidate_projects=EXCLUDED.candidate_projects, result=EXCLUDED.result, cost_usd=EXCLUDED.cost_usd,
    status=EXCLUDED.status, failure_reason=EXCLUDED.failure_reason, updated_at=now()
  RETURNING id INTO v_id;
  RETURN v_id;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_fact_belongs_to_project(p_fact_project uuid, p_fact_post uuid, p_project uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT p_project IS NULL
      OR p_fact_project = p_project
      OR EXISTS (SELECT 1 FROM mkt_content_attributions a
                 WHERE a.content_post_id = p_fact_post
                   AND a.project_id = p_project
                   AND a.review_status IN ('auto_accepted','confirmed'));
$function$;
CREATE OR REPLACE FUNCTION public.mkt_fact_norm_key(p_fact_type text, p_value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p_fact_type
    -- identifiers collapse to their identity, so one phone written three ways
    -- ("920033158", "9200 33 158") is ONE value, not three
    WHEN 'phone' THEN coalesce(nullif(regexp_replace(p_value, '[^0-9]', '', 'g'), ''),
                               left(lower(p_value), 300))
    WHEN 'url'   THEN left(regexp_replace(
                         regexp_replace(lower(trim(p_value)), '^https?://(www\.)?', ''),
                         '/+$', ''), 300)
    ELSE left(lower(regexp_replace(p_value, '\s+', ' ', 'g')), 300)
  END;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_fact_num(p_value text)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT nullif(regexp_replace(
    coalesce((regexp_match(replace(replace(p_value, ',', ''), ' ', ''), '\d{4,}'))[1], ''),
    '[^0-9]', '', 'g'), '')::numeric;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_fact_top(p_fact_type text, p_limit integer DEFAULT 20, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_org uuid DEFAULT NULL::uuid, p_project uuid DEFAULT NULL::uuid, p_min_conf numeric DEFAULT 0.0)
 RETURNS TABLE(normalized_key text, sample_value text, observations bigint, distinct_posts bigint, distinct_orgs bigint, first_seen timestamp with time zone, last_seen timestamp with time zone, share_pct numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH scoped AS (
    SELECT f.* FROM mkt_observed_facts f
    WHERE f.fact_type = p_fact_type
      AND f.confidence >= coalesce(p_min_conf, 0)
      AND (p_from IS NULL OR f.observed_at >= p_from)
      AND (p_to   IS NULL OR f.observed_at <  (p_to + 1))
      AND (p_org  IS NULL OR f.organization_id = p_org)
      AND mkt_fact_belongs_to_project(f.project_id, f.content_post_id, p_project)
  ), tot AS (SELECT count(*)::numeric AS n FROM scoped)
  SELECT s.normalized_key,
         (array_agg(s.value_text ORDER BY length(s.value_text) DESC))[1],
         count(*), count(DISTINCT s.content_post_id), count(DISTINCT s.organization_id),
         min(s.observed_at), max(s.observed_at),
         round(100 * count(*) / nullif((SELECT n FROM tot), 0), 2)
  FROM scoped s GROUP BY s.normalized_key
  ORDER BY 3 DESC, 7 DESC NULLS LAST
  LIMIT greatest(1, coalesce(p_limit, 20));
$function$;
CREATE OR REPLACE FUNCTION public.mkt_fact_trend(p_fact_type text, p_bucket text DEFAULT 'month'::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_org uuid DEFAULT NULL::uuid, p_project uuid DEFAULT NULL::uuid, p_district text DEFAULT NULL::text, p_min_conf numeric DEFAULT 0.0)
 RETURNS TABLE(bucket_start date, observations bigint, distinct_values bigint, numeric_count bigint, min_value numeric, max_value numeric, avg_value numeric, median_value numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH scoped AS (
    SELECT f.* FROM mkt_observed_facts f
    WHERE f.fact_type = p_fact_type
      AND f.observed_at IS NOT NULL
      AND f.confidence >= coalesce(p_min_conf, 0)
      AND (p_from IS NULL OR f.observed_at >= p_from)
      AND (p_to   IS NULL OR f.observed_at <  (p_to + 1))
      AND (p_org  IS NULL OR f.organization_id = p_org)
      AND mkt_fact_belongs_to_project(f.project_id, f.content_post_id, p_project)
      AND (p_district IS NULL OR EXISTS (
            SELECT 1 FROM mkt_observed_facts d
            WHERE d.content_post_id = f.content_post_id
              AND d.fact_type = 'district'
              AND d.normalized_key = mkt_fact_norm_key('district', p_district)))
  )
  SELECT date_trunc(coalesce(p_bucket,'month'), observed_at)::date,
         count(*), count(DISTINCT normalized_key), count(value_num),
         min(value_num), max(value_num), round(avg(value_num), 2),
         percentile_cont(0.5) WITHIN GROUP (ORDER BY value_num)
  FROM scoped GROUP BY 1 ORDER BY 1;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_freshness_scan()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; v_org int:=0; v_gap int:=0; v_prov int:=0; v_ads int:=0; v_met int:=0;
  org_h numeric := mkt_setting_num('ops_org_stale_hours',26);
  prov_h numeric := mkt_setting_num('ops_provider_stale_hours',26);
  ads_h numeric := mkt_setting_num('ops_ads_stale_hours',48);
  met_h numeric := mkt_setting_num('ops_metrics_stale_hours',48);
BEGIN
  FOR r IN
    SELECT o.id, COALESCE(o.name_ar,o.name_en) nm, max(a.last_synced_at) ls
    FROM mkt_organizations o JOIN mkt_social_accounts a ON a.organization_id=o.id AND a.collection_enabled
    GROUP BY o.id, nm
  LOOP
    IF r.ls IS NULL OR r.ls < now() - (org_h * interval '1 hour') THEN
      PERFORM mkt_alert_emit('org_stale', 'org_stale:'||r.id, 'مؤسسة متوقفة عن التجميع — '||COALESCE(r.nm,'?'),
        'warning','organization',r.id::text, 'آخر تجميع ناجح: '||COALESCE(r.ls::text,'never'),
        jsonb_build_object('last_synced_at', r.ls, 'threshold_hours', org_h));
      v_org := v_org + 1;
      IF r.ls IS NOT NULL AND r.ls < now() - (org_h * 3 * interval '1 hour') THEN
        PERFORM mkt_alert_emit('freshness_gap','freshness_gap:'||r.id,'فجوة طويلة في التجميع — '||COALESCE(r.nm,'?'),
          'critical','organization',r.id::text,'لا يوجد تجميع منذ '||round(EXTRACT(EPOCH FROM (now()-r.ls))/3600)||' ساعة',
          jsonb_build_object('last_synced_at', r.ls));
        v_gap := v_gap + 1;
      END IF;
    ELSE
      PERFORM mkt_alert_resolve('org_stale', r.id::text);
      PERFORM mkt_alert_resolve('freshness_gap', r.id::text);
    END IF;
    IF EXISTS (SELECT 1 FROM mkt_social_accounts a WHERE a.organization_id=r.id AND a.collection_enabled
              AND (a.last_metrics_at IS NULL OR a.last_metrics_at < now() - (met_h * interval '1 hour'))) THEN
      PERFORM mkt_alert_emit('metrics_stale','metrics_stale:'||r.id,'مقاييس قديمة — '||COALESCE(r.nm,'?'),
        'info','organization',r.id::text,NULL,jsonb_build_object('threshold_hours', met_h));
      v_met := v_met + 1;
    ELSE
      PERFORM mkt_alert_resolve('metrics_stale', r.id::text);
    END IF;
  END LOOP;

  FOR r IN
    SELECT o.id, COALESCE(o.name_ar,o.name_en) nm, max(pa.last_seen_at) ls, count(*) c
    FROM mkt_organizations o JOIN mkt_paid_ads pa ON pa.organization_id=o.id
    WHERE o.meta_confirmed GROUP BY o.id, nm
  LOOP
    IF r.c > 0 AND (r.ls IS NULL OR r.ls < now() - (ads_h * interval '1 hour')) THEN
      PERFORM mkt_alert_emit('ads_stale','ads_stale:'||r.id,'إعلانات لم تُحدَّث — '||COALESCE(r.nm,'?'),
        'warning','organization',r.id::text,'أحدث ظهور: '||COALESCE(r.ls::text,'?'),jsonb_build_object('last_seen_at', r.ls, 'ad_count', r.c));
      v_ads := v_ads + 1;
    ELSE
      PERFORM mkt_alert_resolve('ads_stale', r.id::text);
    END IF;
  END LOOP;

  FOR r IN SELECT provider_key pk, display_name dn FROM mkt_providers WHERE is_enabled LOOP
    IF NOT EXISTS (SELECT 1 FROM mkt_ingestion_runs x WHERE x.provider=r.pk AND x.status IN ('succeeded','partial') AND x.started_at > now() - (prov_h * interval '1 hour'))
       AND EXISTS (SELECT 1 FROM mkt_ingestion_runs x WHERE x.provider=r.pk) THEN
      PERFORM mkt_alert_emit('provider_no_data','provider_no_data:'||r.pk,'مزوّد لا يُرجع بيانات — '||r.dn,
        'warning','provider',r.pk,'لا تشغيل ناجح خلال '||prov_h||' ساعة',jsonb_build_object('threshold_hours', prov_h));
      v_prov := v_prov + 1;
    ELSE
      PERFORM mkt_alert_resolve('provider_no_data', r.pk);
    END IF;
  END LOOP;

  RETURN jsonb_build_object('org_stale',v_org,'freshness_gap',v_gap,'provider_no_data',v_prov,'ads_stale',v_ads,'metrics_stale',v_met);
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_generate_content_tasks(p_content_item_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item public.mkt_content_items%ROWTYPE;
  v_steps text[][]; v_prev uuid; v_id uuid; v_n int := 0; i int;
  v_type text; v_title_ar text;
BEGIN
  SELECT * INTO v_item FROM public.mkt_content_items WHERE id=p_content_item_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'content item % not found', p_content_item_id; END IF;
  IF EXISTS (SELECT 1 FROM public.mkt_content_tasks WHERE content_item_id=p_content_item_id) THEN
    RETURN 0;   -- idempotent: never duplicate a checklist
  END IF;

  IF v_item.content_type IN ('carousel','static_image','infographic','paid_image_ad') THEN
    v_steps := ARRAY[
      ARRAY['write_brief','كتابة الموجز'], ARRAY['write_copy','كتابة نص الشرائح'],
      ARRAY['approve_script','اعتماد النص'], ARRAY['design_slides','تصميم الشرائح'],
      ARRAY['review_design','مراجعة التصميم'], ARRAY['revisions','تنفيذ التعديلات'],
      ARRAY['approve_final','الاعتماد النهائي'], ARRAY['schedule_publication','جدولة النشر'],
      ARRAY['record_performance','تسجيل الأداء']];
  ELSE
    v_steps := ARRAY[
      ARRAY['write_brief','كتابة الموجز'], ARRAY['write_script','كتابة السيناريو'],
      ARRAY['approve_script','اعتماد السيناريو'], ARRAY['prepare_assets','تجهيز المواد الخام'],
      ARRAY['record','التصوير'], ARRAY['edit_video','مونتاج الفيديو'],
      ARRAY['review_video','مراجعة الفيديو'], ARRAY['revisions','تنفيذ التعديلات'],
      ARRAY['write_caption','كتابة التعليق'], ARRAY['approve_final','الاعتماد النهائي'],
      ARRAY['schedule_publication','جدولة النشر'], ARRAY['record_performance','تسجيل الأداء']];
  END IF;

  FOR i IN 1 .. array_length(v_steps,1) LOOP
    v_type := v_steps[i][1]; v_title_ar := v_steps[i][2];
    INSERT INTO public.mkt_content_tasks
      (title, task_type, content_item_id, campaign_id, project_id, due_date,
       depends_on_task_id, sort_order, created_by_user_id,
       status, blocked_reason)
    VALUES (v_title_ar, v_type, p_content_item_id, v_item.campaign_id, v_item.project_id,
            v_item.due_date, v_prev, i, v_item.created_by_user_id,
            CASE WHEN v_prev IS NULL THEN 'not_started' ELSE 'blocked' END,
            CASE WHEN v_prev IS NULL THEN NULL ELSE 'في انتظار إنهاء المهمة السابقة' END)
    RETURNING id INTO v_id;
    v_prev := v_id; v_n := v_n + 1;
  END LOOP;
  RETURN v_n;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_generate_deliverable_tasks(p_deliverable_id uuid, p_replace boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  d record; tkey text; s record; n int := 0;
  v_id uuid; v_map jsonb := '{}'::jsonb; v_dep uuid;
BEGIN
  SELECT * INTO d FROM public.mkt_content_deliverables WHERE id = p_deliverable_id;
  IF d IS NULL THEN RAISE EXCEPTION 'deliverable not found' USING ERRCODE='no_data_found'; END IF;

  tkey := COALESCE(d.workflow_template_key,
                   (SELECT key FROM public.mkt_workflow_templates
                     WHERE format = d.format AND is_active LIMIT 1));
  IF tkey IS NULL THEN
    RAISE EXCEPTION 'no workflow template for format "%" — pick one explicitly', d.format
      USING ERRCODE='no_data_found';
  END IF;

  IF p_replace THEN
    DELETE FROM public.mkt_content_tasks
     WHERE deliverable_id = p_deliverable_id
       AND step_key IS NOT NULL
       AND status = 'not_started'
       AND completed_at IS NULL;
  END IF;

  FOR s IN SELECT * FROM public.mkt_workflow_steps WHERE template_key = tkey ORDER BY sort_order LOOP
    v_dep := NULLIF(v_map ->> s.depends_on_step_key, '')::uuid;
    v_id := NULL;

    INSERT INTO public.mkt_content_tasks
      (title, task_type, content_item_id, deliverable_id, project_id, status, priority,
       sort_order, template_key, step_key, artifact_type, depends_on_task_id,
       assigned_user_id, created_by_user_id)
    VALUES
      (s.label_ar, s.task_type, d.content_item_id, p_deliverable_id,
       (SELECT project_id FROM public.mkt_content_items WHERE id = d.content_item_id),
       CASE WHEN s.depends_on_step_key IS NULL THEN 'not_started' ELSE 'blocked' END,
       'normal', s.sort_order, tkey, s.step_key, s.artifact_type, v_dep,
       CASE WHEN s.role_key = 'owner' THEN d.owner_user_id ELSE NULL END,
       d.created_by_user_id)
    ON CONFLICT (deliverable_id, step_key)
      WHERE deliverable_id IS NOT NULL AND step_key IS NOT NULL
      DO NOTHING
    RETURNING id INTO v_id;

    IF v_id IS NULL THEN
      SELECT id INTO v_id FROM public.mkt_content_tasks
       WHERE deliverable_id = p_deliverable_id AND step_key = s.step_key;
    ELSE
      n := n + 1;
    END IF;
    v_map := v_map || jsonb_build_object(s.step_key, v_id);
  END LOOP;

  UPDATE public.mkt_content_deliverables
     SET workflow_template_key = tkey, updated_at = now()
   WHERE id = p_deliverable_id AND workflow_template_key IS DISTINCT FROM tkey;

  RETURN n;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_generate_trend_insights(p_window_days integer DEFAULT 30, p_min_prior integer DEFAULT 5, p_change_pct numeric DEFAULT 30)
 RETURNS TABLE(kind text, emitted integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now      date := current_date;
  v_cur_from date := current_date - p_window_days;
  v_prv_from date := current_date - (p_window_days * 2);
  v_period   text := to_char(current_date, 'YYYY-MM');
  v_n        int;
BEGIN
  -- ── 1. Posting frequency changed (org) ────────────────────────────────────
  WITH windows AS (
    SELECT cp.organization_id,
           count(*) FILTER (WHERE cp.published_at >= v_cur_from) AS cur,
           count(*) FILTER (WHERE cp.published_at >= v_prv_from AND cp.published_at < v_cur_from) AS prv
    FROM mkt_content_posts cp
    WHERE cp.published_at >= v_prv_from AND cp.organization_id IS NOT NULL
    GROUP BY cp.organization_id
  ),
  scored AS (
    SELECT w.*, o.name_en, o.name_ar,
           round(100.0 * (w.cur - w.prv) / nullif(w.prv,0), 1) AS pct
    FROM windows w JOIN mkt_organizations o ON o.id = w.organization_id
    WHERE w.prv >= p_min_prior
      AND abs(round(100.0 * (w.cur - w.prv) / nullif(w.prv,0), 1)) >= p_change_pct
  )
  SELECT count(*) INTO v_n FROM (
    SELECT mkt_insight_emit(
      'posting_frequency_change', 'pfc:' || organization_id::text || ':' || v_period,
      coalesce(name_ar, name_en) || ' — ' ||
        CASE WHEN pct > 0 THEN 'ارتفع النشر ' ELSE 'انخفض النشر ' END || abs(pct)::text || '%',
      NULL, CASE WHEN pct > 0 THEN 'opportunity' ELSE 'warning' END,
      organization_id, NULL, NULL,
      jsonb_build_object('rule','posting_frequency_change',
        'current_window_posts', cur, 'prior_window_posts', prv,
        'change_pct', pct, 'window_days', p_window_days,
        'window_current', jsonb_build_array(v_cur_from, v_now),
        'window_prior', jsonb_build_array(v_prv_from, v_cur_from),
        'threshold_pct', p_change_pct, 'min_prior_posts', p_min_prior))
    AS emitted_id FROM scored) z WHERE z.emitted_id IS NOT NULL;
  kind := 'posting_frequency_change'; emitted := v_n; RETURN NEXT;

  -- ── 2. Advertiser gone inactive ───────────────────────────────────────────
  WITH prior_active AS (
    SELECT cp.organization_id, count(*) AS prv, max(cp.published_at) AS last_post
    FROM mkt_content_posts cp
    WHERE cp.published_at >= v_now - (p_window_days * 4) AND cp.published_at < v_cur_from
      AND cp.organization_id IS NOT NULL
    GROUP BY cp.organization_id HAVING count(*) >= p_min_prior
  ),
  silent AS (
    SELECT pa.*, o.name_en, o.name_ar FROM prior_active pa
    JOIN mkt_organizations o ON o.id = pa.organization_id
    WHERE NOT EXISTS (SELECT 1 FROM mkt_content_posts c2
                      WHERE c2.organization_id = pa.organization_id AND c2.published_at >= v_cur_from)
      AND NOT EXISTS (SELECT 1 FROM mkt_paid_ads a2
                      WHERE a2.organization_id = pa.organization_id
                        AND coalesce(a2.platform_started_at, a2.first_seen_at) >= v_cur_from)
  )
  SELECT count(*) INTO v_n FROM (
    SELECT mkt_insight_emit(
      'advertiser_inactive', 'inact:' || organization_id::text || ':' || v_period,
      coalesce(name_ar, name_en) || ' — توقّف النشاط التسويقي',
      NULL, 'warning', organization_id, NULL, NULL,
      jsonb_build_object('rule','advertiser_inactive',
        'posts_in_prior_period', prv, 'last_post_at', last_post,
        'silent_since_days', p_window_days, 'checked_organic_and_paid', true,
        'min_prior_posts', p_min_prior))
    AS emitted_id FROM silent) z WHERE z.emitted_id IS NOT NULL;
  kind := 'advertiser_inactive'; emitted := v_n; RETURN NEXT;

  -- ── 3. Platform shift ─────────────────────────────────────────────────────
  WITH pw AS (
    SELECT cp.organization_id, cp.platform,
           count(*) FILTER (WHERE cp.published_at >= v_cur_from) AS cur,
           count(*) FILTER (WHERE cp.published_at >= v_prv_from AND cp.published_at < v_cur_from) AS prv
    FROM mkt_content_posts cp
    WHERE cp.published_at >= v_prv_from AND cp.organization_id IS NOT NULL
    GROUP BY 1,2
  ),
  shifted AS (
    SELECT pw.*, o.name_en, o.name_ar,
           round((pw.cur::numeric) / nullif(pw.prv,0), 2) AS ratio
    FROM pw JOIN mkt_organizations o ON o.id = pw.organization_id
    WHERE pw.prv >= 3 AND (pw.cur >= pw.prv * 2 OR pw.cur * 2 <= pw.prv)
  )
  SELECT count(*) INTO v_n FROM (
    SELECT mkt_insight_emit(
      'platform_shift',
      'pshift:' || organization_id::text || ':' || platform || ':' || v_period,
      coalesce(name_ar, name_en) || ' — ' || platform || ': ' ||
        CASE WHEN ratio >= 2 THEN 'تضاعف النشاط' ELSE 'تراجع النشاط للنصف' END,
      NULL, CASE WHEN ratio >= 2 THEN 'opportunity' ELSE 'info' END,
      organization_id, NULL, NULL,
      jsonb_build_object('rule','platform_shift', 'platform', platform,
        'current_window_posts', cur, 'prior_window_posts', prv, 'ratio', ratio,
        'window_days', p_window_days, 'min_prior_posts', 3))
    AS emitted_id FROM shifted) z WHERE z.emitted_id IS NOT NULL;
  kind := 'platform_shift'; emitted := v_n; RETURN NEXT;

  -- ── 4. Messaging shift ────────────────────────────────────────────────────
  WITH fw AS (
    SELECT f.organization_id, f.fact_type,
           count(*) FILTER (WHERE f.observed_at >= v_cur_from) AS cur,
           count(*) FILTER (WHERE f.observed_at >= v_prv_from AND f.observed_at < v_cur_from) AS prv
    FROM mkt_observed_facts f
    WHERE f.observed_at >= v_prv_from AND f.organization_id IS NOT NULL
      AND f.fact_type IN ('payment_plan','financing','offer','content_type','price')
    GROUP BY 1,2
  ),
  shifted AS (
    SELECT fw.*, o.name_en, o.name_ar,
           round(100.0 * (fw.cur - fw.prv) / nullif(fw.prv,0), 1) AS pct
    FROM fw JOIN mkt_organizations o ON o.id = fw.organization_id
    WHERE fw.prv >= 3 AND abs(round(100.0 * (fw.cur - fw.prv) / nullif(fw.prv,0), 1)) >= 50
  )
  SELECT count(*) INTO v_n FROM (
    SELECT mkt_insight_emit(
      'messaging_shift',
      'mshift:' || organization_id::text || ':' || fact_type || ':' || v_period,
      coalesce(name_ar, name_en) || ' — ' ||
        CASE WHEN pct > 0 THEN 'تزايد استخدام ' ELSE 'تراجع استخدام ' END || fact_type ||
        ' (' || abs(pct)::text || '%)',
      NULL, 'info', organization_id, NULL, NULL,
      jsonb_build_object('rule','messaging_shift', 'fact_type', fact_type,
        'current_window_observations', cur, 'prior_window_observations', prv,
        'change_pct', pct, 'window_days', p_window_days,
        'threshold_pct', 50, 'min_prior_observations', 3))
    AS emitted_id FROM shifted) z WHERE z.emitted_id IS NOT NULL;
  kind := 'messaging_shift'; emitted := v_n; RETURN NEXT;

  -- ── 5. New COMMERCIAL offer detected (noise-filtered) ─────────────────────
  WITH first_seen AS (
    SELECT f.organization_id, f.fact_type,
           -- punctuation-insensitive novelty key: "تحكم ذكي - X" and
           -- "تحكم ذكي / X" are ONE claim
           regexp_replace(lower(f.normalized_key), '[^[:alnum:][:space:]؀-ۿ]', '', 'g') AS novelty_key,
           min(f.observed_at) AS first_at,
           (array_agg(f.value_text ORDER BY f.observed_at))[1] AS sample_value,
           (array_agg(f.id ORDER BY f.observed_at))[1] AS sample_fact_id,
           (array_agg(f.content_post_id ORDER BY f.observed_at))[1] AS sample_post_id
    FROM mkt_observed_facts f
    WHERE f.fact_type IN ('offer','financing','payment_plan')
      AND f.organization_id IS NOT NULL
      -- financing/payment_plan are inherently commercial; a bare `offer` must
      -- carry a commercial signal or it is a tagline, not an offer.
      AND (f.fact_type IN ('financing','payment_plan')
           OR f.value_text ~ '[0-9]'
           OR f.value_text ~* '(%|ريال|SAR|تقسيط|دفعة|خصم|تمويل|مجان|كاش|قسط|عرض خاص)')
    GROUP BY 1,2,3
  ),
  org_history AS (
    SELECT organization_id, min(observed_at) AS org_first_fact
    FROM mkt_observed_facts WHERE organization_id IS NOT NULL GROUP BY 1
  ),
  novel AS (
    SELECT fs.*, o.name_en, o.name_ar FROM first_seen fs
    JOIN mkt_organizations o ON o.id = fs.organization_id
    JOIN org_history h ON h.organization_id = fs.organization_id
    WHERE fs.first_at >= v_cur_from AND h.org_first_fact < v_cur_from
  )
  SELECT count(*) INTO v_n FROM (
    SELECT mkt_insight_emit(
      'new_offer_detected',
      'newoffer:' || organization_id::text || ':' || fact_type || ':' || left(novelty_key, 120),
      coalesce(name_ar, name_en) || ' — عرض جديد: ' || left(sample_value, 80),
      sample_value, 'opportunity', organization_id, NULL, NULL,
      jsonb_build_object('rule','new_offer_detected', 'fact_type', fact_type,
        'value', sample_value, 'novelty_key', novelty_key, 'first_observed_at', first_at,
        'source_fact_id', sample_fact_id, 'source_post_id', sample_post_id,
        'commercial_signal_required', fact_type = 'offer', 'window_days', p_window_days))
    AS emitted_id FROM novel) z WHERE z.emitted_id IS NOT NULL;
  kind := 'new_offer_detected'; emitted := v_n; RETURN NEXT;

  -- ── 6. New marketer on a project (import-safe) ────────────────────────────
  -- Requires a PRIOR marketer link on the same project, observed >= 1 day
  -- earlier. The first marketer we ever record cannot be called "new" — we just
  -- started looking. Only a genuine ADDITION fires.
  WITH entered AS (
    SELECT po.project_id, po.organization_id, po.relationship_type,
           po.first_observed_at, po.confidence, po.human_confirmed,
           o.name_en, o.name_ar, r.data->>'project_name' AS project_name,
           (SELECT min(p2.first_observed_at) FROM mkt_project_organizations p2
             WHERE p2.project_id = po.project_id
               AND p2.relationship_type IN ('authorized_marketer','observed_marketer')
               AND p2.organization_id <> po.organization_id) AS prior_marketer_at
    FROM mkt_project_organizations po
    JOIN mkt_organizations o ON o.id = po.organization_id
    LEFT JOIN unified_records r ON r.id = po.project_id
    WHERE po.relationship_type IN ('authorized_marketer','observed_marketer')
      AND po.first_observed_at >= v_cur_from
  ),
  additions AS (
    SELECT * FROM entered
    WHERE prior_marketer_at IS NOT NULL
      AND prior_marketer_at < first_observed_at - interval '1 day'
  )
  SELECT count(*) INTO v_n FROM (
    SELECT mkt_insight_emit(
      'new_marketer',
      'newmkt:' || project_id::text || ':' || organization_id::text || ':' || relationship_type,
      'مسوّق جديد على ' || coalesce(project_name, 'مشروع') || ' — ' || coalesce(name_ar, name_en),
      NULL, 'opportunity', organization_id, project_id, NULL,
      jsonb_build_object('rule','new_marketer', 'relationship_type', relationship_type,
        'first_observed_at', first_observed_at,
        'prior_marketer_first_observed_at', prior_marketer_at,
        'link_confidence', confidence, 'human_confirmed', human_confirmed,
        'guard', 'requires an existing marketer on the project >= 1 day earlier, '
              || 'so a bulk import cannot be reported as arrivals',
        'window_days', p_window_days))
    AS emitted_id FROM additions) z WHERE z.emitted_id IS NOT NULL;
  kind := 'new_marketer'; emitted := v_n; RETURN NEXT;

  -- ── 7. Advertised price movement ──────────────────────────────────────────
  WITH pw AS (
    SELECT f.organization_id,
           avg(f.value_num) FILTER (WHERE f.observed_at >= v_now - (p_window_days*3)) AS cur_avg,
           count(*)         FILTER (WHERE f.observed_at >= v_now - (p_window_days*3)) AS cur_n,
           avg(f.value_num) FILTER (WHERE f.observed_at >= v_now - (p_window_days*6)
                                      AND f.observed_at <  v_now - (p_window_days*3)) AS prv_avg,
           count(*)         FILTER (WHERE f.observed_at >= v_now - (p_window_days*6)
                                      AND f.observed_at <  v_now - (p_window_days*3)) AS prv_n
    FROM mkt_observed_facts f
    WHERE f.fact_type = 'price' AND f.value_num IS NOT NULL
      AND f.organization_id IS NOT NULL AND f.observed_at >= v_now - (p_window_days*6)
    GROUP BY 1
  ),
  moved AS (
    SELECT pw.*, o.name_en, o.name_ar,
           round(100.0 * (pw.cur_avg - pw.prv_avg) / nullif(pw.prv_avg,0), 1) AS pct
    FROM pw JOIN mkt_organizations o ON o.id = pw.organization_id
    WHERE pw.cur_n >= 2 AND pw.prv_n >= 2
      AND abs(round(100.0 * (pw.cur_avg - pw.prv_avg) / nullif(pw.prv_avg,0), 1)) >= 10
  )
  SELECT count(*) INTO v_n FROM (
    SELECT mkt_insight_emit(
      'price_movement', 'pmove:' || organization_id::text || ':' || v_period,
      coalesce(name_ar, name_en) || ' — ' ||
        CASE WHEN pct > 0 THEN 'ارتفاع الأسعار المعلنة ' ELSE 'انخفاض الأسعار المعلنة ' END
        || abs(pct)::text || '%',
      NULL, 'info', organization_id, NULL, NULL,
      jsonb_build_object('rule','price_movement',
        'current_avg', round(cur_avg), 'prior_avg', round(prv_avg),
        'current_observations', cur_n, 'prior_observations', prv_n,
        'change_pct', pct, 'currency', 'SAR', 'window_days', p_window_days * 3,
        'threshold_pct', 10, 'min_observations_each_side', 2))
    AS emitted_id FROM moved) z WHERE z.emitted_id IS NOT NULL;
  kind := 'price_movement'; emitted := v_n; RETURN NEXT;

  RETURN;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_goal_actual(p_goal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE g record; v numeric; n int; v_last date;
BEGIN
  SELECT * INTO g FROM public.mkt_goals WHERE id = p_goal_id;
  IF g IS NULL THEN RETURN NULL; END IF;

  SELECT count(*), max(measured_at) INTO n, v_last
    FROM public.mkt_goal_measurements WHERE goal_id = p_goal_id;

  IF n = 0 THEN
    RETURN jsonb_build_object('value', NULL, 'measurements', 0, 'is_measured', false,
      'method', g.aggregation_method, 'last_measured_at', NULL);
  END IF;

  v := CASE COALESCE(g.aggregation_method, 'latest')
    WHEN 'sum'     THEN (SELECT sum(value)  FROM public.mkt_goal_measurements WHERE goal_id=p_goal_id)
    WHEN 'average' THEN (SELECT avg(value)  FROM public.mkt_goal_measurements WHERE goal_id=p_goal_id)
    WHEN 'rate'    THEN (SELECT value FROM public.mkt_goal_measurements
                          WHERE goal_id=p_goal_id ORDER BY measured_at DESC, created_at DESC LIMIT 1)
    WHEN 'min'     THEN (SELECT min(value)  FROM public.mkt_goal_measurements WHERE goal_id=p_goal_id)
    WHEN 'max'     THEN (SELECT max(value)  FROM public.mkt_goal_measurements WHERE goal_id=p_goal_id)
    WHEN 'custom'  THEN (SELECT value FROM public.mkt_goal_measurements
                          WHERE goal_id=p_goal_id ORDER BY measured_at DESC, created_at DESC LIMIT 1)
    ELSE                (SELECT value FROM public.mkt_goal_measurements
                          WHERE goal_id=p_goal_id ORDER BY measured_at DESC, created_at DESC LIMIT 1)
  END;

  RETURN jsonb_build_object('value', v, 'measurements', n, 'is_measured', true,
    'method', COALESCE(g.aggregation_method, 'latest'), 'last_measured_at', v_last);
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_goal_allocation_status(p_goal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE g record; v_sum numeric; n int; v_additive boolean;
BEGIN
  SELECT * INTO g FROM public.mkt_goals WHERE id = p_goal_id;
  IF g IS NULL THEN RETURN NULL; END IF;

  SELECT count(*), sum(target_value) INTO n, v_sum
    FROM public.mkt_goal_target_periods WHERE goal_id = p_goal_id;

  v_additive := COALESCE(g.aggregation_method, 'latest') = 'sum';

  RETURN jsonb_build_object(
    'goal_id',    p_goal_id,
    'periods',    n,
    'has_allocation', n > 0,
    'is_additive', v_additive,
    'target',     g.target_value,
    'allocated',  v_sum,
    'difference', CASE WHEN v_additive AND g.target_value IS NOT NULL AND n > 0
                       THEN COALESCE(v_sum,0) - g.target_value ELSE NULL END,
    'consistent', CASE WHEN NOT v_additive THEN NULL
                       WHEN n = 0 OR g.target_value IS NULL THEN NULL
                       ELSE COALESCE(v_sum,0) = g.target_value END,
    'note', CASE
      WHEN NOT v_additive THEN 'non-additive metric: periods are independent targets, they do not sum to the total'
      WHEN n = 0 THEN 'no allocation set'
      ELSE NULL END);
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_goal_effective_dates(p_goal_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'start',      COALESCE(g.start_date, p.period_start),
    'end',        COALESCE(g.end_date,   p.period_end),
    'start_overridden', g.start_date IS NOT NULL,
    'end_overridden',   g.end_date   IS NOT NULL,
    'plan_start', p.period_start,
    'plan_end',   p.period_end)
  FROM public.mkt_goals g JOIN public.mkt_plans p ON p.id = g.plan_id
  WHERE g.id = p_goal_id;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_goal_missing_requirements(p_goal_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE g record; d jsonb; missing text[] := ARRAY[]::text[];
BEGIN
  SELECT * INTO g FROM public.mkt_goals WHERE id = p_goal_id;
  IF g IS NULL THEN RETURN ARRAY['goal not found']; END IF;

  IF g.plan_id IS NULL                                THEN missing := array_append(missing,'plan'); END IF;
  IF g.goal_class IS NULL                             THEN missing := array_append(missing,'goal_class'); END IF;
  IF g.metric IS NULL OR btrim(g.metric) = ''         THEN missing := array_append(missing,'metric'); END IF;
  IF g.unit IS NULL OR btrim(g.unit) = ''             THEN missing := array_append(missing,'unit'); END IF;
  IF g.target_value IS NULL                           THEN missing := array_append(missing,'target'); END IF;
  IF g.owner_user_id IS NULL                          THEN missing := array_append(missing,'owner'); END IF;
  IF g.measurement_frequency IS NULL                  THEN missing := array_append(missing,'measurement_frequency'); END IF;
  IF g.source_of_truth IS NULL                        THEN missing := array_append(missing,'source_of_truth'); END IF;
  IF g.aggregation_method IS NULL                     THEN missing := array_append(missing,'aggregation_method'); END IF;
  IF g.baseline_state IS NULL                         THEN missing := array_append(missing,'baseline_state'); END IF;

  d := public.mkt_goal_effective_dates(p_goal_id);
  IF d IS NULL OR d->>'start' IS NULL                 THEN missing := array_append(missing,'start_date'); END IF;
  IF d IS NULL OR d->>'end'   IS NULL                 THEN missing := array_append(missing,'end_date'); END IF;

  RETURN missing;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_goal_pacing(p_goal_id uuid, p_as_of date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE g record; v_expected numeric; v_actual numeric; v_periods int; v_measured int;
BEGIN
  SELECT * INTO g FROM public.mkt_goals WHERE id = p_goal_id;
  IF g IS NULL THEN RETURN NULL; END IF;
  SELECT count(*), count(actual_value),
         sum(target_value) FILTER (WHERE period_start <= p_as_of),
         sum(actual_value)
    INTO v_periods, v_measured, v_expected, v_actual
    FROM public.mkt_goal_target_periods WHERE goal_id = p_goal_id;
  RETURN jsonb_build_object(
    'goal_id',        p_goal_id,
    'target',         g.target_value,
    'has_periods',    COALESCE(v_periods, 0) > 0,
    'periods_total',  COALESCE(v_periods, 0),
    'periods_measured', COALESCE(v_measured, 0),
    'expected_to_date', v_expected,
    'actual_to_date',   COALESCE(v_actual, g.actual_value),
    'forecast',       g.forecast_value,
    'forecast_is_estimate', g.forecast_value IS NOT NULL,
    'result',         g.result,
    'source_of_truth', g.source_of_truth,
    'coverage', CASE WHEN COALESCE(v_periods,0) = 0 THEN NULL
                     ELSE jsonb_build_object('measured', COALESCE(v_measured,0), 'total', v_periods) END
  );
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_goal_rollup(p_goal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_items int; v_direct int; v_influenced int; v_revenue numeric;
        v_measured int; v_pubs int;
BEGIN
  WITH items AS (
    SELECT DISTINCT ci.id
      FROM public.mkt_content_items ci
     WHERE ci.archived_at IS NULL AND (
       ci.primary_goal_id = p_goal_id
       OR ci.origin_program_id IN (
            SELECT id FROM public.mkt_programs WHERE primary_goal_id = p_goal_id
            UNION SELECT program_id FROM public.mkt_activity_goals
                   WHERE goal_id = p_goal_id AND program_id IS NOT NULL)
       OR ci.origin_campaign_id IN (
            SELECT id FROM public.mkt_internal_campaigns WHERE primary_goal_id = p_goal_id
            UNION SELECT campaign_id FROM public.mkt_activity_goals
                   WHERE goal_id = p_goal_id AND campaign_id IS NOT NULL)
       OR EXISTS (SELECT 1 FROM public.mkt_content_usage u
                   WHERE u.content_item_id = ci.id AND (
                     u.campaign_id IN (SELECT id FROM public.mkt_internal_campaigns
                                        WHERE primary_goal_id = p_goal_id)
                  OR u.program_id  IN (SELECT id FROM public.mkt_programs
                                        WHERE primary_goal_id = p_goal_id)))
     )
  ),
  pubs AS (
    SELECT p.id,
           EXISTS (SELECT 1 FROM public.mkt_performance_snapshots s
                    WHERE s.publication_id = p.id
                      AND s.collection_status IN ('collected','partial')) AS measured
      FROM public.mkt_publications p
     WHERE p.content_item_id IN (SELECT id FROM items)
  ),
  leads AS (
    SELECT count(DISTINCT client_id) FILTER (WHERE touch_type = 'last'
               OR attribution_type IN ('platform_lead_form','manual_confirmed')) AS direct,
           count(DISTINCT client_id) FILTER (WHERE touch_type IN ('first','multi')
               AND attribution_type NOT IN ('platform_lead_form','manual_confirmed')) AS influenced,
           sum(revenue) AS revenue
      FROM public.mkt_lead_attributions
     WHERE content_item_id IN (SELECT id FROM items)
  )
  SELECT (SELECT count(*) FROM items),
         (SELECT count(*) FROM pubs),
         (SELECT count(*) FROM pubs WHERE measured),
         l.direct, l.influenced, l.revenue
    INTO v_items, v_pubs, v_measured, v_direct, v_influenced, v_revenue
    FROM leads l;

  RETURN jsonb_build_object(
    'goal_id',          p_goal_id,
    'content_items',    COALESCE(v_items, 0),
    'publications',     COALESCE(v_pubs, 0),
    'coverage',         jsonb_build_object('measured', COALESCE(v_measured, 0),
                                           'total', COALESCE(v_pubs, 0)),
    'leads_direct',     COALESCE(v_direct, 0),
    'leads_influenced', COALESCE(v_influenced, 0),
    'revenue',          v_revenue,
    'pacing',           public.mkt_goal_pacing(p_goal_id)
  );
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_heartbeat(p_component text, p_detail jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  INSERT INTO public.mkt_ops_heartbeats (component, last_beat_at, detail)
  VALUES (p_component, now(), COALESCE(p_detail,'{}'::jsonb))
  ON CONFLICT (component) DO UPDATE SET last_beat_at=now(), detail=EXCLUDED.detail;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_identity_candidate_upsert(p_org uuid, p_platform text, p_handle text, p_account_id text, p_url text, p_class text, p_score numeric, p_confidence text, p_is_marketplace boolean, p_reasons jsonb, p_evidence jsonb, p_status text, p_verification_method text, p_run uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_existing text;
BEGIN
  SELECT id, status INTO v_id, v_existing FROM public.mkt_identity_candidates
   WHERE organization_id=p_org AND platform=p_platform AND handle=p_handle;
  IF v_id IS NULL THEN
    INSERT INTO public.mkt_identity_candidates
      (organization_id, platform, handle, account_id, url, account_class, score, confidence, is_marketplace,
       reasons, evidence, status, verification_method, discovery_run_id)
    VALUES (p_org, p_platform, p_handle, p_account_id, p_url, COALESCE(p_class,'unknown'), p_score, p_confidence,
            COALESCE(p_is_marketplace,false), COALESCE(p_reasons,'[]'::jsonb), COALESCE(p_evidence,'[]'::jsonb),
            COALESCE(p_status,'candidate'), p_verification_method, p_run)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.mkt_identity_candidates SET
      account_id=COALESCE(p_account_id, account_id), url=COALESCE(p_url, url), account_class=COALESCE(p_class, account_class),
      score=p_score, confidence=p_confidence, is_marketplace=COALESCE(p_is_marketplace,false),
      reasons=COALESCE(p_reasons, reasons), evidence=COALESCE(p_evidence, evidence),
      status=CASE WHEN status IN ('confirmed','rejected') AND p_status NOT IN ('confirmed','rejected') THEN status ELSE COALESCE(p_status, status) END,
      verification_method=COALESCE(p_verification_method, verification_method),
      discovery_run_id=COALESCE(p_run, discovery_run_id), last_verified_at=now(), updated_at=now()
    WHERE id=v_id;
  END IF;
  RETURN v_id;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_ingestion_run_finish(p_run_id uuid, p_status text, p_received integer, p_inserted integer, p_updated integer, p_skipped integer, p_errors jsonb DEFAULT '[]'::jsonb, p_cost jsonb DEFAULT NULL::jsonb, p_rate jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  UPDATE public.mkt_ingestion_runs
     SET status=p_status, finished_at=now(), items_received=p_received, items_inserted=p_inserted,
         items_updated=p_updated, items_skipped=p_skipped, errors=COALESCE(p_errors,'[]'::jsonb),
         provider_cost=p_cost, rate_limit_info=p_rate
   WHERE id=p_run_id;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_ingestion_run_start(p_provider text, p_source_account_id uuid, p_scope jsonb, p_worker_job_ref text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  INSERT INTO public.mkt_ingestion_runs (provider, source_account_id, requested_scope, worker_job_ref)
  VALUES (p_provider, p_source_account_id, COALESCE(p_scope,'{}'::jsonb), p_worker_job_ref)
  RETURNING id;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_initiative_missing_requirements(p_initiative_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE i record; missing text[] := '{}'; n_exec int;
BEGIN
  SELECT * INTO i FROM public.mkt_initiatives WHERE id = p_initiative_id;
  IF i IS NULL THEN RETURN ARRAY['not_found']; END IF;
  IF i.plan_id IS NULL         THEN missing := array_append(missing, 'plan'); END IF;
  IF i.primary_goal_id IS NULL THEN missing := array_append(missing, 'primary_goal'); END IF;
  IF i.owner_user_id IS NULL   THEN missing := array_append(missing, 'owner'); END IF;
  IF i.hypothesis IS NULL OR btrim(i.hypothesis) = ''
                               THEN missing := array_append(missing, 'hypothesis'); END IF;
  IF i.expected_contribution IS NULL OR btrim(i.expected_contribution) = ''
                               THEN missing := array_append(missing, 'expected_contribution'); END IF;
  SELECT (SELECT count(*) FROM public.mkt_programs WHERE initiative_id = i.id AND archived_at IS NULL)
       + (SELECT count(*) FROM public.mkt_internal_campaigns WHERE initiative_id = i.id AND archived_at IS NULL)
    INTO n_exec;
  IF n_exec = 0 THEN missing := array_append(missing, 'execution'); END IF;
  RETURN missing;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_insight_emit(p_kind text, p_dedup_key text, p_title text, p_body text DEFAULT NULL::text, p_severity text DEFAULT 'info'::text, p_organization_id uuid DEFAULT NULL::uuid, p_project_id uuid DEFAULT NULL::uuid, p_campaign_id uuid DEFAULT NULL::uuid, p_evidence jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  INSERT INTO public.mkt_insights (kind, dedup_key, title, body, severity, organization_id, project_id, campaign_id, evidence)
  VALUES (p_kind, p_dedup_key, p_title, p_body, p_severity, p_organization_id, p_project_id, p_campaign_id, COALESCE(p_evidence,'{}'::jsonb))
  ON CONFLICT (dedup_key) DO NOTHING RETURNING id INTO v_id;
  RETURN v_id;  -- NULL when it already existed (idempotent)
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_insight_set_dismissed(p_insight_id uuid, p_dismissed boolean)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  UPDATE public.mkt_insights SET dismissed = COALESCE(p_dismissed, true)
   WHERE id = p_insight_id
  RETURNING true;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_intelligence_evidence(p_post_ids uuid[])
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(jsonb_agg(ev), '[]'::jsonb) FROM (
    SELECT jsonb_build_object(
      'post_id', cp.id,
      'platform', cp.platform,
      'post_type', cp.post_type,
      'account', (SELECT '@'||handle||' ('||platform||')' FROM mkt_social_accounts sa WHERE sa.id=cp.social_account_id),
      'organization_id', cp.organization_id,
      'caption',    left(coalesce(cp.caption,''), 8000),
      'transcript', left(coalesce(tr.txt,''),    16000),
      'ocr_text',   left(coalesce(oc.txt,''),    12000),
      -- Full lengths + explicit flags: a truncated field is visible, never silent.
      'evidence_lengths', jsonb_build_object(
        'caption',    length(coalesce(cp.caption,'')),
        'transcript', length(coalesce(tr.txt,'')),
        'ocr_text',   length(coalesce(oc.txt,''))
      ),
      'evidence_truncated', jsonb_build_object(
        'caption',    length(coalesce(cp.caption,'')) > 8000,
        'transcript', length(coalesce(tr.txt,''))    > 16000,
        'ocr_text',   length(coalesce(oc.txt,''))    > 12000
      ),
      'candidates', coalesce(e.candidate_projects, '[]'::jsonb),
      'deterministic_partial', coalesce((e.result->>'deterministic_partial')::boolean, false),
      'snippet', coalesce(e.result->>'snippet','')
    ) AS ev
    FROM mkt_content_posts cp
    LEFT JOIN mkt_content_enrichment e ON e.content_post_id = cp.id
    LEFT JOIN LATERAL (
      SELECT string_agg(nullif(t.text,''), ' ') AS txt
      FROM mkt_transcripts t WHERE t.content_post_id = cp.id AND t.status = 'done'
    ) tr ON true
    LEFT JOIN LATERAL (
      SELECT string_agg(nullif(v.text,''), ' | ') AS txt
      FROM mkt_visual_text v WHERE v.content_post_id = cp.id
    ) oc ON true
    WHERE cp.id = ANY(p_post_ids)
  ) s;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_intelligence_index(p_limit integer DEFAULT 60)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_all_projects constant uuid := '220c49b9-de57-492d-9eca-c0d9f54fd40f';
  v_limit int := greatest(1, least(coalesce(p_limit, 60), 500));
  v_insights jsonb; v_projects jsonb; v_orgs jsonb; v_coverage jsonb;
  v_proj_total int; v_org_total int; v_ins_total int;
BEGIN
  SELECT count(*) INTO v_ins_total FROM mkt_insights WHERE COALESCE(dismissed,false) = false;

  SELECT COALESCE(jsonb_agg(x ORDER BY x.severity_rank, x.generated_at DESC), '[]'::jsonb)
    INTO v_insights
  FROM (
    SELECT i.id, i.kind, i.severity, i.title, i.body, i.evidence, i.generated_at,
           i.project_id, i.organization_id,
           r.data->>'project_name' AS project_name,
           COALESCE(o.name_ar, o.name_en) AS organization_name,
           CASE i.severity WHEN 'critical' THEN 0 WHEN 'warning' THEN 1 ELSE 2 END AS severity_rank
    FROM mkt_insights i
    LEFT JOIN unified_records r ON r.id = i.project_id AND r.model_id = v_all_projects
    LEFT JOIN mkt_organizations o ON o.id = i.organization_id
    WHERE COALESCE(i.dismissed,false) = false
    ORDER BY severity_rank, i.generated_at DESC
    LIMIT v_limit
  ) x;

  SELECT count(*) INTO v_proj_total
  FROM mkt_project_marketing_state s
  WHERE s.post_count > 0 OR s.candidate_post_count > 0 OR s.ad_count > 0;

  SELECT COALESCE(jsonb_agg(x ORDER BY x.last_activity_at DESC NULLS LAST), '[]'::jsonb)
    INTO v_projects
  FROM (
    SELECT s.project_id, r.data->>'project_name' AS name, r.data->>'city' AS city,
           s.post_count, s.candidate_post_count, s.ad_count, s.fact_count,
           s.org_count, s.platform_count, s.platforms,
           s.min_advertised_price, s.max_advertised_price, s.last_activity_at
    FROM mkt_project_marketing_state s
    LEFT JOIN unified_records r ON r.id = s.project_id AND r.model_id = v_all_projects
    WHERE s.post_count > 0 OR s.candidate_post_count > 0 OR s.ad_count > 0
    ORDER BY s.last_activity_at DESC NULLS LAST
    LIMIT v_limit
  ) x;

  SELECT count(*) INTO v_org_total
  FROM mkt_organizations o
  WHERE EXISTS (SELECT 1 FROM mkt_content_posts p WHERE p.organization_id = o.id)
     OR EXISTS (SELECT 1 FROM mkt_project_organizations po WHERE po.organization_id = o.id AND po.is_active);

  SELECT COALESCE(jsonb_agg(x ORDER BY x.post_count DESC, x.name), '[]'::jsonb)
    INTO v_orgs
  FROM (
    SELECT o.id AS organization_id,
           COALESCE(o.name_ar, o.name_en) AS name,
           o.name_ar, o.name_en, o.hq_city, o.status, o.website,
           (SELECT count(*) FROM mkt_project_organizations po
             WHERE po.organization_id = o.id AND po.is_active)            AS project_count,
           (SELECT count(*) FROM mkt_content_posts p
             WHERE p.organization_id = o.id)                              AS post_count,
           (SELECT count(*) FROM mkt_observed_facts f
             WHERE f.organization_id = o.id)                              AS fact_count,
           (SELECT max(p.published_at) FROM mkt_content_posts p
             WHERE p.organization_id = o.id)                              AS last_activity_at
    FROM mkt_organizations o
    WHERE EXISTS (SELECT 1 FROM mkt_content_posts p WHERE p.organization_id = o.id)
       OR EXISTS (SELECT 1 FROM mkt_project_organizations po WHERE po.organization_id = o.id AND po.is_active)
    ORDER BY post_count DESC, name
    LIMIT v_limit
  ) x;

  SELECT jsonb_build_object(
    'posts_total',        (SELECT count(*) FROM mkt_content_posts),
    'posts_processed',    (SELECT count(*) FROM mkt_content_posts
                            WHERE processing_status IN ('processed','partial')),
    'posts_awaiting_intelligence', (SELECT count(*) FROM mkt_content_posts
                                     WHERE processing_status = 'awaiting_intelligence'),
    'posts_failed',       (SELECT count(*) FROM mkt_content_posts
                            WHERE processing_status = 'failed'),
    'posts_by_status',    (SELECT COALESCE(jsonb_object_agg(s, n), '{}'::jsonb)
                             FROM (SELECT COALESCE(processing_status,'(none)') AS s, count(*) AS n
                                     FROM mkt_content_posts GROUP BY 1) q),
    'posts_without_ocr',  (SELECT count(*) FROM mkt_content_posts p
                            WHERE NOT EXISTS (SELECT 1 FROM mkt_visual_text v
                                               WHERE v.content_post_id = p.id)),
    'facts_total',        (SELECT count(*) FROM mkt_observed_facts),
    'orgs_total',         v_org_total,
    'orgs_with_facts',    (SELECT count(DISTINCT organization_id) FROM mkt_observed_facts
                            WHERE organization_id IS NOT NULL),
    'attribution',        jsonb_build_object(
                            'confirmed',   (SELECT count(*) FROM mkt_content_attributions
                                             WHERE review_status IN ('auto_accepted','confirmed')),
                            'speculative', (SELECT count(*) FROM mkt_content_attributions
                                             WHERE review_status = 'candidate')),
    'note_ar', 'أعداد منشورات المشاريع تحتسب الإسناد المؤكد فقط. المرشّحة تُعرض منفصلة ولا تُخلط أبداً. المنشورات بانتظار الإسناد لها حقائق مستخرجة بالفعل (الوسائط وقراءة الصور واستخراج الحقائق مكتملة) لكن دون قرار مشروع بعد. المنشورات بلا قراءة صور تساهم بنص التعليق والتفريغ فقط.', 'note', 'Project post counts are CONFIRMED attributions only. Speculative '
         || 'candidates are reported separately and are never mixed in. Posts '
         || 'awaiting_intelligence already contribute facts (media, OCR and fact '
         || 'extraction are complete) but carry no project decision yet. Posts '
         || 'without OCR contribute caption and transcript evidence only.'
  ) INTO v_coverage;

  RETURN jsonb_build_object(
    'generated_at', now(),
    'insights',      jsonb_build_object('shown', jsonb_array_length(v_insights),
                                        'total', v_ins_total, 'rows', v_insights),
    'projects',      jsonb_build_object('shown', jsonb_array_length(v_projects),
                                        'total', v_proj_total, 'rows', v_projects),
    'organizations', jsonb_build_object('shown', jsonb_array_length(v_orgs),
                                        'total', v_org_total, 'rows', v_orgs),
    'coverage', v_coverage
  );
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_is_commercial_offer(p_value text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(
    p_value ~* ('(تقسيط|أقساط|قسط\y|دفعة|مقدم'
             || '|خصم|خصوم|تخفيض|عرض خاص|عرض لفترة|سعر خاص'
             || '|مجان|هدية|كاش ?باك|استرداد|إعفاء|اعفاء|بدون رسوم'
             || '|تمويل|دعم عقاري'
             || '|discount|cashback|free|gift|installment|instalment|waiv|bonus|promo)')
    OR (p_value ~ '[0-9]' AND p_value ~* '(%|ريال|ر\.س|SAR|halala|هللة)'),
    false);
$function$;
CREATE OR REPLACE FUNCTION public.mkt_job_claim_next(p_worker_id text, p_lease_seconds integer DEFAULT 600)
 RETURNS TABLE(job_id uuid, kind text, provider text, social_account_id uuid, params jsonb, attempts integer, max_attempts integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_paused boolean;
BEGIN
  SELECT (value)::boolean INTO v_paused FROM public.mkt_settings WHERE key='collection_paused';
  IF COALESCE(v_paused, true) THEN RETURN; END IF;
  RETURN QUERY
  UPDATE public.mkt_collection_jobs j
     SET status='running', worker_id=p_worker_id, started_at=now(),
         lease_expires_at=now() + make_interval(secs => p_lease_seconds), attempts=j.attempts + 1
   WHERE j.id = (
     SELECT c.id FROM public.mkt_collection_jobs c
      LEFT JOIN public.mkt_social_accounts a ON a.id = c.social_account_id
      JOIN public.mkt_providers pr ON pr.provider_key = c.provider
      WHERE c.status='queued' AND c.next_run_at <= now()
        AND pr.is_enabled
        AND (c.social_account_id IS NULL OR (a.collection_enabled AND a.is_active))
        AND (SELECT count(*) FROM public.mkt_collection_jobs rr WHERE rr.status='running' AND rr.provider=c.provider) < pr.max_concurrency
      ORDER BY c.priority, c.next_run_at
      FOR UPDATE OF c SKIP LOCKED LIMIT 1
   )
   RETURNING j.id, j.kind, j.provider, j.social_account_id, j.params, j.attempts, j.max_attempts;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_job_complete(p_job_id uuid, p_result jsonb, p_run_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  UPDATE public.mkt_collection_jobs SET status='succeeded', result=COALESCE(p_result,'{}'::jsonb),
         ingestion_run_id=COALESCE(p_run_id, ingestion_run_id), finished_at=now(), lease_expires_at=NULL
   WHERE id=p_job_id AND status='running';
$function$;
CREATE OR REPLACE FUNCTION public.mkt_job_enqueue(p_kind text, p_provider text, p_social_account_id uuid, p_params jsonb DEFAULT '{}'::jsonb, p_priority integer DEFAULT 100, p_requested_by uuid DEFAULT NULL::uuid, p_fallback_of uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_max int; v_org uuid; v_conf boolean; v_page text;
BEGIN
  IF p_kind = 'paid_ads' THEN
    v_org := NULLIF(p_params->>'organization_id','')::uuid;
    IF v_org IS NULL THEN RAISE EXCEPTION 'paid_ads requires organization_id in params' USING ERRCODE='23514'; END IF;
    SELECT meta_confirmed, meta_page_id INTO v_conf, v_page FROM public.mkt_organizations WHERE id=v_org;
    IF NOT COALESCE(v_conf,false) OR v_page IS NULL THEN
      RAISE EXCEPTION 'paid_ads blocked: organization % has no confirmed advertiser page', v_org USING ERRCODE='23514';
    END IF;
  END IF;

  -- account-scoped dedup: never queue two of the same kind for one account
  IF p_social_account_id IS NOT NULL THEN
    SELECT id INTO v_id FROM public.mkt_collection_jobs
     WHERE social_account_id = p_social_account_id AND kind = p_kind AND status IN ('pending','queued','running') LIMIT 1;
    IF v_id IS NOT NULL THEN RETURN v_id; END IF;
  -- org-scoped dedup for account-less kinds (discover_advertiser, paid_ads):
  -- a double-click/retry returns the in-flight job instead of a duplicate Apify run.
  ELSIF p_kind IN ('discover_advertiser','paid_ads') AND NULLIF(p_params->>'organization_id','') IS NOT NULL THEN
    SELECT id INTO v_id FROM public.mkt_collection_jobs
     WHERE kind = p_kind AND status IN ('pending','queued','running')
       AND params->>'organization_id' = (p_params->>'organization_id') LIMIT 1;
    IF v_id IS NOT NULL THEN RETURN v_id; END IF;
  END IF;

  SELECT COALESCE((SELECT (value)::int FROM public.mkt_settings WHERE key='max_attempts'),5) INTO v_max;
  INSERT INTO public.mkt_collection_jobs (kind, provider, social_account_id, params, priority, max_attempts, requested_by, fallback_of)
  VALUES (p_kind, p_provider, p_social_account_id, COALESCE(p_params,'{}'::jsonb), p_priority, v_max, p_requested_by, p_fallback_of)
  RETURNING id INTO v_id;
  RETURN v_id;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_job_fail(p_job_id uuid, p_error text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_att int; v_max int; v_delay int;
BEGIN
  SELECT attempts, max_attempts INTO v_att, v_max FROM public.mkt_collection_jobs WHERE id=p_job_id AND status='running';
  IF NOT FOUND THEN RETURN 'noop'; END IF;
  IF v_att >= v_max THEN
    UPDATE public.mkt_collection_jobs SET status='failed', error_message=p_error, finished_at=now(), lease_expires_at=NULL WHERE id=p_job_id;
    RETURN 'failed';
  ELSE
    v_delay := LEAST(3600, (power(2, v_att) * 60)::int);
    UPDATE public.mkt_collection_jobs SET status='queued', error_message=p_error, next_run_at=now() + make_interval(secs => v_delay),
           worker_id=NULL, started_at=NULL, lease_expires_at=NULL WHERE id=p_job_id;
    RETURN 'requeued';
  END IF;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_job_retry(p_job_id uuid, p_requested_by uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  UPDATE public.mkt_collection_jobs SET status='queued', attempts=0, next_run_at=now(), error_message=NULL,
         worker_id=NULL, started_at=NULL, lease_expires_at=NULL, finished_at=NULL, requested_by=COALESCE(p_requested_by, requested_by)
   WHERE id=p_job_id AND status IN ('failed','cancelled');
$function$;
CREATE OR REPLACE FUNCTION public.mkt_jobs_watchdog()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n int;
BEGIN
  UPDATE public.mkt_collection_jobs
     SET status = CASE WHEN attempts >= max_attempts THEN 'failed' ELSE 'queued' END,
         error_message = COALESCE(error_message,'') || ' [lease expired]',
         next_run_at = now(), worker_id=NULL, started_at=NULL, lease_expires_at=NULL,
         finished_at = CASE WHEN attempts >= max_attempts THEN now() ELSE NULL END
   WHERE status='running' AND lease_expires_at < now();
  GET DIAGNOSTICS n = ROW_COUNT; RETURN n;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_landing_recount()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP IN ('UPDATE','DELETE') AND OLD.landing_page_id IS NOT NULL THEN
    UPDATE public.mkt_landing_pages SET ad_count=(SELECT count(*) FROM public.mkt_paid_ads WHERE landing_page_id=OLD.landing_page_id) WHERE id=OLD.landing_page_id;
  END IF;
  IF TG_OP IN ('INSERT','UPDATE') AND NEW.landing_page_id IS NOT NULL THEN
    UPDATE public.mkt_landing_pages SET ad_count=(SELECT count(*) FROM public.mkt_paid_ads WHERE landing_page_id=NEW.landing_page_id) WHERE id=NEW.landing_page_id;
  END IF;
  RETURN NULL;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_landing_upsert(p_canonical_url text, p_destination_domain text, p_project_id uuid DEFAULT NULL::uuid, p_organization_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  INSERT INTO public.mkt_landing_pages (canonical_url, destination_domain, project_id, organization_id)
  VALUES (p_canonical_url, p_destination_domain, p_project_id, p_organization_id)
  ON CONFLICT (canonical_url) DO UPDATE SET last_seen_at=now(),
    project_id=COALESCE(mkt_landing_pages.project_id, EXCLUDED.project_id),
    organization_id=COALESCE(mkt_landing_pages.organization_id, EXCLUDED.organization_id)
  RETURNING id INTO v_id;
  RETURN v_id;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_metric_snapshot_insert(p_subject_type text, p_subject_id uuid, p_metrics jsonb, p_provider text DEFAULT NULL::text, p_raw_ref uuid DEFAULT NULL::uuid, p_captured_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  INSERT INTO public.mkt_metric_snapshots (subject_type, subject_id, captured_at, metrics, provider, raw_ref)
  VALUES (p_subject_type, p_subject_id, COALESCE(p_captured_at, now()), p_metrics, p_provider, p_raw_ref)
  RETURNING id INTO v_id;
  IF p_subject_type = 'post' THEN
    UPDATE public.mkt_content_posts SET engagement = p_metrics, last_seen_at = now() WHERE id = p_subject_id;
  END IF;
  RETURN v_id;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_metrics_capture(p_day date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  d0 timestamptz := p_day::timestamptz;
  d1 timestamptz := (p_day + 1)::timestamptz;
  v_runs int; v_fail int; v_recv numeric; v_ins numeric; v_updskip numeric; v_cost numeric; v_lat numeric; v_ok numeric; v_total numeric;
BEGIN
  SELECT count(*) FILTER (WHERE status <> 'running'),
         count(*) FILTER (WHERE status='failed'),
         COALESCE(sum((provider_cost->>'dataset_items')::numeric),0),
         COALESCE(sum(items_inserted),0),
         COALESCE(sum(items_updated + items_skipped),0),
         COALESCE(sum((provider_cost->>'usage_total_usd')::numeric),0),
         AVG(EXTRACT(EPOCH FROM (finished_at - started_at))*1000) FILTER (WHERE finished_at IS NOT NULL),
         count(*) FILTER (WHERE status IN ('succeeded','partial')),
         count(*) FILTER (WHERE status <> 'running')
    INTO v_runs, v_fail, v_recv, v_ins, v_updskip, v_cost, v_lat, v_ok, v_total
    FROM public.mkt_ingestion_runs WHERE started_at >= d0 AND started_at < d1;

  INSERT INTO public.mkt_metric_daily (day, metric, provider, value) VALUES
    (p_day,'runs','all',COALESCE(v_runs,0)),
    (p_day,'failures','all',COALESCE(v_fail,0)),
    (p_day,'items_collected','all',COALESCE(v_recv,0)),
    (p_day,'duplicates_prevented','all',COALESCE(v_updskip,0)),
    (p_day,'provider_cost_usd','all',COALESCE(v_cost,0)),
    (p_day,'avg_latency_ms','all',COALESCE(round(v_lat),0)),
    (p_day,'success_rate','all',CASE WHEN COALESCE(v_total,0)>0 THEN round(v_ok/v_total,4) ELSE 0 END),
    (p_day,'posts_collected','all',(SELECT count(*) FROM public.mkt_content_posts WHERE first_seen_at>=d0 AND first_seen_at<d1)),
    (p_day,'ads_collected','all',(SELECT count(*) FROM public.mkt_paid_ads WHERE first_seen_at>=d0 AND first_seen_at<d1)),
    (p_day,'new_campaigns','all',(SELECT count(*) FROM public.mkt_ad_campaigns WHERE first_seen_at>=d0 AND first_seen_at<d1)),
    (p_day,'new_landing_pages','all',(SELECT count(*) FROM public.mkt_landing_pages WHERE first_seen_at>=d0 AND first_seen_at<d1)),
    (p_day,'new_projects','all',(SELECT count(*) FROM public.mkt_project_organizations WHERE first_observed_at>=d0 AND first_observed_at<d1))
  ON CONFLICT (day, metric, provider) DO UPDATE SET value=EXCLUDED.value, updated_at=now();

  INSERT INTO public.mkt_metric_daily (day, metric, provider, value)
  SELECT p_day, m.metric, r.provider, m.value FROM (
    SELECT provider,
      COALESCE(sum((provider_cost->>'usage_total_usd')::numeric),0) AS cost,
      count(*) FILTER (WHERE status<>'running') AS runs,
      count(*) FILTER (WHERE status='failed') AS fails
    FROM public.mkt_ingestion_runs WHERE started_at>=d0 AND started_at<d1 GROUP BY provider
  ) r, LATERAL (VALUES ('provider_cost_usd', r.cost), ('runs', r.runs), ('failures', r.fails)) AS m(metric, value)
  ON CONFLICT (day, metric, provider) DO UPDATE SET value=EXCLUDED.value, updated_at=now();
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_mgmt_generate_alerts()
 RETURNS TABLE(kind text, emitted integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n int;
BEGIN
  -- 1. missed content deadline
  WITH x AS (
    INSERT INTO public.mkt_mgmt_alerts(kind,severity,title_ar,title_en,body_ar,body_en,target_type,target_id,evidence,dedup_key)
    SELECT 'content_overdue','warning',
           'محتوى متأخر: '||i.title, 'Overdue content: '||i.title,
           'تاريخ الاستحقاق '||i.due_date::text, 'Due '||i.due_date::text,
           'content_item', i.id,
           jsonb_build_object('rule','content_overdue','due_date',i.due_date,'status',i.status),
           'content_overdue:'||i.id::text||':'||i.due_date::text
    FROM public.mkt_content_items i
    WHERE i.archived_at IS NULL AND i.due_date < current_date
      AND i.status NOT IN ('published','cancelled','archived')
    ON CONFLICT (dedup_key) DO NOTHING RETURNING 1)
  SELECT count(*) INTO n FROM x; kind:='content_overdue'; emitted:=n; RETURN NEXT;

  -- 2. campaign with no content
  WITH x AS (
    INSERT INTO public.mkt_mgmt_alerts(kind,severity,title_ar,title_en,target_type,target_id,evidence,dedup_key)
    SELECT 'campaign_without_content','warning',
           'حملة بلا محتوى: '||c.name_ar, 'Campaign has no content: '||COALESCE(c.name_en,c.name_ar),
           'campaign', c.id, jsonb_build_object('rule','campaign_without_content','status',c.status),
           'campaign_without_content:'||c.id::text
    FROM public.mkt_internal_campaigns c
    WHERE c.status IN ('planned','active') AND c.archived_at IS NULL
      AND NOT EXISTS (SELECT 1 FROM public.mkt_content_items i WHERE i.campaign_id=c.id AND i.archived_at IS NULL)
    ON CONFLICT (dedup_key) DO NOTHING RETURNING 1)
  SELECT count(*) INTO n FROM x; kind:='campaign_without_content'; emitted:=n; RETURN NEXT;

  -- 3. scheduled publication with no APPROVED final asset
  WITH x AS (
    INSERT INTO public.mkt_mgmt_alerts(kind,severity,title_ar,title_en,target_type,target_id,evidence,dedup_key)
    SELECT 'scheduled_without_approved_asset','critical',
           'نشر مجدول بلا نسخة معتمدة', 'Scheduled publication has no approved version',
           'publication', p.id,
           jsonb_build_object('rule','scheduled_without_approved_asset','platform',p.platform,'scheduled_for',p.scheduled_for),
           'sched_no_approved:'||p.id::text
    FROM public.mkt_publications p
    WHERE p.status IN ('scheduled','ready')
      AND NOT EXISTS (SELECT 1 FROM public.mkt_content_versions v
                       WHERE v.content_item_id=p.content_item_id
                         AND v.approval_state='approved' AND v.version_type IN ('final','published'))
    ON CONFLICT (dedup_key) DO NOTHING RETURNING 1)
  SELECT count(*) INTO n FROM x; kind:='scheduled_without_approved_asset'; emitted:=n; RETURN NEXT;

  -- 4. waiting too long for approval (>3 days)
  WITH x AS (
    INSERT INTO public.mkt_mgmt_alerts(kind,severity,title_ar,title_en,target_type,target_id,evidence,dedup_key)
    SELECT 'approval_stalled','warning',
           'موافقة متعثرة منذ '||round(EXTRACT(EPOCH FROM (now()-a.created_at))/86400)||' أيام',
           'Approval pending '||round(EXTRACT(EPOCH FROM (now()-a.created_at))/86400)||' days',
           'content_item', a.target_id,
           jsonb_build_object('rule','approval_stalled','stage',a.stage,'threshold_days',3,'created_at',a.created_at),
           'approval_stalled:'||a.id::text
    FROM public.mkt_approvals a
    WHERE a.decision='pending' AND a.created_at < now() - interval '3 days' AND a.target_type='content_item'
    ON CONFLICT (dedup_key) DO NOTHING RETURNING 1)
  SELECT count(*) INTO n FROM x; kind:='approval_stalled'; emitted:=n; RETURN NEXT;

  -- 5. content item with no owner
  WITH x AS (
    INSERT INTO public.mkt_mgmt_alerts(kind,severity,title_ar,title_en,target_type,target_id,evidence,dedup_key)
    SELECT 'content_without_owner','info',
           'محتوى بلا مسؤول: '||i.title, 'Content has no owner: '||i.title,
           'content_item', i.id, jsonb_build_object('rule','content_without_owner'),
           'content_no_owner:'||i.id::text
    FROM public.mkt_content_items i
    WHERE i.owner_user_id IS NULL AND i.archived_at IS NULL AND i.status NOT IN ('cancelled','archived')
    ON CONFLICT (dedup_key) DO NOTHING RETURNING 1)
  SELECT count(*) INTO n FROM x; kind:='content_without_owner'; emitted:=n; RETURN NEXT;

  -- 6. published content with no performance snapshot after 3 days
  WITH x AS (
    INSERT INTO public.mkt_mgmt_alerts(kind,severity,title_ar,title_en,target_type,target_id,evidence,dedup_key)
    SELECT 'published_without_performance','warning',
           'منشور بلا بيانات أداء', 'Published content missing performance data',
           'publication', p.id,
           jsonb_build_object('rule','published_without_performance','published_at',p.published_at,'threshold_days',3),
           'pub_no_perf:'||p.id::text
    FROM public.mkt_publications p
    WHERE p.status='published' AND p.published_at < now() - interval '3 days'
      AND NOT EXISTS (SELECT 1 FROM public.mkt_performance_snapshots s WHERE s.publication_id=p.id)
    ON CONFLICT (dedup_key) DO NOTHING RETURNING 1)
  SELECT count(*) INTO n FROM x; kind:='published_without_performance'; emitted:=n; RETURN NEXT;

  -- 7. campaign nearing end date with low completion
  WITH x AS (
    INSERT INTO public.mkt_mgmt_alerts(kind,severity,title_ar,title_en,target_type,target_id,evidence,dedup_key)
    SELECT 'campaign_at_risk','critical',
           'حملة معرّضة للخطر: '||c.name_ar, 'Campaign at risk: '||COALESCE(c.name_en,c.name_ar),
           'campaign', c.id,
           jsonb_build_object('rule','campaign_at_risk','end_date',c.end_date,
             'published', (SELECT count(*) FROM public.mkt_content_items i WHERE i.campaign_id=c.id AND i.status='published'),
             'total', (SELECT count(*) FROM public.mkt_content_items i WHERE i.campaign_id=c.id)),
           'campaign_at_risk:'||c.id::text||':'||c.end_date::text
    FROM public.mkt_internal_campaigns c
    WHERE c.status='active' AND c.end_date IS NOT NULL
      AND c.end_date BETWEEN current_date AND current_date + 7
      AND (SELECT count(*) FROM public.mkt_content_items i WHERE i.campaign_id=c.id AND i.status='published')
          < (SELECT count(*) FROM public.mkt_content_items i WHERE i.campaign_id=c.id) * 0.5
      AND EXISTS (SELECT 1 FROM public.mkt_content_items i WHERE i.campaign_id=c.id)
    ON CONFLICT (dedup_key) DO NOTHING RETURNING 1)
  SELECT count(*) INTO n FROM x; kind:='campaign_at_risk'; emitted:=n; RETURN NEXT;

  -- resolve alerts whose cause has cleared
  UPDATE public.mkt_mgmt_alerts a SET resolved_at=now()
  WHERE a.resolved_at IS NULL AND (
    (a.kind='content_overdue' AND EXISTS (SELECT 1 FROM public.mkt_content_items i
        WHERE i.id=a.target_id AND (i.status IN ('published','cancelled','archived') OR i.due_date >= current_date)))
    OR (a.kind='campaign_without_content' AND EXISTS (SELECT 1 FROM public.mkt_content_items i WHERE i.campaign_id=a.target_id))
    OR (a.kind='content_without_owner' AND EXISTS (SELECT 1 FROM public.mkt_content_items i WHERE i.id=a.target_id AND i.owner_user_id IS NOT NULL))
    OR (a.kind='published_without_performance' AND EXISTS (SELECT 1 FROM public.mkt_performance_snapshots s WHERE s.publication_id=a.target_id))
  );
  RETURN;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_mgmt_generate_v2_alerts()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE out jsonb := '[]'::jsonb; n int; r record;
BEGIN
  n := 0;
  FOR r IN SELECT p.id, p.name_ar FROM public.mkt_plans p
            WHERE p.status = 'active' AND p.archived_at IS NULL
              AND (p.strategy_version_id IS NULL
                   OR NOT EXISTS (SELECT 1 FROM public.mkt_strategy_versions s
                                   WHERE s.id = p.strategy_version_id AND s.status = 'approved'))
  LOOP
    n := n + public.mkt_alert_emit('plan_without_approved_strategy','critical',
      'خطة نشطة بلا استراتيجية معتمدة', 'Active plan without an approved strategy',
      'plan', r.id, jsonb_build_object('plan', r.name_ar),
      'plan_no_strategy:'||r.id::text);
  END LOOP;
  out := out || jsonb_build_array(jsonb_build_object('kind','plan_without_approved_strategy','emitted',n));

  n := 0;
  FOR r IN SELECT p.id, p.name_ar FROM public.mkt_plans p
            WHERE p.status IN ('approved','active') AND p.archived_at IS NULL
              AND NOT EXISTS (SELECT 1 FROM public.mkt_goals g
                               WHERE g.plan_id = p.id AND g.archived_at IS NULL)
  LOOP
    n := n + public.mkt_alert_emit('plan_without_goals','critical',
      'خطة بلا أهداف', 'Plan without goals', 'plan', r.id,
      jsonb_build_object('plan', r.name_ar), 'plan_no_goals:'||r.id::text);
  END LOOP;
  out := out || jsonb_build_array(jsonb_build_object('kind','plan_without_goals','emitted',n));

  n := 0;
  FOR r IN SELECT g.id, g.name_ar FROM public.mkt_goals g
            WHERE g.status = 'active' AND g.archived_at IS NULL
              AND (g.source_of_truth IS NULL OR btrim(g.source_of_truth) = '')
  LOOP
    n := n + public.mkt_alert_emit('goal_without_source_of_truth','warning',
      'هدف بلا مصدر قياس', 'Goal without a source of truth', 'goal', r.id,
      jsonb_build_object('goal', r.name_ar), 'goal_no_source:'||r.id::text);
  END LOOP;
  out := out || jsonb_build_array(jsonb_build_object('kind','goal_without_source_of_truth','emitted',n));

  n := 0;
  FOR r IN SELECT g.id, g.name_ar, g.result FROM public.mkt_goals g
            WHERE g.status = 'active' AND g.archived_at IS NULL AND g.result = 'off_track'
  LOOP
    n := n + public.mkt_alert_emit('goal_off_track','critical',
      'هدف خارج المسار', 'Goal off track', 'goal', r.id,
      jsonb_build_object('goal', r.name_ar, 'result', r.result), 'goal_off_track:'||r.id::text);
  END LOOP;
  out := out || jsonb_build_array(jsonb_build_object('kind','goal_off_track','emitted',n));

  n := 0;
  FOR r IN SELECT i.id, i.name_ar FROM public.mkt_initiatives i
            WHERE i.status IN ('proposed','active') AND i.archived_at IS NULL
              AND i.primary_goal_id IS NULL
  LOOP
    n := n + public.mkt_alert_emit('initiative_without_primary_goal','warning',
      'مبادرة بلا هدف رئيسي', 'Initiative without a primary goal', 'initiative', r.id,
      jsonb_build_object('initiative', r.name_ar), 'init_no_goal:'||r.id::text);
  END LOOP;
  out := out || jsonb_build_array(jsonb_build_object('kind','initiative_without_primary_goal','emitted',n));

  n := 0;
  FOR r IN SELECT i.id, i.name_ar FROM public.mkt_initiatives i
            WHERE i.status = 'active' AND i.archived_at IS NULL
              AND NOT EXISTS (SELECT 1 FROM public.mkt_programs pr WHERE pr.initiative_id = i.id)
              AND NOT EXISTS (SELECT 1 FROM public.mkt_internal_campaigns c WHERE c.initiative_id = i.id)
  LOOP
    n := n + public.mkt_alert_emit('initiative_without_activity','warning',
      'مبادرة نشطة بلا برامج أو حملات', 'Active initiative with no programs or campaigns',
      'initiative', r.id, jsonb_build_object('initiative', r.name_ar),
      'init_no_activity:'||r.id::text);
  END LOOP;
  out := out || jsonb_build_array(jsonb_build_object('kind','initiative_without_activity','emitted',n));

  n := 0;
  FOR r IN SELECT p.id, p.name_ar FROM public.mkt_programs p
            WHERE p.status = 'active' AND p.archived_at IS NULL AND p.commitment_count IS NULL
  LOOP
    n := n + public.mkt_alert_emit('program_without_commitment','warning',
      'برنامج بلا التزام متكرر', 'Program without a recurring commitment', 'program', r.id,
      jsonb_build_object('program', r.name_ar),
      'prog_no_commitment:'||r.id::text);
  END LOOP;
  out := out || jsonb_build_array(jsonb_build_object('kind','program_without_commitment','emitted',n));

  n := 0;
  FOR r IN SELECT p.id, p.name_ar, p.commitment_count, p.commitment_unit
             FROM public.mkt_programs p
            WHERE p.status = 'active' AND p.archived_at IS NULL
              AND p.commitment_unit = 'week' AND p.commitment_count > 0
              AND (SELECT count(*) FROM public.mkt_content_items ci
                    WHERE ci.origin_program_id = p.id
                      AND ci.created_at >= date_trunc('week', now()) - interval '7 days'
                      AND ci.created_at <  date_trunc('week', now())) < p.commitment_count
  LOOP
    n := n + public.mkt_alert_emit('program_commitment_overdue','warning',
      'التزام برنامج غير مُنجز', 'Program commitment not met last week', 'program', r.id,
      jsonb_build_object('committed', r.commitment_count, 'unit', r.commitment_unit),
      'prog_overdue:'||r.id::text||':'||to_char(date_trunc('week', now()), 'IYYY-IW'));
  END LOOP;
  out := out || jsonb_build_array(jsonb_build_object('kind','program_commitment_overdue','emitted',n));

  n := 0;
  FOR r IN SELECT c.id, c.code FROM public.mkt_internal_campaigns c
            WHERE c.status IN ('planned','active') AND c.archived_at IS NULL
              AND jsonb_array_length(COALESCE(c.deliverables, '[]'::jsonb)) = 0
  LOOP
    n := n + public.mkt_alert_emit('campaign_without_deliverables','warning',
      'حملة بلا مخرجات محددة', 'Campaign without deliverables', 'campaign', r.id,
      jsonb_build_object('code', r.code), 'camp_no_deliverables:'||r.id::text);
  END LOOP;
  out := out || jsonb_build_array(jsonb_build_object('kind','campaign_without_deliverables','emitted',n));

  n := 0;
  FOR r IN
    SELECT cp.id AS channel_plan_id, a.week_start, cp.platform,
           cp.max_per_week,
           sum(a.slots_requested) FILTER (WHERE a.allocation_kind='campaign_allocation') AS requested,
           sum(a.slots_requested) FILTER (WHERE a.allocation_kind='program_reservation')  AS reserved,
           COALESCE(sum(a.slots_requested) FILTER (WHERE a.allocation_kind='reactive_reserve'),
                    cp.reactive_reserve) AS reactive
      FROM public.mkt_capacity_allocations a
      JOIN public.mkt_channel_plans cp ON cp.id = a.channel_plan_id
     WHERE cp.max_per_week IS NOT NULL
     GROUP BY cp.id, a.week_start, cp.platform, cp.max_per_week, cp.reactive_reserve
    HAVING COALESCE(sum(a.slots_requested) FILTER (WHERE a.allocation_kind='campaign_allocation'), 0)
         > cp.max_per_week
         - COALESCE(sum(a.slots_requested) FILTER (WHERE a.allocation_kind='program_reservation'), 0)
         - COALESCE(sum(a.slots_requested) FILTER (WHERE a.allocation_kind='reactive_reserve'),
                    cp.reactive_reserve)
  LOOP
    n := n + public.mkt_alert_emit('channel_over_allocated','critical',
      'طلبات الحملات تتجاوز سعة القناة', 'Campaign requests exceed channel capacity',
      'channel_plan', r.channel_plan_id,
      jsonb_build_object('platform', r.platform, 'week_start', r.week_start,
                         'week_capacity', r.max_per_week, 'program_reserved', r.reserved,
                         'reactive_reserved', r.reactive, 'campaign_requested', r.requested),
      'chan_over:'||r.channel_plan_id::text||':'||r.week_start::text);
  END LOOP;
  out := out || jsonb_build_array(jsonb_build_object('kind','channel_over_allocated','emitted',n));

  n := 0;
  FOR r IN SELECT ci.id, ci.content_number FROM public.mkt_content_items ci
            WHERE ci.status IN ('internal_review','awaiting_final_approval')
              AND ci.archived_at IS NULL
              AND array_length(public.mkt_content_missing_context(ci.id), 1) > 0
  LOOP
    n := n + public.mkt_alert_emit('content_without_strategic_context','warning',
      'محتوى بانتظار الاعتماد بلا سياق استراتيجي',
      'Content awaiting approval without strategic context', 'content_item', r.id,
      jsonb_build_object('content_number', r.content_number,
                         'missing', public.mkt_content_missing_context(r.id)),
      'content_no_context:'||r.id::text);
  END LOOP;
  out := out || jsonb_build_array(jsonb_build_object('kind','content_without_strategic_context','emitted',n));

  n := 0;
  FOR r IN SELECT ad.id, ad.name FROM public.mkt_ads ad
            WHERE ad.status = 'active'
              AND (ad.content_item_id IS NULL
                   OR NOT EXISTS (SELECT 1 FROM public.mkt_content_items ci
                                   WHERE ci.id = ad.content_item_id
                                     AND ci.status IN ('approved','ready_to_publish','scheduled','published')))
  LOOP
    n := n + public.mkt_alert_emit('ad_without_approved_creative','critical',
      'إعلان نشط بلا مادة معتمدة', 'Active ad without an approved creative', 'ad', r.id,
      jsonb_build_object('ad', r.name), 'ad_no_creative:'||r.id::text);
  END LOOP;
  out := out || jsonb_build_array(jsonb_build_object('kind','ad_without_approved_creative','emitted',n));

  n := 0;
  FOR r IN SELECT ci.id, ci.content_number FROM public.mkt_content_items ci
            WHERE ci.needs_classification AND ci.archived_at IS NULL
  LOOP
    n := n + public.mkt_alert_emit('legacy_needs_classification','info',
      'سجل قديم يحتاج تصنيفاً استراتيجياً', 'Legacy record needs strategic classification',
      'content_item', r.id, jsonb_build_object('content_number', r.content_number),
      'legacy_class:'||r.id::text);
  END LOOP;
  out := out || jsonb_build_array(jsonb_build_object('kind','legacy_needs_classification','emitted',n));

  RETURN out;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_mgmt_overview(p_limit integer DEFAULT 12)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'generated_at', now(),
    'kpis', jsonb_build_object(
      'planned_this_month', (SELECT count(*) FROM mkt_content_items
         WHERE archived_at IS NULL AND planned_publish_at >= date_trunc('month', now())
           AND planned_publish_at < date_trunc('month', now()) + interval '1 month'),
      'in_production', (SELECT count(*) FROM mkt_content_items WHERE archived_at IS NULL
         AND status IN ('writing','approved_for_production','raw_assets_required','recording','designing','editing')),
      'awaiting_approval', (SELECT count(*) FROM mkt_content_items WHERE archived_at IS NULL
         AND status IN ('awaiting_script_approval','awaiting_final_approval','internal_review')),
      'ready_to_publish', (SELECT count(*) FROM mkt_content_items WHERE archived_at IS NULL AND status='ready_to_publish'),
      'scheduled', (SELECT count(*) FROM mkt_publications WHERE status='scheduled'),
      'published_this_month', (SELECT count(*) FROM mkt_publications
         WHERE status='published' AND published_at >= date_trunc('month', now())),
      'late', (SELECT count(*) FROM mkt_content_items WHERE archived_at IS NULL
         AND due_date < current_date AND status NOT IN ('published','cancelled','archived')),
      'blocked', (SELECT count(*) FROM mkt_content_tasks WHERE status='blocked'),
      'active_organic_campaigns', (SELECT count(*) FROM mkt_internal_campaigns
         WHERE status='active' AND channel_mix IN ('organic','both')),
      'active_paid_campaigns', (SELECT count(*) FROM mkt_internal_campaigns
         WHERE status='active' AND channel_mix IN ('paid','both')),
      'raw_assets_available', (SELECT count(*) FROM mkt_raw_assets
         WHERE archived_at IS NULL AND usage_status='available'),
      'leads_attributed', (SELECT count(*) FROM mkt_lead_attributions WHERE client_id IS NOT NULL),
      'revenue_attributed', (SELECT sum(revenue) FROM mkt_lead_attributions),
      -- unmeasurable until a source exists: null, NOT zero
      'appointments_attributed', (SELECT count(*) FROM mkt_lead_attributions WHERE appointment_id IS NOT NULL),
      'sales_attributed', (SELECT count(*) FROM mkt_lead_attributions WHERE reservation_id IS NOT NULL)
    ),
    'due_today', COALESCE((SELECT jsonb_agg(to_jsonb(t)) FROM (
        SELECT i.id, i.content_number, i.title, i.status, i.due_date, i.owner_user_id
        FROM mkt_content_items i WHERE i.archived_at IS NULL AND i.due_date = current_date
          AND i.status NOT IN ('published','cancelled','archived')
        ORDER BY i.priority DESC LIMIT p_limit) t), '[]'::jsonb),
    'overdue', COALESCE((SELECT jsonb_agg(to_jsonb(t)) FROM (
        SELECT i.id, i.content_number, i.title, i.status, i.due_date,
               (current_date - i.due_date) AS days_late
        FROM mkt_content_items i WHERE i.archived_at IS NULL AND i.due_date < current_date
          AND i.status NOT IN ('published','cancelled','archived')
        ORDER BY i.due_date LIMIT p_limit) t), '[]'::jsonb),
    'approval_queue', COALESCE((SELECT jsonb_agg(to_jsonb(t)) FROM (
        SELECT a.id, a.stage, a.target_id, a.created_at, i.title, i.content_number,
               round(EXTRACT(EPOCH FROM (now()-a.created_at))/3600)::int AS hours_waiting
        FROM mkt_approvals a LEFT JOIN mkt_content_items i ON i.id=a.target_id
        WHERE a.decision='pending' ORDER BY a.created_at LIMIT p_limit) t), '[]'::jsonb),
    'publishing_queue', COALESCE((SELECT jsonb_agg(to_jsonb(t)) FROM (
        SELECT p.id, p.platform, p.scheduled_for, p.status, i.title, i.content_number,
               EXISTS (SELECT 1 FROM mkt_content_versions v WHERE v.content_item_id=p.content_item_id
                        AND v.approval_state='approved') AS has_approved_version
        FROM mkt_publications p JOIN mkt_content_items i ON i.id=p.content_item_id
        WHERE p.status IN ('ready','scheduled') ORDER BY p.scheduled_for NULLS LAST LIMIT p_limit) t), '[]'::jsonb),
    'recently_published', COALESCE((SELECT jsonb_agg(to_jsonb(t)) FROM (
        SELECT p.id, p.platform, p.published_at, p.published_url, i.title, i.content_number,
               EXISTS (SELECT 1 FROM mkt_performance_snapshots s WHERE s.publication_id=p.id) AS has_performance
        FROM mkt_publications p JOIN mkt_content_items i ON i.id=p.content_item_id
        WHERE p.status='published' ORDER BY p.published_at DESC LIMIT p_limit) t), '[]'::jsonb),
    'alerts', COALESCE((SELECT jsonb_agg(to_jsonb(t)) FROM (
        SELECT a.id, a.kind, a.severity, a.title_ar, a.title_en, a.target_type, a.target_id, a.evidence, a.generated_at
        FROM mkt_mgmt_alerts a WHERE a.resolved_at IS NULL AND a.dismissed=false
        ORDER BY CASE a.severity WHEN 'critical' THEN 0 WHEN 'warning' THEN 1 ELSE 2 END,
                 a.generated_at DESC LIMIT p_limit) t), '[]'::jsonb),
    'workload', COALESCE((SELECT jsonb_agg(to_jsonb(t)) FROM (
        SELECT t2.assigned_user_id, count(*) AS open_tasks,
               count(*) FILTER (WHERE t2.due_date < current_date) AS overdue_tasks
        FROM mkt_content_tasks t2
        WHERE t2.assigned_user_id IS NOT NULL AND t2.status NOT IN ('completed','cancelled')
        GROUP BY 1 ORDER BY 2 DESC LIMIT p_limit) t), '[]'::jsonb),
    'coverage', jsonb_build_object(
      'campaigns_total', (SELECT count(*) FROM mkt_internal_campaigns WHERE archived_at IS NULL),
      'content_total',   (SELECT count(*) FROM mkt_content_items WHERE archived_at IS NULL),
      'publications_total', (SELECT count(*) FROM mkt_publications),
      'assets_total',    (SELECT count(*) FROM mkt_raw_assets WHERE archived_at IS NULL),
      'note_ar', 'أرقام الإسناد تحتسب ما هو مسجَّل فقط. غياب الرقم يعني أنه غير مسجَّل، وليس أنه صفر.', 'note', 'Attribution figures count only recorded attributions. Absence of a number means not recorded, not zero.'
    )
  );
$function$;
CREATE OR REPLACE FUNCTION public.mkt_next_campaign_code()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_code text; v_guard int := 0;
BEGIN
  LOOP
    v_code := 'CMP-' || lpad(nextval('public.mkt_campaign_code_seq')::text, 4, '0');
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.mkt_internal_campaigns WHERE code = v_code);
    v_guard := v_guard + 1;
    IF v_guard > 10000 THEN
      RAISE EXCEPTION 'MKT:campaign_code_unavailable' USING ERRCODE = 'check_violation';
    END IF;
  END LOOP;
  RETURN v_code;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_norm_ar(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT lower(btrim(regexp_replace(
    translate(COALESCE(t,''),
      'أإآٱىﻻئؤةـًٌٍَُِّْ',
      'ااااي  ه          '),
    '\s+', ' ', 'g')));
$function$;
CREATE OR REPLACE FUNCTION public.mkt_notification_emit(p_insight_id uuid, p_kind text, p_dedup_key text, p_organization_id uuid DEFAULT NULL::uuid, p_project_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  INSERT INTO public.mkt_notifications (insight_id, kind, dedup_key, organization_id, project_id, payload)
  VALUES (p_insight_id, p_kind, p_dedup_key, p_organization_id, p_project_id, COALESCE(p_payload,'{}'::jsonb))
  ON CONFLICT (dedup_key) DO NOTHING RETURNING id INTO v_id;
  RETURN v_id;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_ops_dashboard()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH ph AS (SELECT mkt_provider_health() AS v), q AS (SELECT mkt_queue_health() AS v)
  SELECT jsonb_build_object(
    'generated_at', now(),
    'providers', (SELECT v FROM ph),
    'provider_counts', (SELECT jsonb_build_object(
        'healthy', count(*) FILTER (WHERE e->>'health_status'='healthy' OR ((e->>'success_rate')::numeric >= 0.8 AND (e->>'consecutive_failures')::int = 0)),
        'degraded', count(*) FILTER (WHERE (e->>'consecutive_failures')::int BETWEEN 1 AND 2 OR ((e->>'success_rate')::numeric < 0.8 AND (e->>'success_rate') IS NOT NULL)),
        'offline', count(*) FILTER (WHERE (e->>'consecutive_failures')::int >= 3 OR NOT (e->>'is_enabled')::boolean),
        'total', count(*))
      FROM jsonb_array_elements((SELECT v FROM ph)) e),
    'queue', (SELECT v FROM q),
    'diagnostics', (SELECT COALESCE(jsonb_object_agg(check_name, jsonb_build_object('status',status,'detail',detail,'checked_at',checked_at)),'{}'::jsonb) FROM mkt_diagnostics),
    'heartbeats', (SELECT COALESCE(jsonb_object_agg(component, last_beat_at),'{}'::jsonb) FROM mkt_ops_heartbeats),
    'cost', mkt_cost_summary(),
    'open_alerts', (SELECT count(*) FROM mkt_ops_alerts WHERE status='open'),
    'critical_alerts', (SELECT count(*) FROM mkt_ops_alerts WHERE status='open' AND severity='critical'),
    'last_success_collection', (SELECT max(finished_at) FROM mkt_ingestion_runs WHERE status IN ('succeeded','partial')),
    'last_failed_collection', (SELECT max(finished_at) FROM mkt_ingestion_runs WHERE status='failed'),
    'jobs_running', (SELECT count(*) FROM mkt_collection_jobs WHERE status='running'),
    'avg_collection_duration_ms', (SELECT round(avg(EXTRACT(EPOCH FROM (finished_at-started_at))*1000)) FROM mkt_ingestion_runs WHERE finished_at IS NOT NULL AND started_at > now()-interval '7 days'),
    'collections_today', (SELECT count(*) FROM mkt_ingestion_runs WHERE started_at >= date_trunc('day',now()) AND status<>'running'),
    'failures_today', (SELECT count(*) FROM mkt_ingestion_runs WHERE started_at >= date_trunc('day',now()) AND status='failed'),
    'collection_paused', COALESCE((SELECT (value#>>'{}')::boolean FROM mkt_settings WHERE key='collection_paused'), false)
  );
$function$;
CREATE OR REPLACE FUNCTION public.mkt_ops_evaluate()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  fresh jsonb; diag jsonb; cost jsonb; q jsonb; r record;
  backlog_n numeric := mkt_setting_num('ops_queue_backlog_count',25);
  backlog_age numeric := mkt_setting_num('ops_queue_backlog_age_minutes',30);
  timeout_m numeric := mkt_setting_num('ops_collection_timeout_minutes',20);
  cons_n numeric := mkt_setting_num('ops_consecutive_failures_alert',3);
  n_pending int; oldest timestamptz;
BEGIN
  PERFORM mkt_heartbeat('ops', jsonb_build_object('at', now()));
  PERFORM mkt_metrics_capture(current_date);
  PERFORM mkt_metrics_capture(current_date - 1);
  diag := mkt_run_diagnostics();
  fresh := mkt_freshness_scan();
  cost := mkt_cost_summary();
  q := mkt_queue_health();

  SELECT count(*), min(created_at) INTO n_pending, oldest FROM mkt_collection_jobs WHERE status='queued';
  IF n_pending >= backlog_n OR (oldest IS NOT NULL AND oldest < now() - (backlog_age * interval '1 minute')) THEN
    PERFORM mkt_alert_emit('queue_backlog','queue_backlog','تكدّس في قائمة المهام','warning','queue','queue',
      n_pending||' مهمة معلّقة',jsonb_build_object('pending', n_pending, 'oldest', oldest));
  ELSE
    PERFORM mkt_alert_resolve('queue_backlog','queue');
  END IF;

  FOR r IN SELECT id, kind, provider, started_at FROM mkt_collection_jobs WHERE status='running' AND started_at < now() - (timeout_m * interval '1 minute') LOOP
    PERFORM mkt_alert_emit('collection_timeout','collection_timeout:'||r.id,'مهمة تجاوزت المهلة — '||r.kind,'warning','queue',r.id::text,
      'قيد التشغيل منذ '||round(EXTRACT(EPOCH FROM (now()-r.started_at))/60)||' دقيقة',jsonb_build_object('provider', r.provider, 'started_at', r.started_at));
  END LOOP;

  IF (cost->'spike'->>'is_spike')::boolean THEN
    PERFORM mkt_alert_emit('cost_spike','cost_spike:'||current_date,'ارتفاع غير معتاد في التكلفة','critical','system','cost',
      'تكلفة اليوم '||(cost->'spike'->>'today_usd')||'$ مقابل متوسط '||(cost->'spike'->>'avg7_usd')||'$',cost->'spike');
  ELSE
    PERFORM mkt_alert_resolve('cost_spike', 'cost');
  END IF;

  FOR r IN SELECT provider_key pk, display_name dn FROM mkt_providers WHERE is_enabled LOOP
    IF (SELECT count(*) FROM mkt_ingestion_runs x WHERE x.provider=r.pk AND x.status='failed'
        AND x.started_at > COALESCE((SELECT max(s.started_at) FROM mkt_ingestion_runs s WHERE s.provider=r.pk AND s.status IN ('succeeded','partial')),'-infinity'::timestamptz)) >= cons_n THEN
      PERFORM mkt_alert_emit('consecutive_failures','consecutive_failures:'||r.pk,'إخفاقات متتالية — '||r.dn,'critical','provider',r.pk,NULL,
        jsonb_build_object('threshold', cons_n));
    ELSE
      PERFORM mkt_alert_resolve('consecutive_failures', r.pk);
    END IF;
  END LOOP;

  BEGIN
    PERFORM public.mkt_generate_trend_insights();
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'mkt_generate_trend_insights failed during ops evaluate: % (%)', SQLERRM, SQLSTATE;
  END;

  BEGIN
    PERFORM public.mkt_check_processing_health();
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'mkt_check_processing_health failed during ops evaluate: % (%)', SQLERRM, SQLSTATE;
  END;

  RETURN jsonb_build_object('evaluated_at', now(), 'freshness', fresh, 'diagnostics', diag, 'queue', q,
    'cost_spike', cost->'spike', 'open_alerts', (SELECT count(*) FROM mkt_ops_alerts WHERE status='open'));
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_org_health()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(jsonb_agg(row ORDER BY (row->>'is_stale')::boolean DESC NULLS LAST), '[]'::jsonb) FROM (
    SELECT jsonb_build_object(
      'organization_id', o.id,
      'name_ar', o.name_ar, 'name_en', o.name_en, 'org_type', o.org_type,
      'accounts', (SELECT count(*) FROM mkt_social_accounts a WHERE a.organization_id=o.id AND a.collection_enabled),
      'last_success_collection', (SELECT max(a.last_synced_at) FROM mkt_social_accounts a WHERE a.organization_id=o.id),
      'last_metrics_update', (SELECT max(a.last_metrics_at) FROM mkt_social_accounts a WHERE a.organization_id=o.id),
      'last_new_content', (SELECT max(first_seen_at) FROM mkt_content_posts c WHERE c.organization_id=o.id),
      'last_paid_ad', (SELECT max(first_seen_at) FROM mkt_paid_ads pa WHERE pa.organization_id=o.id),
      'cadence', (SELECT to_jsonb(a.cadence) FROM mkt_social_accounts a WHERE a.organization_id=o.id AND a.collection_enabled LIMIT 1),
      'next_scheduled_run', (SELECT min(j.next_run_at) FROM mkt_collection_jobs j JOIN mkt_social_accounts a ON a.id=j.social_account_id WHERE a.organization_id=o.id AND j.status IN ('pending','retrying')),
      'consecutive_failures', (SELECT count(*) FROM mkt_ingestion_runs r JOIN mkt_social_accounts a ON a.id=r.source_account_id WHERE a.organization_id=o.id AND r.status='failed'
          AND r.started_at > COALESCE((SELECT max(s.started_at) FROM mkt_ingestion_runs s JOIN mkt_social_accounts a2 ON a2.id=s.source_account_id WHERE a2.organization_id=o.id AND s.status IN ('succeeded','partial')), '-infinity'::timestamptz)),
      'is_stale', (SELECT COALESCE(max(a.last_synced_at) < now() - (mkt_setting_num('ops_org_stale_hours',26) * interval '1 hour'), true)
          FROM mkt_social_accounts a WHERE a.organization_id=o.id AND a.collection_enabled)
    ) AS row
    FROM mkt_organizations o
    WHERE EXISTS (SELECT 1 FROM mkt_social_accounts a WHERE a.organization_id=o.id AND a.collection_enabled)
       OR o.meta_confirmed
  ) x;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_org_in_our_projects_scope(p_org uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.mkt_project_organizations po
    JOIN public.v_our_projects_scope s ON s.project_id = po.project_id
    WHERE po.organization_id = p_org AND po.is_active
  );
$function$;
CREATE OR REPLACE FUNCTION public.mkt_org_set_advertiser(p_org uuid, p_page_id text, p_advertiser_id text, p_page_url text, p_display_name text, p_verification jsonb DEFAULT NULL::jsonb, p_confirmed boolean DEFAULT true, p_candidates jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_old_page text; v_old_confirmed boolean;
BEGIN
  SELECT meta_page_id, meta_confirmed INTO v_old_page, v_old_confirmed FROM public.mkt_organizations WHERE id=p_org;

  IF p_confirmed THEN
    IF p_page_id IS NULL OR p_page_id = '' THEN
      RAISE EXCEPTION 'a confirmed advertiser must have a Meta Page ID' USING ERRCODE='23514';
    END IF;
    IF v_old_page IS NOT NULL AND v_old_page <> p_page_id THEN
      INSERT INTO public.mkt_advertiser_audit(organization_id, event, old_page_id, new_page_id, detail)
      VALUES (p_org, 'page_id_changed', v_old_page, p_page_id, COALESCE(p_verification,'{}'::jsonb));
    END IF;
    UPDATE public.mkt_organizations SET
      meta_page_id=p_page_id, meta_advertiser_id=COALESCE(p_advertiser_id, p_page_id),
      meta_page_url=p_page_url, meta_display_name=p_display_name,
      meta_verification=p_verification, meta_confirmation_evidence=p_verification,
      meta_discovery_confidence=(p_verification->>'confidence'),
      meta_confirmed=true, meta_confirmed_at=now(),
      meta_candidates=COALESCE(p_candidates, meta_candidates), updated_at=now()
    WHERE id=p_org;
    INSERT INTO public.mkt_advertiser_audit(organization_id, event, old_page_id, new_page_id, detail)
    VALUES (p_org, 'confirmed', v_old_page, p_page_id, COALESCE(p_verification,'{}'::jsonb));
  ELSE
    IF COALESCE(v_old_confirmed,false) AND (p_page_id IS NULL OR p_page_id='') THEN
      UPDATE public.mkt_organizations SET meta_candidates=COALESCE(p_candidates, meta_candidates), updated_at=now() WHERE id=p_org;
    ELSE
      IF COALESCE(v_old_confirmed,false) THEN
        INSERT INTO public.mkt_advertiser_audit(organization_id, event, old_page_id, new_page_id, detail)
        VALUES (p_org, 'unconfirmed', v_old_page, NULL, COALESCE(p_verification,'{}'::jsonb));
      END IF;
      UPDATE public.mkt_organizations SET
        meta_page_id=p_page_id, meta_advertiser_id=p_advertiser_id, meta_page_url=p_page_url,
        meta_display_name=p_display_name, meta_verification=p_verification,
        meta_confirmed=false, meta_confirmed_at=NULL,
        meta_candidates=COALESCE(p_candidates, meta_candidates), updated_at=now()
      WHERE id=p_org;
    END IF;
  END IF;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_organization_intelligence(p_org_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_lim  int  := greatest(1, least(coalesce(p_limit,10), 50));
  v_from date := coalesce(p_from, '1900-01-01'::date);
  v_to   date := coalesce(p_to,   '2999-12-31'::date);
  v_out  jsonb;
BEGIN
  SELECT jsonb_build_object(
    'generated_at', now(),
    'window', jsonb_build_object('from', p_from, 'to', p_to),

    'organization', (
      SELECT jsonb_build_object(
        'id', o.id, 'name', coalesce(o.name_en, o.name_ar),
        'name_ar', o.name_ar, 'name_en', o.name_en,
        'website', o.website, 'hq_city', o.hq_city, 'status', o.status,
        'followers_cached', o.followers_cached,
        'meta_page_url', o.meta_page_url, 'meta_confirmed', o.meta_confirmed,
        'developer_record_id', o.developer_record_id)
      FROM mkt_organizations o WHERE o.id = p_org_id),

    -- What this org IS, derived from its links (never from org_type, which is
    -- superseded — see docs §2.6).
    'roles', coalesce((
      SELECT jsonb_object_agg(relationship_type, n) FROM (
        SELECT relationship_type, count(DISTINCT project_id) AS n
        FROM mkt_project_organizations WHERE organization_id = p_org_id
        GROUP BY relationship_type) r), '{}'::jsonb),

    -- ── Projects it develops / markets, with their marketing state ─────────
    'projects', jsonb_build_object(
      'total', (SELECT count(DISTINCT project_id) FROM mkt_project_organizations
                WHERE organization_id = p_org_id),
      'shown', v_lim,
      'items', coalesce((
        SELECT jsonb_agg(x ORDER BY (x->>'post_count')::int DESC NULLS LAST) FROM (
          SELECT jsonb_build_object(
            'project_id', po.project_id,
            'name', r.data->>'project_name',
            'city', r.data->>'city_name',
            'status', r.data->>'project_status',
            'role', po.relationship_type,
            'human_confirmed', po.human_confirmed,
            'post_count', coalesce(s.post_count, 0),
            'candidate_post_count', coalesce(s.candidate_post_count, 0),
            'fact_count', coalesce(s.fact_count, 0),
            'last_activity_at', s.last_activity_at,
            'min_advertised_price', s.min_advertised_price,
            'max_advertised_price', s.max_advertised_price) AS x
          FROM mkt_project_organizations po
          LEFT JOIN unified_records r ON r.id = po.project_id
          LEFT JOIN mkt_project_marketing_state s ON s.project_id = po.project_id
          WHERE po.organization_id = p_org_id
          ORDER BY coalesce(s.post_count,0) DESC, s.last_activity_at DESC NULLS LAST
          LIMIT v_lim) z), '[]'::jsonb)),

    'social_accounts', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', sa.id, 'platform', sa.platform, 'handle', sa.handle,
        'profile_url', sa.profile_url, 'followers', sa.followers,
        'verified', sa.verified, 'collection_enabled', sa.collection_enabled,
        'last_synced_at', sa.last_synced_at)
        ORDER BY sa.followers DESC NULLS LAST, sa.platform)
      FROM mkt_social_accounts sa WHERE sa.organization_id = p_org_id), '[]'::jsonb),

    -- ── Audience growth. Honest about whether it is measurable AT ALL. ─────
    'audience', (
      WITH series AS (
        SELECT am.social_account_id, am.captured_at, am.followers
        FROM mkt_account_metrics am
        JOIN mkt_social_accounts sa ON sa.id = am.social_account_id
        WHERE sa.organization_id = p_org_id
      ),
      per_account AS (
        SELECT social_account_id, count(*) AS points,
               min(captured_at) AS first_at, max(captured_at) AS last_at,
               (array_agg(followers ORDER BY captured_at))[1] AS first_followers,
               (array_agg(followers ORDER BY captured_at DESC))[1] AS last_followers
        FROM series GROUP BY social_account_id
      )
      SELECT jsonb_build_object(
        'current_followers', (SELECT sum(followers) FROM mkt_social_accounts
                              WHERE organization_id = p_org_id),
        'history_points', coalesce((SELECT sum(points) FROM per_account), 0),
        -- Growth needs >= 2 observations on at least one account. Saying so is
        -- the difference between "no growth" and "we cannot see growth yet".
        'growth_measurable', coalesce((SELECT bool_or(points >= 2) FROM per_account), false),
        'net_change', (SELECT sum(last_followers - first_followers) FROM per_account WHERE points >= 2),
        'first_observed_at', (SELECT min(first_at) FROM per_account),
        'last_observed_at', (SELECT max(last_at) FROM per_account),
        'series', coalesce((
          SELECT jsonb_agg(jsonb_build_object('day', d, 'followers', f) ORDER BY d)
          FROM (SELECT captured_at::date AS d, sum(followers) AS f
                FROM series GROUP BY 1) g), '[]'::jsonb))),

    -- ── Posting frequency: rate + a current-vs-prior comparison ────────────
    'posting_frequency', (
      WITH months AS (
        SELECT t.bucket_start, t.posts
        FROM mkt_activity_trend('month', p_from, p_to, p_org_id, NULL) t
      ),
      recent AS (
        SELECT coalesce(sum(posts),0)::numeric AS n FROM months
        WHERE bucket_start >= (date_trunc('month', now()) - interval '3 months')::date
      ),
      prior AS (
        SELECT coalesce(sum(posts),0)::numeric AS n FROM months
        WHERE bucket_start >= (date_trunc('month', now()) - interval '6 months')::date
          AND bucket_start <  (date_trunc('month', now()) - interval '3 months')::date
      )
      SELECT jsonb_build_object(
        'total_posts', (SELECT coalesce(sum(posts),0) FROM months),
        'months_active', (SELECT count(*) FROM months WHERE posts > 0),
        'avg_posts_per_active_month',
          (SELECT round(avg(posts)::numeric, 1) FROM months WHERE posts > 0),
        'last_3_months', (SELECT n FROM recent),
        'prior_3_months', (SELECT n FROM prior),
        -- NULL (not 0) when there is no prior baseline: a percentage against
        -- zero history would be a fabricated claim.
        'change_pct', CASE WHEN (SELECT n FROM prior) > 0
                           THEN round(100 * ((SELECT n FROM recent) - (SELECT n FROM prior))
                                          / (SELECT n FROM prior), 1) END)),

    -- ── Paid activity ───────────────────────────────────────────────────────
    'ads', jsonb_build_object(
      'total', (SELECT count(*) FROM mkt_paid_ads WHERE organization_id = p_org_id),
      'active', (SELECT count(*) FROM mkt_paid_ads WHERE organization_id = p_org_id AND is_active),
      'shown', v_lim,
      'recent', coalesce((
        SELECT jsonb_agg(x ORDER BY x->>'started_at' DESC NULLS LAST) FROM (
          SELECT jsonb_build_object(
            'ad_id', pa.id, 'platform', pa.platform, 'headline', pa.headline,
            'cta', pa.cta, 'landing_url', pa.landing_url, 'is_active', pa.is_active,
            'started_at', coalesce(pa.platform_started_at, pa.first_seen_at),
            'ended_at', pa.platform_ended_at,
            'creative_url', pa.creative_stored_url) AS x
          FROM mkt_paid_ads pa WHERE pa.organization_id = p_org_id
          ORDER BY coalesce(pa.platform_started_at, pa.first_seen_at) DESC NULLS LAST
          LIMIT v_lim) z), '[]'::jsonb)),

    -- ── What they say. campaign_message/selling_point ARE the hooks. ───────
    'facts', (
      SELECT jsonb_object_agg(ft, vals) FROM (
        SELECT ft, coalesce((
          SELECT jsonb_agg(jsonb_build_object(
            'value', t.sample_value, 'key', t.normalized_key,
            'observations', t.observations, 'posts', t.distinct_posts,
            'first_seen', t.first_seen, 'last_seen', t.last_seen,
            'share_pct', t.share_pct))
          FROM mkt_fact_top(ft, v_lim, p_from, p_to, p_org_id, NULL) t), '[]'::jsonb) AS vals
        FROM unnest(ARRAY['cta','offer','campaign_message','selling_point','content_type',
                          'price','phone','payment_plan','unit_type','district',
                          'delivery_date','financing','amenity','audience','objective']) ft) z),

    'trends', jsonb_build_object(
      'activity', coalesce((
        SELECT jsonb_agg(jsonb_build_object(
          'bucket', t.bucket_start, 'posts', t.posts, 'ads', t.ads,
          'platforms', t.platforms, 'engagement', t.engagement) ORDER BY t.bucket_start)
        FROM mkt_activity_trend('month', p_from, p_to, p_org_id, NULL) t), '[]'::jsonb),
      'price', coalesce((
        SELECT jsonb_agg(jsonb_build_object(
          'bucket', t.bucket_start, 'observations', t.observations,
          'min', t.min_value, 'max', t.max_value, 'avg', t.avg_value) ORDER BY t.bucket_start)
        FROM mkt_fact_trend('price','month', p_from, p_to, p_org_id, NULL) t
        WHERE t.numeric_count > 0), '[]'::jsonb),
      'platforms', coalesce((
        SELECT jsonb_agg(jsonb_build_object(
          'platform', d.platform, 'posts', d.posts, 'share_pct', d.share_pct,
          'engagement', d.engagement))
        FROM mkt_platform_distribution(p_from, p_to, p_org_id, NULL) d), '[]'::jsonb)),

    'share_of_voice', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'period_start', s.period_start, 'period_end', s.period_end,
        'scope', s.scope_type, 'scope_key', s.scope_key,
        'post_count', s.post_count, 'ad_count', s.ad_count,
        'engagement_total', s.engagement_total, 'share_pct', s.share_pct)
        ORDER BY s.period_start DESC)
      FROM mkt_share_of_voice s WHERE s.organization_id = p_org_id), '[]'::jsonb),

    'campaigns', jsonb_build_object(
      'total', (SELECT count(*) FROM mkt_campaigns WHERE organization_id = p_org_id),
      'active', (SELECT count(*) FROM mkt_campaigns WHERE organization_id = p_org_id AND is_active),
      'shown', v_lim,
      'items', coalesce((
        SELECT jsonb_agg(x ORDER BY x->>'last_seen_at' DESC NULLS LAST) FROM (
          SELECT jsonb_build_object(
            'campaign_id', c.id, 'label', coalesce(c.manual_label, c.label),
            'objective', c.objective, 'platforms', to_jsonb(c.platforms),
            'is_active', c.is_active, 'member_count', c.member_count,
            'first_seen_at', c.first_seen_at, 'last_seen_at', c.last_seen_at,
            'summary', (SELECT jsonb_build_object('confidence', su.confidence,
                          'summary_ar', su.result->>'summary_ar',
                          'summary_en', su.result->>'summary_en')
                        FROM mkt_campaign_summaries su WHERE su.campaign_id = c.id)) AS x
          FROM mkt_campaigns c WHERE c.organization_id = p_org_id
          ORDER BY c.last_seen_at DESC NULLS LAST LIMIT v_lim) z), '[]'::jsonb)),

    'insights', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', i.id, 'kind', i.kind, 'severity', i.severity, 'title', i.title,
        'body', i.body, 'evidence', i.evidence, 'generated_at', i.generated_at)
        ORDER BY i.generated_at DESC)
      FROM mkt_insights i
      WHERE i.organization_id = p_org_id AND NOT coalesce(i.dismissed,false)), '[]'::jsonb),

    -- ── Coverage: what this page CANNOT answer yet, and why ────────────────
    -- Stated explicitly so an empty section is never mistaken for a zero.
    'coverage', jsonb_build_object(
      'has_content', (SELECT count(*) > 0 FROM mkt_content_posts WHERE organization_id = p_org_id),
      'has_facts',   (SELECT count(*) > 0 FROM mkt_observed_facts WHERE organization_id = p_org_id),
      'has_ads',     (SELECT count(*) > 0 FROM mkt_paid_ads WHERE organization_id = p_org_id),
      'content_processed_posts', (
        SELECT count(*) FROM mkt_content_posts
        WHERE organization_id = p_org_id AND processing_status IN ('processed','partial')),
      'content_unprocessed_posts', (
        SELECT count(*) FROM mkt_content_posts
        WHERE organization_id = p_org_id AND processing_status NOT IN ('processed','partial')),
      'note', 'Facts (offers, prices, CTAs, hooks) exist only for posts that have '
           || 'been through content processing. An empty facts section with a high '
           || 'content_unprocessed_posts count means the content was collected but '
           || 'not yet OCR''d/enriched — not that the advertiser says nothing.')
  ) INTO v_out;
  RETURN v_out;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_paid_ad_upsert(p_platform text, p_external_ad_id text, p_provider text, p_organization_id uuid DEFAULT NULL::uuid, p_advertiser_name text DEFAULT NULL::text, p_creative_media_ref text DEFAULT NULL::text, p_creative_type text DEFAULT NULL::text, p_headline text DEFAULT NULL::text, p_body text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_cta text DEFAULT NULL::text, p_landing_url text DEFAULT NULL::text, p_languages text[] DEFAULT '{}'::text[], p_platform_started_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_is_active boolean DEFAULT true, p_reach_info jsonb DEFAULT '{}'::jsonb, p_raw_ref uuid DEFAULT NULL::uuid, p_run_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, was_inserted boolean, changes text[])
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; e record; ch text[] := '{}';
BEGIN
  SELECT * INTO e FROM public.mkt_paid_ads a WHERE a.platform=p_platform AND a.external_ad_id=p_external_ad_id;
  IF e.id IS NULL THEN
    INSERT INTO public.mkt_paid_ads (platform, external_ad_id, organization_id, advertiser_name, creative_media_ref, creative_type, headline, body, description, cta, landing_url, languages, platform_started_at, is_active, reach_info, providers, raw_ref, first_seen_at, last_seen_at)
    VALUES (p_platform, p_external_ad_id, p_organization_id, p_advertiser_name, p_creative_media_ref, p_creative_type, p_headline, p_body, p_description, p_cta, p_landing_url, COALESCE(p_languages,'{}'), p_platform_started_at, p_is_active, COALESCE(p_reach_info,'{}'::jsonb), ARRAY[p_provider], p_raw_ref, now(), now())
    RETURNING mkt_paid_ads.id INTO v_id;
    INSERT INTO public.mkt_ad_history (paid_ad_id, change_type, new_value, run_id) VALUES (v_id,'new',to_jsonb(p_external_ad_id),p_run_id);
    RETURN QUERY SELECT v_id, true, ARRAY['new']; RETURN;
  END IF;
  v_id := e.id;
  IF p_creative_media_ref IS NOT NULL AND mkt_url_key(p_creative_media_ref) IS DISTINCT FROM mkt_url_key(e.creative_media_ref) THEN
    INSERT INTO mkt_ad_history(paid_ad_id,change_type,field,old_value,new_value,run_id) VALUES (v_id,'creative_change','creative_media_ref',to_jsonb(e.creative_media_ref),to_jsonb(p_creative_media_ref),p_run_id);
    ch := array_append(ch,'creative_change');
  END IF;
  IF p_cta IS NOT NULL AND p_cta IS DISTINCT FROM e.cta THEN
    INSERT INTO mkt_ad_history(paid_ad_id,change_type,field,old_value,new_value,run_id) VALUES (v_id,'cta_change','cta',to_jsonb(e.cta),to_jsonb(p_cta),p_run_id);
    ch := array_append(ch,'cta_change');
  END IF;
  IF p_landing_url IS NOT NULL AND mkt_url_key(p_landing_url) IS DISTINCT FROM mkt_url_key(e.landing_url) THEN
    INSERT INTO mkt_ad_history(paid_ad_id,change_type,field,old_value,new_value,run_id) VALUES (v_id,'landing_change','landing_url',to_jsonb(e.landing_url),to_jsonb(p_landing_url),p_run_id);
    ch := array_append(ch,'landing_change');
  END IF;
  IF p_is_active IS DISTINCT FROM e.is_active THEN
    INSERT INTO mkt_ad_history(paid_ad_id,change_type,field,old_value,new_value,run_id) VALUES (v_id,'status_change','is_active',to_jsonb(e.is_active),to_jsonb(p_is_active),p_run_id);
    ch := array_append(ch,'status_change');
  END IF;
  IF (p_body IS NOT NULL AND p_body IS DISTINCT FROM e.body) OR (p_headline IS NOT NULL AND p_headline IS DISTINCT FROM e.headline) THEN
    INSERT INTO mkt_ad_history(paid_ad_id,change_type,field,old_value,new_value,run_id) VALUES (v_id,'text_change','body/headline',jsonb_build_object('headline',e.headline,'body',e.body),jsonb_build_object('headline',p_headline,'body',p_body),p_run_id);
    ch := array_append(ch,'text_change');
  END IF;
  UPDATE public.mkt_paid_ads a SET
    providers=(SELECT array_agg(DISTINCT x) FROM unnest(a.providers || ARRAY[p_provider]) x),
    organization_id=COALESCE(p_organization_id,a.organization_id), advertiser_name=COALESCE(p_advertiser_name,a.advertiser_name),
    creative_media_ref=COALESCE(p_creative_media_ref,a.creative_media_ref), creative_type=COALESCE(p_creative_type,a.creative_type),
    headline=COALESCE(p_headline,a.headline), body=COALESCE(p_body,a.body), description=COALESCE(p_description,a.description),
    cta=COALESCE(p_cta,a.cta), landing_url=COALESCE(p_landing_url,a.landing_url),
    languages=CASE WHEN p_languages IS NULL OR p_languages='{}' THEN a.languages ELSE p_languages END,
    platform_started_at=COALESCE(p_platform_started_at,a.platform_started_at), is_active=p_is_active,
    platform_ended_at=CASE WHEN a.is_active AND NOT p_is_active THEN now() ELSE a.platform_ended_at END,
    reach_info=CASE WHEN p_reach_info IS NULL OR p_reach_info='{}'::jsonb THEN a.reach_info ELSE p_reach_info END,
    raw_ref=COALESCE(p_raw_ref,a.raw_ref), last_seen_at=now(), updated_at=now()
  WHERE a.id=v_id;
  RETURN QUERY SELECT v_id, false, ch;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_plan_missing_requirements(p_plan_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE p record; v_status text; missing text[] := ARRAY[]::text[];
BEGIN
  SELECT * INTO p FROM public.mkt_plans WHERE id = p_plan_id;
  IF p IS NULL THEN RETURN ARRAY['plan not found']; END IF;

  IF p.strategy_version_id IS NULL THEN
    missing := array_append(missing, 'strategy_version');
  ELSE
    SELECT status INTO v_status FROM public.mkt_strategy_versions WHERE id = p.strategy_version_id;
    IF v_status IS DISTINCT FROM 'approved' THEN
      missing := array_append(missing, 'approved_strategy_version');
    END IF;
  END IF;

  IF p.owner_user_id IS NULL THEN missing := array_append(missing, 'owner'); END IF;
  IF NOT EXISTS (SELECT 1 FROM public.mkt_goals g
                  WHERE g.plan_id = p_plan_id AND g.archived_at IS NULL) THEN
    missing := array_append(missing, 'at_least_one_goal');
  END IF;

  RETURN missing;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_plan_rank(p_type text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p_type WHEN 'annual' THEN 4 WHEN 'quarterly' THEN 3
                     WHEN 'monthly' THEN 2 ELSE 1 END;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_plan_rebase_strategy(p_plan_id uuid, p_new_version_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE p record; v record; v_old_id uuid;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.wassell_mkt_can('write_plan') THEN
    RAISE EXCEPTION 'your marketing role does not permit changing a plan''s strategy version'
      USING ERRCODE='insufficient_privilege';
  END IF;

  SELECT * INTO p FROM public.mkt_plans WHERE id = p_plan_id;
  IF p IS NULL THEN RAISE EXCEPTION 'plan not found' USING ERRCODE='no_data_found'; END IF;

  SELECT * INTO v FROM public.mkt_strategy_versions WHERE id = p_new_version_id;
  IF v IS NULL THEN
    RAISE EXCEPTION 'strategy version not found' USING ERRCODE='foreign_key_violation';
  END IF;

  IF p.status IN ('approved','active') AND v.status <> 'approved' THEN
    RAISE EXCEPTION
      'plan "%" is % — it can only be rebased onto an APPROVED strategy version (target is %)',
      p.name_ar, p.status, v.status USING ERRCODE='check_violation';
  END IF;

  IF p.strategy_version_id = p_new_version_id THEN
    RETURN jsonb_build_object('changed', false, 'reason', 'already bound to this version');
  END IF;

  v_old_id := p.strategy_version_id;
  PERFORM set_config('wassell.rebase_reason',
                     COALESCE(p_reason, 'rebased without a stated reason'), true);
  UPDATE public.mkt_plans SET strategy_version_id = p_new_version_id, updated_at = now()
   WHERE id = p_plan_id;
  PERFORM set_config('wassell.rebase_reason', '', true);

  RETURN jsonb_build_object(
    'changed', true, 'plan_id', p_plan_id,
    'from_version_id', v_old_id, 'to_version_id', p_new_version_id,
    'to_version_number', v.version_number, 'to_status', v.status);
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_platform_config_issues(p_platform text, p_config jsonb, p_schema_version integer DEFAULT 1)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE issues text[] := ARRAY[]::text[];
BEGIN
  IF p_config IS NULL OR jsonb_typeof(p_config) <> 'object' THEN
    RETURN ARRAY['platform_config must be a JSON object'];
  END IF;
  IF p_schema_version < 1 THEN issues := issues || 'config_schema_version must be >= 1'; END IF;
  IF p_config ? 'daily_budget' AND jsonb_typeof(p_config->'daily_budget') <> 'number' THEN
    issues := issues || 'daily_budget must be a number'; END IF;
  IF p_config ? 'placements' AND jsonb_typeof(p_config->'placements') <> 'array' THEN
    issues := issues || 'placements must be an array'; END IF;
  RETURN issues;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_platform_distribution(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_org uuid DEFAULT NULL::uuid, p_project uuid DEFAULT NULL::uuid)
 RETURNS TABLE(platform text, posts bigint, share_pct numeric, engagement bigint, first_post timestamp with time zone, last_post timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH scoped AS (
    SELECT cp.* FROM mkt_content_posts cp
    WHERE (p_from IS NULL OR cp.published_at >= p_from)
      AND (p_to   IS NULL OR cp.published_at <  (p_to + 1))
      AND (p_org  IS NULL OR cp.organization_id = p_org)
      AND (p_project IS NULL OR EXISTS (
            SELECT 1 FROM mkt_content_attributions a
            WHERE a.content_post_id = cp.id AND a.project_id = p_project
              AND a.review_status IN ('auto_accepted','confirmed')))
  ), tot AS (SELECT count(*)::numeric n FROM scoped)
  SELECT s.platform, count(*) AS posts,
         round(100 * count(*) / nullif((SELECT n FROM tot),0), 2) AS share_pct,
         sum(coalesce((s.engagement->>'likes')::bigint,0)
           + coalesce((s.engagement->>'comments')::bigint,0)
           + coalesce((s.engagement->>'shares')::bigint,0)
           + coalesce((s.engagement->>'views')::bigint,0)) AS engagement,
         min(s.published_at), max(s.published_at)
  FROM scoped s GROUP BY s.platform ORDER BY posts DESC;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_program_missing_requirements(p_program_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE g record; missing text[] := '{}';
BEGIN
  SELECT * INTO g FROM public.mkt_programs WHERE id = p_program_id;
  IF g IS NULL THEN RETURN ARRAY['not_found']; END IF;
  IF g.plan_id IS NULL         THEN missing := array_append(missing, 'plan'); END IF;
  IF g.primary_goal_id IS NULL THEN missing := array_append(missing, 'primary_goal'); END IF;
  IF g.owner_user_id IS NULL   THEN missing := array_append(missing, 'owner'); END IF;
  IF g.commitment_count IS NULL OR g.commitment_unit IS NULL
                               THEN missing := array_append(missing, 'commitment'); END IF;
  IF g.output_type IS NULL OR btrim(g.output_type) = ''
                               THEN missing := array_append(missing, 'output_type'); END IF;
  IF g.purpose IS NULL OR btrim(g.purpose) = ''
                               THEN missing := array_append(missing, 'purpose'); END IF;
  RETURN missing;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_project_intelligence(p_project_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_lim int := greatest(1, least(coalesce(p_limit,10), 50));
  v_from date := coalesce(p_from, '1900-01-01'::date);
  v_to   date := coalesce(p_to,   '2999-12-31'::date);
  v_out jsonb;
BEGIN
  SELECT jsonb_build_object(

    'generated_at', now(),
    'window', jsonb_build_object('from', p_from, 'to', p_to),

    -- ── Project header ──────────────────────────────────────────────────────
    'project', (
      SELECT jsonb_build_object(
        'id', r.id,
        'name', r.data->>'project_name',
        'city', r.data->>'city_name',
        'status', r.data->>'project_status',
        'type', r.data->>'project_type',
        'page_url', r.data->>'project_page_url',
        'developer', (SELECT jsonb_build_object('record_id', d.id, 'name',
                        coalesce(d.data->>'developer_name', d.data->>'name'))
                      FROM unified_records d WHERE d.id = (r.data->>'developer')::uuid))
      FROM unified_records r WHERE r.id = p_project_id),

    -- ── Who markets it (role lives on the LINK, not the org) ────────────────
    'organizations', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'organization_id', o.id,
        'name', coalesce(o.name_en, o.name_ar),
        'role', po.relationship_type,
        'confidence', po.confidence,
        'human_confirmed', po.human_confirmed,
        'first_observed_at', po.first_observed_at,
        'last_observed_at', po.last_observed_at,
        'is_active', po.is_active)
        ORDER BY po.relationship_type, po.confidence DESC NULLS LAST)
      FROM mkt_project_organizations po
      JOIN mkt_organizations o ON o.id = po.organization_id
      WHERE po.project_id = p_project_id), '[]'::jsonb),

    'social_accounts', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', sa.id, 'platform', sa.platform, 'handle', sa.handle,
        'profile_url', sa.profile_url, 'followers', sa.followers,
        'organization_id', sa.organization_id,
        'collection_enabled', sa.collection_enabled,
        'last_synced_at', sa.last_synced_at)
        ORDER BY sa.platform, sa.handle)
      FROM mkt_social_accounts sa
      WHERE sa.organization_id IN (
        SELECT organization_id FROM mkt_project_organizations WHERE project_id = p_project_id)
      ), '[]'::jsonb),

    -- ── Organic content ─────────────────────────────────────────────────────
    'content', jsonb_build_object(
      'total', (SELECT count(DISTINCT cp.id) FROM mkt_content_posts cp
                JOIN mkt_content_attributions a ON a.content_post_id = cp.id
                WHERE a.project_id = p_project_id
                  AND a.review_status IN ('auto_accepted','confirmed')
                  AND cp.published_at BETWEEN v_from AND v_to),
      'shown', v_lim,
      'recent', coalesce((
        SELECT jsonb_agg(x ORDER BY x->>'published_at' DESC) FROM (
          SELECT jsonb_build_object(
            'post_id', cp.id, 'platform', cp.platform, 'post_type', cp.post_type,
            'url', cp.post_url, 'published_at', cp.published_at,
            'caption_preview', left(coalesce(cp.caption,''), 240),
            'caption_full_length', length(coalesce(cp.caption,'')),
            'engagement', cp.engagement,
            'attribution_method', a.attribution_method,
            'attribution_confidence', a.confidence) AS x
          FROM mkt_content_posts cp
          JOIN mkt_content_attributions a ON a.content_post_id = cp.id
          WHERE a.project_id = p_project_id
            AND a.review_status IN ('auto_accepted','confirmed')
            AND cp.published_at BETWEEN v_from AND v_to
          ORDER BY cp.published_at DESC LIMIT v_lim) s), '[]'::jsonb)),

    -- ── Paid ads (via mkt_ad_attributions) ──────────────────────────────────
    'paid_ads', jsonb_build_object(
      'total', (SELECT count(*) FROM mkt_ad_attributions aa
                WHERE aa.project_id = p_project_id),
      'shown', v_lim,
      'recent', coalesce((
        SELECT jsonb_agg(jsonb_build_object(
          'ad_id', pa.id, 'platform', pa.platform, 'headline', pa.headline,
          'cta', pa.cta, 'landing_url', pa.landing_url,
          'is_active', pa.is_active,
          'started_at', coalesce(pa.platform_started_at, pa.first_seen_at),
          'ended_at', pa.platform_ended_at,
          'creative_url', pa.creative_stored_url))
        FROM mkt_ad_attributions aa
        JOIN mkt_paid_ads pa ON pa.id = aa.paid_ad_id
        WHERE aa.project_id = p_project_id), '[]'::jsonb)),

    -- ── What they are saying (facts; each carries its evidence counts) ──────
    'facts', (
      SELECT jsonb_object_agg(ft, vals) FROM (
        SELECT ft, coalesce((
          SELECT jsonb_agg(jsonb_build_object(
            'value', t.sample_value, 'key', t.normalized_key,
            'observations', t.observations, 'posts', t.distinct_posts,
            'first_seen', t.first_seen, 'last_seen', t.last_seen,
            'share_pct', t.share_pct))
          FROM mkt_fact_top(ft, v_lim, p_from, p_to, NULL, p_project_id) t), '[]'::jsonb) AS vals
        FROM unnest(ARRAY['price','offer','cta','campaign_message','selling_point',
                          'phone','payment_plan','delivery_date','unit_type',
                          'district','financing','amenity','audience']) ft) z),

    -- ── Trends ──────────────────────────────────────────────────────────────
    'trends', jsonb_build_object(
      'activity', coalesce((
        SELECT jsonb_agg(jsonb_build_object(
          'bucket', t.bucket_start, 'posts', t.posts, 'ads', t.ads,
          'platforms', t.platforms, 'engagement', t.engagement) ORDER BY t.bucket_start)
        FROM mkt_activity_trend('month', p_from, p_to, NULL, p_project_id) t), '[]'::jsonb),
      'price', coalesce((
        SELECT jsonb_agg(jsonb_build_object(
          'bucket', t.bucket_start, 'observations', t.observations,
          'min', t.min_value, 'max', t.max_value, 'avg', t.avg_value) ORDER BY t.bucket_start)
        FROM mkt_fact_trend('price','month', p_from, p_to, NULL, p_project_id) t
        WHERE t.numeric_count > 0), '[]'::jsonb),
      'platforms', coalesce((
        SELECT jsonb_agg(jsonb_build_object(
          'platform', d.platform, 'posts', d.posts, 'share_pct', d.share_pct,
          'engagement', d.engagement))
        FROM mkt_platform_distribution(p_from, p_to, NULL, p_project_id) d), '[]'::jsonb)),

    -- ── Share of voice for the orgs marketing this project ──────────────────
    'share_of_voice', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'organization_id', s.organization_id,
        'name', coalesce(o.name_en, o.name_ar),
        'period_start', s.period_start, 'period_end', s.period_end,
        'scope', s.scope_type, 'post_count', s.post_count, 'ad_count', s.ad_count,
        'share_pct', s.share_pct) ORDER BY s.period_start DESC, s.share_pct DESC)
      FROM mkt_share_of_voice s
      JOIN mkt_organizations o ON o.id = s.organization_id
      WHERE s.organization_id IN (
        SELECT organization_id FROM mkt_project_organizations WHERE project_id = p_project_id)
      ), '[]'::jsonb),

    -- ── Timeline: campaigns + when each marketer first appeared ─────────────
    'timeline', jsonb_build_object(
      'campaigns', coalesce((
        SELECT jsonb_agg(jsonb_build_object(
          'campaign_id', c.id, 'label', coalesce(c.manual_label, c.label),
          'objective', c.objective, 'platforms', to_jsonb(c.platforms),
          'is_active', c.is_active, 'member_count', c.member_count,
          'first_seen_at', c.first_seen_at, 'last_seen_at', c.last_seen_at,
          'summary', (SELECT jsonb_build_object('confidence', su.confidence,
                        'summary_ar', su.result->>'summary_ar',
                        'summary_en', su.result->>'summary_en')
                      FROM mkt_campaign_summaries su WHERE su.campaign_id = c.id))
          ORDER BY c.last_seen_at DESC NULLS LAST)
        FROM mkt_campaigns c WHERE c.project_id = p_project_id), '[]'::jsonb),
      'org_first_seen', coalesce((
        SELECT jsonb_agg(jsonb_build_object(
          'organization_id', po.organization_id,
          'name', coalesce(o.name_en, o.name_ar),
          'role', po.relationship_type,
          'first_observed_at', po.first_observed_at) ORDER BY po.first_observed_at)
        FROM mkt_project_organizations po
        JOIN mkt_organizations o ON o.id = po.organization_id
        WHERE po.project_id = p_project_id AND po.first_observed_at IS NOT NULL), '[]'::jsonb)),

    -- ── Rollup state (already maintained; do not recompute here) ────────────
    'state', (SELECT to_jsonb(s) FROM mkt_project_marketing_state s
              WHERE s.project_id = p_project_id),

    -- ── Existing insights (AI-derived content, surfaced with provenance) ────
    'insights', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', i.id, 'kind', i.kind, 'severity', i.severity,
        'title', i.title, 'body', i.body, 'evidence', i.evidence,
        'generated_at', i.generated_at, 'dismissed', i.dismissed)
        ORDER BY i.generated_at DESC)
      FROM mkt_insights i
      WHERE i.project_id = p_project_id AND NOT coalesce(i.dismissed,false)), '[]'::jsonb),

    -- ── Honesty block: what is being EXCLUDED and why ───────────────────────
    'attribution_quality', (
      SELECT jsonb_build_object(
        'confirmed_posts', count(DISTINCT a.content_post_id)
                             FILTER (WHERE a.review_status IN ('auto_accepted','confirmed')),
        'speculative_posts', count(DISTINCT a.content_post_id)
                             FILTER (WHERE a.review_status NOT IN ('auto_accepted','confirmed')),
        'note', 'Everything above counts CONFIRMED attributions only. Speculative '
              || 'marketer_assignment candidates (confidence 0.40) are excluded; they '
              || 'would overstate project activity roughly 4x. See docs section 6a.')
      FROM mkt_content_attributions a WHERE a.project_id = p_project_id)

  ) INTO v_out;

  RETURN v_out;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_provider_health()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(jsonb_agg(row), '[]'::jsonb) FROM (
    SELECT jsonb_build_object(
      'provider', p.provider_key,
      'display_name', p.display_name,
      'is_enabled', p.is_enabled,
      'health_status', p.health_status,
      'health_detail', p.health_detail,
      'last_checked_at', p.last_checked_at,
      'last_success', (SELECT max(finished_at) FROM mkt_ingestion_runs r WHERE r.provider=p.provider_key AND r.status IN ('succeeded','partial')),
      'last_failure', (SELECT max(finished_at) FROM mkt_ingestion_runs r WHERE r.provider=p.provider_key AND r.status='failed'),
      'consecutive_failures', (SELECT count(*) FROM mkt_ingestion_runs r WHERE r.provider=p.provider_key AND r.status='failed'
          AND r.started_at > COALESCE((SELECT max(started_at) FROM mkt_ingestion_runs s WHERE s.provider=p.provider_key AND s.status IN ('succeeded','partial')), '-infinity'::timestamptz)),
      'avg_run_duration_ms', (SELECT round(avg(EXTRACT(EPOCH FROM (finished_at-started_at))*1000)) FROM mkt_ingestion_runs r WHERE r.provider=p.provider_key AND r.finished_at IS NOT NULL AND r.started_at > now()-interval '14 days'),
      'avg_response_ms', (SELECT round(avg(EXTRACT(EPOCH FROM (finished_at-started_at))*1000)) FROM mkt_ingestion_runs r WHERE r.provider=p.provider_key AND r.finished_at IS NOT NULL AND r.started_at > now()-interval '14 days'),
      'runs_14d', (SELECT count(*) FROM mkt_ingestion_runs r WHERE r.provider=p.provider_key AND r.status<>'running' AND r.started_at > now()-interval '14 days'),
      'success_rate', (SELECT CASE WHEN count(*) FILTER (WHERE status<>'running')>0
          THEN round(count(*) FILTER (WHERE status IN ('succeeded','partial'))::numeric / count(*) FILTER (WHERE status<>'running'),4) ELSE NULL END
          FROM mkt_ingestion_runs r WHERE r.provider=p.provider_key AND r.started_at > now()-interval '14 days'),
      'error_rate', (SELECT CASE WHEN count(*) FILTER (WHERE status<>'running')>0
          THEN round(count(*) FILTER (WHERE status='failed')::numeric / count(*) FILTER (WHERE status<>'running'),4) ELSE NULL END
          FROM mkt_ingestion_runs r WHERE r.provider=p.provider_key AND r.started_at > now()-interval '14 days'),
      'cost_today', (SELECT COALESCE(sum((provider_cost->>'usage_total_usd')::numeric),0) FROM mkt_ingestion_runs r WHERE r.provider=p.provider_key AND r.started_at >= date_trunc('day', now())),
      'cost_month', (SELECT COALESCE(sum((provider_cost->>'usage_total_usd')::numeric),0) FROM mkt_ingestion_runs r WHERE r.provider=p.provider_key AND r.started_at >= date_trunc('month', now()))
    ) AS row
    FROM mkt_providers p ORDER BY p.provider_key
  ) x;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_queue_health()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'queued',     (SELECT count(*) FROM mkt_collection_jobs WHERE status='pending'),
    'running',    (SELECT count(*) FROM mkt_collection_jobs WHERE status='running'),
    'retrying',   (SELECT count(*) FROM mkt_collection_jobs WHERE status='retrying'),
    'succeeded_24h', (SELECT count(*) FROM mkt_collection_jobs WHERE status='succeeded' AND finished_at > now()-interval '24 hours'),
    'failed_24h',    (SELECT count(*) FROM mkt_collection_jobs WHERE status='failed' AND updated_at > now()-interval '24 hours'),
    'retried_total', (SELECT COALESCE(sum(GREATEST(attempts-1,0)),0) FROM mkt_collection_jobs WHERE attempts>1),
    'oldest_queued_at',  (SELECT min(created_at) FROM mkt_collection_jobs WHERE status='pending'),
    'longest_running_at',(SELECT min(started_at) FROM mkt_collection_jobs WHERE status='running')
  );
$function$;
CREATE OR REPLACE FUNCTION public.mkt_raw_ingestion_insert(p_provider text, p_source_type text, p_external_identity text, p_payload jsonb, p_dedup_key text DEFAULT NULL::text, p_run_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  INSERT INTO public.mkt_raw_ingestions (provider, source_type, external_identity, payload, dedup_key, ingestion_run_id)
  VALUES (p_provider, p_source_type, p_external_identity, p_payload, p_dedup_key, p_run_id)
  RETURNING id;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_raw_ingestions_cleanup(p_days integer DEFAULT 90)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n int;
BEGIN
  DELETE FROM public.mkt_raw_ingestions WHERE collected_at < now() - (p_days || ' days')::interval;
  GET DIAGNOSTICS n = ROW_COUNT; RETURN n;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_recompute_project_marketing_state()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n integer;
BEGIN
  WITH strong AS (
    SELECT a.project_id,
           count(DISTINCT cp.id)              AS post_count,
           count(DISTINCT cp.platform)        AS platform_count,
           array_agg(DISTINCT cp.platform)    AS platforms,
           count(DISTINCT cp.organization_id) AS org_count,
           min(cp.published_at)               AS first_at,
           max(cp.published_at)               AS last_at
    FROM mkt_content_attributions a
    JOIN mkt_content_posts cp ON cp.id = a.content_post_id
    WHERE a.review_status IN ('auto_accepted','confirmed')
    GROUP BY a.project_id
  ),
  weak AS (
    SELECT a.project_id, count(DISTINCT a.content_post_id) AS candidate_post_count
    FROM mkt_content_attributions a
    WHERE a.review_status NOT IN ('auto_accepted','confirmed')
    GROUP BY a.project_id
  ),
  camps AS (
    SELECT project_id, count(*) AS campaign_count,
           count(*) FILTER (WHERE is_active) AS active_campaign_count
    FROM mkt_campaigns WHERE project_id IS NOT NULL GROUP BY project_id
  ),
  -- facts resolved the SAME way the intelligence page resolves them
  facts AS (
    SELECT a.project_id, count(DISTINCT f.id) AS fact_count,
           min(f.value_num) FILTER (WHERE f.fact_type='price') AS min_price,
           max(f.value_num) FILTER (WHERE f.fact_type='price') AS max_price
    FROM mkt_observed_facts f
    JOIN mkt_content_attributions a ON a.content_post_id = f.content_post_id
    WHERE a.review_status IN ('auto_accepted','confirmed')
    GROUP BY a.project_id
  ),
  keys AS (
    SELECT project_id FROM strong UNION SELECT project_id FROM weak
    UNION SELECT project_id FROM camps UNION SELECT project_id FROM facts
  ),
  merged AS (
    SELECT k.project_id,
           coalesce(s.post_count, 0)            AS post_count,
           coalesce(w.candidate_post_count, 0)  AS candidate_post_count,
           coalesce(s.platform_count, 0)        AS platform_count,
           coalesce(s.platforms, '{}')          AS platforms,
           coalesce(s.org_count, 0)             AS org_count,
           coalesce(c.campaign_count, 0)        AS campaign_count,
           coalesce(c.active_campaign_count, 0) AS active_campaign_count,
           coalesce(f.fact_count, 0)            AS fact_count,
           f.min_price, f.max_price, s.first_at, s.last_at
    FROM keys k
    LEFT JOIN strong s ON s.project_id = k.project_id
    LEFT JOIN weak   w ON w.project_id = k.project_id
    LEFT JOIN camps  c ON c.project_id = k.project_id
    LEFT JOIN facts  f ON f.project_id = k.project_id
  )
  INSERT INTO mkt_project_marketing_state
    (project_id, post_count, candidate_post_count, platform_count, platforms,
     org_count, campaign_count, active_campaign_count, fact_count,
     min_advertised_price, max_advertised_price, first_activity_at, last_activity_at, computed_at)
  SELECT project_id, post_count, candidate_post_count, platform_count, platforms,
         org_count, campaign_count, active_campaign_count, fact_count,
         min_price, max_price, first_at, last_at, now()
  FROM merged WHERE project_id IS NOT NULL
  ON CONFLICT (project_id) DO UPDATE SET
    post_count=EXCLUDED.post_count, candidate_post_count=EXCLUDED.candidate_post_count,
    platform_count=EXCLUDED.platform_count, platforms=EXCLUDED.platforms,
    org_count=EXCLUDED.org_count, campaign_count=EXCLUDED.campaign_count,
    active_campaign_count=EXCLUDED.active_campaign_count, fact_count=EXCLUDED.fact_count,
    min_advertised_price=EXCLUDED.min_advertised_price,
    max_advertised_price=EXCLUDED.max_advertised_price,
    first_activity_at=EXCLUDED.first_activity_at, last_activity_at=EXCLUDED.last_activity_at,
    computed_at=now();
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_reemit_all_facts()
 RETURNS TABLE(source text, rows_processed bigint, facts_emitted bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; c bigint; f bigint;
BEGIN
  c := 0; f := 0;
  FOR r IN SELECT id FROM mkt_visual_text LOOP
    f := f + mkt_emit_facts_visual_text(r.id); c := c + 1;
  END LOOP;
  source := 'visual_text'; rows_processed := c; facts_emitted := f; RETURN NEXT;

  c := 0; f := 0;
  FOR r IN SELECT id FROM mkt_content_enrichment LOOP
    f := f + mkt_emit_facts_enrichment(r.id); c := c + 1;
  END LOOP;
  source := 'enrichment'; rows_processed := c; facts_emitted := f; RETURN NEXT;

  c := 0; f := 0;
  FOR r IN SELECT id FROM mkt_paid_ads LOOP
    f := f + mkt_emit_facts_paid_ad(r.id); c := c + 1;
  END LOOP;
  source := 'paid_ad'; rows_processed := c; facts_emitted := f; RETURN NEXT;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_refresh_our_projects_coverage()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_n integer;
BEGIN
  INSERT INTO public.mkt_project_coverage (project_id)
  SELECT s.project_id FROM public.v_our_projects_scope s
  ON CONFLICT (project_id) DO NOTHING;

  WITH s AS (SELECT * FROM public.v_our_projects_scope),
  dev AS (
    SELECT s.project_id,
           (SELECT po.organization_id FROM public.mkt_project_organizations po
             WHERE po.project_id = s.project_id AND po.is_active
               AND po.relationship_type = 'developer' LIMIT 1) AS dev_org
    FROM s
  ),
  agg AS (
    SELECT s.project_id,
      (SELECT count(*) FROM public.mkt_project_organizations po
        WHERE po.project_id=s.project_id AND po.is_active
          AND po.relationship_type <> 'developer')                          AS marketers,
      (SELECT count(DISTINCT a2.id) FROM public.mkt_social_accounts a2
         JOIN public.mkt_project_organizations po2 ON po2.organization_id=a2.organization_id
        WHERE po2.project_id=s.project_id AND po2.is_active)                AS accounts_cfg,
      (SELECT count(*) FROM public.mkt_content_attributions ca
        WHERE ca.project_id=s.project_id
          AND ca.review_status IN ('auto_accepted','confirmed'))            AS confirmed,
      (SELECT COALESCE(array_agg(DISTINCT a3.platform), '{}')
         FROM public.mkt_social_accounts a3
         JOIN public.mkt_project_organizations po3 ON po3.organization_id=a3.organization_id
        WHERE po3.project_id=s.project_id AND po3.is_active)                AS platforms
    FROM s
  )
  UPDATE public.mkt_project_coverage c
  SET developer_org_id     = dev.dev_org,
      developer_resolved   = dev.dev_org IS NOT NULL,
      marketers_found      = agg.marketers,
      accounts_configured  = agg.accounts_cfg,
      accounts_found       = agg.accounts_cfg,
      platforms_researched = agg.platforms,
      project_aliases      = ARRAY[COALESCE(s.project_name_ar,'')]::text[],
      coverage_state = CASE
        WHEN agg.accounts_cfg = 0 AND dev.dev_org IS NULL THEN 'not_researched'
        WHEN agg.accounts_cfg = 0                          THEN 'accounts_not_found'
        WHEN agg.confirmed >= 20                           THEN 'sufficient_coverage'
        WHEN agg.confirmed > 0                             THEN 'partial_coverage'
        ELSE 'accounts_configured'
      END,
      coverage_limitations = CASE
        WHEN agg.accounts_cfg = 0 THEN 'no social account configured for any linked organization'
        WHEN agg.confirmed = 0    THEN 'accounts collected but no content attributed to this project yet'
        WHEN agg.confirmed < 20   THEN 'below the 20-confirmed-record sufficiency bar'
        ELSE NULL END,
      last_audited_at = now(),
      updated_at      = now()
  FROM s, dev, agg
  WHERE c.project_id = s.project_id AND dev.project_id = s.project_id AND agg.project_id = s.project_id;

  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_run_diagnostics()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  wb timestamptz; sb timestamptz; enabled_n int; ok_n int;
  woff numeric := mkt_setting_num('ops_worker_offline_seconds',180);
  soff numeric := mkt_setting_num('ops_scheduler_offline_seconds',5400);
  prov_h numeric := mkt_setting_num('ops_provider_stale_hours',26);
BEGIN
  PERFORM mkt_diagnostic_set('db_connectivity','ok','reachable',0);
  PERFORM mkt_diagnostic_set('queue_responsive','ok', (SELECT count(*)::text||' jobs' FROM mkt_collection_jobs),0);

  SELECT last_beat_at INTO wb FROM mkt_ops_heartbeats WHERE component='worker';
  IF wb IS NULL THEN
    PERFORM mkt_diagnostic_set('worker_heartbeat','down','no heartbeat recorded',NULL);
    PERFORM mkt_alert_emit('worker_offline','worker_offline','العامل غير متصل (لا نبضة)','critical','worker','worker','No worker heartbeat',jsonb_build_object());
  ELSIF wb < now() - (woff * interval '1 second') THEN
    PERFORM mkt_diagnostic_set('worker_heartbeat','down','stale: '||round(EXTRACT(EPOCH FROM (now()-wb)))||'s',NULL);
    PERFORM mkt_alert_emit('worker_offline','worker_offline','العامل غير متصل','critical','worker','worker','Heartbeat stale '||round(EXTRACT(EPOCH FROM (now()-wb)))||'s',jsonb_build_object('last_beat_at', wb));
  ELSE
    PERFORM mkt_diagnostic_set('worker_heartbeat','ok','fresh',round(EXTRACT(EPOCH FROM (now()-wb))*1000)::int);
    PERFORM mkt_alert_resolve('worker_offline','worker');
  END IF;

  SELECT last_beat_at INTO sb FROM mkt_ops_heartbeats WHERE component='scheduler';
  IF sb IS NULL OR sb < now() - (soff * interval '1 second') THEN
    PERFORM mkt_diagnostic_set('scheduler_heartbeat', CASE WHEN sb IS NULL THEN 'down' ELSE 'degraded' END, COALESCE('stale: '||round(EXTRACT(EPOCH FROM (now()-sb)))||'s','no heartbeat'),NULL);
    PERFORM mkt_alert_emit('scheduler_offline','scheduler_offline','المُجدوِل متوقف','warning','scheduler','scheduler',NULL,jsonb_build_object('last_beat_at', sb));
  ELSE
    PERFORM mkt_diagnostic_set('scheduler_heartbeat','ok','fresh',NULL);
    PERFORM mkt_alert_resolve('scheduler_offline','scheduler');
  END IF;

  SELECT count(*) FILTER (WHERE is_enabled),
         count(*) FILTER (WHERE is_enabled AND EXISTS (SELECT 1 FROM mkt_ingestion_runs x WHERE x.provider=p.provider_key AND x.status IN ('succeeded','partial') AND x.started_at > now() - (prov_h * interval '1 hour')))
    INTO enabled_n, ok_n FROM mkt_providers p;
  PERFORM mkt_diagnostic_set('provider_connectivity',
    CASE WHEN enabled_n=0 THEN 'down' WHEN ok_n=enabled_n THEN 'ok' WHEN ok_n=0 THEN 'down' ELSE 'degraded' END,
    ok_n||'/'||enabled_n||' providers with recent success', NULL);

  RETURN (SELECT COALESCE(jsonb_object_agg(check_name, jsonb_build_object('status',status,'detail',detail,'latency_ms',latency_ms,'checked_at',checked_at)),'{}'::jsonb) FROM mkt_diagnostics);
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_set_role_grant(p_user_id uuid, p_role text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.wassell_mkt_can('manage_roles') THEN
    RAISE EXCEPTION 'your marketing role does not permit granting marketing roles'
      USING ERRCODE='insufficient_privilege';
  END IF;
  IF p_role IS NULL THEN
    DELETE FROM public.mkt_role_grants WHERE user_id = p_user_id;
    RETURN;
  END IF;
  IF p_role NOT IN ('administrator','marketing_manager','content_manager','writer','designer',
                    'video_editor','publisher','reviewer','sales','viewer') THEN
    RAISE EXCEPTION 'unknown marketing role: %', p_role USING ERRCODE='check_violation';
  END IF;
  INSERT INTO public.mkt_role_grants (user_id, mkt_role, granted_by_user_id)
  VALUES (p_user_id, p_role, public.wassell_app_user_id(auth.uid()))
  ON CONFLICT (user_id) DO UPDATE
    SET mkt_role = EXCLUDED.mkt_role,
        granted_by_user_id = EXCLUDED.granted_by_user_id;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_setting_num(p_key text, p_default numeric)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE((SELECT (value#>>'{}')::numeric FROM public.mkt_settings WHERE key=p_key), p_default);
$function$;
CREATE OR REPLACE FUNCTION public.mkt_snapshot_account_followers()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.followers IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW.followers IS DISTINCT FROM OLD.followers)
  THEN
    BEGIN
      INSERT INTO public.mkt_account_metrics
        (social_account_id, captured_at, followers, following, posts_count, raw)
      VALUES (NEW.id, date_trunc('hour', now()), NEW.followers, NULL, NULL,
              jsonb_build_object('source','snapshot-on-write trigger',
                                 'display_name', NEW.display_name,
                                 'platform', NEW.platform))
      ON CONFLICT (social_account_id, captured_at) DO NOTHING;
    EXCEPTION WHEN OTHERS THEN
      -- Never let history capture break an account update. Losing a snapshot is
      -- recoverable; losing the collection write is not.
      RAISE WARNING 'follower snapshot failed for account % : % (%)', NEW.id, SQLERRM, SQLSTATE;
    END;
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_ad_creative_approved()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_status text;
BEGIN
  IF NEW.status IN ('active','in_review') AND NEW.content_item_id IS NOT NULL THEN
    SELECT status INTO v_status FROM public.mkt_content_items WHERE id = NEW.content_item_id;
    IF v_status NOT IN ('approved','ready_to_publish','scheduled','published') THEN
      RAISE EXCEPTION
        'ad creative must be approved content before the ad goes %; creative status is %',
        NEW.status, v_status USING ERRCODE='check_violation';
    END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_artifact_version_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' AND (NEW.version_number IS NULL OR NEW.version_number = 0) THEN
    SELECT COALESCE(max(version_number), 0) + 1 INTO NEW.version_number
      FROM public.mkt_content_versions
     WHERE version_type = NEW.version_type
       AND ((NEW.deliverable_id IS NOT NULL AND deliverable_id = NEW.deliverable_id)
         OR (NEW.deliverable_id IS NULL AND deliverable_id IS NULL
             AND content_item_id = NEW.content_item_id));
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_campaign_block_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n bigint;
BEGIN
  SELECT
    (SELECT count(*) FROM public.mkt_content_items      WHERE campaign_id = OLD.id)
  + (SELECT count(*) FROM public.mkt_publications       WHERE campaign_id = OLD.id)
  + (SELECT count(*) FROM public.mkt_platform_campaigns WHERE campaign_id = OLD.id)
  + (SELECT count(*) FROM public.mkt_performance_snapshots WHERE campaign_id = OLD.id)
  + (SELECT count(*) FROM public.mkt_lead_attributions  WHERE campaign_id = OLD.id)
  INTO n;
  IF n > 0 THEN
    RAISE EXCEPTION 'MKT:has_dependents' USING ERRCODE = 'check_violation';
  END IF;
  RETURN OLD;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_campaign_channel_mix()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.campaign_class IS NOT NULL THEN
    IF TG_OP = 'INSERT' OR COALESCE(OLD.channel_mix, '') <> 'both' THEN
      NEW.channel_mix := NEW.campaign_class;
    END IF;
  END IF;
  NEW.needs_classification := (
    NEW.plan_id IS NULL OR NEW.primary_goal_id IS NULL
    OR NEW.campaign_class IS NULL OR NEW.campaign_type IS NULL
    OR NEW.channel_mix = 'both');
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_campaign_history_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND NOT EXISTS (
       SELECT 1 FROM public.mkt_internal_campaigns WHERE id = OLD.campaign_id) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'MKT:history_append_only' USING ERRCODE = 'check_violation';
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_campaign_portfolio_valid()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_init_plan uuid; v_prog_plan uuid; p record;
BEGIN
  IF NEW.code IS NULL OR btrim(NEW.code) = '' THEN
    NEW.code := public.mkt_next_campaign_code();
  END IF;

  IF TG_OP = 'INSERT' AND NEW.campaign_class IS NULL THEN
    RAISE EXCEPTION 'MKT:campaign_class_required' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.initiative_id IS NOT NULL THEN
    SELECT plan_id INTO v_init_plan FROM public.mkt_initiatives WHERE id = NEW.initiative_id;
    IF NEW.plan_id IS NOT NULL AND v_init_plan IS NOT NULL AND v_init_plan <> NEW.plan_id THEN
      RAISE EXCEPTION 'MKT:initiative_other_plan' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.plan_id IS NULL THEN NEW.plan_id := v_init_plan; END IF;
  END IF;

  IF NEW.program_id IS NOT NULL THEN
    SELECT plan_id INTO v_prog_plan FROM public.mkt_programs WHERE id = NEW.program_id;
    IF NEW.plan_id IS NOT NULL AND v_prog_plan IS NOT NULL AND v_prog_plan <> NEW.plan_id THEN
      RAISE EXCEPTION 'MKT:program_other_plan' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF NEW.primary_goal_id IS NOT NULL AND NEW.plan_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.mkt_goals
                    WHERE id = NEW.primary_goal_id AND plan_id = NEW.plan_id) THEN
      RAISE EXCEPTION 'MKT:goal_other_plan' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF NEW.plan_id IS NOT NULL AND NEW.start_date IS NOT NULL AND NEW.end_date IS NOT NULL THEN
    SELECT period_start, period_end INTO p FROM public.mkt_plans WHERE id = NEW.plan_id;
    IF p IS NOT NULL AND (NEW.start_date < p.period_start OR NEW.end_date > p.period_end)
       AND COALESCE(btrim(NEW.period_override_reason), '') = '' THEN
      RAISE EXCEPTION 'MKT:dates_outside_plan' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF COALESCE(btrim(NEW.period_override_reason), '') <> ''
     AND (TG_OP = 'INSERT' OR COALESCE(btrim(OLD.period_override_reason), '') = '') THEN
    NEW.period_override_at := now();
    IF NEW.period_override_by_user_id IS NULL THEN
      NEW.period_override_by_user_id := public.wassell_app_user_id(auth.uid());
    END IF;
  END IF;

  NEW.needs_classification := (NEW.plan_id IS NULL OR NEW.primary_goal_id IS NULL);

  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_campaign_status_log()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' OR NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO public.mkt_campaign_status_history
      (campaign_id, from_status, to_status, changed_by_user_id)
    VALUES (NEW.id, CASE WHEN TG_OP = 'UPDATE' THEN OLD.status END, NEW.status,
            public.wassell_app_user_id(auth.uid()));
  END IF;
  RETURN NULL;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_campaign_status_machine()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE blockers text[];
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    IF NOT public.mkt_campaign_status_allowed(OLD.status, NEW.status) THEN
      RAISE EXCEPTION 'MKT:invalid_status_transition' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status IN ('planned', 'active') THEN
      blockers := public.mkt_campaign_activation_blockers(NEW.id);
      IF array_length(blockers, 1) IS NOT NULL THEN
        RAISE EXCEPTION 'MKT:campaign_incomplete:%', array_to_string(blockers, ',')
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_capture_account_metrics()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  BEGIN
    IF NEW.followers IS NOT NULL THEN
      INSERT INTO mkt_account_metrics (social_account_id, captured_at, followers, provider)
      VALUES (NEW.id, date_trunc('day', now()), NEW.followers, NEW.provider)
      ON CONFLICT (social_account_id, captured_at)
      DO UPDATE SET followers = EXCLUDED.followers, provider = EXCLUDED.provider;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- Same asymmetric-cost rule as fact emission: losing the account sync to
    -- protect a derived history row would be the worse trade. Loud, not silent.
    RAISE WARNING 'mkt_account_metrics capture failed for account % : % (%)',
      NEW.id, SQLERRM, SQLSTATE;
  END;
  RETURN NULL;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_content_activation_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE missing text[];
BEGIN
  IF NEW.status = 'idea' OR NEW.status IN ('cancelled','archived') THEN RETURN NULL; END IF;
  IF TG_OP = 'UPDATE' AND OLD.status = NEW.status THEN RETURN NULL; END IF;
  IF TG_OP = 'UPDATE' AND OLD.status <> 'idea' THEN RETURN NULL; END IF;

  missing := public.mkt_content_missing_requirements(NEW.id);
  IF array_length(missing, 1) > 0 THEN
    RAISE EXCEPTION 'content % cannot leave the idea stage yet — missing: %',
      NEW.content_number, array_to_string(missing, ', ') USING ERRCODE='check_violation';
  END IF;
  RETURN NULL;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_content_context_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE gated text[] := ARRAY['awaiting_final_approval','approved','ready_to_publish',
                              'scheduled','published'];
        missing text[];
BEGIN
  IF NEW.status = ANY(gated) AND NEW.status IS DISTINCT FROM OLD.status THEN
    missing := public.mkt_content_missing_context(NEW.id);
    IF array_length(missing, 1) > 0 THEN
      RAISE EXCEPTION
        'content % cannot move to % until its strategic context is complete — missing: %',
        NEW.content_number, NEW.status, array_to_string(missing, ', ')
        USING ERRCODE='check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_content_origin_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.origin_campaign_id IS NULL AND NEW.campaign_id IS NOT NULL THEN
      NEW.origin_campaign_id := NEW.campaign_id;
      IF NEW.origin_kind IS NULL THEN NEW.origin_kind := 'campaign'; END IF;
    ELSIF NEW.origin_campaign_id IS NOT NULL THEN
      NEW.campaign_id := NEW.origin_campaign_id;
    END IF;
  ELSE
    IF NEW.origin_campaign_id IS DISTINCT FROM OLD.origin_campaign_id THEN
      NEW.campaign_id := NEW.origin_campaign_id;
    ELSIF NEW.campaign_id IS DISTINCT FROM OLD.campaign_id THEN
      NEW.origin_campaign_id := NEW.campaign_id;
      IF NEW.campaign_id IS NOT NULL AND NEW.origin_kind IS NULL THEN
        NEW.origin_kind := 'campaign';
      END IF;
    END IF;
  END IF;
  IF NEW.primary_pillar_id IS NULL AND NEW.content_pillar IS NOT NULL THEN
    SELECT id INTO NEW.primary_pillar_id FROM public.mkt_content_pillars
      WHERE slug = NEW.content_pillar OR name_en = NEW.content_pillar OR name_ar = NEW.content_pillar
      LIMIT 1;
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_content_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP='UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    IF NOT public.mkt_content_status_allowed(OLD.status, NEW.status) THEN
      RAISE EXCEPTION 'invalid content status transition: % -> % (content %)',
        OLD.status, NEW.status, OLD.content_number USING ERRCODE='check_violation';
    END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_content_status_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP='INSERT' THEN
    INSERT INTO public.mkt_content_status_history(content_item_id, from_status, to_status, changed_by_user_id, reason)
    VALUES (NEW.id, NULL, NEW.status,
            COALESCE(NEW.created_by_user_id, public.wassell_app_user_id(auth.uid())), 'created');
  ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO public.mkt_content_status_history(content_item_id, from_status, to_status, changed_by_user_id, reason)
    VALUES (NEW.id, OLD.status, NEW.status, public.wassell_app_user_id(auth.uid()),
            NULLIF(current_setting('wassell.status_reason', true),''));
  END IF;
  RETURN NULL;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_deliverable_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.deliverable_number IS NULL OR NEW.deliverable_number = 0 THEN
    SELECT COALESCE(max(deliverable_number), 0) + 1 INTO NEW.deliverable_number
      FROM public.mkt_content_deliverables WHERE content_item_id = NEW.content_item_id;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_emit_facts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  BEGIN
    CASE TG_TABLE_NAME
      WHEN 'mkt_visual_text'         THEN PERFORM mkt_emit_facts_visual_text(NEW.id);
      WHEN 'mkt_content_enrichment'  THEN PERFORM mkt_emit_facts_enrichment(NEW.id);
      WHEN 'mkt_paid_ads'            THEN PERFORM mkt_emit_facts_paid_ad(NEW.id);
    END CASE;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'mkt fact emission failed for %.% : % (%) — artifact was still saved; run mkt_reemit_all_facts() to recover',
      TG_TABLE_NAME, NEW.id, SQLERRM, SQLSTATE;
  END;
  RETURN NULL;  -- AFTER trigger
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_final_media_to_library()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE d record; c record; v_asset uuid;
BEGIN
  IF NEW.approval_state <> 'approved' OR NEW.version_type <> 'final_media'
     OR NEW.file_id IS NULL OR NEW.deliverable_id IS NULL THEN
    RETURN NULL;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.approval_state = 'approved' THEN RETURN NULL; END IF;

  SELECT * INTO d FROM public.mkt_content_deliverables WHERE id = NEW.deliverable_id;
  SELECT * INTO c FROM public.mkt_content_items WHERE id = NEW.content_item_id;

  SELECT id INTO v_asset FROM public.mkt_raw_assets WHERE file_id = NEW.file_id LIMIT 1;
  IF v_asset IS NULL THEN
    INSERT INTO public.mkt_raw_assets
      (file_id, asset_name, asset_type, asset_class, project_id, source_kind,
       owner_user_id, uploaded_by_user_id, approval_status, usage_status)
    VALUES
      (NEW.file_id,
       COALESCE(NULLIF(d.label,''), c.title)
         || CASE WHEN d.platform IS NULL THEN '' ELSE ' — ' || d.platform END,
       'custom',
       'final', c.project_id, 'in_house',
       COALESCE(d.owner_user_id, c.owner_user_id), NEW.approved_by_user_id,
       'approved', 'in_use')
    RETURNING id INTO v_asset;
  ELSE
    UPDATE public.mkt_raw_assets
       SET asset_class = 'final', usage_status = 'in_use'
     WHERE id = v_asset AND asset_class <> 'final';
  END IF;

  INSERT INTO public.mkt_asset_links (asset_id, target_type, target_id, role, created_by_user_id)
  VALUES (v_asset, 'deliverable', NEW.deliverable_id, 'final', NEW.approved_by_user_id)
  ON CONFLICT (asset_id, target_type, target_id) DO NOTHING;

  RETURN NULL;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_goal_activation_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE missing text[];
BEGIN
  IF NEW.status = 'active'
     AND (TG_OP = 'INSERT' OR NEW.status IS DISTINCT FROM OLD.status) THEN
    missing := public.mkt_goal_missing_requirements(NEW.id);
    IF array_length(missing,1) > 0 THEN
      RAISE EXCEPTION
        'goal "%" cannot be activated until it is complete — missing: %',
        NEW.name_ar, array_to_string(missing, ', ') USING ERRCODE='check_violation';
    END IF;
  END IF;
  RETURN NULL;   -- AFTER trigger: return value is ignored
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_goal_hierarchy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_plan uuid; hops int := 0; cur uuid;
BEGIN
  IF NEW.parent_goal_id IS NOT NULL THEN
    SELECT plan_id INTO v_plan FROM public.mkt_goals WHERE id = NEW.parent_goal_id;
    IF v_plan IS NULL THEN
      RAISE EXCEPTION 'parent goal does not exist' USING ERRCODE='foreign_key_violation';
    END IF;
    IF v_plan <> NEW.plan_id THEN
      RAISE EXCEPTION 'a sub-goal must belong to the same plan as its parent'
        USING ERRCODE='check_violation';
    END IF;
    cur := NEW.parent_goal_id;
    WHILE cur IS NOT NULL AND hops < 20 LOOP
      IF cur = NEW.id THEN
        RAISE EXCEPTION 'goal hierarchy would form a cycle' USING ERRCODE='check_violation';
      END IF;
      SELECT parent_goal_id INTO cur FROM public.mkt_goals WHERE id = cur;
      hops := hops + 1;
    END LOOP;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_goal_refresh_actual()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.mkt_goals
     SET actual_value = (public.mkt_goal_actual(NEW.goal_id) ->> 'value')::numeric,
         updated_at = now()
   WHERE id = NEW.goal_id;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_history_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP='UPDATE' THEN
    RAISE EXCEPTION 'mkt_content_status_history is append-only — status history is never rewritten'
      USING ERRCODE='check_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM public.mkt_content_items i WHERE i.id = OLD.content_item_id) THEN
    RAISE EXCEPTION 'status history cannot be deleted while its content item exists (archive the item instead)'
      USING ERRCODE='check_violation';
  END IF;
  RETURN OLD;   -- cascade cleanup
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_initiative_block_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n bigint;
BEGIN
  SELECT
    (SELECT count(*) FROM public.mkt_internal_campaigns WHERE initiative_id = OLD.id)
  + (SELECT count(*) FROM public.mkt_programs           WHERE initiative_id = OLD.id)
  + (SELECT count(*) FROM public.mkt_content_usage      WHERE initiative_id = OLD.id)
  INTO n;
  IF n > 0 THEN
    RAISE EXCEPTION 'MKT:has_dependents' USING ERRCODE = 'check_violation';
  END IF;
  RETURN OLD;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_initiative_goal_valid()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.primary_goal_id IS NOT NULL AND NEW.plan_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.mkt_goals
                    WHERE id = NEW.primary_goal_id AND plan_id = NEW.plan_id) THEN
      RAISE EXCEPTION 'MKT:goal_other_plan' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  NEW.needs_classification := (NEW.plan_id IS NULL OR NEW.primary_goal_id IS NULL);
  NEW.updated_at := now();
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_measurements_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND NOT EXISTS (SELECT 1 FROM public.mkt_goals WHERE id = OLD.goal_id) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION
    'goal measurements are append-only — record a NEW measurement instead of editing (attempted %)', TG_OP
    USING ERRCODE='check_violation';
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_plan_hierarchy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE p record; hops int := 0; cur uuid;
BEGIN
  IF NEW.parent_plan_id IS NOT NULL THEN
    SELECT plan_type, period_start, period_end INTO p
      FROM public.mkt_plans WHERE id = NEW.parent_plan_id;
    IF p IS NULL THEN
      RAISE EXCEPTION 'parent plan does not exist' USING ERRCODE='foreign_key_violation';
    END IF;
    IF public.mkt_plan_rank(NEW.plan_type) >= public.mkt_plan_rank(p.plan_type) THEN
      RAISE EXCEPTION
        'a % plan cannot sit under a % plan — a parent must cover a longer period',
        NEW.plan_type, p.plan_type
        USING ERRCODE='check_violation';
    END IF;
    IF NEW.period_start < p.period_start OR NEW.period_end > p.period_end THEN
      RAISE EXCEPTION 'child plan period (% .. %) must fall inside its parent (% .. %)',
        NEW.period_start, NEW.period_end, p.period_start, p.period_end
        USING ERRCODE='check_violation';
    END IF;
    cur := NEW.parent_plan_id;
    WHILE cur IS NOT NULL AND hops < 20 LOOP
      IF cur = NEW.id THEN
        RAISE EXCEPTION 'plan hierarchy would form a cycle' USING ERRCODE='check_violation';
      END IF;
      SELECT parent_plan_id INTO cur FROM public.mkt_plans WHERE id = cur;
      hops := hops + 1;
    END LOOP;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_plan_needs_approved_strategy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_status text; v_name text; v_ver int;
BEGIN
  IF NEW.status IN ('approved','active')
     AND (TG_OP = 'INSERT' OR NEW.status IS DISTINCT FROM OLD.status
          OR NEW.strategy_version_id IS DISTINCT FROM OLD.strategy_version_id) THEN
    IF NEW.strategy_version_id IS NULL THEN
      RAISE EXCEPTION
        'plan "%" cannot be % without a strategy version — link one first', NEW.name_ar, NEW.status
        USING ERRCODE='check_violation';
    END IF;
    SELECT status, name_ar, version_number INTO v_status, v_name, v_ver
      FROM public.mkt_strategy_versions WHERE id = NEW.strategy_version_id;
    IF v_status IS DISTINCT FROM 'approved' THEN
      RAISE EXCEPTION
        'plan "%" cannot be % — its strategy version (% v%) is %, not approved',
        NEW.name_ar, NEW.status, v_name, v_ver, COALESCE(v_status, 'missing')
        USING ERRCODE='check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_plan_strategy_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.strategy_version_id IS NOT NULL THEN
      INSERT INTO public.mkt_plan_strategy_links
        (plan_id, from_strategy_version_id, to_strategy_version_id,
         plan_status_at_change, reason, changed_by_user_id)
      VALUES (NEW.id, NULL, NEW.strategy_version_id, NEW.status, 'created',
              COALESCE(NEW.created_by_user_id, public.wassell_app_user_id(auth.uid())));
    END IF;
  ELSIF NEW.strategy_version_id IS DISTINCT FROM OLD.strategy_version_id THEN
    INSERT INTO public.mkt_plan_strategy_links
      (plan_id, from_strategy_version_id, to_strategy_version_id,
       plan_status_at_change, reason, changed_by_user_id)
    VALUES (NEW.id, OLD.strategy_version_id, NEW.strategy_version_id, NEW.status,
            NULLIF(current_setting('wassell.rebase_reason', true), ''),
            public.wassell_app_user_id(auth.uid()));
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_plan_strategy_links_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RAISE EXCEPTION 'mkt_plan_strategy_links is append-only (attempted %)', TG_OP
    USING ERRCODE='check_violation';
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_platform_campaign_valid()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_class text;
BEGIN
  SELECT campaign_class INTO v_class FROM public.mkt_internal_campaigns WHERE id = NEW.campaign_id;
  IF v_class IS DISTINCT FROM 'paid' THEN
    RAISE EXCEPTION
      'a platform campaign requires a paid parent campaign (campaign_class is %)',
      COALESCE(v_class, 'not set') USING ERRCODE='check_violation';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_program_block_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n bigint;
BEGIN
  SELECT
    (SELECT count(*) FROM public.mkt_internal_campaigns WHERE program_id = OLD.id)
  + (SELECT count(*) FROM public.mkt_content_items      WHERE origin_program_id = OLD.id)
  + (SELECT count(*) FROM public.mkt_content_usage      WHERE program_id = OLD.id)
  INTO n;
  IF n > 0 THEN
    RAISE EXCEPTION 'MKT:has_dependents' USING ERRCODE = 'check_violation';
  END IF;
  RETURN OLD;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_program_portfolio_valid()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_init_plan uuid;
BEGIN
  IF NEW.initiative_id IS NOT NULL THEN
    SELECT plan_id INTO v_init_plan FROM public.mkt_initiatives WHERE id = NEW.initiative_id;
    IF NEW.plan_id IS NOT NULL AND v_init_plan IS NOT NULL AND v_init_plan <> NEW.plan_id THEN
      RAISE EXCEPTION 'MKT:initiative_other_plan' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.plan_id IS NULL THEN NEW.plan_id := v_init_plan; END IF;
  END IF;
  IF NEW.primary_goal_id IS NOT NULL AND NEW.plan_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.mkt_goals
                    WHERE id = NEW.primary_goal_id AND plan_id = NEW.plan_id) THEN
      RAISE EXCEPTION 'MKT:goal_other_plan' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  NEW.needs_classification := (NEW.plan_id IS NULL OR NEW.primary_goal_id IS NULL);
  NEW.updated_at := now();
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_publication_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE blockers text[];
BEGIN
  IF NEW.status NOT IN ('scheduled','publishing','published') THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.status = NEW.status THEN RETURN NEW; END IF;

  IF NEW.deliverable_id IS NULL THEN
    RAISE EXCEPTION 'a publication must belong to a deliverable before it can be scheduled'
      USING ERRCODE='check_violation';
  END IF;

  blockers := public.mkt_deliverable_schedule_blockers(NEW.deliverable_id);
  IF array_length(blockers, 1) > 0 THEN
    RAISE EXCEPTION 'cannot schedule this deliverable yet — missing: %',
      array_to_string(blockers, ', ') USING ERRCODE='check_violation';
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_publication_lock_versions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.deliverable_id IS NOT NULL AND NEW.status IN ('scheduled','publishing','published') THEN
    NEW.locked_copy_version_id := COALESCE(NEW.locked_copy_version_id,
      public.mkt_approved_artifact(NEW.deliverable_id, 'caption'));
    NEW.locked_media_version_id := COALESCE(NEW.locked_media_version_id,
      public.mkt_approved_artifact(NEW.deliverable_id, 'final_media'),
      public.mkt_approved_artifact(NEW.deliverable_id, 'design_file'));
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_review_decision_apply()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.decision IN ('continue','change','scale','pause','stop') THEN
    IF NEW.initiative_id IS NOT NULL THEN
      UPDATE public.mkt_initiatives
         SET decision = NEW.decision, decision_note = NEW.rationale, decided_at = now()
       WHERE id = NEW.initiative_id;
    ELSIF NEW.program_id IS NOT NULL THEN
      UPDATE public.mkt_programs
         SET decision = NEW.decision, decision_note = NEW.rationale, decided_at = now()
       WHERE id = NEW.program_id;
    ELSIF NEW.campaign_id IS NOT NULL THEN
      UPDATE public.mkt_internal_campaigns
         SET decision = NEW.decision, decision_note = NEW.rationale, decided_at = now()
       WHERE id = NEW.campaign_id;
    END IF;
  END IF;
  IF NEW.goal_id IS NOT NULL AND NEW.goal_forecast_after IS NOT NULL THEN
    UPDATE public.mkt_goals SET forecast_value = NEW.goal_forecast_after, updated_at = now()
     WHERE id = NEW.goal_id;
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_saved_view_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at := now();
  IF NEW.is_default THEN
    UPDATE public.mkt_content_saved_views
       SET is_default = false
     WHERE owner_user_id = NEW.owner_user_id AND id <> NEW.id AND is_default;
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_strategy_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.status IN ('approved','superseded') THEN
    IF (NEW.status IS DISTINCT FROM OLD.status
        AND NEW.status IN ('superseded','archived'))
       OR (NEW.archived_at IS DISTINCT FROM OLD.archived_at)
       OR (NEW.expires_at IS DISTINCT FROM OLD.expires_at) THEN
      NEW.updated_at := now();
      RETURN NEW;
    END IF;
    IF to_jsonb(NEW) - 'updated_at' IS DISTINCT FROM to_jsonb(OLD) - 'updated_at' THEN
      RAISE EXCEPTION
        'strategy version % is % — create a NEW version instead of editing it',
        OLD.version_number, OLD.status USING ERRCODE='check_violation';
    END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_strategy_supersede_valid()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_status text;
BEGIN
  IF NEW.supersedes_version_id IS NOT NULL THEN
    SELECT status INTO v_status FROM public.mkt_strategy_versions WHERE id = NEW.supersedes_version_id;
    IF v_status IS NULL THEN
      RAISE EXCEPTION 'superseded strategy version does not exist' USING ERRCODE='foreign_key_violation';
    END IF;
    IF v_status NOT IN ('approved','superseded') THEN
      RAISE EXCEPTION 'a strategy version can only supersede an approved version (target is %)', v_status
        USING ERRCODE='check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_task_dependency_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_dep text;
BEGIN
  IF NEW.status IN ('in_progress','completed','waiting_review')
     AND NEW.depends_on_task_id IS NOT NULL THEN
    SELECT status INTO v_dep FROM public.mkt_content_tasks WHERE id=NEW.depends_on_task_id;
    IF v_dep IS DISTINCT FROM 'completed' AND v_dep IS DISTINCT FROM 'cancelled' THEN
      RAISE EXCEPTION 'task "%" is blocked by an unfinished dependency (dependency status: %)',
        NEW.title, COALESCE(v_dep,'missing') USING ERRCODE='check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_task_unblock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status IN ('completed','skipped') AND OLD.status IS DISTINCT FROM NEW.status THEN
    UPDATE public.mkt_content_tasks
       SET status = 'not_started', updated_at = now()
     WHERE depends_on_task_id = NEW.id AND status = 'blocked';
  END IF;
  IF NEW.status = 'completed' AND NEW.completed_at IS NULL THEN
    NEW.completed_at := now();
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN NEW.updated_at := now(); RETURN NEW; END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_version_approved()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n int;
BEGIN
  IF NEW.approval_state <> 'approved'
     OR (TG_OP = 'UPDATE' AND OLD.approval_state = 'approved') THEN
    RETURN NULL;
  END IF;

  UPDATE public.mkt_content_versions
     SET approval_state = 'superseded', superseded_by = NEW.id
   WHERE id <> NEW.id
     AND version_type = NEW.version_type
     AND approval_state = 'approved'
     AND ((NEW.deliverable_id IS NOT NULL AND deliverable_id = NEW.deliverable_id)
       OR (NEW.deliverable_id IS NULL AND deliverable_id IS NULL
           AND content_item_id = NEW.content_item_id));

  UPDATE public.mkt_content_versions
     SET is_stale = true,
         stale_since = COALESCE(stale_since, now()),
         stale_reason = COALESCE(stale_reason,
           format('upstream %s was replaced by v%s', NEW.version_type, NEW.version_number))
   WHERE parent_version_id IN (
           SELECT id FROM public.mkt_content_versions
            WHERE version_type = NEW.version_type AND id <> NEW.id
              AND ((NEW.deliverable_id IS NOT NULL AND deliverable_id = NEW.deliverable_id)
                OR (NEW.deliverable_id IS NULL AND deliverable_id IS NULL
                    AND content_item_id = NEW.content_item_id)))
     AND approval_state = 'approved' AND NOT is_stale;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN
    RAISE NOTICE '% downstream artifact(s) marked stale by % v%', n, NEW.version_type, NEW.version_number;
  END IF;

  RETURN NULL;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_version_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.approval_state = 'approved' THEN
    IF NEW.payload IS DISTINCT FROM OLD.payload
       OR NEW.file_id IS DISTINCT FROM OLD.file_id
       OR NEW.version_type IS DISTINCT FROM OLD.version_type
       OR NEW.version_number IS DISTINCT FROM OLD.version_number
       OR NEW.content_item_id IS DISTINCT FROM OLD.content_item_id
       OR NEW.deliverable_id IS DISTINCT FROM OLD.deliverable_id THEN
      RAISE EXCEPTION
        'artifact % v% is approved and cannot be edited — create a new version instead',
        OLD.version_type, OLD.version_number USING ERRCODE='check_violation';
    END IF;
    IF NEW.approval_state NOT IN ('approved','superseded') THEN
      RAISE EXCEPTION
        'artifact % v% is approved — supersede it with a new version rather than reverting its state',
        OLD.version_type, OLD.version_number USING ERRCODE='check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_tg_version_no_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.is_locked
     AND EXISTS (SELECT 1 FROM public.mkt_content_items i WHERE i.id = OLD.content_item_id) THEN
    RAISE EXCEPTION 'approved/published version % (%) cannot be deleted — supersede it instead',
      OLD.version_number, OLD.version_type USING ERRCODE='check_violation';
  END IF;
  RETURN OLD;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN NEW.updated_at := now(); RETURN NEW; END; $function$;
CREATE OR REPLACE FUNCTION public.mkt_transcript_upsert(p_media uuid, p_post uuid, p_provider text, p_model text, p_language text, p_text text, p_segments jsonb, p_duration_ms integer, p_confidence numeric, p_cost numeric, p_status text, p_failure text, p_source_checksum text, p_raw jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  INSERT INTO public.mkt_transcripts(content_media_id,content_post_id,provider,model,language,text,segments,duration_ms,confidence,cost_usd,status,failure_reason,source_checksum,raw)
  VALUES (p_media,p_post,p_provider,p_model,p_language,p_text,COALESCE(p_segments,'[]'::jsonb),p_duration_ms,p_confidence,COALESCE(p_cost,0),COALESCE(p_status,'done'),p_failure,p_source_checksum,p_raw)
  ON CONFLICT (content_media_id,model) DO UPDATE SET
    language=EXCLUDED.language, text=EXCLUDED.text, segments=EXCLUDED.segments, duration_ms=EXCLUDED.duration_ms,
    confidence=EXCLUDED.confidence, cost_usd=EXCLUDED.cost_usd, status=EXCLUDED.status, failure_reason=EXCLUDED.failure_reason,
    source_checksum=EXCLUDED.source_checksum, raw=EXCLUDED.raw, updated_at=now()
  RETURNING id INTO v_id;
  RETURN v_id;
END $function$;
CREATE OR REPLACE FUNCTION public.mkt_url_key(u text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT regexp_replace(split_part(COALESCE(u,''),'?',1),'^https?://[^/]+','');
$function$;
CREATE OR REPLACE FUNCTION public.mkt_v2_reconcile()
 RETURNS TABLE(check_name text, count bigint, detail text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT 'campaigns_total', count(*)::bigint, 'all campaigns preserved'
    FROM public.mkt_internal_campaigns
  UNION ALL SELECT 'content_total', count(*)::bigint, 'all content preserved'
    FROM public.mkt_content_items
  UNION ALL SELECT 'content_without_origin', count(*)::bigint,
                   'must be 0 after backfill'
    FROM public.mkt_content_items WHERE origin_kind IS NULL
  UNION ALL SELECT 'content_origin_mismatch', count(*)::bigint,
                   'campaign_id and origin_campaign_id disagree — mirror trigger failed'
    FROM public.mkt_content_items WHERE campaign_id IS DISTINCT FROM origin_campaign_id
  UNION ALL SELECT 'active_content_missing_context', count(*)::bigint,
                   'approved/scheduled/published content lacking required context'
    FROM public.mkt_content_items
   WHERE status IN ('approved','ready_to_publish','scheduled','published')
     AND array_length(public.mkt_content_missing_context(id), 1) > 0
  UNION ALL SELECT 'broken_publication_links', count(*)::bigint,
                   'publications whose content item is gone'
    FROM public.mkt_publications p
   WHERE p.content_item_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.mkt_content_items c WHERE c.id = p.content_item_id)
  UNION ALL SELECT 'broken_asset_links', count(*)::bigint,
                   'asset links pointing at a missing asset'
    FROM public.mkt_asset_links l
   WHERE NOT EXISTS (SELECT 1 FROM public.mkt_raw_assets a WHERE a.id = l.asset_id)
  UNION ALL SELECT 'broken_attribution_links', count(*)::bigint,
                   'attribution rows with no surviving marketing side'
    FROM public.mkt_lead_attributions a
   WHERE a.campaign_id IS NULL AND a.content_item_id IS NULL
     AND a.publication_id IS NULL AND a.paid_ad_id IS NULL
  UNION ALL SELECT 'duplicate_usage_links', count(*)::bigint,
                   'must be 0 — unique indexes should prevent this'
    FROM (SELECT content_item_id, usage_kind, campaign_id, program_id, initiative_id, publication_id
            FROM public.mkt_content_usage
           GROUP BY 1,2,3,4,5,6 HAVING count(*) > 1) d
  UNION ALL SELECT 'orphan_platform_campaigns', count(*)::bigint,
                   'platform campaigns whose parent is not paid'
    FROM public.mkt_platform_campaigns pc
    JOIN public.mkt_internal_campaigns c ON c.id = pc.campaign_id
   WHERE c.campaign_class IS DISTINCT FROM 'paid'
  UNION ALL SELECT 'campaigns_needing_classification', count(*)::bigint,
                   'legacy campaigns with no plan — expected, not an error'
    FROM public.mkt_internal_campaigns WHERE needs_classification
  UNION ALL SELECT 'content_needing_classification', count(*)::bigint,
                   'legacy content with no plan — expected, not an error'
    FROM public.mkt_content_items WHERE needs_classification
  UNION ALL SELECT 'invalid_plan_parents', count(*)::bigint,
                   'child plan of an equal-or-shorter parent'
    FROM public.mkt_plans c JOIN public.mkt_plans p ON p.id = c.parent_plan_id
   WHERE public.mkt_plan_rank(c.plan_type) > public.mkt_plan_rank(p.plan_type)
  UNION ALL SELECT 'goals_in_wrong_plan', count(*)::bigint,
                   'sub-goal whose parent belongs to another plan'
    FROM public.mkt_goals g JOIN public.mkt_goals p ON p.id = g.parent_goal_id
   WHERE g.plan_id <> p.plan_id;
$function$;
CREATE OR REPLACE FUNCTION public.mkt_visual_text_upsert(p_media uuid, p_post uuid, p_source text, p_frame_ts_ms integer, p_model text, p_text text, p_structured jsonb, p_confidence numeric, p_cost numeric, p_status text, p_failure text, p_raw jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  INSERT INTO public.mkt_visual_text(content_media_id,content_post_id,source,frame_ts_ms,model,text,structured,confidence,cost_usd,status,failure_reason,raw)
  VALUES (p_media,p_post,p_source,p_frame_ts_ms,p_model,p_text,COALESCE(p_structured,'{}'::jsonb),p_confidence,COALESCE(p_cost,0),COALESCE(p_status,'done'),p_failure,p_raw)
  ON CONFLICT (content_media_id,source,frame_ts_ms) DO UPDATE SET
    model=EXCLUDED.model, text=EXCLUDED.text, structured=EXCLUDED.structured, confidence=EXCLUDED.confidence,
    cost_usd=EXCLUDED.cost_usd, status=EXCLUDED.status, failure_reason=EXCLUDED.failure_reason, raw=EXCLUDED.raw
  RETURNING id INTO v_id;
  RETURN v_id;
END $function$;
CREATE OR REPLACE FUNCTION public.models_view_sync_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM public.drop_model_view(OLD.name);
    RETURN OLD;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.name IS DISTINCT FROM NEW.name THEN
    PERFORM public.drop_model_view(OLD.name);
  END IF;
  PERFORM public.regenerate_model_view(NEW.id);
  RETURN NEW;
EXCEPTION WHEN others THEN
  BEGIN
    INSERT INTO public.model_view_sync_failures (model_id, model_name, tg_op, sqlstate, message)
    VALUES (
      COALESCE(NEW.id, OLD.id),
      COALESCE(NEW.name, OLD.name),
      TG_OP,
      SQLSTATE,
      SQLERRM
    );
  EXCEPTION WHEN others THEN
    NULL;
  END;
  RAISE WARNING '[models_view_sync] % on model %: %', TG_OP, COALESCE(NEW.id, OLD.id), SQLERRM;
  RETURN COALESCE(NEW, OLD);
END;
$function$;
CREATE OR REPLACE FUNCTION public.mos_next_ref(p_prefix text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_num integer;
BEGIN
  INSERT INTO public.mos_ref_counters (prefix, next_number) VALUES (p_prefix, 2)
  ON CONFLICT (prefix) DO UPDATE SET next_number = public.mos_ref_counters.next_number + 1
  RETURNING next_number - 1 INTO v_num;
  RETURN p_prefix || lpad(v_num::text, 3, '0');
END $function$;
CREATE OR REPLACE FUNCTION public.mos_tg_asset_ref()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.ref IS NULL THEN NEW.ref := public.mos_next_ref('A-'); END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mos_tg_assign_ref()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_prefix text;
BEGIN
  IF NEW.ref IS NOT NULL THEN RETURN NEW; END IF;

  SELECT prefix INTO v_prefix FROM public.mos_content_types WHERE id = NEW.content_type_id;
  IF v_prefix IS NULL THEN
    RAISE EXCEPTION 'MOS:UNKNOWN_CONTENT_TYPE' USING ERRCODE = 'check_violation';
  END IF;

  NEW.ref := public.mos_next_ref(v_prefix);
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mos_tg_campaign_ref()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.ref IS NULL THEN NEW.ref := public.mos_next_ref('C-'); END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mos_tg_shoot_ref()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.ref IS NULL THEN NEW.ref := public.mos_next_ref('SH-'); END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.mos_tg_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN NEW.updated_at := now(); RETURN NEW; END $function$;
CREATE OR REPLACE FUNCTION public.our_projects_sync_website()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_is_our boolean;
  v_new text;
  v_old text;
BEGIN
  SELECT (m.name = 'our_projects') INTO v_is_our
  FROM public.models m WHERE m.id = COALESCE(NEW.model_id, OLD.model_id);
  IF NOT COALESCE(v_is_our, false) THEN RETURN NULL; END IF;

  IF TG_OP <> 'DELETE' THEN
    v_new := CASE WHEN jsonb_typeof(NEW.data->'project') = 'array'
                  THEN NEW.data->'project'->>0 ELSE NEW.data->>'project' END;
  END IF;
  IF TG_OP <> 'INSERT' THEN
    v_old := CASE WHEN jsonb_typeof(OLD.data->'project') = 'array'
                  THEN OLD.data->'project'->>0 ELSE OLD.data->>'project' END;
  END IF;

  IF v_new ~ '^[0-9a-fA-F-]{36}$' THEN
    UPDATE public.records SET data = data WHERE id = v_new::uuid;
  END IF;
  IF v_old ~ '^[0-9a-fA-F-]{36}$' AND v_old IS DISTINCT FROM v_new THEN
    UPDATE public.records SET data = data WHERE id = v_old::uuid;
  END IF;
  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.pdf_compress_claim_next(p_worker_id text)
 RETURNS TABLE(job_id uuid, file_id uuid, attempts integer, storage_bucket text, storage_path text, mime_type text, size_bytes bigint, original_name text, folder_id uuid, model_id uuid, record_id uuid, uploaded_by_user_id uuid)
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  WITH claimed AS (
    UPDATE public.pdf_compress_jobs j
       SET status     = 'running',
           worker_id  = p_worker_id,
           started_at = now(),
           attempts   = j.attempts + 1
     WHERE j.id = (
       SELECT id FROM public.pdf_compress_jobs
        WHERE status = 'queued'
        ORDER BY created_at
        FOR UPDATE SKIP LOCKED
        LIMIT 1
     )
     RETURNING j.id, j.file_id, j.attempts
  )
  SELECT c.id, c.file_id, c.attempts,
         f.storage_bucket, f.storage_path, f.mime_type, f.size_bytes, f.original_name,
         f.folder_id, f.model_id, f.record_id, f.uploaded_by_user_id
    FROM claimed c
    JOIN public.files f ON f.id = c.file_id;
$function$;
CREATE OR REPLACE FUNCTION public.pdf_compress_complete(p_job_id uuid, p_result_file_id uuid, p_original_bytes bigint, p_compressed_bytes bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_file uuid;
BEGIN
  UPDATE public.pdf_compress_jobs
     SET status = 'completed',
         finished_at = now(),
         error = NULL,
         result_file_id = p_result_file_id,
         original_bytes = p_original_bytes,
         compressed_bytes = p_compressed_bytes
   WHERE id = p_job_id AND status = 'running'
  RETURNING file_id INTO v_file;
  RETURN v_file IS NOT NULL;
END $function$;
CREATE OR REPLACE FUNCTION public.pdf_compress_enqueue(p_file_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  PERFORM 1 FROM public.files WHERE id = p_file_id FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;

  INSERT INTO public.pdf_compress_jobs (file_id)
  VALUES (p_file_id)
  ON CONFLICT (file_id) WHERE status IN ('queued','running') DO NOTHING;

  RETURN 'pending';
END $function$;
CREATE OR REPLACE FUNCTION public.pdf_compress_fail(p_job_id uuid, p_error text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_file uuid;
BEGIN
  UPDATE public.pdf_compress_jobs
     SET status = 'failed', finished_at = now(), error = p_error
   WHERE id = p_job_id AND status = 'running'
  RETURNING file_id INTO v_file;
  RETURN v_file IS NOT NULL;
END $function$;
CREATE OR REPLACE FUNCTION public.pdf_compress_requeue(p_job_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_file uuid;
BEGIN
  UPDATE public.pdf_compress_jobs
     SET status = 'queued', worker_id = NULL, started_at = NULL
   WHERE id = p_job_id AND status = 'running'
  RETURNING file_id INTO v_file;
  RETURN v_file IS NOT NULL;
END $function$;
CREATE OR REPLACE FUNCTION public.pdf_compress_watchdog()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_count int := 0;
BEGIN
  WITH stale AS (
    UPDATE public.pdf_compress_jobs
       SET status = 'failed',
           finished_at = now(),
           error = 'watchdog: compression did not finish within 15 minutes — likely crashed mid-run.'
     WHERE status = 'running'
       AND started_at < now() - interval '15 minutes'
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_count FROM stale;
  RETURN v_count;
END $function$;
CREATE OR REPLACE FUNCTION public.phone_normalize(p_raw text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_trimmed text;
  v_has_plus boolean;
  v_digits text;
BEGIN
  IF p_raw IS NULL THEN RETURN NULL; END IF;
  v_trimmed := btrim(p_raw);
  IF v_trimmed = '' THEN RETURN NULL; END IF;
  v_has_plus := starts_with(v_trimmed, '+');
  v_digits := regexp_replace(v_trimmed, '\D', '', 'g');
  IF length(v_digits) < 7 THEN RETURN NULL; END IF;

  IF v_has_plus THEN
    RETURN '+' || public.phone_strip_trunk_zero(v_digits);
  END IF;
  IF starts_with(v_digits, '00') THEN
    RETURN '+' || public.phone_strip_trunk_zero(substring(v_digits FROM 3));
  END IF;
  IF starts_with(v_digits, '0') THEN
    RETURN '+966' || substring(v_digits FROM 2);
  END IF;
  IF starts_with(v_digits, '966') THEN
    RETURN '+' || public.phone_strip_trunk_zero(v_digits);
  END IF;
  RETURN '+966' || v_digits;
END;
$function$;
CREATE OR REPLACE FUNCTION public.phone_strip_trunk_zero(p_digits text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  cc text;
BEGIN
  -- Longest-prefix wins. Saudi (3) checked before US/Canada (1).
  FOR cc IN
    SELECT v FROM (VALUES
      ('966'), ('971'), ('965'), ('973'), ('974'), ('968'), ('967'),
      ('962'), ('961'), ('963'), ('964'), ('212'),
      ('20'), ('90'), ('92'), ('91'), ('44'), ('33'), ('49'),
      ('1')
    ) AS t(v) ORDER BY length(v) DESC
  LOOP
    IF starts_with(p_digits, cc || '0') THEN
      RETURN cc || substring(p_digits FROM length(cc) + 2);
    END IF;
  END LOOP;
  RETURN p_digits;
END;
$function$;
CREATE OR REPLACE FUNCTION public.preserve_market_listing_enrichment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE k text;
BEGIN
  -- Fields NO scraper run produces: they come from the one-off bulkFetch
  -- enrichment, the REGA lookup worker, or the user. A writer that replaces the
  -- whole `data` blob must not be able to drop them.
  FOREACH k IN ARRAY ARRAY[
    'deed_number','ad_license_number','ad_license_url','scraped_extras',
    'property_split','advertiser','advertiser_phone',
    'rega_lookup_status','rega_lookup_at','rega_lookup_error',
    'rega_license_no','rega_agent_name','rega_fal_license','rega_unified_number'
  ] LOOP
    IF (OLD.data ? k) AND NOT (NEW.data ? k) THEN
      NEW.data := NEW.data || jsonb_build_object(k, OLD.data -> k);
    END IF;
  END LOOP;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.project_geo_integrity_summary()
 RETURNS TABLE(geo_status text, geo_confidence text, n bigint)
 LANGUAGE sql
 STABLE
AS $function$
  select geo_status, geo_confidence, count(*)::bigint as n
  from public.v_all_projects_geo_integrity
  group by geo_status, geo_confidence
  order by n desc
$function$;
CREATE OR REPLACE FUNCTION public.prune_webhook_payloads(p_keep_days integer DEFAULT 90)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_deleted int;
BEGIN
  IF NOT public.wassell_is_admin((SELECT auth.uid())) THEN
    RAISE EXCEPTION 'prune_webhook_payloads: admin only';
  END IF;
  DELETE FROM public.webhook_payloads
   WHERE received_at < now() - (p_keep_days || ' days')::interval;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$function$;
CREATE OR REPLACE FUNCTION public.push_outbox_claim_next(p_limit integer DEFAULT 10)
 RETURNS SETOF push_outbox
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  UPDATE push_outbox
     SET status = 'running', attempts = attempts + 1, claimed_at = now()
   WHERE id IN (
     SELECT id FROM push_outbox
      WHERE status = 'pending'
      ORDER BY created_at
      FOR UPDATE SKIP LOCKED
      LIMIT p_limit
   )
   RETURNING *;
$function$;
CREATE OR REPLACE FUNCTION public.push_outbox_complete(p_id uuid, p_delivered integer DEFAULT 0, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  UPDATE push_outbox
     SET status    = CASE WHEN p_delivered > 0 THEN 'sent' ELSE 'no_devices' END,
         delivered = p_delivered,
         note      = p_note,
         sent_at   = now()
   WHERE id = p_id AND status = 'running';
$function$;
CREATE OR REPLACE FUNCTION public.push_outbox_expire_stale()
 RETURNS integer
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH expired AS (
    UPDATE push_outbox
       SET status = 'failed', error = 'expired before delivery'
     WHERE status = 'pending' AND created_at < now() - interval '1 hour'
     RETURNING 1
  )
  SELECT COALESCE(count(*), 0)::integer FROM expired;
$function$;
CREATE OR REPLACE FUNCTION public.push_outbox_fail(p_id uuid, p_error text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  UPDATE push_outbox
     SET status = CASE WHEN attempts >= 5 THEN 'failed' ELSE 'pending' END,
         error = p_error
   WHERE id = p_id AND status = 'running';
$function$;
CREATE OR REPLACE FUNCTION public.push_outbox_watchdog()
 RETURNS integer
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH swept AS (
    UPDATE push_outbox
       SET status = CASE WHEN attempts >= 5 THEN 'failed' ELSE 'pending' END,
           error  = 'watchdog: claimed but never completed'
     WHERE status = 'running' AND claimed_at < now() - interval '5 minutes'
     RETURNING 1
  )
  SELECT COALESCE(count(*), 0)::integer FROM swept;
$function$;
CREATE OR REPLACE FUNCTION public.rebuild_unified_records()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sql       text := 'SELECT id, model_id, data, created_by_user_id, created_at, updated_at, version FROM public.records';
  v_model     record;
  v_view_name text;
  v_locked    boolean;
BEGIN
  v_locked := pg_try_advisory_xact_lock(hashtext('rebuild_unified_records'));
  IF NOT v_locked THEN PERFORM pg_advisory_xact_lock(hashtext('rebuild_unified_records')); END IF;

  FOR v_model IN SELECT name FROM models WHERE is_hardcoded = true ORDER BY name LOOP
    v_view_name := public.freeze_safe_ident(v_model.name) || '_v';
    IF EXISTS (SELECT 1 FROM information_schema.views WHERE table_schema = 'public' AND table_name = v_view_name) THEN
      v_sql := v_sql || format(
        ' UNION ALL SELECT id, model_id, data, created_by_user_id, created_at, updated_at, version FROM public.%I',
        v_view_name);
    END IF;
  END LOOP;

  EXECUTE 'DROP VIEW IF EXISTS public.unified_records';
  EXECUTE 'CREATE VIEW public.unified_records WITH (security_invoker = true) AS ' || v_sql;
  EXECUTE 'GRANT SELECT ON public.unified_records TO authenticated, anon, service_role';
END;
$function$;
CREATE OR REPLACE FUNCTION public.recalc_client_derived_data(p_client_id uuid, p_stage text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_followups uuid := public._sales_followups_model_id();
  v_clients   uuid := public._sales_clients_model_id();
  v_calls     uuid := (SELECT id FROM public.models WHERE name = 'phone_calls' LIMIT 1);
  v_chats     uuid := (SELECT id FROM public.models WHERE name = 'chats' LIMIT 1);
  v_cid  text := p_client_id::text;
  v_stage text := p_stage;
  v_na   record;
  v_next_id text; v_next_type text; v_next_due text;
  v_last timestamptz;
  v_lost_reason text; v_lost_at text;
  v_lifecycle text;
  v_terminal boolean;
  v_lost boolean;
  v_owner text;
BEGIN
  IF v_followups IS NULL OR v_clients IS NULL THEN RETURN '{}'::jsonb; END IF;

  IF v_stage IS NULL THEN
    SELECT data->>'client_stage' INTO v_stage FROM public.records WHERE id = p_client_id;
  END IF;
  v_terminal := v_stage IN ('خاسر', 'غير مؤهل', 'مغلق ناجح');
  v_lost     := v_stage IN ('خاسر', 'غير مؤهل');

  SELECT f.id, f.data->>'scheduled_datetime' AS due, public._followup_next_action_type(f.data) AS nat
  INTO v_na
  FROM public.records f
  WHERE f.model_id = v_followups
    AND public._followup_client_id_of(f.data) = v_cid
    AND COALESCE(NULLIF(f.data->>'followup_status', ''), 'open') IN ('open', 'in_progress')
  ORDER BY public.try_timestamptz(f.data->>'scheduled_datetime') ASC NULLS LAST, f.created_at ASC
  LIMIT 1;
  IF v_na.id IS NOT NULL THEN
    v_next_id := v_na.id::text; v_next_type := v_na.nat; v_next_due := v_na.due;
  END IF;

  SELECT GREATEST(
    (SELECT max(public.try_timestamptz(f.data->>'actual_datetime')) FROM public.records f
       WHERE f.model_id = v_followups AND public._followup_client_id_of(f.data) = v_cid),
    (SELECT max(public.try_timestamptz(c.data->>'call_time')) FROM public.records c
       WHERE v_calls IS NOT NULL AND c.model_id = v_calls AND public._link_client_id_of(c.data) = v_cid),
    (SELECT max(public.try_timestamptz(ch.data->>'last_message_at')) FROM public.records ch
       WHERE v_chats IS NOT NULL AND ch.model_id = v_chats AND public._link_client_id_of(ch.data) = v_cid)
  ) INTO v_last;

  SELECT CASE WHEN jsonb_typeof(f.data->'sales_rep') = 'array'
              THEN nullif(f.data->'sales_rep'->>0, '')
              ELSE nullif(f.data->>'sales_rep', '') END
  INTO v_owner
  FROM public.records f
  WHERE f.model_id = v_followups
    AND public._followup_client_id_of(f.data) = v_cid
    AND (CASE WHEN jsonb_typeof(f.data->'sales_rep') = 'array'
              THEN nullif(f.data->'sales_rep'->>0, '')
              ELSE nullif(f.data->>'sales_rep', '') END) IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.users u
      WHERE u.id::text = (CASE WHEN jsonb_typeof(f.data->'sales_rep') = 'array'
                               THEN nullif(f.data->'sales_rep'->>0, '')
                               ELSE nullif(f.data->>'sales_rep', '') END)
        AND u.is_active = false
    )
  ORDER BY f.created_at DESC, public.try_timestamptz(f.data->>'scheduled_datetime') DESC NULLS LAST
  LIMIT 1;

  IF v_lost THEN
    SELECT f.data->>'lost_reason',
           COALESCE(nullif(f.data->>'actual_datetime',''), to_char(f.created_at, 'YYYY-MM-DD"T"HH24:MI:SS'))
    INTO v_lost_reason, v_lost_at
    FROM public.records f
    WHERE f.model_id = v_followups
      AND public._followup_client_id_of(f.data) = v_cid
      AND nullif(f.data->>'lost_reason','') IS NOT NULL
    ORDER BY public.try_timestamptz(COALESCE(nullif(f.data->>'actual_datetime',''), f.created_at::text)) DESC NULLS LAST,
             f.created_at DESC
    LIMIT 1;

    IF v_lost_at IS NULL THEN
      SELECT f.data->>'actual_datetime' INTO v_lost_at
      FROM public.records f
      WHERE f.model_id = v_followups
        AND public._followup_client_id_of(f.data) = v_cid
        AND nullif(f.data->>'actual_datetime','') IS NOT NULL
      ORDER BY public.try_timestamptz(f.data->>'actual_datetime') DESC
      LIMIT 1;
    END IF;
  END IF;

  IF v_terminal THEN
    v_lifecycle := 'closed';
  ELSIF v_next_id IS NULL THEN
    v_lifecycle := 'no_next_action';
  ELSIF public.try_timestamptz(v_next_due) IS NOT NULL AND public.try_timestamptz(v_next_due) < now() THEN
    v_lifecycle := 'overdue';
  ELSE
    v_lifecycle := 'on_track';
  END IF;

  RETURN jsonb_build_object(
    'next_followup_id',   v_next_id,
    'next_action_type',   v_next_type,
    'next_action_due_at', v_next_due,
    'last_activity_at',   to_jsonb(v_last),
    'lifecycle_health',   v_lifecycle,
    'lost_reason',        v_lost_reason,
    'lost_at',            v_lost_at
  )
  || CASE WHEN v_owner IS NOT NULL
          THEN jsonb_build_object('client_owner', v_owner)
          ELSE '{}'::jsonb END;
END;
$function$;
CREATE OR REPLACE FUNCTION public.recalc_project_rollups_data(p_project_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_units uuid := public._rollups_units_model_id();
  v_proj  uuid := public._rollups_all_projects_model_id();
  v_pid   text := p_project_id::text;
  a       record;
  v_schema jsonb;
  f       jsonb;
  v_patch jsonb := '{}'::jsonb;
  v_ut_field jsonb;
  v_ut_slug  text;
  v_ut_opts  jsonb;
  v_ut_types jsonb;
BEGIN
  IF v_units IS NULL OR v_proj IS NULL THEN
    RETURN '{}'::jsonb;
  END IF;

  SELECT
    count(*)                                                                              AS n,
    count(*) FILTER (WHERE public._rollup_status_is(u.data->>'unit_status','available'))  AS n_avail,
    count(*) FILTER (WHERE public._rollup_status_is(u.data->>'unit_status','sold'))        AS n_sold,
    count(*) FILTER (WHERE public._rollup_status_is(u.data->>'unit_status','reserved'))    AS n_res,
    min(public.try_numeric(u.data->>'total_price'))                                        AS price_min,
    max(public.try_numeric(u.data->>'total_price'))                                        AS price_max,
    min(public.try_numeric(u.data->>'unit_area'))                                          AS area_min,
    max(public.try_numeric(u.data->>'unit_area'))                                          AS area_max,
    min(public.try_numeric(u.data->>'total_price'))
      FILTER (WHERE public._rollup_status_is(u.data->>'unit_status','available'))          AS avail_price_min,
    max(public.try_numeric(u.data->>'total_price'))
      FILTER (WHERE public._rollup_status_is(u.data->>'unit_status','available'))          AS avail_price_max,
    min(public.try_numeric(u.data->>'unit_area'))
      FILTER (WHERE public._rollup_status_is(u.data->>'unit_status','available'))          AS avail_area_min,
    max(public.try_numeric(u.data->>'unit_area'))
      FILTER (WHERE public._rollup_status_is(u.data->>'unit_status','available'))          AS avail_area_max,
    min(public.try_numeric(u.data->>'bedrooms'))                                           AS bed_min,
    max(public.try_numeric(u.data->>'bedrooms'))                                           AS bed_max,
    min(public.try_numeric(u.data->>'bathrooms'))                                          AS bath_min,
    max(public.try_numeric(u.data->>'bathrooms'))                                          AS bath_max,
    min(public.try_numeric(u.data->>'total_price') / nullif(public.try_numeric(u.data->>'unit_area'), 0))
      FILTER (WHERE public.try_numeric(u.data->>'unit_area') > 0
                AND public.try_numeric(u.data->>'total_price') IS NOT NULL)                AS ppm_min,
    max(public.try_numeric(u.data->>'total_price') / nullif(public.try_numeric(u.data->>'unit_area'), 0))
      FILTER (WHERE public.try_numeric(u.data->>'unit_area') > 0
                AND public.try_numeric(u.data->>'total_price') IS NOT NULL)                AS ppm_max,
    avg(public.try_numeric(u.data->>'total_price') / nullif(public.try_numeric(u.data->>'unit_area'), 0))
      FILTER (WHERE public.try_numeric(u.data->>'unit_area') > 0
                AND public.try_numeric(u.data->>'total_price') IS NOT NULL)                AS ppm_avg
  INTO a
  FROM public.records u
  WHERE u.model_id = v_units
    AND (
      u.data->>'project_id' = v_pid
      OR (jsonb_typeof(u.data->'project_id') = 'array' AND u.data->'project_id' ? v_pid)
    );

  SELECT schema INTO v_schema FROM public.models WHERE id = v_proj;

  FOR f IN
    SELECT fld
    FROM jsonb_array_elements(v_schema->'sections') sec,
         jsonb_array_elements(sec->'fields') fld
    WHERE (fld->>'is_rollup')::boolean IS TRUE
       OR (fld->>'is_computed')::boolean IS TRUE
  LOOP
    v_patch := v_patch || jsonb_build_object(
      f->>'name',
      CASE COALESCE(f->>'rollup_kind', f->>'computed_kind')
        WHEN 'units_count'            THEN to_jsonb(COALESCE(a.n, 0))
        WHEN 'units_available_count'  THEN to_jsonb(COALESCE(a.n_avail, 0))
        WHEN 'units_sold_count'       THEN to_jsonb(COALESCE(a.n_sold, 0))
        WHEN 'units_reserved_count'   THEN to_jsonb(COALESCE(a.n_res, 0))
        WHEN 'price_range'            THEN public._rollup_range(a.price_min, a.price_max)
        WHEN 'area_range'             THEN public._rollup_range(a.area_min, a.area_max)
        WHEN 'available_price_range'  THEN public._rollup_range(a.avail_price_min, a.avail_price_max)
        WHEN 'available_area_range'   THEN public._rollup_range(a.avail_area_min, a.avail_area_max)
        WHEN 'bedroom_range'          THEN public._rollup_range(a.bed_min, a.bed_max)
        WHEN 'bathroom_range'         THEN public._rollup_range(a.bath_min, a.bath_max)
        WHEN 'min_price_per_meter'    THEN CASE WHEN a.ppm_min IS NULL THEN 'null'::jsonb ELSE to_jsonb(round(a.ppm_min, 4)) END
        WHEN 'max_price_per_meter'    THEN CASE WHEN a.ppm_max IS NULL THEN 'null'::jsonb ELSE to_jsonb(round(a.ppm_max, 4)) END
        WHEN 'avg_price_per_meter'    THEN CASE WHEN a.ppm_avg IS NULL THEN 'null'::jsonb ELSE to_jsonb(round(a.ppm_avg, 4)) END
        ELSE 'null'::jsonb
      END
    );
  END LOOP;

  IF COALESCE(a.n, 0) > 0 THEN
    SELECT fld INTO v_ut_field
    FROM jsonb_array_elements(v_schema->'sections') sec,
         jsonb_array_elements(sec->'fields') fld
    WHERE (fld->>'auto_from_units')::boolean IS TRUE
    LIMIT 1;

    IF v_ut_field IS NOT NULL THEN
      v_ut_slug := v_ut_field->>'name';
      v_ut_opts := COALESCE(v_ut_field->'options', '[]'::jsonb);

      SELECT COALESCE(jsonb_agg(mapped ORDER BY mapped), '[]'::jsonb)
      INTO v_ut_types
      FROM (
        SELECT DISTINCT COALESCE(
          (SELECT o->>'value'
             FROM jsonb_array_elements(v_ut_opts) o
            WHERE lower(btrim(o->>'value'))    = lower(dr.raw)
               OR lower(btrim(o->>'label_en')) = lower(dr.raw)
               OR lower(btrim(o->>'label_ar')) = lower(dr.raw)
            LIMIT 1),
          dr.raw
        ) AS mapped
        FROM (
          SELECT DISTINCT btrim(u.data->>'unit_type') AS raw
          FROM public.records u
          WHERE u.model_id = v_units
            AND (
              u.data->>'project_id' = v_pid
              OR (jsonb_typeof(u.data->'project_id') = 'array' AND u.data->'project_id' ? v_pid)
            )
            AND btrim(COALESCE(u.data->>'unit_type', '')) <> ''
        ) dr
      ) m;

      v_patch := v_patch || jsonb_build_object(v_ut_slug, v_ut_types);
    END IF;
  END IF;

  RETURN v_patch;
END;
$function$;
CREATE OR REPLACE FUNCTION public.reconcile_inbound_whatsapp(p_client_id uuid, p_message_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_model_id uuid;
  v_msg_at   timestamptz := COALESCE(p_message_at, now());
  v_stage    text;
  v_rep      text;
  v_replied  int := 0;
  v_has_open boolean;
  v_now_iso  text;
BEGIN
  IF p_client_id IS NULL THEN RETURN 0; END IF;

  v_replied := public.mark_whatsapp_replied(p_client_id, v_msg_at);

  SELECT id INTO v_model_id FROM public.models WHERE name = 'followups' LIMIT 1;
  IF v_model_id IS NULL THEN RETURN v_replied; END IF;

  SELECT data->>'client_stage', data->>'client_owner'
    INTO v_stage, v_rep
  FROM public.records WHERE id = p_client_id;
  IF v_stage IN ('خاسر', 'مغلق ناجح', 'غير مؤهل') THEN RETURN v_replied; END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.records r
    WHERE r.model_id = v_model_id
      AND r.data->>'client_id' = p_client_id::text
      AND COALESCE(NULLIF(r.data->>'followup_status', ''), 'open') IN ('open', 'in_progress')
  ) INTO v_has_open;

  IF NOT v_has_open THEN
    v_now_iso := to_char(v_msg_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');
    INSERT INTO public.records (id, model_id, data, created_by_user_id)
    VALUES (gen_random_uuid(), v_model_id,
      jsonb_build_object(
        'client_id',               p_client_id::text,
        'sales_rep',               v_rep,
        'followup_type',           jsonb_build_array('whatsapp_follow_up'),
        'followup_status',         'open',
        'whatsapp_state',          'replied',
        'client_messaged_at',      v_now_iso,
        'whatsapp_attempt_number', 1,
        'followup_number',         1,
        'scheduled_datetime',      v_now_iso,
        'creation_source',         'inbound_whatsapp'),
      NULL);
    v_replied := v_replied + 1;
  END IF;

  RETURN v_replied;
END;
$function$;
CREATE OR REPLACE FUNCTION public.reconcile_outbound_whatsapp(p_client_id uuid, p_message_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_model_id  uuid;
  v_msg_at    timestamptz := COALESCE(p_message_at, now());
  v_stage     text;
  v_rep       text;
  v_wa_id     uuid;
  v_first     text;
  v_attempt   int;
  v_cancelled int := 0;
  v_deadline  text;
  v_now_iso   text;
BEGIN
  IF p_client_id IS NULL THEN RETURN 0; END IF;

  SELECT id INTO v_model_id FROM public.models WHERE name = 'followups' LIMIT 1;
  IF v_model_id IS NULL THEN RETURN 0; END IF;

  SELECT data->>'client_stage', data->>'client_owner'
    INTO v_stage, v_rep
  FROM public.records WHERE id = p_client_id;
  IF v_stage IN ('خاسر', 'مغلق ناجح', 'غير مؤهل') THEN RETURN 0; END IF;

  v_deadline := to_char((v_msg_at + interval '24 hours') AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');
  v_now_iso  := to_char(v_msg_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');

  SELECT r.id,
         NULLIF(r.data->>'first_whatsapp_sent_at', ''),
         COALESCE(NULLIF(r.data->>'whatsapp_attempt_number', '')::int, 1)
    INTO v_wa_id, v_first, v_attempt
  FROM public.records r
  WHERE r.model_id = v_model_id
    AND COALESCE(NULLIF(r.data->>'followup_status', ''), 'open') IN ('open', 'in_progress')
    AND ( (jsonb_typeof(r.data->'followup_type') = 'array'  AND r.data->'followup_type' ? 'whatsapp_follow_up')
       OR (jsonb_typeof(r.data->'followup_type') = 'string' AND r.data->>'followup_type' = 'whatsapp_follow_up') )
    AND r.data->>'client_id' = p_client_id::text
  ORDER BY r.created_at DESC
  LIMIT 1;

  IF v_wa_id IS NOT NULL THEN
    UPDATE public.records
    SET data = (data - 'fired_at' - 'client_messaged_at')
      || jsonb_build_object(
           'whatsapp_state',          'message_sent_waiting_response',
           'followup_status',         'in_progress',
           'sent_at',                 v_now_iso,
           'first_whatsapp_sent_at',  COALESCE(v_first, v_now_iso),
           'whatsapp_attempt_number', v_attempt,
           'scheduled_datetime',      v_deadline,
           'source_followup_id',      v_wa_id::text)
    WHERE id = v_wa_id;
  ELSE
    v_wa_id := gen_random_uuid();
    INSERT INTO public.records (id, model_id, data, created_by_user_id)
    VALUES (v_wa_id, v_model_id,
      jsonb_build_object(
        'client_id',               p_client_id::text,
        'sales_rep',               v_rep,
        'followup_type',           jsonb_build_array('whatsapp_follow_up'),
        'followup_status',         'in_progress',
        'whatsapp_state',          'message_sent_waiting_response',
        'sent_at',                 v_now_iso,
        'first_whatsapp_sent_at',  v_now_iso,
        'whatsapp_attempt_number', 1,
        'followup_number',         1,
        'scheduled_datetime',      v_deadline,
        'source_followup_id',      v_wa_id::text,
        'creation_source',         'outbound_whatsapp'),
      NULL);
  END IF;

  UPDATE public.records r
  SET data = (r.data - 'whatsapp_state')
    || jsonb_build_object(
         'followup_status',     'cancelled',
         'cancel_reason',       CASE
             WHEN (jsonb_typeof(r.data->'followup_type') = 'array' AND r.data->'followup_type' ? 'whatsapp_follow_up')
               OR r.data->>'followup_type' = 'whatsapp_follow_up'
             THEN 'superseded_by_newer_whatsapp_task'
             ELSE 'contacted_via_whatsapp' END,
         'cancelled_at',        v_now_iso,
         'cancelled_by_system', true)
  WHERE r.model_id = v_model_id
    AND r.id <> v_wa_id
    AND r.data->>'client_id' = p_client_id::text
    AND COALESCE(NULLIF(r.data->>'followup_status', ''), 'open') IN ('open', 'in_progress')
    AND ( (jsonb_typeof(r.data->'followup_type') = 'array'
             AND r.data->'followup_type' ?| ARRAY['appointment_booking_call','no_show_recovery_call','whatsapp_follow_up'])
       OR (jsonb_typeof(r.data->'followup_type') = 'string'
             AND r.data->>'followup_type' = ANY(ARRAY['appointment_booking_call','no_show_recovery_call','whatsapp_follow_up'])) );
  GET DIAGNOSTICS v_cancelled = ROW_COUNT;

  RETURN v_cancelled + 1;
END;
$function$;
CREATE OR REPLACE FUNCTION public.reconcile_outbound_whatsapp(p_client_id uuid, p_message_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_source text DEFAULT 'composer'::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_model_id  uuid;
  v_msg_at    timestamptz := COALESCE(p_message_at, now());
  v_stage     text;
  v_rep       text;
  v_wa_id     uuid;
  v_first     text;
  v_attempt   int;
  v_cancelled int := 0;
  v_deadline  text;
  v_now_iso   text;
  v_conversational boolean := COALESCE(p_source, 'composer') NOT IN ('bulk', 'document', 'media_batch');
BEGIN
  IF p_client_id IS NULL THEN RETURN 0; END IF;

  SELECT id INTO v_model_id FROM public.models WHERE name = 'followups' LIMIT 1;
  IF v_model_id IS NULL THEN RETURN 0; END IF;

  SELECT data->>'client_stage', data->>'client_owner'
    INTO v_stage, v_rep
  FROM public.records WHERE id = p_client_id;
  IF v_stage IN ('خاسر', 'مغلق ناجح', 'غير مؤهل') THEN RETURN 0; END IF;

  v_deadline := to_char((v_msg_at + interval '24 hours') AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');
  v_now_iso  := to_char(v_msg_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');

  SELECT r.id,
         NULLIF(r.data->>'first_whatsapp_sent_at', ''),
         COALESCE(NULLIF(r.data->>'whatsapp_attempt_number', '')::int, 1)
    INTO v_wa_id, v_first, v_attempt
  FROM public.records r
  WHERE r.model_id = v_model_id
    AND COALESCE(NULLIF(r.data->>'followup_status', ''), 'open') IN ('open', 'in_progress')
    AND ( (jsonb_typeof(r.data->'followup_type') = 'array'  AND r.data->'followup_type' ? 'whatsapp_follow_up')
       OR (jsonb_typeof(r.data->'followup_type') = 'string' AND r.data->>'followup_type' = 'whatsapp_follow_up') )
    AND r.data->>'client_id' = p_client_id::text
  ORDER BY r.created_at DESC
  LIMIT 1;

  IF v_wa_id IS NOT NULL THEN
    UPDATE public.records
    SET data = (data - 'fired_at' - 'client_messaged_at')
      || jsonb_build_object(
           'whatsapp_state',          'message_sent_waiting_response',
           'followup_status',         'in_progress',
           'sent_at',                 v_now_iso,
           'first_whatsapp_sent_at',  COALESCE(v_first, v_now_iso),
           'whatsapp_attempt_number', v_attempt,
           'scheduled_datetime',      v_deadline,
           'source_followup_id',      v_wa_id::text)
    WHERE id = v_wa_id;
  ELSE
    v_wa_id := gen_random_uuid();
    INSERT INTO public.records (id, model_id, data, created_by_user_id)
    VALUES (v_wa_id, v_model_id,
      jsonb_build_object(
        'client_id',               p_client_id::text,
        'sales_rep',               v_rep,
        'followup_type',           jsonb_build_array('whatsapp_follow_up'),
        'followup_status',         'in_progress',
        'whatsapp_state',          'message_sent_waiting_response',
        'sent_at',                 v_now_iso,
        'first_whatsapp_sent_at',  v_now_iso,
        'whatsapp_attempt_number', 1,
        'followup_number',         1,
        'scheduled_datetime',      v_deadline,
        'source_followup_id',      v_wa_id::text,
        'creation_source',         'outbound_whatsapp'),
      NULL);
  END IF;

  -- ONLY a conversational message retires the client's other open work.
  IF NOT v_conversational THEN
    RETURN 1;
  END IF;

  UPDATE public.records r
  SET data = (r.data - 'whatsapp_state')
    || jsonb_build_object(
         'followup_status',     'cancelled',
         'cancel_reason',       CASE
             WHEN (jsonb_typeof(r.data->'followup_type') = 'array' AND r.data->'followup_type' ? 'whatsapp_follow_up')
               OR r.data->>'followup_type' = 'whatsapp_follow_up'
             THEN 'superseded_by_newer_whatsapp_task'
             ELSE 'contacted_via_whatsapp' END,
         'cancelled_at',        v_now_iso,
         'cancelled_by_system', true)
  WHERE r.model_id = v_model_id
    AND r.id <> v_wa_id
    AND r.data->>'client_id' = p_client_id::text
    AND COALESCE(NULLIF(r.data->>'followup_status', ''), 'open') IN ('open', 'in_progress')
    AND ( (jsonb_typeof(r.data->'followup_type') = 'array'
             AND r.data->'followup_type' ?| ARRAY['appointment_booking_call','no_show_recovery_call','whatsapp_follow_up'])
       OR (jsonb_typeof(r.data->'followup_type') = 'string'
             AND r.data->>'followup_type' = ANY(ARRAY['appointment_booking_call','no_show_recovery_call','whatsapp_follow_up'])) );
  GET DIAGNOSTICS v_cancelled = ROW_COUNT;

  RETURN v_cancelled + 1;
END;
$function$;
CREATE OR REPLACE FUNCTION public.reconcile_superseded_followups(p_client_id uuid, p_event_type text, p_event_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_model_id uuid;
  v_types    text[];
  v_all      boolean := false;
  v_count    integer;
BEGIN
  IF p_client_id IS NULL THEN RETURN 0; END IF;
  SELECT id INTO v_model_id FROM models WHERE name = 'followups' LIMIT 1;
  IF v_model_id IS NULL THEN RETURN 0; END IF;

  CASE p_event_type
    WHEN 'appointment_created' THEN
      v_types := ARRAY['appointment_booking_call','whatsapp_follow_up','no_show_recovery_call'];
    WHEN 'visit_created' THEN
      v_types := ARRAY['appointment_booking_call','whatsapp_follow_up','no_show_recovery_call',
                       'appointment_confirmation_call','same_day_appointment_confirmation'];
    WHEN 'offer_created' THEN
      v_types := ARRAY['appointment_booking_call','whatsapp_follow_up','no_show_recovery_call',
                       'appointment_confirmation_call','same_day_appointment_confirmation',
                       'follow_up_call_after_visit'];
    WHEN 'reservation_created' THEN
      v_types := ARRAY['appointment_booking_call','whatsapp_follow_up','no_show_recovery_call',
                       'appointment_confirmation_call','same_day_appointment_confirmation',
                       'follow_up_call_after_visit','offer_follow_up'];
    WHEN 'financing_advanced' THEN
      v_types := ARRAY['appointment_booking_call','whatsapp_follow_up','no_show_recovery_call',
                       'appointment_confirmation_call','same_day_appointment_confirmation',
                       'follow_up_call_after_visit','offer_follow_up','reservation_payment_follow_up'];
    WHEN 'transfer_started' THEN
      v_types := ARRAY['appointment_booking_call','whatsapp_follow_up','no_show_recovery_call',
                       'appointment_confirmation_call','same_day_appointment_confirmation',
                       'follow_up_call_after_visit','offer_follow_up','reservation_payment_follow_up',
                       'financing_follow_up'];
    WHEN 'transfer_completed' THEN v_all := true;
    WHEN 'client_closed_won'  THEN v_all := true;
    WHEN 'client_lost'        THEN v_all := true;
    ELSE
      RETURN 0;
  END CASE;

  UPDATE records r
  SET data = (r.data - 'whatsapp_state')
    || jsonb_build_object(
         'followup_status',          'cancelled',
         'cancel_reason',            'superseded_by_' || p_event_type,
         'cancelled_at',             to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
         'cancelled_by_event_type',  p_event_type,
         'cancelled_by_event_id',    COALESCE(p_event_id::text, ''),
         'cancelled_by_system',      true)
  WHERE r.model_id = v_model_id
    AND r.data->>'client_id' = p_client_id::text
    AND COALESCE(NULLIF(r.data->>'followup_status', ''), 'open') IN ('open','in_progress')
    AND (
      v_all
      OR (jsonb_typeof(r.data->'followup_type') = 'array'  AND r.data->'followup_type' ?| v_types)
      OR (jsonb_typeof(r.data->'followup_type') = 'string' AND (r.data->>'followup_type') = ANY(v_types))
    );

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$;
CREATE OR REPLACE FUNCTION public.record_assign_auto_id(p_model_id uuid, p_field_id uuid, p_scope_key text, p_start integer DEFAULT 1)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_value        int;
  v_field_name   text;
  v_max_existing bigint;
BEGIN
  -- M13 (unchanged): gate behind the same model-level 'create' permission
  -- that gates record creation, so a low-privilege user can't inflate
  -- counters for a model they can't create on.
  IF NOT public.wassell_user_has_action((SELECT auth.uid()), p_model_id, 'create') THEN
    RAISE EXCEPTION 'record_assign_auto_id: caller lacks create permission on model %', p_model_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Atomic increment (unchanged): Postgres serializes the row-level op so two
  -- concurrent callers can never read the same value.
  INSERT INTO public.auto_id_counters (model_id, field_id, scope_key, current_value)
  VALUES (p_model_id, p_field_id, COALESCE(p_scope_key, ''), GREATEST(p_start, 1))
  ON CONFLICT (model_id, field_id, scope_key)
  DO UPDATE SET current_value = public.auto_id_counters.current_value + 1,
                updated_at    = now()
  RETURNING current_value INTO v_value;

  -- 2026-06-01 SELF-HEAL. The atomic counter only stops two SIMULTANEOUS
  -- saves from colliding with each other. It does NOT stop the counter from
  -- drifting BELOW ids already in use — which happens whenever a record is
  -- imported, duplicated, or saved with its auto_id pre-filled (those paths
  -- set the value directly and never call this RPC, so the counter never
  -- learns about them). When that gap exists the next "fresh" assignment
  -- re-issues an in-use id (root cause of the duplicate ع218 / م ش… incident).
  --
  -- Fix: for the GLOBAL scope, never return a value at or below the highest
  -- numeric id already present in the model's records. Scoped counters
  -- (auto_id_scope_field_id set) are skipped — re-deriving each row's scope
  -- key in SQL would mean duplicating the client-side slugify, and every
  -- auto_id field in the app today is global scope. Revisit if that changes.
  IF COALESCE(p_scope_key, '') IN ('', '__global__') THEN
    SELECT (f->>'name') INTO v_field_name
    FROM public.models m
    CROSS JOIN LATERAL jsonb_array_elements(m.schema->'sections') s
    CROSS JOIN LATERAL jsonb_array_elements(s->'fields') f
    WHERE m.id = p_model_id AND (f->>'id') = p_field_id::text
    LIMIT 1;

    IF v_field_name IS NOT NULL THEN
      -- Highest numeric id across BOTH storage shapes via the unified view.
      -- Non-numeric / empty values parse to NULL and are ignored. Runs as the
      -- definer so RLS can't hide rows and make us under-count the max.
      SELECT MAX(NULLIF(regexp_replace(ur.data->>v_field_name, '\D', '', 'g'), '')::bigint)
        INTO v_max_existing
      FROM public.unified_records ur
      WHERE ur.model_id = p_model_id;

      IF v_max_existing IS NOT NULL AND v_max_existing >= v_value THEN
        v_value := (v_max_existing + 1)::int;
        UPDATE public.auto_id_counters
           SET current_value = v_value, updated_at = now()
         WHERE model_id = p_model_id
           AND field_id = p_field_id
           AND scope_key = COALESCE(p_scope_key, '');
      END IF;
    END IF;
  END IF;

  RETURN v_value;
END;
$function$;
CREATE OR REPLACE FUNCTION public.record_conflict_report(p_record_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_session   text;
  v_count     int;
  v_scount    int;
  v_model     uuid;
  c_window    interval := interval '15 seconds';
  c_trip      int := 8;
  c_block     interval := interval '5 minutes';
  c_swindow   interval := interval '30 seconds';
  c_strip     int := 25;
  c_sblock    interval := interval '10 minutes';
  v_blocked   boolean := false;
  v_sblocked  boolean := false;
  v_headers   jsonb;
  v_reason    text;
  v_rec_blk   boolean;
  v_sess_blk  boolean;
BEGIN
  BEGIN v_session := coalesce(
      nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'session_id', '?');
  EXCEPTION WHEN others THEN v_session := '?'; END;

  BEGIN
    BEGIN v_headers := nullif(current_setting('request.headers', true), '')::jsonb;
    EXCEPTION WHEN others THEN v_headers := NULL; END;

    v_rec_blk := EXISTS (SELECT 1 FROM public.record_save_blocks b
                          WHERE b.record_id = p_record_id AND b.blocked_until > now());
    v_sess_blk := v_session <> '?' AND EXISTS (SELECT 1 FROM public.session_save_blocks s
                          WHERE s.session_id = v_session AND s.blocked_until > now());
    v_reason := CASE WHEN v_rec_blk OR v_sess_blk THEN 'conflict_storm_blocked'
                     ELSE 'version_mismatch' END;

    INSERT INTO public.conflict_telemetry_buckets AS t (
      bucket_start, service, user_id, session_id, tab_id, build_id, instance,
      record_id, model_id, reject_reason, count, first_seen_at, last_seen_at)
    VALUES (
      to_timestamp(floor(extract(epoch FROM now()) / 10) * 10),
      v_headers->>'x-wassel-service',
      auth.uid(),
      v_session,
      v_headers->>'x-wassel-tab',
      v_headers->>'x-wassel-build',
      v_headers->>'x-wassel-instance',
      p_record_id,
      (SELECT model_id FROM public.records WHERE id = p_record_id),
      v_reason,
      1, now(), now())
    ON CONFLICT (bucket_start, service, session_id, tab_id, record_id, reject_reason)
    DO UPDATE SET
      count        = t.count + 1,
      last_seen_at = now(),
      user_id      = COALESCE(t.user_id, EXCLUDED.user_id),
      build_id     = COALESCE(EXCLUDED.build_id, t.build_id),
      instance     = COALESCE(EXCLUDED.instance, t.instance),
      model_id     = COALESCE(t.model_id, EXCLUDED.model_id);
  EXCEPTION WHEN others THEN
    RAISE WARNING 'record_conflict_report telemetry write failed (non-fatal): % %', SQLSTATE, SQLERRM;
  END;

  INSERT INTO public.record_conflict_counters (record_id, session_id, window_start, count, updated_at)
  VALUES (p_record_id, v_session, now(), 1, now())
  ON CONFLICT (record_id, session_id) DO UPDATE SET
    count = CASE WHEN public.record_conflict_counters.window_start < now() - c_window
                 THEN 1 ELSE public.record_conflict_counters.count + 1 END,
    window_start = CASE WHEN public.record_conflict_counters.window_start < now() - c_window
                       THEN now() ELSE public.record_conflict_counters.window_start END,
    updated_at = now()
  RETURNING count INTO v_count;

  IF v_count >= c_trip THEN
    SELECT model_id INTO v_model FROM public.records WHERE id = p_record_id;
    INSERT INTO public.record_save_blocks (record_id, model_id, blocked_until, reason, created_by)
    VALUES (p_record_id, v_model, now() + c_block,
            format('auto-throttle: %s conflicts/%s from session %s', v_count, c_window, v_session),
            'auto_throttle')
    ON CONFLICT (record_id) DO UPDATE
      SET blocked_until = EXCLUDED.blocked_until, reason = EXCLUDED.reason,
          model_id = COALESCE(public.record_save_blocks.model_id, EXCLUDED.model_id),
          created_at = now(), created_by = 'auto_throttle';
    INSERT INTO public.system_alerts (kind, severity, detail)
    VALUES ('conflict_auto_block', 'warning', jsonb_build_object(
      'record_id', p_record_id, 'model_id', v_model, 'session_id', v_session,
      'count', v_count, 'blocked_for', c_block::text));
    v_blocked := true;
  END IF;

  IF v_session <> '?' THEN
    INSERT INTO public.session_conflict_counters (session_id, window_start, count, updated_at)
    VALUES (v_session, now(), 1, now())
    ON CONFLICT (session_id) DO UPDATE SET
      count = CASE WHEN public.session_conflict_counters.window_start < now() - c_swindow
                   THEN 1 ELSE public.session_conflict_counters.count + 1 END,
      window_start = CASE WHEN public.session_conflict_counters.window_start < now() - c_swindow
                         THEN now() ELSE public.session_conflict_counters.window_start END,
      updated_at = now()
    RETURNING count INTO v_scount;

    IF v_scount >= c_strip THEN
      INSERT INTO public.session_save_blocks (session_id, blocked_until, reason)
      VALUES (v_session, now() + c_sblock,
              format('auto-throttle: %s conflicts/%s across records', v_scount, c_swindow))
      ON CONFLICT (session_id) DO UPDATE
        SET blocked_until = EXCLUDED.blocked_until, reason = EXCLUDED.reason, created_at = now();
      INSERT INTO public.system_alerts (kind, severity, detail)
      VALUES ('conflict_session_block', 'critical', jsonb_build_object(
        'session_id', v_session, 'count', v_scount, 'blocked_for', c_sblock::text));
      v_sblocked := true;
    END IF;
  END IF;

  RETURN jsonb_build_object('count', v_count, 'blocked', v_blocked,
                            'session_count', v_scount, 'session_blocked', v_sblocked);
END;
$function$;
CREATE OR REPLACE FUNCTION public.record_delete(p_model_id uuid, p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_model record;
BEGIN
  SELECT id, name, is_hardcoded INTO v_model FROM models WHERE id = p_model_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'model % not found', p_model_id;
  END IF;

  IF v_model.is_hardcoded THEN
    EXECUTE format(
      'DELETE FROM public.%I WHERE id = $1',
      public.freeze_safe_ident(v_model.name)
    ) USING p_id;
  ELSE
    DELETE FROM records WHERE id = p_id AND model_id = p_model_id;
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.record_reserve_auto_ids(p_model_id uuid, p_field_id uuid, p_scope_key text, p_count integer, p_start bigint DEFAULT 1)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_last bigint;
BEGIN
  IF p_count < 1 THEN
    RAISE EXCEPTION 'record_reserve_auto_ids: p_count must be >= 1 (got %)', p_count;
  END IF;

  INSERT INTO public.auto_id_counters (model_id, field_id, scope_key, current_value)
  VALUES (p_model_id, p_field_id, p_scope_key, p_start + p_count - 1)
  ON CONFLICT (model_id, field_id, scope_key) DO UPDATE
    SET current_value = public.auto_id_counters.current_value + p_count,
        updated_at    = now()
  RETURNING current_value INTO v_last;

  RETURN v_last - p_count + 1;
END;
$function$;
CREATE OR REPLACE FUNCTION public.record_save(p_model_id uuid, p_id uuid, p_data jsonb, p_created_by uuid DEFAULT NULL::uuid, p_expected_version integer DEFAULT NULL::integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_model record; v_table text; v_existing_version int; v_user uuid; v_headers jsonb; v_claims jsonb; v_session text; v_block_mode text;
BEGIN
  BEGIN v_claims := nullif(current_setting('request.jwt.claims', true),'')::jsonb; EXCEPTION WHEN others THEN v_claims := NULL; END;
  v_session := v_claims->>'session_id';
  IF v_session IS NOT NULL THEN
    SELECT s.mode INTO v_block_mode FROM public.session_save_blocks s WHERE s.session_id = v_session AND s.blocked_until > now();
    IF FOUND THEN
      IF v_block_mode = 'noop' THEN RETURN p_id; END IF;
      RAISE EXCEPTION 'conflict_storm_blocked: this session is rate-limited after repeated version conflicts'
        USING ERRCODE='serialization_failure', HINT='reload the page to continue';
    END IF;
  END IF;
  SELECT b.mode INTO v_block_mode FROM public.record_save_blocks b WHERE b.record_id = p_id AND b.blocked_until > now();
  IF FOUND THEN
    IF v_block_mode = 'noop' THEN RETURN p_id; END IF;
    RAISE EXCEPTION 'conflict_storm_blocked: saves to record % are temporarily blocked after a retry storm', p_id
      USING ERRCODE='serialization_failure', HINT='reload the record; the block clears automatically';
  END IF;
  SELECT id, name, is_hardcoded INTO v_model FROM models WHERE id = p_model_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'model % not found', p_model_id; END IF;
  IF v_model.is_hardcoded THEN
    v_table := public.freeze_safe_ident(v_model.name);
    EXECUTE format('INSERT INTO public.%I (id) VALUES ($1) ON CONFLICT (id) DO NOTHING', v_table) USING p_id;
    PERFORM public.freeze_apply_row(p_model_id, p_id, p_data, p_created_by, p_expected_version);
  ELSE
    IF p_expected_version IS NOT NULL THEN
      -- FOR UPDATE (2026-07-18): lock the row BEFORE the version check so
      -- check+write are atomic. Without it, two writers could both pass the
      -- check and the second silently overwrote the first's committed data.
      SELECT version INTO v_existing_version FROM records WHERE id = p_id FOR UPDATE;
      IF FOUND AND v_existing_version <> p_expected_version THEN
        v_user := auth.uid();
        BEGIN v_headers := nullif(current_setting('request.headers', true),'')::jsonb; EXCEPTION WHEN others THEN v_headers := NULL; END;
        RAISE LOG 'record_save_conflict v2 record=% model=% user=% session=% role=% tab=% build=% expected=% current=% ip=% client=% referer=% path=% ua=%',
          p_id, p_model_id, v_user, v_session, v_claims->>'role', v_headers->>'x-wassel-tab', v_headers->>'x-wassel-build',
          p_expected_version, v_existing_version, coalesce(v_headers->>'x-forwarded-for',v_headers->>'x-real-ip',v_headers->>'cf-connecting-ip'),
          v_headers->>'x-client-info', v_headers->>'referer', current_setting('request.path', true), v_headers->>'user-agent';
        RAISE EXCEPTION 'version_mismatch: record was edited by another user (loaded v%, current v%) [record=% model=% user=% session=% role=%]',
          p_expected_version, v_existing_version, p_id, p_model_id, v_user, v_session, v_claims->>'role'
          USING ERRCODE='serialization_failure', HINT='reload the record to see latest changes';
      END IF;
    END IF;
    INSERT INTO records (id, model_id, data, created_by_user_id) VALUES (p_id, p_model_id, p_data, p_created_by)
    ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data,
      created_by_user_id = COALESCE(records.created_by_user_id, EXCLUDED.created_by_user_id), updated_at = now();
  END IF;
  RETURN p_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.record_save_workflow(p_model_id uuid, p_id uuid, p_data jsonb, p_created_by uuid, p_expected_version integer, p_depth integer, p_origin_run uuid, p_parent_job uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id uuid;
BEGIN
  PERFORM set_config('wassell.workflow_depth',      p_depth::text,                  true);
  PERFORM set_config('wassell.workflow_origin_run', COALESCE(p_origin_run::text,''), true);
  PERFORM set_config('wassell.workflow_parent_job', COALESCE(p_parent_job::text,''), true);
  v_id := public.record_save(p_model_id, p_id, p_data, p_created_by, p_expected_version);
  RETURN v_id;
END $function$;
CREATE OR REPLACE FUNCTION public.record_search(p_model_id uuid, p_filters jsonb DEFAULT '{}'::jsonb, p_cursor jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 50, p_search_text text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, model_id uuid, data jsonb, created_by_user_id uuid, created_at timestamp with time zone, updated_at timestamp with time zone, has_more boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_cursor_created_at timestamptz;
  v_cursor_id         uuid;
  v_limit             int;
BEGIN
  IF p_limit IS NOT NULL AND p_limit < 1 THEN
    RAISE EXCEPTION 'record_search: p_limit must be >= 1, got %', p_limit
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  v_limit := LEAST(COALESCE(p_limit, 50), 500);

  IF p_cursor IS NOT NULL THEN
    IF jsonb_typeof(p_cursor) <> 'object'
       OR p_cursor->>'created_at' IS NULL
       OR p_cursor->>'id' IS NULL THEN
      RAISE EXCEPTION 'record_search: malformed cursor — expected {created_at, id}, got %', p_cursor
        USING ERRCODE = 'invalid_parameter_value';
    END IF;
    BEGIN
      v_cursor_created_at := (p_cursor->>'created_at')::timestamptz;
      v_cursor_id         := (p_cursor->>'id')::uuid;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'record_search: cursor parse failed — created_at must be ISO timestamptz, id must be uuid'
        USING ERRCODE = 'invalid_parameter_value';
    END;
  END IF;

  RETURN QUERY
  WITH page AS (
    SELECT u.id, u.model_id, u.data, u.created_by_user_id, u.created_at, u.updated_at
    FROM public.unified_records u
    WHERE u.model_id = p_model_id
      AND (p_filters = '{}'::jsonb OR u.data @> p_filters)
      AND (
        p_search_text IS NULL OR p_search_text = ''
        OR u.data::text ILIKE '%' || p_search_text || '%'
      )
      AND (
        v_cursor_created_at IS NULL
        OR (u.created_at, u.id) < (v_cursor_created_at, v_cursor_id)
      )
    ORDER BY u.created_at DESC, u.id DESC
    LIMIT v_limit + 1
  ),
  counted AS (
    SELECT *, COUNT(*) OVER () AS total FROM page
  )
  SELECT
    c.id,
    c.model_id,
    c.data,
    c.created_by_user_id,
    c.created_at,
    c.updated_at,
    (c.total > v_limit) AS has_more
  FROM counted c
  ORDER BY c.created_at DESC, c.id DESC
  LIMIT v_limit;
END;
$function$;
CREATE OR REPLACE FUNCTION public.record_shared_link_view(p_token text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  link_id uuid;
  fid uuid;
BEGIN
  UPDATE public.shared_links
     SET view_count = view_count + 1,
         last_viewed_at = now()
   WHERE token = p_token
     AND is_active = true
     AND (expires_at IS NULL OR expires_at > now())
  RETURNING id, file_id INTO link_id, fid;
  IF link_id IS NULL THEN RETURN; END IF;
  INSERT INTO public.activity_log
    (category, event_type, summary_ar, summary_en, details, status)
  VALUES (
    'file', 'shared_view',
    'مشاهدة ملف عبر رابط مشاركة',
    'File viewed via share link',
    jsonb_build_object('shared_link_id', link_id, 'file_id', fid, 'token_prefix', left(p_token, 6)),
    'info'
  );
END $function$;
CREATE OR REPLACE FUNCTION public.records_block_frozen_writes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_frozen boolean;
  v_name   text;
BEGIN
  SELECT is_hardcoded, name INTO v_frozen, v_name FROM models WHERE id = NEW.model_id;
  IF v_frozen THEN
    RAISE EXCEPTION 'model "%" is frozen — write via record_save() RPC, not records table directly', v_name
      USING HINT = 'Frozen models live in their own table. The dispatcher RPC handles routing.';
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.records_bulk_save(p_model_id uuid, p_rows jsonb, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_elem     jsonb;
  v_id       uuid;
  v_inserted int   := 0;
  v_errors   jsonb := '[]'::jsonb;
BEGIN
  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'records_bulk_save: p_rows must be a JSON array (got %)',
      COALESCE(jsonb_typeof(p_rows), 'null');
  END IF;

  FOR v_elem IN SELECT jsonb_array_elements(p_rows) LOOP
    BEGIN
      v_id := COALESCE(NULLIF(v_elem->>'id', '')::uuid, gen_random_uuid());
      PERFORM public.record_save(
        p_model_id,
        v_id,
        COALESCE(v_elem->'data', '{}'::jsonb),
        COALESCE(NULLIF(v_elem->>'created_by', '')::uuid, p_created_by),
        NULL
      );
      v_inserted := v_inserted + 1;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors || jsonb_build_object('id', v_elem->>'id', 'error', SQLERRM);
    END;
  END LOOP;

  RETURN jsonb_build_object('inserted', v_inserted, 'errors', v_errors);
END;
$function$;
CREATE OR REPLACE FUNCTION public.records_bump_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF OLD.version = NEW.version THEN
    NEW.version := OLD.version + 1;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.records_enforce_our_projects_public()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF EXISTS (SELECT 1 FROM public.models m WHERE m.id = NEW.model_id AND m.name = 'all_projects') THEN
    NEW.data := jsonb_set(
      COALESCE(NEW.data, '{}'::jsonb),
      '{is_public}',
      to_jsonb(public.wassell_project_in_our_projects(NEW.id))
    );
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.records_enqueue_listing_mirror()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_enabled boolean;
BEGIN
  IF NEW.model_id IS DISTINCT FROM public._listing_mirror_model_id() THEN
    RETURN NULL;
  END IF;

  IF TG_OP = 'UPDATE'
     AND NEW.data->'image_urls' IS NOT DISTINCT FROM OLD.data->'image_urls' THEN
    RETURN NULL;
  END IF;

  SELECT s.is_enabled INTO v_enabled FROM public.listing_mirror_settings s WHERE s.id;
  IF NOT COALESCE(v_enabled, false) THEN
    RETURN NULL;
  END IF;

  PERFORM public.listing_mirror_enqueue(
    NEW.id,
    CASE WHEN TG_OP = 'INSERT' THEN 'scan-insert' ELSE 'scan-update' END);
  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.records_stamp_visit_rating_token()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF (NEW.data->>'rating_token') IS NULL
     AND NEW.model_id = (SELECT id FROM public.models WHERE name='visits' LIMIT 1) THEN
    -- gen_random_uuid() lives in pg_catalog (always resolvable, unlike
    -- pgcrypto's gen_random_bytes which sits in the extensions schema and is
    -- NOT on record_save's restricted search_path).
    NEW.data := NEW.data || jsonb_build_object('rating_token', replace(gen_random_uuid()::text,'-',''));
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.refresh_frozen_model_artifacts(p_model_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_model record;
  v_table text;
BEGIN
  SELECT id, name, is_hardcoded INTO v_model FROM models WHERE id = p_model_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'refresh_frozen_model_artifacts: model % not found', p_model_id;
  END IF;
  IF NOT v_model.is_hardcoded THEN
    RAISE EXCEPTION 'refresh_frozen_model_artifacts: model "%" is not frozen (is_hardcoded=false) — nothing to refresh', v_model.name;
  END IF;
  v_table := public.freeze_safe_ident(v_model.name);

  PERFORM pg_advisory_xact_lock(hashtext('rebuild_unified_records'));

  EXECUTE 'DROP VIEW IF EXISTS public.unified_records';
  PERFORM public.regenerate_frozen_model_artifacts(p_model_id);
  PERFORM public.rebuild_unified_records();

  RETURN jsonb_build_object(
    'model_id',     p_model_id,
    'table_name',   v_table,
    'view_name',    v_table || '_v',
    'refreshed_at', now(),
    'success',      true
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.rega_lookup_job_claim_next(p_worker_id text)
 RETURNS TABLE(job_id uuid, listing_record_id uuid, user_id uuid, attempts integer)
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  UPDATE public.rega_lookup_jobs
     SET status='running', worker_id=p_worker_id, started_at=now(),
         attempts=rega_lookup_jobs.attempts + 1
   WHERE id = (SELECT id FROM public.rega_lookup_jobs WHERE status='queued'
               ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 1)
   RETURNING id, listing_record_id, user_id, attempts;
$function$;
CREATE OR REPLACE FUNCTION public.rega_lookup_job_complete(p_job_id uuid, p_result jsonb DEFAULT NULL::jsonb)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  WITH updated AS (
    UPDATE public.rega_lookup_jobs
       SET status='done', finished_at=now(), result=p_result, error_message=NULL
     WHERE id=p_job_id AND status='running' RETURNING 1)
  SELECT EXISTS (SELECT 1 FROM updated);
$function$;
CREATE OR REPLACE FUNCTION public.rega_lookup_job_enqueue(p_listing_record_id uuid, p_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id uuid;
BEGIN
  INSERT INTO public.rega_lookup_jobs (listing_record_id, user_id)
  VALUES (p_listing_record_id, p_user_id)
  ON CONFLICT (listing_record_id) WHERE status IN ('queued','running') DO NOTHING
  RETURNING id INTO v_id;
  IF v_id IS NULL THEN
    SELECT id INTO v_id FROM public.rega_lookup_jobs
     WHERE listing_record_id = p_listing_record_id AND status IN ('queued','running')
     ORDER BY created_at DESC LIMIT 1;
  END IF;
  RETURN v_id;
END $function$;
CREATE OR REPLACE FUNCTION public.rega_lookup_job_fail(p_job_id uuid, p_error text)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  WITH updated AS (
    UPDATE public.rega_lookup_jobs
       SET status='failed', finished_at=now(), error_message=p_error
     WHERE id=p_job_id AND status='running' RETURNING 1)
  SELECT EXISTS (SELECT 1 FROM updated);
$function$;
CREATE OR REPLACE FUNCTION public.rega_lookup_jobs_watchdog()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_count int := 0;
  v_msg   text := 'تعذّر جلب رقم المعلن — لم يكمل العامل خلال 10 دقائق. حاول مرة أخرى.';
BEGIN
  CREATE TEMP TABLE _stale_rega ON COMMIT DROP AS
    SELECT id, listing_record_id FROM public.rega_lookup_jobs
     WHERE status='running' AND started_at < now() - interval '10 minutes';
  UPDATE public.rega_lookup_jobs j SET status='failed', finished_at=now(), error_message=v_msg
    FROM _stale_rega s WHERE j.id = s.id;
  UPDATE public.records r
     SET data = r.data || jsonb_build_object('rega_lookup_status','failed','rega_lookup_error',v_msg),
         updated_at = now()
    FROM _stale_rega s WHERE r.id = s.listing_record_id
     AND COALESCE(r.data->>'rega_lookup_status','') = 'running';
  SELECT COUNT(*) INTO v_count FROM _stale_rega;
  RETURN v_count;
END $function$;
CREATE OR REPLACE FUNCTION public.rega_upsert_advertiser(p_name text, p_phone text, p_agent text, p_fal text, p_unified text, p_broker_type text, p_created_by uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_model uuid := 'a1b2c3d4-e5f6-4a7b-8c9d-000000000001';
  v_id uuid;
  v_patch jsonb;
  v_creator uuid;
BEGIN
  IF p_phone IS NULL OR p_phone = '' THEN RETURN NULL; END IF;
  -- Resolve a valid public.users.id (accept a users.id OR the caller's auth uid).
  -- NULL when unknown — an auth-uid p_created_by would violate the created_by FK
  -- and silently kill the INSERT (new-advertiser) path.
  SELECT id INTO v_creator FROM public.users WHERE id = p_created_by OR auth_uid = p_created_by LIMIT 1;
  v_patch := jsonb_strip_nulls(jsonb_build_object(
    'name', p_name, 'agent_name', p_agent, 'fal_license', p_fal,
    'unified_number', p_unified, 'broker_type', p_broker_type, 'source', 'rega', 'last_seen', now()));
  SELECT id INTO v_id FROM public.records WHERE model_id = v_model AND data->>'phone' = p_phone LIMIT 1;
  IF v_id IS NOT NULL THEN
    UPDATE public.records SET data = data || v_patch, updated_at = now() WHERE id = v_id; RETURN v_id;
  END IF;
  BEGIN
    v_id := gen_random_uuid();
    INSERT INTO public.records (id, model_id, data, created_by_user_id)
    VALUES (v_id, v_model, v_patch || jsonb_build_object('phone', p_phone, 'first_seen', now()), v_creator);
    RETURN v_id;
  EXCEPTION WHEN unique_violation THEN
    SELECT id INTO v_id FROM public.records WHERE model_id = v_model AND data->>'phone' = p_phone LIMIT 1;
    UPDATE public.records SET data = data || v_patch, updated_at = now() WHERE id = v_id; RETURN v_id;
  END;
END $function$;
CREATE OR REPLACE FUNCTION public.regenerate_all_model_views()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_count integer := 0; v_id uuid;
BEGIN
  FOR v_id IN SELECT id FROM public.models LOOP
    PERFORM public.regenerate_model_view(v_id);
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$function$;
CREATE OR REPLACE FUNCTION public.regenerate_frozen_model_artifacts(p_model_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_model        record;
  v_table        text;
  v_view_name    text;
  v_field        jsonb;
  v_fname        text;
  v_ftype        text;
  v_is_multi     boolean;
  v_view_keys    text := '';
  v_data_json    text := '';
  v_view_data_expr text;
BEGIN
  SELECT * INTO v_model FROM models WHERE id = p_model_id;
  IF NOT FOUND OR NOT v_model.is_hardcoded THEN RETURN; END IF;
  v_table := public.freeze_safe_ident(v_model.name);
  v_view_name := v_table || '_v';

  EXECUTE format('ALTER TABLE public.%I ADD COLUMN IF NOT EXISTS version int NOT NULL DEFAULT 1', v_table);
  EXECUTE format('ALTER TABLE public.%I ADD COLUMN IF NOT EXISTS custom_data jsonb NOT NULL DEFAULT ''{}''::jsonb', v_table);
  EXECUTE format('DROP TRIGGER IF EXISTS bump_version_trigger ON public.%I', v_table);
  EXECUTE format('CREATE TRIGGER bump_version_trigger BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.frozen_bump_version()', v_table);

  FOR v_field IN
    SELECT field FROM jsonb_array_elements(v_model.schema->'sections') AS sec(value),
         LATERAL jsonb_array_elements(sec.value->'fields') AS field
  LOOP
    v_fname := v_field->>'name'; v_ftype := v_field->>'type';
    v_is_multi := COALESCE((v_field->>'is_multi')::boolean, false);
    IF v_fname IS NULL OR v_fname = '' THEN CONTINUE; END IF;
    IF public.freeze_is_virtual(v_ftype) THEN CONTINUE; END IF;
    IF COALESCE(v_field->>'storage','column') = 'overflow' THEN CONTINUE; END IF;
    IF v_view_keys <> '' THEN v_view_keys := v_view_keys || ', '; END IF;

    IF v_ftype = 'range' THEN
      v_view_keys := v_view_keys || format('%L, jsonb_build_object(''min'', t.%I, ''max'', t.%I)', v_fname, v_fname || '_min', v_fname || '_max');
      IF v_data_json <> '' THEN v_data_json := v_data_json || ', '; END IF;
      v_data_json := v_data_json || format('%L, jsonb_build_object(''min'', %I, ''max'', %I)', v_fname, v_fname || '_min', v_fname || '_max');
    ELSIF v_ftype = 'multiselect' THEN
      v_view_keys := v_view_keys || format('%L, COALESCE((SELECT jsonb_agg(value ORDER BY value) FROM public.%I WHERE record_id = t.id), ''[]''::jsonb)', v_fname, v_table || '__' || v_fname);
    ELSIF v_ftype = 'lookup' AND v_is_multi THEN
      v_view_keys := v_view_keys || format('%L, COALESCE((SELECT jsonb_agg(target_record_id ORDER BY target_record_id) FROM public.%I WHERE record_id = t.id), ''[]''::jsonb)', v_fname, v_table || '__' || v_fname);
    ELSIF v_ftype = 'table' THEN
      v_view_keys := v_view_keys || format('%L, COALESCE((SELECT jsonb_agg(to_jsonb(s) - ''id'' - ''record_id'' - ''row_index'' ORDER BY row_index) FROM public.%I s WHERE record_id = t.id), ''[]''::jsonb)', v_fname, v_table || '__' || v_fname);
    ELSE
      v_view_keys := v_view_keys || format('%L, t.%I', v_fname, v_fname);
      IF v_data_json <> '' THEN v_data_json := v_data_json || ', '; END IF;
      v_data_json := v_data_json || format('%L, %I::text', v_fname, v_fname);
    END IF;
  END LOOP;

  IF v_view_keys = '' THEN
    v_view_data_expr := 'COALESCE(t.custom_data, ''{}''::jsonb)';
  ELSE
    v_view_data_expr := '(jsonb_strip_nulls(jsonb_build_object(' || v_view_keys || ')) || COALESCE(t.custom_data, ''{}''::jsonb))';
  END IF;

  IF v_data_json = '' THEN
    v_data_json := 'COALESCE(custom_data, ''{}''::jsonb)';
  ELSE
    v_data_json := '(jsonb_build_object(' || v_data_json || ') || COALESCE(custom_data, ''{}''::jsonb))';
  END IF;

  EXECUTE format('DROP VIEW IF EXISTS public.%I', v_view_name);
  EXECUTE format(
    'CREATE VIEW public.%I WITH (security_invoker = true) AS SELECT t.id, %L::uuid AS model_id, %s AS data, t.created_by_user_id, t.created_at, t.updated_at, t.version FROM public.%I t',
    v_view_name, p_model_id, v_view_data_expr, v_table);
  EXECUTE format('GRANT SELECT ON public.%I TO authenticated, anon, service_role', v_view_name);

  EXECUTE format('DROP POLICY IF EXISTS "frozen_view"   ON public.%I', v_table);
  EXECUTE format('DROP POLICY IF EXISTS "frozen_insert" ON public.%I', v_table);
  EXECUTE format('DROP POLICY IF EXISTS "frozen_update" ON public.%I', v_table);
  EXECUTE format('DROP POLICY IF EXISTS "frozen_delete" ON public.%I', v_table);

  EXECUTE format(
    $pol$CREATE POLICY "frozen_view" ON public.%I FOR SELECT TO authenticated USING (
      public.wassell_can_view_jsonb((SELECT auth.uid()), %L::uuid, id, created_by_user_id, %s)
    )$pol$, v_table, p_model_id, v_data_json);
  EXECUTE format(
    $pol$CREATE POLICY "frozen_insert" ON public.%I FOR INSERT TO authenticated WITH CHECK (
      public.wassell_user_has_action((SELECT auth.uid()), %L::uuid, 'create')
    )$pol$, v_table, p_model_id);
  EXECUTE format(
    $pol$CREATE POLICY "frozen_update" ON public.%I FOR UPDATE TO authenticated
      USING (public.wassell_can_edit_jsonb((SELECT auth.uid()), %L::uuid, id, created_by_user_id, %s))
      WITH CHECK (public.wassell_can_edit_jsonb((SELECT auth.uid()), %L::uuid, id, created_by_user_id, %s))$pol$,
    v_table, p_model_id, v_data_json, p_model_id, v_data_json);
  EXECUTE format(
    $pol$CREATE POLICY "frozen_delete" ON public.%I FOR DELETE TO authenticated USING (
      public.wassell_can_edit_jsonb((SELECT auth.uid()), %L::uuid, id, created_by_user_id, %s)
      AND public.wassell_user_has_action((SELECT auth.uid()), %L::uuid, 'delete')
    )$pol$, v_table, p_model_id, v_data_json, p_model_id);
END;
$function$;
CREATE OR REPLACE FUNCTION public.regenerate_model_view(p_model_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_model       record;
  v_view_name   text;
  v_field       jsonb;
  v_fname       text;
  v_ftype       text;
  v_parts       text[] := ARRAY['id', 'created_at', 'updated_at', 'model_id'];
  v_sql         text;
BEGIN
  SELECT id, name, schema, is_hardcoded INTO v_model FROM public.models WHERE id = p_model_id;
  IF NOT FOUND THEN RETURN; END IF;
  -- Frozen models have their own <name>_v JSONB-shape view; skip the
  -- legacy records-based v_<name>.
  IF v_model.is_hardcoded THEN RETURN; END IF;
  v_view_name := 'v_' || v_model.name;
  FOR v_field IN
    SELECT field
    FROM jsonb_array_elements(v_model.schema->'sections') AS sec(value),
         LATERAL jsonb_array_elements(sec.value->'fields') AS field
  LOOP
    v_fname := v_field->>'name';
    v_ftype := v_field->>'type';
    IF v_fname IS NULL OR v_fname = '' THEN CONTINUE; END IF;
    IF v_ftype = 'range' THEN
      v_parts := v_parts || format('public.try_numeric(data->%L->>''min'') AS %I', v_fname, v_fname || '_min');
      v_parts := v_parts || format('public.try_numeric(data->%L->>''max'') AS %I', v_fname, v_fname || '_max');
    ELSIF v_ftype IN ('number', 'currency', 'formula') THEN
      v_parts := v_parts || format('public.try_numeric(data->>%L) AS %I', v_fname, v_fname);
    ELSIF v_ftype IN ('date', 'datetime') THEN
      v_parts := v_parts || format('public.try_timestamptz(data->>%L) AS %I', v_fname, v_fname);
    ELSIF v_ftype = 'checkbox' THEN
      v_parts := v_parts || format('public.try_boolean(data->>%L) AS %I', v_fname, v_fname);
    ELSIF v_ftype IN ('multiselect', 'table', 'notes') THEN
      v_parts := v_parts || format('(data->%L) AS %I', v_fname, v_fname);
    ELSE
      v_parts := v_parts || format('(data->>%L) AS %I', v_fname, v_fname);
    END IF;
  END LOOP;
  -- DROP first because CREATE OR REPLACE VIEW only allows ADDING columns
  -- at the end. When a model's schema changes (a field is renamed,
  -- removed, or its type changes the column-list shape), the new view
  -- has a different column list and the replace fails with
  -- `cannot drop columns from view`.
  v_sql := format(
    'DROP VIEW IF EXISTS public.%I; CREATE VIEW public.%I WITH (security_invoker = true) AS SELECT %s FROM public.records WHERE model_id = %L',
    v_view_name, v_view_name, array_to_string(v_parts, ', '), v_model.id
  );
  EXECUTE v_sql;
  EXECUTE format('GRANT SELECT ON public.%I TO authenticated, anon, service_role', v_view_name);
END;
$function$;
CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$;
CREATE OR REPLACE FUNCTION public.sales_process_publish_version(p_version_id uuid)
 RETURNS sales_process_versions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_process UUID; v_row public.sales_process_versions;
BEGIN
  IF NOT public.wassell_is_admin(auth.uid()) THEN RAISE EXCEPTION 'not authorized'; END IF;
  SELECT sales_process_id INTO v_process FROM public.sales_process_versions WHERE id = p_version_id;
  IF v_process IS NULL THEN RAISE EXCEPTION 'version not found'; END IF;
  UPDATE public.sales_process_versions SET status = 'archived', updated_at = now()
   WHERE sales_process_id = v_process AND status = 'active' AND id <> p_version_id;
  UPDATE public.sales_process_versions SET status = 'active', published_at = now(), published_by = auth.uid(), updated_at = now()
   WHERE id = p_version_id RETURNING * INTO v_row;
  UPDATE public.sales_processes SET active_version_id = p_version_id,
         status = CASE WHEN status = 'archived' THEN status ELSE 'active' END, updated_at = now()
   WHERE id = v_process;
  RETURN v_row;
END;
$function$;
CREATE OR REPLACE FUNCTION public.sales_process_set_default(p_process_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.wassell_is_admin(auth.uid()) THEN RAISE EXCEPTION 'not authorized'; END IF;
  UPDATE public.sales_processes SET is_default = false WHERE is_default = true AND id <> p_process_id;
  UPDATE public.sales_processes SET is_default = true, status = 'active', updated_at = now() WHERE id = p_process_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.scheduled_report_claim_due(p_worker_id text, p_limit integer DEFAULT 5)
 RETURNS SETOF scheduled_reports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN QUERY
  UPDATE public.scheduled_reports r
     SET status = 'running', worker_id = p_worker_id, running_since = now(), updated_at = now()
   WHERE r.id IN (
     SELECT id FROM public.scheduled_reports
      WHERE status = 'active' AND next_run_at IS NOT NULL AND next_run_at <= now()
      ORDER BY next_run_at LIMIT p_limit FOR UPDATE SKIP LOCKED
   )
   RETURNING r.*;
END;
$function$;
CREATE OR REPLACE FUNCTION public.scheduled_report_next_run(p_frequency text, p_hour integer, p_dow integer, p_dom integer, p_after timestamp with time zone)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  tz        TEXT := 'Asia/Riyadh';
  local_now TIMESTAMP;
  cand      TIMESTAMP;
  add_days  INT;
BEGIN
  local_now := (p_after AT TIME ZONE tz);
  IF p_frequency = 'weekly' THEN
    cand := date_trunc('day', local_now) + make_interval(hours => COALESCE(p_hour,8));
    add_days := ((COALESCE(p_dow,0) - EXTRACT(DOW FROM local_now)::int) % 7 + 7) % 7;
    cand := cand + make_interval(days => add_days);
    IF cand <= local_now THEN cand := cand + interval '7 days'; END IF;
  ELSIF p_frequency = 'monthly' THEN
    cand := date_trunc('month', local_now) + make_interval(days => COALESCE(p_dom,1) - 1, hours => COALESCE(p_hour,8));
    IF cand <= local_now THEN
      cand := date_trunc('month', local_now + interval '1 month') + make_interval(days => COALESCE(p_dom,1) - 1, hours => COALESCE(p_hour,8));
    END IF;
  ELSE
    cand := date_trunc('day', local_now) + make_interval(hours => COALESCE(p_hour,8));
    IF cand <= local_now THEN cand := cand + interval '1 day'; END IF;
  END IF;
  RETURN (cand AT TIME ZONE tz);
END;
$function$;
CREATE OR REPLACE FUNCTION public.scheduled_reports_fill_next_run()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.next_run_at IS NULL THEN
      NEW.next_run_at := public.scheduled_report_next_run(NEW.frequency, NEW.hour_of_day, NEW.day_of_week, NEW.day_of_month, now());
    END IF;
  ELSE
    -- Recompute when the schedule definition changes, or on resume (→active from
    -- a non-active, non-running state). The running→active transition (the runner
    -- finishing a run) is EXCLUDED so the runner's own next_run_at write stands.
    IF NEW.frequency   IS DISTINCT FROM OLD.frequency
    OR NEW.hour_of_day IS DISTINCT FROM OLD.hour_of_day
    OR NEW.day_of_week IS DISTINCT FROM OLD.day_of_week
    OR NEW.day_of_month IS DISTINCT FROM OLD.day_of_month
    OR (NEW.status = 'active' AND OLD.status NOT IN ('active','running'))
    THEN
      NEW.next_run_at := public.scheduled_report_next_run(NEW.frequency, NEW.hour_of_day, NEW.day_of_week, NEW.day_of_month, now());
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.scheduled_reports_watchdog()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE n INT;
BEGIN
  UPDATE public.scheduled_reports
     SET status = 'active', worker_id = NULL, running_since = NULL, last_status = 'failed',
         error_message = COALESCE(error_message, 'watchdog: run exceeded 10 min and was reset'), updated_at = now()
   WHERE status = 'running' AND running_since < now() - interval '10 minutes';
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END;
$function$;
CREATE OR REPLACE FUNCTION public.scheduled_whatsapp_cancel(p_job_id uuid)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  WITH updated AS (
    UPDATE public.scheduled_whatsapp_jobs
       SET status='cancelled', finished_at=now()
     WHERE id=p_job_id AND status='queued' RETURNING 1)
  SELECT EXISTS (SELECT 1 FROM updated);
$function$;
CREATE OR REPLACE FUNCTION public.scheduled_whatsapp_claim_due(p_worker_id text, p_limit integer DEFAULT 5)
 RETURNS TABLE(job_id uuid, device_id text, chat_wid text, phone text, body text, media jsonb, reference text, attempts integer)
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  UPDATE public.scheduled_whatsapp_jobs
     SET status='running', worker_id=p_worker_id, started_at=now(),
         attempts=scheduled_whatsapp_jobs.attempts+1
   WHERE id IN (
     SELECT j.id FROM public.scheduled_whatsapp_jobs j
      WHERE j.status='queued' AND j.deliver_at <= now()
        AND public.whatsapp_send_budget_remaining(j.device_id) > 0
      ORDER BY j.deliver_at FOR UPDATE SKIP LOCKED
      LIMIT GREATEST(p_limit,1))
   RETURNING id, device_id, chat_wid, phone, body, media, reference, attempts;
$function$;
CREATE OR REPLACE FUNCTION public.scheduled_whatsapp_complete(p_job_id uuid, p_result jsonb DEFAULT NULL::jsonb)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  WITH updated AS (
    UPDATE public.scheduled_whatsapp_jobs
       SET status='sent', finished_at=now(), result=p_result, error_message=NULL
     WHERE id=p_job_id AND status='running' RETURNING 1)
  SELECT EXISTS (SELECT 1 FROM updated);
$function$;
CREATE OR REPLACE FUNCTION public.scheduled_whatsapp_enqueue(p_device_id text, p_chat_wid text, p_phone text, p_body text, p_media jsonb, p_reference text, p_deliver_at timestamp with time zone, p_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id uuid;
BEGIN
  INSERT INTO public.scheduled_whatsapp_jobs
    (device_id, chat_wid, phone, body, media, reference, deliver_at, created_by_user_id)
  VALUES (p_device_id, p_chat_wid, p_phone, p_body, COALESCE(p_media,'[]'::jsonb),
          p_reference, p_deliver_at, p_user_id)
  RETURNING id INTO v_id;
  RETURN v_id;
END $function$;
CREATE OR REPLACE FUNCTION public.scheduled_whatsapp_fail(p_job_id uuid, p_error text)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  WITH updated AS (
    UPDATE public.scheduled_whatsapp_jobs
       SET status='failed', finished_at=now(), error_message=p_error
     WHERE id=p_job_id AND status='running' RETURNING 1)
  SELECT EXISTS (SELECT 1 FROM updated);
$function$;
CREATE OR REPLACE FUNCTION public.scheduled_whatsapp_list_for_chat(p_device_id text, p_chat_wid text)
 RETURNS TABLE(id uuid, phone text, body text, deliver_at timestamp with time zone, created_at timestamp with time zone, has_media boolean)
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  SELECT id, phone, body, deliver_at, created_at,
         (jsonb_array_length(COALESCE(media,'[]'::jsonb)) > 0)
    FROM public.scheduled_whatsapp_jobs
   WHERE device_id=p_device_id AND chat_wid=p_chat_wid AND status='queued'
   ORDER BY deliver_at;
$function$;
CREATE OR REPLACE FUNCTION public.scheduled_whatsapp_requeue(p_job_id uuid, p_error text, p_delay_s integer)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  WITH updated AS (
    UPDATE public.scheduled_whatsapp_jobs
       SET status        = 'queued',
           deliver_at    = now() + make_interval(secs => GREATEST(p_delay_s, 10)),
           error_message = p_error,
           worker_id     = NULL,
           started_at    = NULL
     WHERE id = p_job_id AND status = 'running'
    RETURNING 1
  )
  SELECT EXISTS (SELECT 1 FROM updated);
$function$;
CREATE OR REPLACE FUNCTION public.scheduled_whatsapp_watchdog()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_count int := 0;
BEGIN
  -- 'unknown', not 'failed'. The worker may have handed the message to WhatsApp
  -- and died before recording it, so the only honest statement is that we do
  -- not know. Nothing auto-retries an unknown — resending a message that may
  -- already have arrived is the worse error.
  WITH swept AS (
    UPDATE public.scheduled_whatsapp_jobs
       SET status = 'unknown', finished_at = now(),
           error_message = 'Send worker did not finish within 15 minutes. The message MAY have been delivered — reconcile against the gateway before resending.'
     WHERE status = 'running' AND started_at < now() - interval '15 minutes'
     RETURNING 1)
  SELECT COUNT(*) INTO v_count FROM swept;
  RETURN v_count;
END $function$;
CREATE OR REPLACE FUNCTION public.search_all_projects(p_model_id uuid, p_min_price numeric DEFAULT NULL::numeric, p_max_price numeric DEFAULT NULL::numeric, p_city text DEFAULT NULL::text, p_district text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_unit_type text DEFAULT NULL::text, p_min_size numeric DEFAULT NULL::numeric, p_max_size numeric DEFAULT NULL::numeric, p_text_query text DEFAULT NULL::text, p_limit integer DEFAULT 5)
 RETURNS TABLE(id uuid, data jsonb, score integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT r.id, r.data,
    ( (p_city       IS NULL OR r.data->>'city'           = p_city)::int
    + (p_district   IS NULL OR r.data->>'district'       = p_district)::int
    + (p_status     IS NULL OR r.data->>'project_status' = p_status)::int
    + (p_unit_type  IS NULL OR r.data->>'item_mo4kz61h'  = p_unit_type)::int
    + (p_min_price  IS NULL OR NULLIF(r.data->>'max_price','')::numeric >= p_min_price)::int
    + (p_max_price  IS NULL OR NULLIF(r.data->>'min_price','')::numeric <= p_max_price)::int
    + (p_text_query IS NULL OR r.data::text ILIKE '%'||p_text_query||'%')::int
    ) AS score
  FROM records r
  WHERE r.model_id = p_model_id
    AND (p_city       IS NULL OR r.data->>'city'           = p_city)
    AND (p_district   IS NULL OR r.data->>'district'       = p_district)
    AND (p_status     IS NULL OR r.data->>'project_status' = p_status)
    AND (p_unit_type  IS NULL OR r.data->>'item_mo4kz61h'  = p_unit_type)
    AND (p_max_price  IS NULL OR NULLIF(r.data->>'min_price','')::numeric <= p_max_price)
    AND (p_min_price  IS NULL OR NULLIF(r.data->>'max_price','')::numeric >= p_min_price)
    AND (p_text_query IS NULL OR r.data::text ILIKE '%'||p_text_query||'%')
  ORDER BY score DESC, r.updated_at DESC
  LIMIT p_limit;
$function$;
CREATE OR REPLACE FUNCTION public.set_shared_link_password(p_link_id uuid, p_pw text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF p_pw IS NULL OR length(p_pw) = 0 THEN
    UPDATE public.shared_links SET password_hash = NULL WHERE id = p_link_id;
  ELSE
    UPDATE public.shared_links
       SET password_hash = crypt(p_pw, gen_salt('bf'))
     WHERE id = p_link_id;
  END IF;
END $function$;
CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.slow_query_log(p_threshold_ms numeric DEFAULT 1000, p_limit integer DEFAULT 50)
 RETURNS TABLE(query text, calls bigint, total_ms numeric, mean_ms numeric, max_ms numeric, rows_returned bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.wassell_is_admin((SELECT auth.uid())) THEN
    RAISE EXCEPTION 'admin access required' USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN QUERY
  SELECT
    s.query,
    s.calls,
    round(s.total_exec_time::numeric, 2) AS total_ms,
    round(s.mean_exec_time::numeric, 2)  AS mean_ms,
    round(s.max_exec_time::numeric, 2)   AS max_ms,
    s.rows AS rows_returned
  FROM pg_stat_statements s
  WHERE s.mean_exec_time > p_threshold_ms
  ORDER BY s.total_exec_time DESC
  LIMIT GREATEST(1, LEAST(p_limit, 500));
END;
$function$;
CREATE OR REPLACE FUNCTION public.snapshot_slow_queries(p_threshold_ms numeric DEFAULT 1000)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_id bigint;
  v_rows jsonb;
BEGIN
  IF NOT public.wassell_is_admin((SELECT auth.uid())) THEN
    RAISE EXCEPTION 'admin access required' USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'query', query,
    'calls', calls,
    'total_ms', total_ms,
    'mean_ms', mean_ms,
    'max_ms', max_ms,
    'rows', rows_returned
  )), '[]'::jsonb)
  INTO v_rows
  FROM public.slow_query_log(p_threshold_ms, 100);

  INSERT INTO public.query_perf_snapshot (threshold_ms, rows)
  VALUES (p_threshold_ms, v_rows)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.submit_visit_rating(p_token text, p_rating integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_client text; v_visits uuid;
BEGIN
  IF p_rating IS NULL OR p_rating < 1 OR p_rating > 5 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_rating');
  END IF;
  SELECT id INTO v_visits FROM public.models WHERE name='visits' LIMIT 1;
  SELECT id INTO v_id FROM public.records
   WHERE model_id = v_visits AND NULLIF(data->>'rating_token','') = p_token
   LIMIT 1;
  IF v_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;
  UPDATE public.records
     SET data = data || jsonb_build_object('visit_rating', p_rating, 'rated_at', now()),
         updated_at = now()
   WHERE id = v_id
   RETURNING COALESCE(NULLIF(data->'client_id'->>0,''), NULLIF(data->>'client_id','')) INTO v_client;
  IF v_client IS NOT NULL AND v_client <> '' THEN
    UPDATE public.records
       SET data = data || jsonb_build_object('latest_visit_rating', p_rating, 'latest_visit_rated_at', now()),
           updated_at = now()
     WHERE id = v_client::uuid;
  END IF;
  RETURN jsonb_build_object('ok', true);
END;
$function$;
CREATE OR REPLACE FUNCTION public.svr_backfill_reviews(p_dry_run boolean DEFAULT false, p_include_flags boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE r public.records; n int := 0;
BEGIN
  IF auth.uid() IS NOT NULL
     AND NOT public.wassell_user_has_action(auth.uid(), '5a1e7a10-0000-4000-8000-000000000001'::uuid, 'create') THEN
    RAISE EXCEPTION 'not authorized to backfill sales valuation reviews';
  END IF;

  FOR r IN
    SELECT * FROM public.records
     WHERE model_id = '764e0e67-0ad1-4e21-8ed3-8f32cb0e6e63'
       AND data->>'followup_status' = 'completed'
  LOOP
    IF public.svr_eval_review_for_followup(r, true, p_dry_run, p_include_flags) IS NOT NULL THEN
      n := n + 1;
    END IF;
  END LOOP;
  RETURN n;
END $function$;
CREATE OR REPLACE FUNCTION public.svr_create_correction_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  new_task uuid;
  due      timestamptz;
BEGIN
  IF coalesce((NEW.data->>'requires_correction')::boolean,false) = false THEN RETURN NEW; END IF;
  IF EXISTS (SELECT 1 FROM public.records
              WHERE model_id = '5a1e7a10-0000-4000-8000-000000000003'
                AND data->>'valuation_review' = NEW.id::text) THEN
    RETURN NEW;
  END IF;

  due := coalesce(nullif(NEW.data->>'correction_deadline','')::timestamptz,
                  public.svr_next_business_day(now()));
  new_task := gen_random_uuid();

  INSERT INTO public.records (id, model_id, data, created_by_user_id)
  VALUES (
    new_task, '5a1e7a10-0000-4000-8000-000000000003',
    jsonb_build_object(
      'valuation_review', NEW.id::text,
      'follow_up', NEW.data->>'follow_up',
      'client', NEW.data->>'client',
      'client_name_snapshot', NEW.data->>'client_name_snapshot',
      'sales_rep', NEW.data->>'sales_rep',
      'sales_manager', NEW.data->>'sales_manager',
      'required_action', coalesce(nullif(NEW.data->>'correct_action',''),
                                  nullif(NEW.data->>'coaching_note',''),
                                  'يرجى تصحيح هذه المتابعة'),
      'due_date', due,
      'task_status', 'open',
      'manager_approval', 'pending'
    ),
    NULL
  );

  -- back-link the task onto the review (bounded re-fire; guarded by IS NULL)
  UPDATE public.records
     SET data = jsonb_set(data, '{correction_task}', to_jsonb(new_task::text))
   WHERE id = NEW.id AND nullif(data->>'correction_task','') IS NULL;

  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.svr_create_review_on_followup_complete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF NEW.data->>'followup_status' IS DISTINCT FROM 'completed' THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.data->>'followup_status' = 'completed' THEN RETURN NEW; END IF;
  PERFORM public.svr_eval_review_for_followup(NEW, false, false);
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.svr_eval_review_for_followup(fu records, p_backfill boolean DEFAULT false, p_dry_run boolean DEFAULT false, p_include_flags boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  s jsonb; cr text; ftype text; notes text; client_id text; rep text; cname text;
  sched timestamptz; actual timestamptz; visit_id text;
  flags text[] := ARRAY[]::text[];
  f_weak boolean; f_mismatch boolean; f_unregvisit boolean; f_late boolean; f_missing boolean;
  is_mandatory boolean; is_flagged boolean; is_sample boolean; should_create boolean;
  src text; prio text; v_created timestamptz; new_id uuid;
BEGIN
  SELECT data INTO s FROM public.records WHERE model_id = '5a1e7a10-0000-4000-8000-000000000005' LIMIT 1;
  IF s IS NULL OR coalesce((s->>'is_enabled')::boolean, false) = false THEN RETURN NULL; END IF;

  IF EXISTS (SELECT 1 FROM public.records
              WHERE model_id = '5a1e7a10-0000-4000-8000-000000000001'
                AND data->>'follow_up' = fu.id::text) THEN
    RETURN NULL;
  END IF;

  cr := fu.data->>'call_result';
  ftype := fu.data->'followup_type'->>0;
  notes := fu.data->>'outcome_notes';
  client_id := nullif(fu.data->>'client_id','');
  rep := nullif(fu.data->>'sales_rep','');
  sched := nullif(fu.data->>'scheduled_datetime','')::timestamptz;
  actual := nullif(fu.data->>'actual_datetime','')::timestamptz;
  visit_id := nullif(fu.data->>'visit','');
  IF client_id IS NOT NULL THEN
    SELECT data->>'client_name' INTO cname FROM public.records WHERE id = client_id::uuid;
  END IF;

  f_weak := notes IS NULL OR length(btrim(notes)) < 15;
  f_mismatch := notes IS NOT NULL
    AND notes ~* '(مهتم|يرغب|يريد|طلب|عرض|معلومات|اتصل|زيار|موعد|متابعة)'
    AND cr IN ('not_interested','unanswered_request','invalid_number','no_answer');
  f_unregvisit := ftype = 'follow_up_call_after_visit' AND visit_id IS NULL AND client_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM public.records
                     WHERE model_id = '372ed642-3753-40b4-9dd7-e8390f91b1f8' AND data->>'client_id' = client_id);
  f_late := sched IS NOT NULL AND actual IS NOT NULL AND actual > sched + interval '1 day';
  f_missing := cr IN ('recontact_later','still_interested','needs_financing_info','family_discussion','waiting_decision','requested_another_visit','wrong_time')
    AND client_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM public.records
                     WHERE model_id = '764e0e67-0ad1-4e21-8ed3-8f32cb0e6e63' AND id <> fu.id
                       AND data->>'client_id' = client_id
                       AND data->>'followup_status' IN ('open','scheduled','in_progress')
                       AND coalesce(nullif(data->>'scheduled_datetime','')::timestamptz, now()) > now());

  IF f_missing    THEN flags := array_append(flags, 'missing_next_step'); END IF;
  IF f_weak       THEN flags := array_append(flags, 'weak_notes'); END IF;
  IF f_mismatch   THEN flags := array_append(flags, 'result_mismatch'); END IF;
  IF f_unregvisit THEN flags := array_append(flags, 'unregistered_visit'); END IF;
  IF f_late       THEN flags := array_append(flags, 'late_followup'); END IF;

  is_mandatory :=
       coalesce((s->>'review_all_followups')::boolean,false)
    OR (coalesce((s->>'review_not_interested')::boolean,false) AND cr = 'not_interested')
    OR (coalesce((s->>'review_lost_clients')::boolean,false) AND (cr IN ('not_interested','offer_rejected','appointment_cancelled_lost') OR nullif(fu.data->>'lost_reason','') IS NOT NULL))
    OR (coalesce((s->>'review_offer_requests')::boolean,false) AND cr = 'request_offer')
    OR (coalesce((s->>'review_visits')::boolean,false) AND ftype = 'follow_up_call_after_visit')
    OR (coalesce((s->>'review_missing_next_step')::boolean,false) AND f_missing)
    OR (cr IS NOT NULL AND jsonb_typeof(s->'review_call_results') = 'array' AND (s->'review_call_results') ? cr);
  is_flagged := coalesce(array_length(flags,1),0) > 0;
  is_sample  := (NOT p_backfill) AND (random()*100) < coalesce((s->>'normal_sample_percentage')::numeric, 0);

  IF p_backfill THEN
    should_create := is_mandatory OR (p_include_flags AND is_flagged);
  ELSE
    should_create := is_mandatory OR is_flagged OR is_sample;
  END IF;
  IF NOT should_create THEN RETURN NULL; END IF;

  IF p_dry_run THEN RETURN fu.id; END IF;

  src := CASE WHEN is_mandatory THEN 'mandatory' WHEN is_flagged THEN 'flagged' WHEN is_sample THEN 'sampled' ELSE 'manual' END;
  prio := CASE WHEN cr IN ('not_interested','offer_rejected','appointment_cancelled_lost') OR f_mismatch OR f_unregvisit THEN 'high' ELSE 'normal' END;
  v_created := CASE WHEN p_backfill THEN coalesce(actual, sched, fu.created_at) ELSE now() END;

  INSERT INTO public.records (id, model_id, data, created_by_user_id, created_at)
  VALUES (gen_random_uuid(), '5a1e7a10-0000-4000-8000-000000000001',
    jsonb_build_object(
      'follow_up', fu.id::text, 'client', client_id, 'client_name_snapshot', cname,
      'sales_rep', rep, 'followup_type', ftype, 'follow_up_result', cr,
      'review_status', 'pending_review', 'review_priority', prio, 'review_source', src,
      'review_flags', to_jsonb(flags), 'requires_correction', false, 'dispute_status', 'none'
    ), NULL, v_created)
  RETURNING id INTO new_id;
  RETURN new_id;
END $function$;
CREATE OR REPLACE FUNCTION public.svr_fill_review_computed()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  outcome  text;
  ded      numeric;
  score    numeric;
  status   text;
  dispute  text;
  finaldec text;
BEGIN
  outcome  := nullif(NEW.data->>'review_outcome','');
  status   := nullif(NEW.data->>'review_status','');
  dispute  := nullif(NEW.data->>'dispute_status','');
  finaldec := nullif(NEW.data->>'final_manager_decision','');

  -- score: only when an outcome is set and the manager left the score blank
  IF outcome IS NOT NULL AND nullif(NEW.data->>'overall_score','') IS NULL THEN
    IF nullif(NEW.data->>'mistake_category','') IS NOT NULL THEN
      BEGIN
        SELECT (data->>'score_deduction')::numeric INTO ded FROM public.records
         WHERE id = (NEW.data->>'mistake_category')::uuid
           AND model_id = '5a1e7a10-0000-4000-8000-000000000002';
      EXCEPTION WHEN others THEN ded := NULL; END;
    END IF;
    IF ded IS NOT NULL THEN
      score := greatest(0, 100 - ded);
    ELSE
      score := CASE outcome WHEN 'correct' THEN 100 WHEN 'minor' THEN 85
                            WHEN 'major' THEN 65 WHEN 'critical' THEN 40 ELSE NULL END;
    END IF;
    IF score IS NOT NULL THEN
      NEW.data := jsonb_set(NEW.data, '{overall_score}', to_jsonb(score));
    END IF;
  END IF;

  -- review_date stamp when first evaluated
  IF outcome IS NOT NULL AND nullif(NEW.data->>'review_date','') IS NULL THEN
    NEW.data := jsonb_set(NEW.data, '{review_date}', to_jsonb(now()));
  END IF;

  -- status derivation (precedence: closed > disputed > outcome-derived)
  IF finaldec IS NOT NULL THEN
    NEW.data := jsonb_set(NEW.data, '{review_status}', '"closed"'::jsonb);
    IF nullif(NEW.data->>'closed_at','') IS NULL THEN
      NEW.data := jsonb_set(NEW.data, '{closed_at}', to_jsonb(now()));
    END IF;
    IF dispute = 'disputed' THEN
      NEW.data := jsonb_set(NEW.data, '{dispute_status}',
        to_jsonb(CASE finaldec WHEN 'confirmed' THEN 'rejected'
                               WHEN 'cancelled' THEN 'accepted'
                               ELSE 'adjusted' END));
    END IF;
  ELSIF dispute = 'disputed' THEN
    NEW.data := jsonb_set(NEW.data, '{review_status}', '"disputed_by_rep"'::jsonb);
  ELSIF outcome IS NOT NULL AND (status IS NULL OR status = 'pending_review') THEN
    IF outcome = 'correct' THEN
      NEW.data := jsonb_set(NEW.data, '{review_status}', '"reviewed_no_issue"'::jsonb);
    ELSE
      NEW.data := jsonb_set(NEW.data, '{review_status}',
        to_jsonb(CASE WHEN coalesce((NEW.data->>'requires_correction')::boolean,false)
                      THEN 'requires_correction' ELSE 'issue_flagged' END));
    END IF;
  END IF;

  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.svr_followup_matches_criteria(fu records, p_include_flags boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  s jsonb; cr text; ftype text; notes text; client_id text;
  sched timestamptz; actual timestamptz; visit_id text;
  f_weak boolean; f_mismatch boolean; f_unregvisit boolean; f_late boolean; f_missing boolean;
  is_mandatory boolean; is_flagged boolean;
BEGIN
  IF fu.id IS NULL THEN RETURN false; END IF;
  SELECT data INTO s FROM public.records WHERE model_id = '5a1e7a10-0000-4000-8000-000000000005' LIMIT 1;
  IF s IS NULL THEN RETURN false; END IF;

  cr := fu.data->>'call_result';
  ftype := fu.data->'followup_type'->>0;
  notes := fu.data->>'outcome_notes';
  client_id := nullif(fu.data->>'client_id','');
  sched := nullif(fu.data->>'scheduled_datetime','')::timestamptz;
  actual := nullif(fu.data->>'actual_datetime','')::timestamptz;
  visit_id := nullif(fu.data->>'visit','');

  f_weak := notes IS NULL OR length(btrim(notes)) < 15;
  f_mismatch := notes IS NOT NULL
    AND notes ~* '(مهتم|يرغب|يريد|طلب|عرض|معلومات|اتصل|زيار|موعد|متابعة)'
    AND cr IN ('not_interested','unanswered_request','invalid_number','no_answer');
  f_unregvisit := ftype = 'follow_up_call_after_visit' AND visit_id IS NULL AND client_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM public.records
                     WHERE model_id = '372ed642-3753-40b4-9dd7-e8390f91b1f8' AND data->>'client_id' = client_id);
  f_late := sched IS NOT NULL AND actual IS NOT NULL AND actual > sched + interval '1 day';
  f_missing := cr IN ('recontact_later','still_interested','needs_financing_info','family_discussion','waiting_decision','requested_another_visit','wrong_time')
    AND client_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM public.records
                     WHERE model_id = '764e0e67-0ad1-4e21-8ed3-8f32cb0e6e63' AND id <> fu.id
                       AND data->>'client_id' = client_id
                       AND data->>'followup_status' IN ('open','scheduled','in_progress')
                       AND coalesce(nullif(data->>'scheduled_datetime','')::timestamptz, now()) > now());

  is_mandatory :=
       coalesce((s->>'review_all_followups')::boolean,false)
    OR (coalesce((s->>'review_not_interested')::boolean,false) AND cr = 'not_interested')
    OR (coalesce((s->>'review_lost_clients')::boolean,false) AND (cr IN ('not_interested','offer_rejected','appointment_cancelled_lost') OR nullif(fu.data->>'lost_reason','') IS NOT NULL))
    OR (coalesce((s->>'review_offer_requests')::boolean,false) AND cr = 'request_offer')
    OR (coalesce((s->>'review_visits')::boolean,false) AND ftype = 'follow_up_call_after_visit')
    OR (coalesce((s->>'review_missing_next_step')::boolean,false) AND f_missing)
    OR (cr IS NOT NULL AND jsonb_typeof(s->'review_call_results') = 'array' AND (s->'review_call_results') ? cr);
  is_flagged := f_weak OR f_mismatch OR f_unregvisit OR f_late OR f_missing;

  RETURN is_mandatory OR (p_include_flags AND is_flagged);
END $function$;
CREATE OR REPLACE FUNCTION public.svr_next_business_day(p_from timestamp with time zone)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE v timestamptz;
BEGIN
  v := p_from + interval '1 day';
  IF extract(dow from (v AT TIME ZONE 'Asia/Riyadh')) = 5 THEN v := v + interval '2 days';
  ELSIF extract(dow from (v AT TIME ZONE 'Asia/Riyadh')) = 6 THEN v := v + interval '1 day';
  END IF;
  RETURN v;
END $function$;
CREATE OR REPLACE FUNCTION public.svr_prune_unmatched_reviews(p_dry_run boolean DEFAULT false, p_include_flags boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE rev record; furow public.records; untouched boolean; matches boolean; n int := 0; uid uuid;
BEGIN
  uid := auth.uid();
  IF uid IS NOT NULL
     AND NOT public.wassell_user_has_action(uid, '5a1e7a10-0000-4000-8000-000000000001'::uuid, 'delete') THEN
    RAISE EXCEPTION 'not authorized to prune sales valuation reviews';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.records
                  WHERE model_id='5a1e7a10-0000-4000-8000-000000000005'
                    AND coalesce((data->>'is_enabled')::boolean,false) = true) THEN
    RAISE EXCEPTION 'operation is disabled; enable it before pruning';
  END IF;

  FOR rev IN
    SELECT id, data FROM public.records WHERE model_id = '5a1e7a10-0000-4000-8000-000000000001'
  LOOP
    untouched :=
          nullif(rev.data->>'review_outcome','') IS NULL
      AND nullif(rev.data->>'coaching_note','') IS NULL
      AND coalesce(rev.data->>'review_status','pending_review') = 'pending_review'
      AND coalesce((rev.data->>'requires_correction')::boolean,false) = false
      AND coalesce(nullif(rev.data->>'dispute_status',''),'none') = 'none';
    IF NOT untouched THEN CONTINUE; END IF;

    furow := NULL;
    SELECT * INTO furow FROM public.records
      WHERE id = nullif(rev.data->>'follow_up','')::uuid
        AND model_id = '764e0e67-0ad1-4e21-8ed3-8f32cb0e6e63';

    matches := (furow.id IS NOT NULL) AND public.svr_followup_matches_criteria(furow, p_include_flags);
    IF matches THEN CONTINUE; END IF;

    n := n + 1;
    IF NOT p_dry_run THEN
      INSERT INTO public._backup_sv_pruned_reviews (id, model_id, data, created_by_user_id, created_at, pruned_by)
      SELECT id, model_id, data, created_by_user_id, created_at, uid FROM public.records WHERE id = rev.id;
      DELETE FROM public.records
        WHERE model_id = '5a1e7a10-0000-4000-8000-000000000003' AND data->>'valuation_review' = rev.id::text;
      DELETE FROM public.records WHERE id = rev.id;
    END IF;
  END LOOP;
  RETURN n;
END $function$;
CREATE OR REPLACE FUNCTION public.svr_recompute_daily_summary()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  rec        record;
  rep        text;
  d          date;
  v_total    int;
  v_correct  int;
  v_mistakes int;
  v_avg      numeric;
  v_maincat  text;
  v_opentask int;
  v_mgr      text;
  existing   uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN rec := OLD; ELSE rec := NEW; END IF;
  rep := nullif(rec.data->>'sales_rep','');
  IF rep IS NULL THEN RETURN NULL; END IF;
  d := coalesce(nullif(rec.data->>'review_date','')::timestamptz::date, rec.created_at::date);

  SELECT
    count(*) FILTER (WHERE nullif(data->>'review_outcome','') IS NOT NULL),
    count(*) FILTER (WHERE data->>'review_outcome' = 'correct'),
    count(*) FILTER (WHERE data->>'review_outcome' IN ('minor','major','critical')),
    round(avg((data->>'overall_score')::numeric) FILTER (WHERE nullif(data->>'review_outcome','') IS NOT NULL AND nullif(data->>'overall_score','') IS NOT NULL))
  INTO v_total, v_correct, v_mistakes, v_avg
  FROM public.records
  WHERE model_id = '5a1e7a10-0000-4000-8000-000000000001'
    AND data->>'sales_rep' = rep
    AND coalesce(nullif(data->>'review_date','')::timestamptz::date, created_at::date) = d;

  SELECT data->>'mistake_category' INTO v_maincat
  FROM public.records
  WHERE model_id = '5a1e7a10-0000-4000-8000-000000000001'
    AND data->>'sales_rep' = rep
    AND coalesce(nullif(data->>'review_date','')::timestamptz::date, created_at::date) = d
    AND data->>'review_outcome' IN ('minor','major','critical')
    AND nullif(data->>'mistake_category','') IS NOT NULL
  GROUP BY data->>'mistake_category'
  ORDER BY count(*) DESC LIMIT 1;

  SELECT count(*) INTO v_opentask FROM public.records
  WHERE model_id = '5a1e7a10-0000-4000-8000-000000000003'
    AND data->>'sales_rep' = rep
    AND data->>'task_status' IN ('open','in_progress','overdue');

  SELECT id INTO existing FROM public.records
  WHERE model_id = '5a1e7a10-0000-4000-8000-000000000004'
    AND data->>'sales_rep' = rep AND data->>'valuation_date' = d::text LIMIT 1;

  -- don't spawn an empty draft for days with nothing reviewed yet
  IF existing IS NULL AND coalesce(v_total,0) = 0 THEN
    PERFORM public.svr_sweep_overdue_tasks();
    RETURN NULL;
  END IF;

  IF existing IS NOT NULL THEN
    UPDATE public.records
       SET data = data || jsonb_build_object(
             'total_reviewed', coalesce(v_total,0),
             'correct_follow_ups', coalesce(v_correct,0),
             'mistakes_found', coalesce(v_mistakes,0),
             'average_score', v_avg,
             'main_mistake_category', v_maincat,
             'open_correction_tasks', coalesce(v_opentask,0)
           )
     WHERE id = existing;
  ELSE
    SELECT data->>'default_sales_manager' INTO v_mgr FROM public.records
     WHERE model_id = '5a1e7a10-0000-4000-8000-000000000005' LIMIT 1;
    INSERT INTO public.records (id, model_id, data, created_by_user_id)
    VALUES (
      gen_random_uuid(), '5a1e7a10-0000-4000-8000-000000000004',
      jsonb_build_object(
        'sales_rep', rep,
        'valuation_date', d::text,
        'sales_manager', v_mgr,
        'total_reviewed', coalesce(v_total,0),
        'correct_follow_ups', coalesce(v_correct,0),
        'mistakes_found', coalesce(v_mistakes,0),
        'average_score', v_avg,
        'main_mistake_category', v_maincat,
        'open_correction_tasks', coalesce(v_opentask,0),
        'rep_acknowledged', false,
        'summary_status', 'draft'
      ),
      NULL
    );
  END IF;

  PERFORM public.svr_sweep_overdue_tasks();
  RETURN NULL;
END $function$;
CREATE OR REPLACE FUNCTION public.svr_sweep_overdue_tasks()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE n integer;
BEGIN
  WITH upd AS (
    UPDATE public.records
       SET data = jsonb_set(data, '{task_status}', '"overdue"'::jsonb)
     WHERE model_id = '5a1e7a10-0000-4000-8000-000000000003'
       AND data->>'task_status' IN ('open','in_progress')
       AND nullif(data->>'due_date','') IS NOT NULL
       AND (data->>'due_date')::timestamptz < now()
     RETURNING 1
  ) SELECT count(*) INTO n FROM upd;
  RETURN n;
END $function$;
CREATE OR REPLACE FUNCTION public.tg_records_capture_workflow_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_model    uuid;
  v_event    text;
  v_old      jsonb;
  v_new      jsonb;
  v_changed  text[];
  v_depth    int;
  v_origin   uuid;
  v_parent   uuid;
  v_max      int := 5;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_model := OLD.model_id; v_event := 'delete'; v_old := OLD.data; v_new := NULL;
  ELSIF TG_OP = 'INSERT' THEN
    v_model := NEW.model_id; v_event := 'create'; v_old := NULL; v_new := NEW.data;
  ELSE
    v_model := NEW.model_id; v_event := 'update'; v_old := OLD.data; v_new := NEW.data;
  END IF;

  PERFORM 1 FROM public.workflow_capture_models WHERE model_id = v_model AND enabled = true;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  IF v_event = 'update' AND v_old IS NOT DISTINCT FROM v_new THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(array_agg(k), '{}') INTO v_changed
    FROM (
      SELECT DISTINCT k FROM (
        SELECT jsonb_object_keys(COALESCE(v_old, '{}'::jsonb)) AS k
        UNION
        SELECT jsonb_object_keys(COALESCE(v_new, '{}'::jsonb))
      ) ks
      WHERE (v_old -> k) IS DISTINCT FROM (v_new -> k)
    ) d;

  v_depth  := COALESCE(NULLIF(current_setting('wassell.workflow_depth', true), '')::int, 0);
  v_origin := NULLIF(current_setting('wassell.workflow_origin_run', true), '')::uuid;
  v_parent := NULLIF(current_setting('wassell.workflow_parent_job', true), '')::uuid;

  IF v_depth > v_max THEN
    INSERT INTO public.workflow_jobs
      (model_id, record_id, trigger_event, previous_data, new_data, changed_fields,
       actor_user_id, depth, parent_job_id, origin_run_id, status, skip_reason)
    VALUES
      (v_model, COALESCE(NEW.id, OLD.id), v_event, v_old, v_new, v_changed,
       auth.uid(), v_depth, v_parent, v_origin, 'skipped',
       'max_workflow_depth_exceeded (' || v_depth || ' > ' || v_max || ')');
    RETURN NULL;
  END IF;

  INSERT INTO public.workflow_jobs
    (model_id, record_id, trigger_event, previous_data, new_data, changed_fields,
     actor_user_id, depth, parent_job_id, origin_run_id, idempotency_key)
  VALUES
    (v_model, COALESCE(NEW.id, OLD.id), v_event, v_old, v_new, v_changed,
     auth.uid(), v_depth, v_parent, v_origin,
     md5(COALESCE(NEW.id, OLD.id)::text || ':' || v_event || ':' || v_depth::text || ':' ||
         md5(COALESCE(v_new, v_old, '{}'::jsonb)::text)));

  RETURN NULL;
END $function$;
CREATE OR REPLACE FUNCTION public.tg_records_converge_wa_tasks()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_followups uuid;
  v_client text;
BEGIN
  SELECT id INTO v_followups FROM models WHERE name = 'followups' LIMIT 1;
  IF NEW.model_id IS DISTINCT FROM v_followups THEN RETURN NEW; END IF;

  IF NOT ( (jsonb_typeof(NEW.data->'followup_type') = 'array' AND NEW.data->'followup_type' ? 'whatsapp_follow_up')
        OR NEW.data->>'followup_type' = 'whatsapp_follow_up' ) THEN
    RETURN NEW;
  END IF;

  v_client := NULLIF(NEW.data->>'client_id', '');
  IF v_client IS NULL THEN RETURN NEW; END IF;

  UPDATE records r
  SET data = (r.data - 'whatsapp_state')
    || jsonb_build_object(
         'followup_status',     'cancelled',
         'cancel_reason',       'superseded_by_newer_whatsapp_task',
         'cancelled_at',        to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
         'cancelled_by_system', true)
  WHERE r.model_id = v_followups
    AND r.id <> NEW.id
    AND r.data->>'client_id' = v_client
    AND COALESCE(NULLIF(r.data->>'followup_status', ''), 'open') IN ('open', 'in_progress')
    AND ( (jsonb_typeof(r.data->'followup_type') = 'array' AND r.data->'followup_type' ? 'whatsapp_follow_up')
       OR r.data->>'followup_type' = 'whatsapp_follow_up' );

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.tg_records_dedup_noshow_recovery()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_followups uuid;
  v_appt text;
BEGIN
  SELECT id INTO v_followups FROM models WHERE name = 'followups' LIMIT 1;
  IF NEW.model_id IS DISTINCT FROM v_followups THEN RETURN NEW; END IF;

  IF NOT ( (jsonb_typeof(NEW.data->'followup_type') = 'array' AND NEW.data->'followup_type' ? 'no_show_recovery_call')
        OR NEW.data->>'followup_type' = 'no_show_recovery_call' ) THEN
    RETURN NEW;
  END IF;

  v_appt := NULLIF(NEW.data->>'appointment_id', '');
  IF v_appt IS NULL THEN RETURN NEW; END IF;

  IF EXISTS (
    SELECT 1 FROM records r
    WHERE r.model_id = v_followups
      AND r.data->>'appointment_id' = v_appt
      AND ( (jsonb_typeof(r.data->'followup_type') = 'array' AND r.data->'followup_type' ? 'no_show_recovery_call')
         OR r.data->>'followup_type' = 'no_show_recovery_call' )
  ) THEN
    RETURN NULL;
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.tg_records_enqueue_call_analysis()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_terminal CONSTANT text[] := ARRAY['completed','no_answer','missed','rejected_by_callee','rejected_by_caller','failed','cancelled'];
BEGIN
  IF NEW.model_id IS DISTINCT FROM public._sales_phone_calls_model_id() THEN RETURN NEW; END IF;
  IF NEW.data->>'direction' IS DISTINCT FROM 'outbound' THEN RETURN NEW; END IF;
  IF NOT (COALESCE(NEW.data->>'status','') = ANY (v_terminal)) THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE'
     AND OLD.data->>'status' IS NOT DISTINCT FROM NEW.data->>'status'
     AND OLD.data->>'transcription_text' IS NOT DISTINCT FROM NEW.data->>'transcription_text'
     AND OLD.data->>'client_link' IS NOT DISTINCT FROM NEW.data->>'client_link'
  THEN RETURN NEW; END IF;

  PERFORM public.call_result_suggestion_enqueue(NEW.id);
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.tg_records_enqueue_push()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_followups_model uuid;
  v_rep             uuid;
  v_type            text;
  v_stage           text;
  v_client          uuid;
  v_name            text;
  v_old_state       text;
  v_new_state       text;
  v_status          text;
  v_hot_on          boolean;
  v_replied_on      boolean;
BEGIN
  SELECT id INTO v_followups_model FROM models WHERE name = 'followups';
  IF v_followups_model IS NULL OR NEW.model_id <> v_followups_model THEN
    RETURN NULL;
  END IF;

  BEGIN

  -- Read the switch once. Missing row ⇒ treat both as ON, so a deleted settings
  -- row degrades to today's behaviour rather than silently muting every alert.
  SELECT COALESCE(s.hot_lead_enabled, true), COALESCE(s.customer_replied_enabled, true)
    INTO v_hot_on, v_replied_on
    FROM push_builtin_settings s WHERE s.id = 1;
  v_hot_on     := COALESCE(v_hot_on, true);
  v_replied_on := COALESCE(v_replied_on, true);

  IF NOT v_hot_on AND NOT v_replied_on THEN
    RETURN NULL;   -- both built-ins off; nothing to do
  END IF;

  v_rep := NULLIF(
    CASE jsonb_typeof(NEW.data->'sales_rep')
      WHEN 'array'  THEN NEW.data->'sales_rep'->>0
      WHEN 'string' THEN NEW.data->>'sales_rep'
    END, '')::uuid;
  IF v_rep IS NULL THEN RETURN NULL; END IF;

  v_status := COALESCE(NULLIF(NEW.data->>'followup_status', ''), 'open');
  IF v_status IN ('completed', 'cancelled', 'skipped') THEN RETURN NULL; END IF;

  v_client := NULLIF(
    CASE jsonb_typeof(NEW.data->'client_id')
      WHEN 'array'  THEN NEW.data->'client_id'->>0
      WHEN 'string' THEN NEW.data->>'client_id'
    END, '')::uuid;

  v_name := NULLIF(NEW.data->>'client_name', '');
  IF v_name IS NULL AND v_client IS NOT NULL THEN
    SELECT NULLIF(r.data->>'client_name', '') INTO v_name FROM records r WHERE r.id = v_client;
  END IF;
  v_name := COALESCE(v_name, 'عميل');

  IF TG_OP = 'INSERT' THEN
    IF NOT v_hot_on THEN RETURN NULL; END IF;

    v_type := CASE jsonb_typeof(NEW.data->'followup_type')
                WHEN 'array'  THEN NEW.data->'followup_type'->>0
                WHEN 'string' THEN NEW.data->>'followup_type'
              END;

    IF v_type = 'appointment_booking_call'
       AND COALESCE(NULLIF(NEW.data->>'escalation_reason', ''), '') = ''
       AND COALESCE(NULLIF(NEW.data->>'previous_followup_id', ''), '') = ''
    THEN
      SELECT r.data->>'client_stage' INTO v_stage FROM records r WHERE r.id = v_client;

      IF (v_stage IS NULL OR v_stage = 'جديد')
         AND NOT EXISTS (
           SELECT 1 FROM records o
            WHERE o.model_id = v_followups_model
              AND o.id <> NEW.id
              AND o.created_at <= NEW.created_at
              AND (CASE jsonb_typeof(o.data->'client_id')
                     WHEN 'array'  THEN o.data->'client_id'->>0
                     WHEN 'string' THEN o.data->>'client_id'
                   END)::uuid = v_client
              AND (CASE jsonb_typeof(o.data->'followup_type')
                     WHEN 'array'  THEN o.data->'followup_type'->>0
                     WHEN 'string' THEN o.data->>'followup_type'
                   END) = 'appointment_booking_call'
         )
      THEN
        INSERT INTO push_outbox (user_id, kind, title, body, url, tag, dedupe_key)
        VALUES (v_rep, 'hot_lead', '🔥 عميل جديد — اتصل خلال ٥ دقائق', v_name,
                '/model/followups/' || NEW.id || '?returnTo=%2Fsales%2Fmy-tasks',
                'followup-' || NEW.id, 'hot_lead:' || NEW.id)
        ON CONFLICT (dedupe_key) WHERE dedupe_key IS NOT NULL DO NOTHING;
      END IF;
    END IF;

    RETURN NULL;
  END IF;

  IF NOT v_replied_on THEN RETURN NULL; END IF;

  v_old_state := CASE
    WHEN COALESCE(OLD.data->>'whatsapp_state', '') <> '' THEN OLD.data->>'whatsapp_state'
    WHEN COALESCE(OLD.data->>'client_messaged_at', '') <> '' THEN 'replied'
    ELSE '' END;
  v_new_state := CASE
    WHEN COALESCE(NEW.data->>'whatsapp_state', '') <> '' THEN NEW.data->>'whatsapp_state'
    WHEN COALESCE(NEW.data->>'client_messaged_at', '') <> '' THEN 'replied'
    ELSE '' END;

  IF v_new_state = 'replied' AND v_old_state <> 'replied' THEN
    INSERT INTO push_outbox (user_id, kind, title, body, url, tag, dedupe_key)
    VALUES (v_rep, 'customer_replied', '💬 العميل رد — دورك الآن', v_name,
            '/model/followups/' || NEW.id || '?returnTo=%2Fsales%2Fmy-tasks',
            'followup-' || NEW.id,
            'replied:' || NEW.id || ':' || COALESCE(NEW.data->>'client_messaged_at', NEW.updated_at::text))
    ON CONFLICT (dedupe_key) WHERE dedupe_key IS NOT NULL DO NOTHING;
  END IF;

  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'tg_records_enqueue_push failed for record % : % (%)',
      NEW.id, SQLERRM, SQLSTATE;
  END;

  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.tg_records_fill_client_next_action()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
