CREATE OR REPLACE FUNCTION public.tg_records_link_call_to_followup()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_calls     uuid := public._sales_phone_calls_model_id();
  v_followups uuid := public._sales_followups_model_id();
  -- Half-width of the evidence window, in seconds. 15 min — see
  -- supabase/migrations/2026-07-30_tighten_call_followup_link_window.sql for the
  -- production measurement behind this number.
  v_window    int  := 900;
  v_client    text;
  v_calltime  timestamptz;
  v_match     uuid;
BEGIN
  IF NEW.model_id IS DISTINCT FROM v_calls THEN RETURN NEW; END IF;
  IF NEW.data->>'direction' IS DISTINCT FROM 'outbound' THEN RETURN NEW; END IF;
  IF nullif(NEW.data->>'linked_followup_id', '') IS NOT NULL THEN RETURN NEW; END IF;

  v_client := nullif(NEW.data->>'client_link', '');
  IF v_client IS NULL OR v_client !~* '^[0-9a-f-]{36}$' THEN RETURN NEW; END IF;

  v_calltime := COALESCE(public.try_timestamptz(NEW.data->>'call_time'), now());

  SELECT f.id INTO v_match
  FROM public.records f
  WHERE f.model_id = v_followups
    AND public._followup_client_id_of(f.data) = v_client
    AND f.data->>'followup_status' = 'completed'
    AND nullif(f.data->>'completed_by_call_id', '') IS NULL
    AND COALESCE(f.data->'followup_type'->>0, f.data->>'followup_type') IS DISTINCT FROM 'whatsapp_follow_up'
    AND public.try_timestamptz(f.data->>'actual_datetime') IS NOT NULL
    AND abs(extract(epoch FROM (public.try_timestamptz(f.data->>'actual_datetime') - v_calltime))) <= v_window
  ORDER BY abs(extract(epoch FROM (public.try_timestamptz(f.data->>'actual_datetime') - v_calltime))) ASC
  LIMIT 1;

  IF v_match IS NULL THEN RETURN NEW; END IF;

  NEW.data := NEW.data || jsonb_build_object('linked_followup_id', v_match::text);

  UPDATE public.records
  SET data = data || jsonb_build_object('completed_by_call_id', NEW.id::text)
  WHERE id = v_match AND model_id = v_followups;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.tg_records_supersede_followups()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_name    text;
  v_event   text;
  v_client  uuid;
  v_terminal text[] := ARRAY['مغلق ناجح','خاسر','غير مؤهل'];
BEGIN
  SELECT name INTO v_name FROM models WHERE id = NEW.model_id;
  IF v_name IS NULL THEN RETURN NEW; END IF;

  IF v_name = 'appointments' THEN
    IF TG_OP <> 'INSERT' THEN RETURN NEW; END IF;
    v_event := 'appointment_created';
    v_client := NULLIF(NEW.data->>'client_id','')::uuid;

  ELSIF v_name = 'visits' THEN
    IF TG_OP <> 'INSERT' THEN RETURN NEW; END IF;
    v_event := 'visit_created';
    v_client := NULLIF(NEW.data->>'client_id','')::uuid;

  ELSIF v_name = 'offer_prices' THEN
    IF TG_OP <> 'INSERT' THEN RETURN NEW; END IF;
    v_event := 'offer_created';
    v_client := NULLIF(NEW.data->>'client_id','')::uuid;

  ELSIF v_name = 'reservations' THEN
    IF TG_OP <> 'INSERT' THEN RETURN NEW; END IF;
    v_event := 'reservation_created';
    v_client := NULLIF(NEW.data->>'client_id','')::uuid;

  ELSIF v_name = 'financing' THEN
    IF TG_OP = 'INSERT' THEN
      NULL;
    ELSIF TG_OP = 'UPDATE' AND (OLD.data->>'financing_status') IS DISTINCT FROM (NEW.data->>'financing_status') THEN
      NULL;
    ELSE
      RETURN NEW;
    END IF;
    IF NEW.data->>'financing_status' = 'completed' THEN
      v_event := 'transfer_started';
    ELSE
      v_event := 'financing_advanced';
    END IF;
    v_client := NULLIF(NEW.data->>'client_id','')::uuid;

  ELSIF v_name = 'ownership_transfer' THEN
    IF TG_OP = 'INSERT' THEN
      v_event := 'transfer_started';
      v_client := NULLIF(NEW.data->>'client_id','')::uuid;
    ELSIF TG_OP = 'UPDATE'
          AND (OLD.data->>'transfer_status') IS DISTINCT FROM (NEW.data->>'transfer_status')
          AND NEW.data->>'transfer_status' = 'completed' THEN
      v_event := 'transfer_completed';
      v_client := NULLIF(NEW.data->>'client_id','')::uuid;
    ELSE
      RETURN NEW;
    END IF;

  ELSIF v_name = 'clients' THEN
    IF TG_OP = 'UPDATE'
       AND (NEW.data->>'client_stage') = ANY(v_terminal)
       AND (OLD.data->>'client_stage') IS DISTINCT FROM (NEW.data->>'client_stage') THEN
      v_event := CASE WHEN NEW.data->>'client_stage' = 'مغلق ناجح' THEN 'client_closed_won' ELSE 'client_lost' END;
      v_client := NEW.id;
    ELSE
      RETURN NEW;
    END IF;

  ELSE
    RETURN NEW;
  END IF;

  IF v_client IS NOT NULL THEN
    PERFORM public.reconcile_superseded_followups(v_client, v_event, NEW.id);
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.tg_records_touch_client_on_activity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_followups uuid := public._sales_followups_model_id();
  v_calls uuid := (SELECT id FROM public.models WHERE name = 'phone_calls' LIMIT 1);
  v_chats uuid := (SELECT id FROM public.models WHERE name = 'chats' LIMIT 1);
  v_mid uuid;
  v_old text; v_new text;
BEGIN
  v_mid := CASE WHEN TG_OP = 'DELETE' THEN OLD.model_id ELSE NEW.model_id END;
  IF v_mid IS DISTINCT FROM v_followups
     AND v_mid IS DISTINCT FROM v_calls
     AND v_mid IS DISTINCT FROM v_chats THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  IF TG_OP = 'UPDATE' AND v_mid = v_chats
     AND (OLD.data->>'last_message_at') IS NOT DISTINCT FROM (NEW.data->>'last_message_at') THEN
    RETURN NEW;
  END IF;

  IF TG_OP <> 'INSERT' THEN
    v_old := CASE WHEN OLD.model_id = v_followups THEN public._followup_client_id_of(OLD.data)
                  ELSE public._link_client_id_of(OLD.data) END;
  END IF;
  IF TG_OP <> 'DELETE' THEN
    v_new := CASE WHEN NEW.model_id = v_followups THEN public._followup_client_id_of(NEW.data)
                  ELSE public._link_client_id_of(NEW.data) END;
  END IF;

  IF v_new IS NOT NULL THEN PERFORM public._touch_client(v_new); END IF;
  IF v_old IS NOT NULL AND v_old IS DISTINCT FROM v_new THEN PERFORM public._touch_client(v_old); END IF;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$;
CREATE OR REPLACE FUNCTION public.tg_records_touch_client_on_followup_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_followups uuid := public._sales_followups_model_id();
  v_old text;
  v_new text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.model_id <> v_followups THEN RETURN OLD; END IF;
    v_old := public._followup_client_id_of(OLD.data);
  ELSIF TG_OP = 'INSERT' THEN
    IF NEW.model_id <> v_followups THEN RETURN NEW; END IF;
    v_new := public._followup_client_id_of(NEW.data);
  ELSE
    IF NEW.model_id <> v_followups THEN RETURN NEW; END IF;
    v_old := public._followup_client_id_of(OLD.data);
    v_new := public._followup_client_id_of(NEW.data);
  END IF;
  IF v_new IS NOT NULL THEN PERFORM public._touch_client(v_new); END IF;
  IF v_old IS NOT NULL AND v_old IS DISTINCT FROM v_new THEN PERFORM public._touch_client(v_old); END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$;
CREATE OR REPLACE FUNCTION public.tg_records_touch_project_on_unit_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_units uuid := public._rollups_units_model_id();
  v_proj  uuid := public._rollups_all_projects_model_id();
  v_old   text;
  v_new   text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.model_id <> v_units THEN RETURN OLD; END IF;
    v_old := public._rollup_project_id_of(OLD.data);
  ELSIF TG_OP = 'INSERT' THEN
    IF NEW.model_id <> v_units THEN RETURN NEW; END IF;
    v_new := public._rollup_project_id_of(NEW.data);
  ELSE
    IF NEW.model_id <> v_units THEN RETURN NEW; END IF;
    v_old := public._rollup_project_id_of(OLD.data);
    v_new := public._rollup_project_id_of(NEW.data);
  END IF;

  IF v_new IS NOT NULL THEN
    PERFORM public._touch_project(v_new, v_proj);
  END IF;
  IF v_old IS NOT NULL AND v_old IS DISTINCT FROM v_new THEN
    PERFORM public._touch_project(v_old, v_proj);
  END IF;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$;
CREATE OR REPLACE FUNCTION public.tg_records_visit_completes_appointment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_visits uuid;
  v_appts  uuid;
  v_client text;
  v_visit_at timestamptz;
  v_match uuid;
BEGIN
  SELECT id INTO v_visits FROM models WHERE name = 'visits' LIMIT 1;
  IF NEW.model_id IS DISTINCT FROM v_visits THEN RETURN NEW; END IF;

  v_client := NULLIF(NEW.data->>'client_id', '');
  IF v_client IS NULL OR v_client !~* '^[0-9a-f-]{36}$' THEN RETURN NEW; END IF;

  SELECT id INTO v_appts FROM models WHERE name = 'appointments' LIMIT 1;
  IF v_appts IS NULL THEN RETURN NEW; END IF;

  v_visit_at := COALESCE(
    public.try_timestamptz(NEW.data->>'scheduled_datetime'),
    now());

  SELECT a.id INTO v_match
  FROM records a
  WHERE a.model_id = v_appts
    AND a.data->>'client_id' = v_client
    AND COALESCE(NULLIF(a.data->>'appointment_status', ''), 'scheduled')
        IN ('scheduled', 'confirmed', 'rescheduled')
    AND public.try_timestamptz(a.data->>'appointment_date') IS NOT NULL
    AND abs(extract(epoch FROM (public.try_timestamptz(a.data->>'appointment_date') - v_visit_at))) <= 259200
  ORDER BY abs(extract(epoch FROM (public.try_timestamptz(a.data->>'appointment_date') - v_visit_at))) ASC
  LIMIT 1;

  IF v_match IS NULL THEN RETURN NEW; END IF;

  UPDATE records
  SET data = data || jsonb_build_object(
        'appointment_status', 'completed',
        'completed_by_visit_id', NEW.id::text)
  WHERE id = v_match;

  NEW.data := NEW.data || jsonb_build_object('appointment_id', v_match::text);

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.tg_workflow_capture_models_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_bad  int;
  v_list text;
BEGIN
  SELECT count(*), string_agg(DISTINCT s.workflow_name || ' (' || s.workflow_id || ' / ' || s.action_type || ')', ', ')
    INTO v_bad, v_list
    FROM public.workflow_runner_action_support s
   WHERE s.model_id = NEW.model_id
     AND s.is_active
     AND s.trigger_event IN ('create', 'update', 'delete')
     AND s.runner_support_status = 'unsupported_in_runner_v1';

  IF COALESCE(v_bad, 0) > 0 THEN
    RAISE EXCEPTION
      'Cannot enroll model % for server-authoritative workflows: % unsupported runner action(s) in active create/update/delete workflows: %. Add runner support or handle those workflows before enrolling.',
      NEW.model_id, v_bad, v_list
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $function$;
