CREATE OR REPLACE FUNCTION public.value_translation_candidates(p_limit integer DEFAULT 500)
 RETURNS TABLE(source_text text, kind text, model_hint text, field_hint text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  WITH excluded AS (
    SELECT unnest(ARRAY[
      'chats','ai_chats','image_chats','copywriter_chats','matching_chats',
      'data_migration','decks','market_listings','real_estate_offices',
      'posts_content','project_details','chat_templates','site_settings',
      'districts','cities','regions','countries','developer_knowledge',
      'prompt_snippets','design_templates','image_presets','reel_scripts'
    ]) AS name
  ),
  flds AS (
    SELECT m.id AS model_id, m.name AS model, f->>'name' AS slug, f->>'type' AS ftype
    FROM models m,
         jsonb_array_elements(m.schema->'sections') s,
         jsonb_array_elements(s->'fields') f
    WHERE f->>'type' IN ('text','textarea')
      AND f->>'name' !~ '_(ar|en)$'
      AND m.name NOT IN (SELECT name FROM excluded)
  ),
  vals AS (
    SELECT DISTINCT ON (ur.data->>fl.slug)
      ur.data->>fl.slug AS source_text,
      CASE
        WHEN fl.ftype = 'textarea' THEN 'text'
        WHEN fl.slug ~ '(^|_)(name|title|block|model|project|developer|client)' THEN 'name'
        ELSE 'text'
      END AS kind,
      fl.model AS model_hint,
      fl.slug AS field_hint
    FROM flds fl
    JOIN unified_records ur ON ur.model_id = fl.model_id
    WHERE ur.data->>fl.slug ~ '[؀-ۿ]'
      AND char_length(ur.data->>fl.slug) BETWEEN 1 AND 4000
  )
  SELECT v.source_text, v.kind, v.model_hint, v.field_hint
  FROM vals v
  WHERE NOT EXISTS (
    SELECT 1 FROM value_translations t
    WHERE t.target_lang = 'en'
      AND t.source_hash = encode(digest(v.source_text, 'sha256'::text), 'hex')
  )
  ORDER BY v.source_text
  LIMIT p_limit;
$function$;
CREATE OR REPLACE FUNCTION public.waha_remediation_record_outcome(p_session text, p_recovered boolean, p_outcome text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_attempts integer;
BEGIN
  INSERT INTO public.waha_session_remediation (session, last_attempt_at, attempts, last_outcome)
  VALUES (p_session, now(), 0, p_outcome)
  ON CONFLICT (session) DO UPDATE
    SET last_outcome      = p_outcome,
        attempts          = CASE WHEN p_recovered THEN 0 ELSE public.waha_session_remediation.attempts END,
        last_recovered_at = CASE WHEN p_recovered THEN now() ELSE public.waha_session_remediation.last_recovered_at END,
        alerted_at        = CASE WHEN p_recovered THEN NULL ELSE public.waha_session_remediation.alerted_at END
  RETURNING attempts INTO v_attempts;
  RETURN coalesce(v_attempts, 0);
END $function$;
CREATE OR REPLACE FUNCTION public.waha_should_alert_unrecoverable(p_session text, p_min_attempts integer DEFAULT 3)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_attempts integer;
  v_alerted  timestamptz;
BEGIN
  SELECT attempts, alerted_at INTO v_attempts, v_alerted
  FROM public.waha_session_remediation WHERE session = p_session;

  IF coalesce(v_attempts, 0) < p_min_attempts OR v_alerted IS NOT NULL THEN
    RETURN false;
  END IF;

  UPDATE public.waha_session_remediation
    SET alerted_at = now() WHERE session = p_session AND alerted_at IS NULL;
  RETURN FOUND;
END $function$;
CREATE OR REPLACE FUNCTION public.waha_try_remediation_lock(p_session text, p_min_interval_seconds integer DEFAULT 600)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_key      bigint := hashtextextended(coalesce(p_session,''), 42);
  v_last     timestamptz;
  v_attempts integer := 0;
  v_wait     integer;
BEGIN
  IF NOT pg_try_advisory_xact_lock(v_key) THEN
    RETURN false;
  END IF;

  SELECT last_attempt_at, attempts INTO v_last, v_attempts
  FROM public.waha_session_remediation WHERE session = p_session;

  v_wait := least(
    greatest(p_min_interval_seconds, 60) * power(2, least(coalesce(v_attempts, 0), 6))::integer,
    21600
  );

  IF v_last IS NOT NULL AND v_last > now() - make_interval(secs => v_wait) THEN
    RETURN false;
  END IF;

  INSERT INTO public.waha_session_remediation (session, last_attempt_at, attempts)
  VALUES (p_session, now(), 1)
  ON CONFLICT (session) DO UPDATE
    SET last_attempt_at = now(),
        attempts = public.waha_session_remediation.attempts + 1;
  RETURN true;
END $function$;
CREATE OR REPLACE FUNCTION public.wassell_admin_add_geo_alias(p_external_id text, p_alias text, p_lang text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_eid uuid; v_alias text := nullif(btrim(coalesce(p_alias,'')),'');
BEGIN
  IF v_alias IS NULL THEN RAISE EXCEPTION 'alias is required'; END IF;
  SELECT id INTO v_eid FROM public.geo_elements WHERE external_id = p_external_id LIMIT 1;
  IF v_eid IS NULL THEN RAISE EXCEPTION 'geo_element not found: %', p_external_id; END IF;
  INSERT INTO public.geo_element_aliases (element_id, external_id, alias, alias_norm, lang, source)
  VALUES (v_eid, p_external_id, v_alias, lower(v_alias), nullif(btrim(coalesce(p_lang,'')),''), 'admin')
  ON CONFLICT (element_id, alias_norm, coalesce(lang,'')) DO NOTHING;
  RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'alias', a.alias, 'lang', a.lang) ORDER BY a.lang, a.alias), '[]')
          FROM public.geo_element_aliases a WHERE a.element_id = v_eid);
END;$function$;
CREATE OR REPLACE FUNCTION public.wassell_admin_geo_facets()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'categories',     (SELECT coalesce(jsonb_agg(DISTINCT category ORDER BY category) FILTER (WHERE category IS NOT NULL), '[]') FROM public.geo_elements WHERE external_id IS NOT NULL),
    'types',          (SELECT coalesce(jsonb_agg(DISTINCT type ORDER BY type) FILTER (WHERE type IS NOT NULL), '[]') FROM public.geo_elements WHERE external_id IS NOT NULL),
    'cities',         (SELECT coalesce(jsonb_agg(DISTINCT city ORDER BY city) FILTER (WHERE city IS NOT NULL), '[]') FROM public.geo_elements WHERE external_id IS NOT NULL),
    'geometry_types', (SELECT coalesce(jsonb_agg(DISTINCT geom_kind ORDER BY geom_kind) FILTER (WHERE geom_kind IS NOT NULL), '[]') FROM public.geo_elements WHERE external_id IS NOT NULL),
    'review_statuses',(SELECT coalesce(jsonb_agg(DISTINCT review_status ORDER BY review_status) FILTER (WHERE review_status IS NOT NULL), '[]') FROM public.geo_elements WHERE external_id IS NOT NULL),
    'source_types',   (SELECT coalesce(jsonb_agg(DISTINCT source_type ORDER BY source_type) FILTER (WHERE source_type IS NOT NULL), '[]') FROM public.geo_elements WHERE external_id IS NOT NULL),
    'total',          (SELECT count(*) FROM public.geo_elements WHERE external_id IS NOT NULL));
$function$;
CREATE OR REPLACE FUNCTION public.wassell_admin_geo_geojson(p_q text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_type text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_geom_kind text DEFAULT NULL::text, p_review_status text DEFAULT NULL::text, p_is_verified boolean DEFAULT NULL::boolean, p_is_approximate boolean DEFAULT NULL::boolean, p_is_active boolean DEFAULT NULL::boolean, p_is_searchable boolean DEFAULT NULL::boolean, p_conf_min numeric DEFAULT NULL::numeric, p_conf_max numeric DEFAULT NULL::numeric, p_low_confidence boolean DEFAULT NULL::boolean, p_limit integer DEFAULT 3000)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH f AS (
    SELECT e.* FROM public.geo_elements e
    WHERE e.external_id IS NOT NULL AND e.geom IS NOT NULL
      AND (p_category IS NULL OR e.category = p_category)
      AND (p_type IS NULL OR e.type = p_type)
      AND (p_city IS NULL OR e.city ILIKE p_city)
      AND (p_geom_kind IS NULL OR e.geom_kind = p_geom_kind)
      AND (p_review_status IS NULL OR e.review_status = p_review_status)
      AND (p_is_verified IS NULL OR e.is_verified = p_is_verified)
      AND (p_is_approximate IS NULL OR e.is_approximate = p_is_approximate)
      AND (p_is_active IS NULL OR e.is_active = p_is_active)
      AND (p_is_searchable IS NULL OR e.is_searchable = p_is_searchable)
      AND (p_conf_min IS NULL OR e.confidence_score >= p_conf_min)
      AND (p_conf_max IS NULL OR e.confidence_score <= p_conf_max)
      AND (NOT coalesce(p_low_confidence, false) OR (e.confidence_score IS NOT NULL AND e.confidence_score < 0.5))
      AND (
        nullif(btrim(coalesce(p_q,'')),'') IS NULL
        OR e.name_ar ILIKE '%'||btrim(p_q)||'%' OR e.name_en ILIKE '%'||btrim(p_q)||'%'
        OR e.display_name ILIKE '%'||btrim(p_q)||'%' OR e.external_id ILIKE '%'||btrim(p_q)||'%'
        OR EXISTS (SELECT 1 FROM public.geo_element_aliases a WHERE a.element_id = e.id AND a.alias_norm ILIKE '%'||lower(btrim(p_q))||'%')
      )
    ORDER BY e.category, e.external_id
    LIMIT greatest(1, least(coalesce(p_limit, 3000), 5000))
  )
  SELECT jsonb_build_object(
    'type', 'FeatureCollection',
    'count', (SELECT count(*) FROM f),
    'features', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'type', 'Feature',
        'geometry', ST_AsGeoJSON(ST_SimplifyPreserveTopology(f.geom, 0.0001), 6)::jsonb,
        'properties', jsonb_build_object(
          'external_id', f.external_id, 'name_ar', f.name_ar, 'name_en', f.name_en,
          'category', f.category, 'type', f.type, 'geometry_type', f.geom_kind,
          'review_status', f.review_status, 'is_active', f.is_active, 'is_searchable', f.is_searchable,
          'is_verified', f.is_verified, 'confidence_score', f.confidence_score,
          'lat', f.latitude, 'lng', f.longitude)
      )) FROM f), '[]'::jsonb)
  );
$function$;
CREATE OR REPLACE FUNCTION public.wassell_admin_get_geo_element(p_external_id text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'external_id', e.external_id, 'name_ar', e.name_ar, 'name_en', e.name_en, 'display_name', e.display_name,
    'category', e.category, 'type', e.type, 'city', e.city, 'region_id', e.region_id,
    'geometry_type', e.geom_kind, 'latitude', e.latitude, 'longitude', e.longitude,
    'confidence_score', e.confidence_score, 'is_verified', e.is_verified, 'is_approximate', e.is_approximate,
    'review_status', e.review_status, 'is_active', e.is_active, 'is_searchable', e.is_searchable,
    'source_type', e.source_type, 'source_url', e.source_url, 'notes', e.notes,
    'created_at', e.created_at, 'updated_at', e.updated_at,
    'geometry_summary', jsonb_build_object('postgis_type', ST_GeometryType(e.geom), 'n_points', ST_NPoints(e.geom),
       'n_geometries', ST_NumGeometries(e.geom), 'bbox', ST_AsText(ST_Envelope(e.geom))),
    'geojson', ST_AsGeoJSON(e.geom)::jsonb, 'raw', e.raw,
    'aliases', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'alias', a.alias, 'lang', a.lang) ORDER BY a.lang, a.alias), '[]')
                FROM public.geo_element_aliases a WHERE a.element_id = e.id))
  FROM public.geo_elements e WHERE e.external_id = p_external_id LIMIT 1;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_admin_list_geo_elements(p_q text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_type text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_geom_kind text DEFAULT NULL::text, p_review_status text DEFAULT NULL::text, p_is_verified boolean DEFAULT NULL::boolean, p_is_approximate boolean DEFAULT NULL::boolean, p_is_active boolean DEFAULT NULL::boolean, p_is_searchable boolean DEFAULT NULL::boolean, p_conf_min numeric DEFAULT NULL::numeric, p_conf_max numeric DEFAULT NULL::numeric, p_low_confidence boolean DEFAULT NULL::boolean, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH f AS (
    SELECT e.* FROM public.geo_elements e
    WHERE e.external_id IS NOT NULL
      AND (p_category IS NULL OR e.category = p_category)
      AND (p_type IS NULL OR e.type = p_type)
      AND (p_city IS NULL OR e.city ILIKE p_city)
      AND (p_geom_kind IS NULL OR e.geom_kind = p_geom_kind)
      AND (p_review_status IS NULL OR e.review_status = p_review_status)
      AND (p_is_verified IS NULL OR e.is_verified = p_is_verified)
      AND (p_is_approximate IS NULL OR e.is_approximate = p_is_approximate)
      AND (p_is_active IS NULL OR e.is_active = p_is_active)
      AND (p_is_searchable IS NULL OR e.is_searchable = p_is_searchable)
      AND (p_conf_min IS NULL OR e.confidence_score >= p_conf_min)
      AND (p_conf_max IS NULL OR e.confidence_score <= p_conf_max)
      AND (NOT coalesce(p_low_confidence, false) OR (e.confidence_score IS NOT NULL AND e.confidence_score < 0.5))
      AND (
        nullif(btrim(coalesce(p_q,'')),'') IS NULL
        OR e.name_ar ILIKE '%'||btrim(p_q)||'%' OR e.name_en ILIKE '%'||btrim(p_q)||'%'
        OR e.display_name ILIKE '%'||btrim(p_q)||'%' OR e.external_id ILIKE '%'||btrim(p_q)||'%'
        OR EXISTS (SELECT 1 FROM public.geo_element_aliases a WHERE a.element_id = e.id AND a.alias_norm ILIKE '%'||lower(btrim(p_q))||'%')
      )
  ),
  page AS (
    SELECT jsonb_build_object(
      'external_id', f.external_id, 'name_ar', f.name_ar, 'name_en', f.name_en, 'display_name', f.display_name,
      'category', f.category, 'type', f.type, 'city', f.city, 'geometry_type', f.geom_kind,
      'confidence_score', f.confidence_score, 'is_verified', f.is_verified, 'is_approximate', f.is_approximate,
      'review_status', f.review_status, 'is_active', f.is_active, 'is_searchable', f.is_searchable,
      'source_type', f.source_type, 'updated_at', f.updated_at, 'created_at', f.created_at) AS r
    FROM f ORDER BY f.category, f.name_en NULLS LAST, f.external_id
    LIMIT greatest(1, least(coalesce(p_limit, 50), 200)) OFFSET greatest(0, coalesce(p_offset, 0))
  )
  SELECT jsonb_build_object('total', (SELECT count(*) FROM f), 'rows', (SELECT coalesce(jsonb_agg(r), '[]'::jsonb) FROM page));
$function$;
CREATE OR REPLACE FUNCTION public.wassell_admin_remove_geo_alias(p_alias_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_eid uuid;
BEGIN
  SELECT element_id INTO v_eid FROM public.geo_element_aliases WHERE id = p_alias_id;
  IF v_eid IS NULL THEN RETURN '[]'::jsonb; END IF;
  DELETE FROM public.geo_element_aliases WHERE id = p_alias_id;
  RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'alias', a.alias, 'lang', a.lang) ORDER BY a.lang, a.alias), '[]')
          FROM public.geo_element_aliases a WHERE a.element_id = v_eid);
END;$function$;
CREATE OR REPLACE FUNCTION public.wassell_admin_update_geo_element(p_external_id text, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_rs text;
BEGIN
  IF p_patch ? 'review_status' THEN
    v_rs := p_patch->>'review_status';
    IF v_rs NOT IN ('approved','needs_review','rejected') THEN RAISE EXCEPTION 'invalid review_status: %', v_rs; END IF;
  END IF;
  UPDATE public.geo_elements e SET
    review_status = CASE WHEN p_patch ? 'review_status' THEN p_patch->>'review_status' ELSE e.review_status END,
    is_active     = CASE WHEN p_patch ? 'is_active'     THEN (p_patch->>'is_active')::boolean ELSE e.is_active END,
    is_searchable = CASE WHEN p_patch ? 'is_searchable' THEN (p_patch->>'is_searchable')::boolean ELSE e.is_searchable END,
    name_ar       = CASE WHEN p_patch ? 'name_ar'       THEN nullif(btrim(p_patch->>'name_ar'),'') ELSE e.name_ar END,
    name_en       = CASE WHEN p_patch ? 'name_en'       THEN nullif(btrim(p_patch->>'name_en'),'') ELSE e.name_en END,
    notes         = CASE WHEN p_patch ? 'notes'         THEN nullif(btrim(p_patch->>'notes'),'') ELSE e.notes END,
    display_name  = CASE WHEN (p_patch ? 'name_en') OR (p_patch ? 'name_ar')
                         THEN coalesce(nullif(btrim(coalesce(p_patch->>'name_en', e.name_en)),''),
                                       nullif(btrim(coalesce(p_patch->>'name_ar', e.name_ar)),''), e.external_id)
                         ELSE e.display_name END,
    updated_at    = now()
  WHERE e.external_id = p_external_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'geo_element not found: %', p_external_id; END IF;
  RETURN public.wassell_admin_get_geo_element(p_external_id);
END;$function$;
CREATE OR REPLACE FUNCTION public.wassell_app_user_id(auth_user_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT id FROM users WHERE auth_uid = auth_user_id AND is_active = true LIMIT 1;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_bedrooms_bucket(p_bedrooms numeric)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE
    WHEN p_bedrooms IS NULL THEN 'all'
    WHEN p_bedrooms <= 2 THEN '1-2'
    WHEN p_bedrooms = 3 THEN '3'
    WHEN p_bedrooms = 4 THEN '4'
    ELSE '5+' END;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_benchmark_confidence(p_deduped integer, p_dupe_ratio numeric, p_source text, p_has_txn boolean)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE
    WHEN p_deduped >= 30 AND p_dupe_ratio <= 0.25 THEN 'high'
    WHEN p_deduped >= 12 AND p_dupe_ratio <= 0.45 THEN 'medium'
    ELSE 'low'
  END;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_budget_bucket(p_val numeric)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE
    WHEN p_val IS NULL OR p_val <= 0 THEN 'all'
    WHEN p_val < 1000000 THEN '<1M'
    WHEN p_val < 2000000 THEN '1-2M'
    WHEN p_val < 3000000 THEN '2-3M'
    WHEN p_val < 5000000 THEN '3-5M'
    ELSE '5M+'
  END;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_can_access_file(p_file_id uuid, p_kind text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  app_uid uuid := wassell_app_user_id((SELECT auth.uid()));
  uploader uuid;
  fld uuid;
  direct_role text;
BEGIN
  IF wassell_is_admin((SELECT auth.uid())) THEN RETURN true; END IF;
  IF app_uid IS NULL OR p_file_id IS NULL THEN RETURN false; END IF;
  SELECT uploaded_by_user_id, folder_id INTO uploader, fld FROM public.files WHERE id = p_file_id;
  IF uploader IS NULL THEN RETURN false; END IF;
  IF uploader = app_uid THEN RETURN true; END IF;
  SELECT role INTO direct_role FROM public.file_permissions WHERE file_id = p_file_id AND user_id = app_uid;
  IF direct_role IS NOT NULL AND wassell_role_satisfies(direct_role, p_kind) THEN
    RETURN true;
  END IF;
  IF fld IS NOT NULL THEN
    RETURN wassell_role_satisfies(wassell_folder_cascade_role(fld, app_uid), p_kind);
  END IF;
  RETURN false;
END $function$;
CREATE OR REPLACE FUNCTION public.wassell_can_access_folder(p_folder_id uuid, p_kind text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  app_uid uuid := wassell_app_user_id((SELECT auth.uid()));
  creator uuid;
  cascade_role text;
BEGIN
  IF wassell_is_admin((SELECT auth.uid())) THEN RETURN true; END IF;
  IF app_uid IS NULL OR p_folder_id IS NULL THEN RETURN false; END IF;
  SELECT created_by_user_id INTO creator FROM public.folders WHERE id = p_folder_id;
  IF creator IS NULL THEN RETURN false; END IF;
  IF creator = app_uid THEN RETURN true; END IF;
  cascade_role := wassell_folder_cascade_role(p_folder_id, app_uid);
  RETURN wassell_role_satisfies(cascade_role, p_kind);
END $function$;
