CREATE OR REPLACE FUNCTION public.wassell_city_district_shapes(p_city_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '15s'
AS $function$
  with member_cities as (
    select p_city_id::text as cid
    union
    select member_city_id::text from public.city_metro_groups where parent_city_id = p_city_id
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'district_id', b.district_record_id,
      'name',
        coalesce(d.data->>'display_name', d.data->>'name_ar', d.data->>'name_en')
        || case when d.data->>'city_lookup' <> p_city_id::text
                then ' — ' || coalesce(d.data->>'city_name_ar', d.data->>'city_name_en', '')
                else '' end,
      'geojson', ST_AsGeoJSON(ST_SimplifyPreserveTopology(b.geom, 0.0002), 5)::jsonb
    )
    order by coalesce(d.data->>'display_name', d.data->>'name_ar')
  ), '[]'::jsonb)
  from public.district_boundaries b
  join public.unified_records d on d.id = b.district_record_id
  where b.is_active
    and d.data->>'city_lookup' in (select cid from member_cities)
$function$;
CREATE OR REPLACE FUNCTION public.wassell_city_zone_districts(p_city text, p_zone text)
 RETURNS TABLE(district_id uuid, district_name text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_zone text := lower(btrim(coalesce(p_zone,'')));
  v_city_id text;
BEGIN
  SELECT d.city_id INTO v_city_id
  FROM public.districts d
  WHERE (d.city_name_ar = p_city OR d.city_id = p_city)
  LIMIT 1;
  IF v_city_id IS NULL THEN RETURN; END IF;

  IF EXISTS (SELECT 1 FROM public.geo_zone_overrides o WHERE o.city_id = v_city_id AND o.zone = v_zone) THEN
    RETURN QUERY
      SELECT d.id, coalesce(d.name_ar, d.display_name)
      FROM public.geo_zone_overrides o
      JOIN public.districts d ON d.id::text = o.district_id
      WHERE o.city_id = v_city_id AND o.zone = v_zone;
    RETURN;
  END IF;

  RETURN QUERY
  WITH city_d AS (
    SELECT d.id, coalesce(d.name_ar, d.display_name) AS nm, d.centroid_lat AS lat, d.centroid_lng AS lng
    FROM public.districts d
    WHERE d.city_id = v_city_id AND d.centroid_lat IS NOT NULL AND d.centroid_lng IS NOT NULL
  ), s AS (
    SELECT min(lat) lat0, max(lat) lat1, min(lng) lng0, max(lng) lng1 FROM city_d
  ), rel AS (
    SELECT c.id, c.nm,
      CASE WHEN s.lat1 = s.lat0 THEN 0.5 ELSE (c.lat - s.lat0) / (s.lat1 - s.lat0) END AS rlat,
      CASE WHEN s.lng1 = s.lng0 THEN 0.5 ELSE (c.lng - s.lng0) / (s.lng1 - s.lng0) END AS rlng
    FROM city_d c CROSS JOIN s
  )
  SELECT r.id, r.nm FROM rel r
  WHERE CASE v_zone
    WHEN 'north'     THEN r.rlat >= 0.60
    WHEN 'south'     THEN r.rlat <= 0.40
    WHEN 'east'      THEN r.rlng >= 0.60
    WHEN 'west'      THEN r.rlng <= 0.40
    WHEN 'center'    THEN r.rlat BETWEEN 0.35 AND 0.65 AND r.rlng BETWEEN 0.35 AND 0.65
    WHEN 'northeast' THEN r.rlat >= 0.55 AND r.rlng >= 0.55
    WHEN 'northwest' THEN r.rlat >= 0.55 AND r.rlng <= 0.45
    WHEN 'southeast' THEN r.rlat <= 0.45 AND r.rlng >= 0.55
    WHEN 'southwest' THEN r.rlat <= 0.45 AND r.rlng <= 0.45
    ELSE false END;
END;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_compile_client_geo(p_client_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_items jsonb;
BEGIN
  SELECT r.data->'location_items' INTO v_items
  FROM public.records r JOIN public.models m ON m.id = r.model_id
  WHERE m.name = 'clients' AND r.id = p_client_id LIMIT 1;
  RETURN public.wassell_compile_geo_items(p_client_id, v_items);
END;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_compile_geo_items(p_client_id uuid, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_items jsonb := p_items; v_item jsonb; v_cond jsonb;
  v_kind text; v_polarity text; v_item_id text; v_rule text;
  v_district uuid; v_geom geometry; v_ref_geom geometry; v_direction text;
  v_vstatus text; v_dids uuid[];
  v_el_geom geometry; v_el_geog geography; v_el_kind text; v_el_clean geometry;
  v_el_active boolean; v_el_status text; v_el_conf numeric;
  v_usable boolean; v_buf geometry; v_dist double precision;
  v_line geometry;
  v_includes int := 0; v_excludes int := 0; v_review int := 0; v_n int := 0;
  CONFIDENCE_FLOOR constant numeric := 0.5;
  DIRECTION_DEFAULT_M constant double precision := 5000;
BEGIN
  DELETE FROM public.client_pref_geometry WHERE client_id = p_client_id;

  IF v_items IS NULL OR jsonb_typeof(v_items) <> 'array' THEN
    RETURN jsonb_build_object('compiled', 0, 'includes', 0, 'excludes', 0, 'needs_review', 0);
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_items) LOOP
    v_kind := coalesce(v_item->>'kind', '');
    v_polarity := lower(coalesce(v_item->>'polarity', 'include'));
    IF v_polarity NOT IN ('include', 'exclude') THEN v_polarity := 'include'; END IF;
    v_item_id := coalesce(v_item->>'id', 'item_' || v_n::text);
    v_geom := NULL; v_ref_geom := NULL; v_direction := NULL; v_dids := '{}'; v_vstatus := 'ok';

    IF v_kind = 'district' THEN
      v_district := NULL;
      BEGIN v_district := (v_item->>'district_id')::uuid;
      EXCEPTION WHEN others THEN v_district := NULL; END;
      IF v_district IS NULL THEN
        v_vstatus := 'needs_review';
      ELSE
        SELECT ST_Multi(b.geom) INTO v_geom FROM public.district_boundaries b
        WHERE b.district_record_id = v_district AND b.is_active LIMIT 1;
        v_dids := ARRAY[v_district];
      END IF;

    ELSIF v_kind = 'drawn_area' THEN
      BEGIN
        v_geom := ST_SetSRID(
          ST_GeomFromGeoJSON(jsonb_build_object('type', 'Polygon', 'coordinates', jsonb_build_array(v_item->'coordinates'))::text),
          4326);
        IF v_geom IS NULL OR ST_NPoints(v_geom) < 4 THEN
          v_vstatus := 'needs_review'; v_geom := NULL;
        ELSE
          v_geom := ST_CollectionExtract(ST_MakeValid(v_geom), 3);
          IF v_geom IS NULL OR ST_IsEmpty(v_geom) THEN
            v_vstatus := 'needs_review'; v_geom := NULL;
          END IF;
        END IF;
      EXCEPTION WHEN others THEN
        v_vstatus := 'needs_review'; v_geom := NULL;
      END;

    ELSIF v_kind = 'element_rule' THEN
      IF jsonb_typeof(v_item->'conditions') = 'array' THEN
        FOR v_cond IN SELECT * FROM jsonb_array_elements(v_item->'conditions') LOOP
          v_rule := coalesce(v_cond->>'rule', '');
          v_el_geom := NULL; v_el_geog := NULL; v_el_kind := NULL;
          v_el_active := NULL; v_el_status := NULL; v_el_conf := NULL;
          SELECT e.geom, e.centroid_geog, e.geom_kind, e.is_active, e.review_status, e.confidence_score
            INTO v_el_geom, v_el_geog, v_el_kind, v_el_active, v_el_status, v_el_conf
          FROM public.geo_elements e
          WHERE e.external_id = (v_cond->>'element_id') LIMIT 1;

          v_usable := v_el_active IS NOT NULL
            AND coalesce(v_el_active, false)
            AND coalesce(v_el_status, 'approved') <> 'rejected'
            AND (v_el_conf IS NULL OR v_el_conf >= CONFIDENCE_FLOOR);

          v_el_clean := v_el_geom;
          IF v_el_geom IS NOT NULL AND GeometryType(v_el_geom) = 'GEOMETRYCOLLECTION' THEN
            v_el_clean := ST_CollectionExtract(v_el_geom,
              CASE v_el_kind WHEN 'polygon' THEN 3 WHEN 'linestring' THEN 2 ELSE 1 END);
          END IF;

          IF NOT v_usable THEN
            v_vstatus := 'needs_review';
          ELSIF v_rule = 'within_radius' THEN
            v_dist := public.try_numeric(v_cond->>'distance_m');
            IF v_dist IS NULL OR v_dist <= 0 OR v_el_geog IS NULL THEN
              v_vstatus := 'needs_review';
            ELSE
              v_buf := ST_Buffer(v_el_geog, v_dist, 'quad_segs=16')::geometry;
              v_geom := CASE WHEN v_geom IS NULL THEN v_buf ELSE ST_Intersection(v_geom, v_buf) END;
            END IF;
          ELSIF v_rule = 'within_distance' THEN
            v_dist := public.try_numeric(v_cond->>'distance_m');
            IF v_dist IS NULL OR v_dist <= 0 OR v_el_clean IS NULL THEN
              v_vstatus := 'needs_review';
            ELSE
              v_buf := ST_Buffer(v_el_clean::geography, v_dist, 'quad_segs=16')::geometry;
              v_geom := CASE WHEN v_geom IS NULL THEN v_buf ELSE ST_Intersection(v_geom, v_buf) END;
            END IF;
          ELSIF v_rule = 'inside_area' THEN
            IF v_el_clean IS NULL OR v_el_kind <> 'polygon' THEN
              v_vstatus := 'needs_review';
            ELSE
              v_geom := CASE WHEN v_geom IS NULL THEN v_el_clean ELSE ST_Intersection(v_geom, v_el_clean) END;
            END IF;
          ELSIF v_rule IN ('north_of', 'south_of', 'east_of', 'west_of') THEN
            IF v_el_clean IS NULL OR v_el_kind <> 'linestring' OR v_direction IS NOT NULL THEN
              v_vstatus := 'needs_review';
            ELSE
              v_dist := coalesce(public.try_numeric(v_cond->>'distance_m'), DIRECTION_DEFAULT_M);
              IF v_dist <= 0 THEN v_dist := DIRECTION_DEFAULT_M; END IF;
              v_line := coalesce(ST_SimplifyPreserveTopology(v_el_clean, 0.001), v_el_clean);
              v_buf := ST_Buffer(v_line::geography, v_dist, 'quad_segs=8')::geometry;
              v_geom := CASE WHEN v_geom IS NULL THEN v_buf ELSE ST_Intersection(v_geom, v_buf) END;
              v_ref_geom := v_line;
              v_direction := split_part(v_rule, '_', 1);
            END IF;
          ELSE
            v_vstatus := 'needs_review';
          END IF;
        END LOOP;
      ELSE
        v_vstatus := 'needs_review';
      END IF;

      IF v_vstatus = 'ok' AND v_geom IS NULL AND v_direction IS NULL THEN
        v_vstatus := 'needs_review';
      END IF;

    ELSE
      v_vstatus := 'needs_review';
    END IF;

    IF v_geom IS NOT NULL THEN v_geom := ST_Multi(v_geom); END IF;

    INSERT INTO public.client_pref_geometry
      (client_id, item_id, polarity, kind, geom, ref_geom, direction, district_ids, validation_status, compiled_at)
    VALUES (p_client_id, v_item_id, v_polarity, coalesce(nullif(v_kind,''),'unknown'),
            v_geom, v_ref_geom, v_direction, v_dids, v_vstatus, now())
    ON CONFLICT (client_id, item_id) DO UPDATE
      SET polarity = EXCLUDED.polarity, kind = EXCLUDED.kind, geom = EXCLUDED.geom,
          ref_geom = EXCLUDED.ref_geom, direction = EXCLUDED.direction,
          district_ids = EXCLUDED.district_ids, validation_status = EXCLUDED.validation_status,
          compiled_at = now();

    v_n := v_n + 1;
    IF v_vstatus = 'needs_review' THEN v_review := v_review + 1;
    ELSIF v_polarity = 'include' THEN v_includes := v_includes + 1;
    ELSE v_excludes := v_excludes + 1; END IF;
  END LOOP;

  RETURN jsonb_build_object('compiled', v_n, 'includes', v_includes, 'excludes', v_excludes, 'needs_review', v_review);
END;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_debug_ctx()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT jsonb_build_object(
    'current_user', current_user,
    'session_user', session_user,
    'role_guc', current_setting('role', true),
    'jwt_claims', NULLIF(current_setting('request.jwt.claims', true), '')
  );
$function$;
CREATE OR REPLACE FUNCTION public.wassell_effective_file_roles(p_file_ids uuid[])
 RETURNS TABLE(file_id uuid, role text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  app_uid  uuid    := wassell_app_user_id((SELECT auth.uid()));
  is_admin boolean := wassell_is_admin((SELECT auth.uid()));
  fid uuid;
  uploader uuid;
  fld uuid;
  direct_role text;
  cascade_role text;
  r int;
BEGIN
  IF app_uid IS NULL OR p_file_ids IS NULL THEN RETURN; END IF;
  FOREACH fid IN ARRAY p_file_ids LOOP
    SELECT uploaded_by_user_id, folder_id INTO uploader, fld FROM public.files WHERE id = fid;
    IF uploader IS NULL THEN CONTINUE; END IF;
    IF is_admin OR uploader = app_uid THEN
      file_id := fid; role := 'owner'; RETURN NEXT; CONTINUE;
    END IF;
    SELECT fp.role INTO direct_role
      FROM public.file_permissions fp
     WHERE fp.file_id = fid AND fp.user_id = app_uid;
    cascade_role := CASE WHEN fld IS NOT NULL
                        THEN wassell_folder_cascade_role(fld, app_uid)
                        ELSE NULL END;
    r := GREATEST(wassell_role_rank(direct_role), wassell_role_rank(cascade_role));
    IF r > 0 THEN
      file_id := fid;
      role := CASE r WHEN 3 THEN 'owner' WHEN 2 THEN 'editor' ELSE 'viewer' END;
      RETURN NEXT;
    END IF;
  END LOOP;
END $function$;
CREATE OR REPLACE FUNCTION public.wassell_effective_folder_roles(p_folder_ids uuid[])
 RETURNS TABLE(folder_id uuid, role text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  app_uid  uuid    := wassell_app_user_id((SELECT auth.uid()));
  is_admin boolean := wassell_is_admin((SELECT auth.uid()));
  fid uuid;
  creator uuid;
  cascade_role text;
BEGIN
  IF app_uid IS NULL OR p_folder_ids IS NULL THEN RETURN; END IF;
  FOREACH fid IN ARRAY p_folder_ids LOOP
    SELECT created_by_user_id INTO creator FROM public.folders WHERE id = fid;
    IF creator IS NULL THEN CONTINUE; END IF;
    IF is_admin OR creator = app_uid THEN
      folder_id := fid; role := 'owner'; RETURN NEXT; CONTINUE;
    END IF;
    cascade_role := wassell_folder_cascade_role(fid, app_uid);
    IF cascade_role IS NOT NULL THEN
      folder_id := fid; role := cascade_role; RETURN NEXT;
    END IF;
  END LOOP;
END $function$;
CREATE OR REPLACE FUNCTION public.wassell_file_is_public_marketing(p_file_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    -- (A) Project hero image (main_image, with legacy image_url fallback) on a PUBLIC all_projects record.
    EXISTS (
      SELECT 1
      FROM public.records pr
      JOIN public.models mpr ON mpr.id = pr.model_id AND mpr.name = 'all_projects'
      WHERE COALESCE((pr.data->>'is_public')::boolean, false) = true
        AND p_file_id::text IN (pr.data->>'main_image', pr.data->>'image_url')
    )
    -- (B) project_details sidecar images, gated on the linked project being public.
    OR EXISTS (
      SELECT 1
      FROM public.records pd
      JOIN public.models mpd ON mpd.id = pd.model_id AND mpd.name = 'project_details'
      JOIN public.records pr ON pr.id::text = pd.data->>'project_id'
      JOIN public.models mpr ON mpr.id = pr.model_id AND mpr.name = 'all_projects'
      WHERE COALESCE((pr.data->>'is_public')::boolean, false) = true
        AND p_file_id::text IN (
          pd.data->>'hero_image_url',
          pd.data->>'agent_image_url',
          pd.data->>'gallery_image_1',
          pd.data->>'gallery_image_2',
          pd.data->>'gallery_image_3',
          pd.data->>'gallery_image_4',
          pd.data->>'gallery_image_5',
          pd.data->>'gallery_image_6',
          pd.data->>'gallery_image_7',
          pd.data->>'gallery_image_8'
        )
    );
$function$;
CREATE OR REPLACE FUNCTION public.wassell_folder_cascade_role(p_folder_id uuid, p_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  best_role text;
BEGIN
  IF p_folder_id IS NULL OR p_user_id IS NULL THEN RETURN NULL; END IF;
  WITH RECURSIVE ancestors AS (
    SELECT id, parent_folder_id FROM public.folders WHERE id = p_folder_id
    UNION ALL
    SELECT f.id, f.parent_folder_id
      FROM public.folders f
      JOIN ancestors a ON f.id = a.parent_folder_id
  )
  SELECT CASE
           WHEN MAX(CASE role WHEN 'owner' THEN 3 WHEN 'editor' THEN 2 WHEN 'viewer' THEN 1 ELSE 0 END) = 3 THEN 'owner'
           WHEN MAX(CASE role WHEN 'owner' THEN 3 WHEN 'editor' THEN 2 WHEN 'viewer' THEN 1 ELSE 0 END) = 2 THEN 'editor'
           WHEN MAX(CASE role WHEN 'owner' THEN 3 WHEN 'editor' THEN 2 WHEN 'viewer' THEN 1 ELSE 0 END) = 1 THEN 'viewer'
           ELSE NULL
         END
    INTO best_role
    FROM public.folder_permissions
   WHERE folder_id IN (SELECT id FROM ancestors)
     AND user_id = p_user_id;
  RETURN best_role;
END $function$;
CREATE OR REPLACE FUNCTION public.wassell_geo_dir_match(p_ref geometry, p_pt geometry, p_dir text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN p_ref IS NULL OR p_pt IS NULL THEN false
    WHEN p_dir = 'north' THEN ST_Y(p_pt) > ST_Y(ST_ClosestPoint(p_ref, p_pt))
    WHEN p_dir = 'south' THEN ST_Y(p_pt) < ST_Y(ST_ClosestPoint(p_ref, p_pt))
    WHEN p_dir = 'east'  THEN ST_X(p_pt) > ST_X(ST_ClosestPoint(p_ref, p_pt))
    WHEN p_dir = 'west'  THEN ST_X(p_pt) < ST_X(ST_ClosestPoint(p_ref, p_pt))
    ELSE false
  END
$function$;
CREATE OR REPLACE FUNCTION public.wassell_geo_element_shapes(p_external_ids text[])
 RETURNS TABLE(external_id text, name_ar text, name_en text, display_name text, element_type text, geojson jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    e.external_id,
    e.name_ar,
    e.name_en,
    e.display_name,
    e.element_type,
    ST_AsGeoJSON(ST_SimplifyPreserveTopology(e.geom, 0.0001), 6)::jsonb
  FROM public.geo_elements e
  WHERE e.external_id = ANY (p_external_ids)
    AND e.geom IS NOT NULL
    AND e.is_active
    AND e.is_searchable
    AND coalesce(e.review_status, '') <> 'rejected'
  LIMIT 50;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_geo_elements_set_country()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.country_code IS NULL THEN
    NEW.country_code := CASE NEW.raw->>'country'
      WHEN 'Saudi Arabia'         THEN 'SA'
      WHEN 'United Arab Emirates' THEN 'AE'
      ELSE NULL
    END;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.wassell_geo_exclude_match(p_geom geometry, p_ref geometry, p_dir text, p_dids uuid[], p_pt geometry, p_district uuid)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  SELECT (p_pt IS NOT NULL AND public.wassell_geo_region_contains(p_geom, p_ref, p_dir, p_pt))
      OR (p_district IS NOT NULL AND p_district = ANY(p_dids))
$function$;
CREATE OR REPLACE FUNCTION public.wassell_geo_item_match(p_geom geometry, p_ref geometry, p_dir text, p_dids uuid[], p_pt geometry, p_district uuid)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN p_pt IS NOT NULL THEN public.wassell_geo_region_contains(p_geom, p_ref, p_dir, p_pt)
    ELSE (p_district IS NOT NULL AND p_district = ANY(p_dids))
  END
$function$;
CREATE OR REPLACE FUNCTION public.wassell_geo_match(p_client_id uuid)
 RETURNS TABLE(record_id uuid, matched_item_ids text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '20s'
AS $function$
  with inc as (
    select item_id, geom, ref_geom, direction, district_ids
    from public.client_pref_geometry
    where client_id = p_client_id and polarity = 'include' and validation_status = 'ok'
  ),
  exc as (
    select geom, ref_geom, direction, district_ids
    from public.client_pref_geometry
    where client_id = p_client_id and polarity = 'exclude' and validation_status = 'ok'
  ),
  cand as (
    select record_id, geom as pt, district_id from public.project_points where is_active
    union all
    select record_id, geom, district_id from public.listing_points where is_active
  ),
  inc_hits as (
    -- Polygon-area rules: LATERAL per-table probes so each points table's GiST
    -- index drives the containment (a UNION ALL candidate subquery was being
    -- seq-scanned with per-row ST_Contains — ~5s for a city-scale buffer).
    select c.record_id, i.item_id, c.pt, c.district_id
    from inc i
    cross join lateral (
      select pp.record_id, pp.geom as pt, pp.district_id
      from public.project_points pp
      where pp.is_active and ST_Contains(i.geom, pp.geom)
      union all
      select lp.record_id, lp.geom, lp.district_id
      from public.listing_points lp
      where lp.is_active and ST_Contains(i.geom, lp.geom)
    ) c
    where i.geom is not null
      and (i.direction is null or public.wassell_geo_dir_match(i.ref_geom, c.pt, i.direction))
    union all
    -- Legacy geom-less direction rows (pre-2026-07-18 compiles): bbox reject +
    -- exact-side shortcut + closest-point refine. Kept for safety; new compiles
    -- always emit a bounded buffer geom.
    select c.record_id, i.item_id, c.pt, c.district_id
    from inc i
    join cand c on i.geom is null and i.direction is not null
      and c.pt && case i.direction
        when 'north' then ST_MakeEnvelope(-180, ST_YMin(i.ref_geom), 180, 90, 4326)
        when 'south' then ST_MakeEnvelope(-180, -90, 180, ST_YMax(i.ref_geom), 4326)
        when 'east'  then ST_MakeEnvelope(ST_XMin(i.ref_geom), -90, 180, 90, 4326)
        when 'west'  then ST_MakeEnvelope(-180, -90, ST_XMax(i.ref_geom), 90, 4326)
        else ST_MakeEnvelope(-180, -90, 180, 90, 4326)
      end
    where (case i.direction
             when 'north' then ST_Y(c.pt) > ST_YMax(i.ref_geom)
             when 'south' then ST_Y(c.pt) < ST_YMin(i.ref_geom)
             when 'east'  then ST_X(c.pt) > ST_XMax(i.ref_geom)
             when 'west'  then ST_X(c.pt) < ST_XMin(i.ref_geom)
             else false
           end)
       or public.wassell_geo_dir_match(i.ref_geom, c.pt, i.direction)
  )
  select h.record_id, array_agg(distinct h.item_id) as matched_item_ids
  from inc_hits h
  where not exists (
    select 1 from exc e
    where public.wassell_geo_exclude_match(e.geom, e.ref_geom, e.direction, e.district_ids, h.pt, h.district_id)
  )
  group by h.record_id
  order by h.record_id
$function$;
